// ---- SNG-220: "Weave in the valley" INTEGRATES what the player typed, never overwrites it ----
{
  // §2a/§2b: the player's typed bio goes IN as the seed; the prompt enriches, never replaces (injected fake).
  let capSys = "", capContent = "";
  const cap = async (msgs, opts) => { capSys = opts.system; capContent = msgs[0].content; return { story: "x" }; };
  await generateBio({ name: "Sisu", origin: "valley", background: "farmer", attributes: { craft: 4 }, bio: { hometown: "a fishing hamlet two days upriver", motivation: "a debt he can't name" } }, cap);
  check("220 §2a: the player's typed bio fields reach generateBio (the seed)", /a fishing hamlet two days upriver/.test(capContent) && /a debt he can't name/.test(capContent));
  check("220 §2b: the prompt INTEGRATES — preserve intent, enrich, never replace/discard", /Their words are the SEED/.test(capSys) && /never contradict or discard/.test(capSys) && /do NOT replace their story with yours/.test(capSys));
  const emptyCap = { sys: "", content: "" };
  await generateBio({ name: "A", origin: "valley", background: "b", attributes: {} }, async (m, o) => { emptyCap.content = m[0].content; return {}; });
  check("220: a blank bio still authors fresh (no typed fields → the 'left blank' path)", /left the story blank/.test(emptyCap.content));
  const appSrc220 = readFileSync(join(root, "app.js"), "utf8");
  check("220 §2a: the weave call passes the player's read() as `bio` (the fear-fix)", /generateBio\(\{ name: state\.name, origin: state\.origin, background: state\.background, attributes: state\.attrs, bio: read\(\) \}\)/.test(appSrc220));
  check("220 §2c: an undo — the pre-weave text is stashed + a 'Revert to what I wrote' restores it", /const before = read\(\)/.test(appSrc220) && /bio-revert/.test(appSrc220) && /renderBioStep\(revertTo\)/.test(appSrc220));
  check("220 §2c/§2d: the button is relabelled + a plain description states it keeps your words", /✦ Weave in the valley/.test(appSrc220) && /keeps your words/.test(appSrc220));
}

// ---- SNG-209: death is a STATE, not a terminus — depth grades the wall, and the clock sinks the untended ----
{
  // §5.4: entering the death state is a STATUS extension, never a delete. Fresh → depth 0 (the threshold).
  const fell = enterDeathState({ id: "npc-1", name: "Roan", status: "active" }, { diedDay: 100, cause: "a blade" });
  check("209 §5.4: enterDeathState sets status dead + a deathState record (not a delete)", fell.status === "dead" && !!fell.deathState && fell.deathState.diedDay === 100 && fell.deathState.cause === "a blade");
  check("209 §2: a fresh death is at THE THRESHOLD (depth 0) — reachable, cheap", deathDepth(fell, 100) === 0 && DEATH_DEPTH_NAMES[0] === "the threshold");

  // §2: depth is COMPUTED from time-dead — threshold → near dark → deep dark as the days pass.
  check("209 §2: days pass → the near dark (depth 1)", deathDepth(fell, 120) === 1);
  check("209 §2: a season passes → the deep dark (depth 2)", deathDepth(fell, 200) === 2);
  check("209 §2: body LOST forces the deep dark even when fresh", deathDepth(enterDeathState({ status: "active" }, { diedDay: 100, bodyStatus: "lost" }), 101) === 2);

  // §2: a GM override wins over the computed depth (computed-with-GM-override, ROUND 2 Q1 recommendation).
  const forced = enterDeathState({ status: "active" }, { diedDay: 100, depthOverride: 3 });
  check("209 §2: a GM depthOverride wins over the clock (sealed by fiat)", deathDepth(forced, 101) === 3 && isSealed(forced, 101));

  // §1: retrievable until sealed — a dead figure at a reachable depth is a HOOK, not a void.
  check("209 §1: a deep-dark death is still RETRIEVABLE (dead ≠ gone)", isRetrievable(fell, 200) && !isSealed(fell, 200));
  const sealedOne = enterDeathState({ status: "active" }, { diedDay: 100, sealed: true });
  check("209 §1: a SEALED death is not retrievable (beyond the roads back)", !isRetrievable(sealedOne, 101) && isSealed(sealedOne));

  // §5.6 THE CLOCK: a death untended past sealAfterDays sinks to sealed — and says so once (news).
  const tended = enterDeathState({ id: "a", name: "A", status: "active" }, { diedDay: 100 });
  const stale = enterDeathState({ id: "b", name: "B", status: "active" }, { diedDay: 100 });
  const newlySealed = deepenDeaths([tended, stale], 100 + 130); // 130 > default sealAfterDays (120)
  check("209 §5.6: deepenDeaths seals a death left untended past the threshold", newlySealed.length === 2 && stale.deathState.sealed === true);
  check("209 §5.6: the clock is idempotent — an already-sealed death isn't re-sealed (no duplicate news)", deepenDeaths([stale], 100 + 300).length === 0);
  check("209 §5.6: a still-recent death is NOT swept (the clock only takes the long-neglected)", deepenDeaths([enterDeathState({ status: "active" }, { diedDay: 100 })], 100 + 10).length === 0);

  // §4/§5.5: the retrieval primitive — RETURN restores (optionally CHANGED); FAIL sinks deeper; SEAL is one-way.
  const back = enterDeathState({ id: "r", name: "R", status: "active" }, { diedDay: 100 });
  const rr = resolveRetrieval(back, "return", { currentDay: 110, changed: "hollow-eyed" });
  check("209 §4: resolveRetrieval('return') restores status + records the change, clears the death state", rr.ok && back.status === "active" && !back.deathState && back.returnedFromDeath.changed === "hollow-eyed");
  const risky = enterDeathState({ status: "active" }, { diedDay: 100 });
  const fail1 = resolveRetrieval(risky, "fail", { currentDay: 105 }); // day 105 = near dark (1) → fail sinks to deep dark (2)
  check("209 §4: a FAILED retrieval sinks them deeper (the risk)", fail1.ok && fail1.deepened && deathDepth(risky, 105) === 2);
  const sealedBack = enterDeathState({ status: "active" }, { diedDay: 100, sealed: true });
  check("209 §4 GUARD: a sealed death refuses every road (return fails)", resolveRetrieval(sealedBack, "return").ok === false);

  // §5.1/§5.3 WIRING: a killed legend ENTERS the death state via applyEpicClashOutcome (not a bare status flip).
  const wtSrc209 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  check("209 §5.3: an epic KILL calls enterDeathState (the legend is in the death state, reachable, not deleted)", /enterDeathState\(st, \{ diedDay: worldDay/.test(wtSrc209));
  check("209 §5.6: the offscreen tick runs the CLOCK (deepenDeaths) + surfaces a seal as a real event", /deepenDeaths\(\[\.\.\.deathNames\.keys\(\)\], currentWorldDay/.test(wtSrc209) && /passed beyond the roads back/.test(wtSrc209));

  // §1 WIRING: the reachable dead reach the GM context — a killed-but-unsealed figure surfaces as a hook.
  const wchar209 = { worldState: { lastTickWorldDay: 150, epicStatus: { "ep-1": enterDeathState({ status: "active" }, { diedDay: 140, cause: "a duel" }) } }, npcRegistry: {} };
  const content209 = { legends: { roster: [{ id: "ep-1", name: "Vharos the Grey" }] } };
  const rd = reachableDeadForGM(wchar209, content209, 150);
  check("209 §1: reachableDeadForGM surfaces a killed-but-unsealed legend as a hook (name + the wall)", Array.isArray(rd) && rd[0]?.name === "Vharos the Grey" && rd[0]?.wall === "the near dark");
  wchar209.worldState.epicStatus["ep-1"].deathState.sealed = true;
  check("209 §1: a SEALED death is dropped from the reachable-dead surface (truly gone)", reachableDeadForGM(wchar209, content209, 150) === null);
  const gmRegSrc209 = readFileSync(join(root, "engine/gm_registry.js"), "utf8");
  check("209 §1: reachableDeadDetail is a registered GM_CONTEXT surface (turn + ask)", /key: "reachableDeadDetail"/.test(gmRegSrc209) && /reachableDeadForGM/.test(gmRegSrc209));

  // §4/§5.5 WIRING: the author god-mode is the Phase-1 TRIGGER — it enacts a return/seal on a death state.
  const amod209 = await import("../engine/authormode.js");
  check("209 §4: 'resolveDeath' is in the AUTHOR_OPS vocabulary", amod209.AUTHOR_OPS.includes("resolveDeath"));
  const gchar = { worldState: { epicStatus: { "ep-2": enterDeathState({ status: "active" }, { diedDay: 100 }) } }, authorEdits: [] };
  amod209.applyAuthorOps(gchar, [{ op: "resolveDeath", targetId: "ep-2", outcome: "return", changed: "grey at the temples" }], { worldDay: 120 });
  check("209 §4: the author op RETURNS a dead figure (status active, the change recorded + logged)", gchar.worldState.epicStatus["ep-2"].status === "active" && gchar.worldState.epicStatus["ep-2"].returnedFromDeath?.changed === "grey at the temples" && gchar.authorEdits.some(e => e.kind === "resolveDeath"));
  const gres2 = amod209.applyAuthorOps({ worldState: {}, npcRegistry: {} }, [{ op: "resolveDeath", targetId: "ghost" }], {});
  check("209 §4 GUARD: resolveDeath refuses a target that isn't in any registry", gres2.refused.some(x => /no dead figure/.test(x.reason)));
}

// ---- CCODE-15: the reparent lever + map nesting — a stray transit-stub nests under its true place ----
{
  const wm225 = await import("../engine/worldmap.js");
  // MAP NESTING: a sub-location (parentId → another node IN this region) drops off the top-level region map.
  const CONTENT225 = { locations: {
    "gen-waygate": { id: "gen-waygate", name: "Waygate", regionId: "valley" },
    "gen-the-ent-grove": { id: "gen-the-ent-grove", name: "The Ent Grove", regionId: "valley", parentId: "gen-waygate" },
    millbrook: { id: "millbrook", name: "Millbrook", regionId: "valley" }
  } };
  const flat = wm225.regionTierNodes(CONTENT225, { placeMemory: {} }, "valley").locations.map(l => l.id);
  check("CCODE-15 nesting: a sub-location (in-region parentId) is nested, not a top-level peer node", !flat.includes("gen-the-ent-grove") && flat.includes("gen-waygate") && flat.includes("millbrook"));
  // a parentId pointing OUTSIDE the region does NOT nest (the parent isn't shown here to nest under).
  const CONTENT225b = { locations: { "gen-x": { id: "gen-x", name: "X", regionId: "valley", parentId: "somewhere_else" }, millbrook: { id: "millbrook", name: "Millbrook", regionId: "valley" } } };
  check("CCODE-15 nesting: an OUT-of-region parentId keeps it top-level (no in-region parent to nest under)", wm225.regionTierNodes(CONTENT225b, {}, "valley").locations.map(l => l.id).includes("gen-x"));

  // THE REPARENT OP: nest a gen-location under another, aligning region; clear it; refuse canonical/unknown.
  const amod225 = await import("../engine/authormode.js");
  check("CCODE-15: 'reparentLocation' is in the AUTHOR_OPS vocabulary", amod225.AUTHOR_OPS.includes("reparentLocation"));
  const c225 = { generated: { location: {
    "gen-the-ent-grove": { id: "gen-the-ent-grove", name: "The Ent Grove", regionId: "valley" },
    "gen-waygate": { id: "gen-waygate", name: "Waygate", regionId: "the_center" }
  } }, authorEdits: [] };
  amod225.applyAuthorOps(c225, [{ op: "reparentLocation", locationId: "gen-the-ent-grove", parentId: "gen-waygate" }], {});
  check("CCODE-15: reparent sets parentId + inherits the parent's region (a sub-place shares its parent's region)", c225.generated.location["gen-the-ent-grove"].parentId === "gen-waygate" && c225.generated.location["gen-the-ent-grove"].regionId === "the_center" && c225.authorEdits.some(e => e.kind === "reparentLocation"));
  amod225.applyAuthorOps(c225, [{ op: "reparentLocation", locationId: "gen-the-ent-grove", parentId: "" }], {});
  check("CCODE-15: a falsy parentId CLEARS the parent (un-nest back to top-level)", !c225.generated.location["gen-the-ent-grove"].parentId);
  const r225a = amod225.applyAuthorOps(c225, [{ op: "reparentLocation", locationId: "the_crossing", parentId: "gen-waygate" }], { locations: { the_crossing: { id: "the_crossing" } } });
  check("CCODE-15 GUARD: a canonical location can't be reparented (fixed geography)", r225a.refused.some(x => /canonical places are fixed/.test(x.reason)));
  const r225b = amod225.applyAuthorOps(c225, [{ op: "reparentLocation", locationId: "gen-waygate", parentId: "gen-waygate" }], {});
  check("CCODE-15 GUARD: a place cannot be its own parent", r225b.refused.some(x => /own parent/.test(x.reason)));
  const appSrc225 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-15: the Author panel exposes the reparent lever (dev-gated) + passes CONTENT.locations to ctx", /data-au="reparentLocation"/.test(appSrc225) && /locations: CONTENT\.locations/.test(appSrc225));

  // PREVENTION (root cause): the GM is told to REUSE an existing place's name, not coin a synonym (the mint
  // that made "Center" beside "The Crossing"); the travel directive reinforces it; the mint logs its coin-rate.
  const gmSrc225 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-15 prevention: the moveTo directive forbids coining a NEW name for a place that already exists", /USE THE EXISTING NAME/.test(gmSrc225) && /coined synonym mints a DUPLICATE/.test(gmSrc225));
  check("CCODE-15 prevention: the travel directive tells the GM to reuse a reachable place's exact name/id", /do not coin a new synonym for a place you can already reach/.test(appSrc225));
  check("CCODE-15 observability: mintTransitLocation logs every coin (the coin-rate is measurable)", /\[transit-mint\] coined/.test(appSrc225));
}

// ---- SNG-215 §A: the ability sidebar — grouped by FUNCTION, and a player-set craft BOOST ----
{
  const appSrcA = readFileSync(join(root, "app.js"), "utf8");
  const gmSrcA = readFileSync(join(root, "engine/gm.js"), "utf8");
  const cssA = readFileSync(join(root, "style.css"), "utf8");

  // §A2: the sidebar groups owned crafts by FUNCTION FAMILY (familiesOfAbility), not by tradition.
  check("215 §A2: the sidebar groups crafts by FUNCTION FAMILY (familiesOfAbility + FUNCTION_FAMILIES order)", /familiesOfAbility\(o\.ab, FN_INDEX\)\[0\]/.test(appSrcA) && /FUNCTION_FAMILIES\.filter\(f => byFam\[f\]/.test(appSrcA));
  check("215 §A2: each family group is colour-coded by the world's function colour", /\.skill-group\.fn-fam-know > summary/.test(cssA) && /\.skill-group\.fn-fam-harm > summary/.test(cssA));

  // §A1: the boost toggle in the row, its persist-and-nudge handler, and the CSS.
  check("215 §A1: each craft row carries a boost toggle (data-boost) reading character.boostedCrafts", /data-boost="\$\{esc\(a\.abilityId\)\}"/.test(appSrcA) && /const boostSet = new Set\(character\.boostedCrafts/.test(appSrcA));
  check("215 §A1: the boost handler toggles boostedCrafts + persists (targeted DOM update, no full re-render)", /const el = e\.target\.closest\?\.\("\[data-boost\]"\)/.test(appSrcA) && /character\.boostedCrafts\.push\(id\)/.test(appSrcA) && /saveCharacter\(character\)/.test(appSrcA));

  // §A1 wiring: the boost reaches BOTH suggestion surfaces — the level-up reasoned pick and the choice pre-fill.
  check("215 §A1: the level-up suggestion is now PASSED the boosted crafts (was declared, never fed)", /boosted: \(character\.boostedCrafts \|\| \[\]\)\.map\(id => cat\[id\]\?\.name \|\| id\)/.test(appSrcA));
  check("215 §A1: the SNG-214 choice pre-fill rule FAVOURS a boosted craft (when it fits, never forced)", /FAVOUR a craft the player has BOOSTED/.test(gmSrcA));

  // §A1: the TOOLKIT block surfaces boosted crafts (the shared signal the choice rule reads).
  const { toolkitForGM: tkA } = await import("../engine/toolkit.js");
  const { buildFunctionIndex: bfiA } = await import("../engine/functions.js");
  const chA = { abilities: [{ abilityId: "wither", level: 2 }], boostedCrafts: ["wither"], practice: {} };
  const blockA = tkA(chA, { catalog: { wither: { name: "Wither" } }, fnIndex: bfiA({}), rules: {} });
  check("215 §A1: toolkitForGM surfaces the player's boosted crafts (fed to the GM, atmospherically)", /Player wants to use these MORE/.test(blockA) && /Wither/.test(blockA));
  check("215 §A1 GUARD: no boosted crafts → no boost line (only when the player set one)", !/Player wants to use these MORE/.test(tkA({ abilities: [], practice: {} }, { catalog: {}, fnIndex: bfiA({}), rules: {} })));
  check("215 §A1: the boost is a NUDGE, not an override (the guard is in the prompt + the tooltip)", /never force an ill-fitting one/.test(blockA) || /thumb on the scale/.test(gmSrcA));

  // §B: the inventory is a BAG — a grid of kind-icon tiles, tap → a detail popup (image + mechanics + actions).
  check("215 §B: a kind→icon map + a bag GRID of tiles (scan fast, no image quota in the grid)", /const ITEM_KIND_ICON = \{/.test(appSrcA) && /class="bag-tile/.test(appSrcA) && /<div class="bag-grid">/.test(appSrcA));
  check("215 §B: a tile opens a DETAIL POPUP that reuses itemCard(open) — the larger image + mechanics + actions", /class="item-detail-modal"/.test(appSrcA) && /itemCard\(openIt, \{ open: true, showPin: true \}\)/.test(appSrcA));
  check("215 §B: the popup closes on ✕ or backdrop, and a grown story-item shows the stage it reached", /item-modal-close/.test(appSrcA) && /if \(e\.target === modal\) renderInventoryScreen\(null\)/.test(appSrcA) && /grown to/.test(appSrcA));
  check("215 §B: the bag + popup are styled (grid + modal + larger detail image)", /\.bag-grid \{ display: grid/.test(cssA) && /\.item-detail-modal \{/.test(cssA) && /\.item-detail-sheet \.item-img/.test(cssA));
}

// ---- SNG-215 §C-1: every TRAIT reads in two registers — LORE + MECHANICS (derived fallback + authored) ----
{
  const appSrcC = readFileSync(join(root, "app.js"), "utf8");
  const cssC = readFileSync(join(root, "style.css"), "utf8");
  const stateC = readFileSync(join(root, "engine/state.js"), "utf8");

  // the readout lookup: authored (trait_readouts) wins, else DERIVE from existing data for each trait kind.
  check("215 §C: traitReadout(kind,id) — authored trait_readouts wins (singular OR plural key), else a derived fallback", /function traitReadout\(kind, id\)/.test(appSrcC) && /tr\[kind\]\?\.\[id\] \|\| tr\[kind \+ "s"\]\?\.\[id\]/.test(appSrcC));
  check("215 §C: MECHANICS are DERIVED for each trait — background affinity, origin native craft, tradition families, aspiration progress, form is cosmetic", /background.*affinity/is.test(appSrcC) && /native craft/.test(appSrcC) && /traditionFamilies\(id\)/.test(appSrcC) && /Cosmetic — your form leads/.test(appSrcC));
  check("215 §C: a tradition's granted FUNCTION FAMILIES are derived by unioning its abilities' families", /function traditionFamilies\(tradId\)/.test(appSrcC) && /familiesOfAbility\(ab, FN_INDEX\)/.test(appSrcC));

  // the traits are TAPPABLE — the shared popover shows the readout.
  check("215 §C: origin + background + form + tradition + aspiration are all tappable (data-trait)", /data-trait="origin:/.test(appSrcC) && /data-trait="background:/.test(appSrcC) && /data-trait="form:self"/.test(appSrcC) && /data-trait="tradition:/.test(appSrcC) && /data-trait="aspiration:/.test(appSrcC));
  check("215 §C: a delegated [data-trait] handler opens the lore+mechanics readout on the shared popover", /const el = e\.target\.closest\?\.\("\[data-trait\]"\)/.test(appSrcC) && /traitReadout\(s\.slice/.test(appSrcC) && /showPopoverText\(txt\)/.test(appSrcC));
  check("215 §C: the tappable trait is styled (a dotted underline signals it)", /\.trait-tap \{ cursor: pointer/.test(cssC));

  // the content shell is READY — Aevi's trait_readouts.json loads (optional; derived fallback until then).
  check("215 §C: trait_readouts is wired into loadContent (Aevi drops the file; optional load, empty fallback)", /loadRule\("trait_readouts", \{ readouts: \{\} \}\)/.test(stateC) && /trait_readouts: traitReadoutsDoc/.test(stateC));

  // §C-2: the merge — the character surface is ONE screen with a Traits | Chronicle tab bar.
  check("215 §C-2: a Traits | Chronicle tab bar helper drives the merged character surface", /function characterTabBar\(active\)/.test(appSrcC) && /id="tab-traits"/.test(appSrcC) && /id="tab-chronicle"/.test(appSrcC));
  check("215 §C-2: both surfaces render the tab bar (Traits sheet + Chronicle)", /characterTabBar\("traits"\)/.test(appSrcC) && /characterTabBar\("chronicle"\)/.test(appSrcC));
  // SNG-276: wiring moved into ONE `wireCharacterTabs()` — each render used to wire its own buttons, which
  // is how a third tab gets added to the markup and stays dead on two of the three screens. Assert the
  // INTENT (every tab reaches its render) rather than the old per-render pattern.
  check("215 §C-2: the tabs switch between the renders", /go\("tab-chronicle", \(\) => renderChronicle\(\)\)/.test(appSrcC) && /go\("tab-traits", \(\) => renderCharacterScreen\(\)\)/.test(appSrcC));
  check("276: EVERY character render wires the tab bar (a tab dead on one screen is the bug this prevents)",
    (appSrcC.match(/wireCharacterTabs\(\);/g) || []).length >= 3);
  check("215 §C-2 dedup: the old standalone 'The Chronicle' button is gone (the tab replaces it), lived-story not duplicated on Traits", !/id="cs-chronicle"/.test(appSrcC) && /the Chronicle tab's job now/.test(appSrcC));
  check("215 §C-2: the tab bar is styled", /\.char-tabs \{ display: flex/.test(cssC) && /\.char-tab\.on \{/.test(cssC));
}

// ---- SNG-226: a discovery is RECORDED but must also be USABLE — register it in abilities[] (the one list) ----
{
  const br226 = await import("../engine/braids.js");
  const cat226 = {
    a: { id: "a", name: "Craft A", tradition: "ashwarden", levelReq: 2, functions: ["strike"], harmRung: "wounding", energyCost: 5 },
    b: { id: "b", name: "Craft B", tradition: "ashwarden", levelReq: 3, functions: ["ward"], harmRung: "none", energyCost: 7 }
  };
  // Marrow's Wings shape: a 2-parent discovery recorded in discoveries[] but NOT in abilities[] (the live bug).
  const ch = { level: 6, abilities: [{ abilityId: "a", level: 3 }, { abilityId: "b", level: 2 }] };
  const disc = { key: "a+b:flight", id: "marrow-s-wings", name: "Marrow's Wings", description: "spread death-shadow wings and fly", abilities: ["a", "b"], discoveredDay: 13 };
  const def = br226.registerDiscoveryAbility(ch, disc, cat226, { at: 13 });
  check("226: a discovery REGISTERS as a usable craft in abilities[] under its own id (rank 1, deepens through use)", !!def && ch.abilities.some(a => a.abilityId === "marrow-s-wings" && a.level === 1 && a.discovered));
  check("226: the usable def is resolvable via customAbilities (fullCatalog sees it) — real cost + the GM's description", ch.customAbilities?.["marrow-s-wings"]?.energyCost > 0 && /fly/.test(ch.customAbilities["marrow-s-wings"].description));
  check("226 §3: functions carry over from the parents (the resolver/wheel read them)", Array.isArray(ch.customAbilities["marrow-s-wings"].functions));
  check("226 GUARD: idempotent — a discovery already usable is not re-registered (no duplicate)", br226.registerDiscoveryAbility(ch, disc, cat226) === null && ch.abilities.filter(a => a.abilityId === "marrow-s-wings").length === 1);

  // a 3-parent discovery with a repeated parent DEDUPES to 2 and still registers (You Shall Not Pass shape).
  const ch3 = { level: 6, abilities: [{ abilityId: "a", level: 1 }, { abilityId: "b", level: 1 }] };
  check("226: a 3-parent discovery (a repeated parent) dedupes to 2 and still registers usable", !!br226.registerDiscoveryAbility(ch3, { id: "you-shall-not-pass", name: "You Shall Not Pass", description: "hold the line", abilities: ["a", "a", "b"] }, cat226) && ch3.abilities.some(a => a.abilityId === "you-shall-not-pass"));

  // already usable via a braid of the SAME pairing → skip (it's castable via that braid, don't double-register).
  const chBr = { level: 6, abilities: [{ abilityId: "a", level: 1 }, { abilityId: "b", level: 1 }], braids: [{ id: "braid_a_b", from: ["a", "b"] }] };
  check("226 GUARD: a discovery whose pairing is already braided is skipped (already castable via the braid)", br226.registerDiscoveryAbility(chBr, { id: "resonant-x", name: "Resonant X", abilities: ["a", "b"] }, cat226) === null);

  // fallback: only ONE parent resolves (id-drift / missing) → still a minimal USABLE def from the discovery's words.
  const ch1 = { level: 6, abilities: [{ abilityId: "b", level: 1 }] };
  const def1 = br226.registerDiscoveryAbility(ch1, { id: "half-known", name: "Half Known", description: "a craft half-remembered", abilities: ["missing-parent", "b"] }, cat226);
  check("226: a parent that doesn't resolve still yields a usable craft (a minimal fallback — never a dead reward)", !!def1 && ch1.customAbilities?.["half-known"]?.energyCost > 0 && ch1.abilities.some(a => a.abilityId === "half-known"));
  check("226 GUARD: the discovery record is KEPT — registration ADDS the usable ability, discoveries[] is the moment/codex source", !!disc.id && !!disc.key); // the input discovery object is never mutated away

  // app wiring: at the mint site + a load backfill.
  const appSrc226 = readFileSync(join(root, "app.js"), "utf8");
  check("226: mint-time — recordDiscovery is followed by registerDiscoveryAbility (usable + celebrated together, §5)", /registerDiscoveryAbility\(character, minted, fullCatalog\(\)/.test(appSrc226));
  check("226 §4: a load BACKFILL registers any discovery not yet in abilities[] (Marrow's Wings heals on load)", /for \(const d of \(c\.discoveries \|\| \[\]\)\)[\s\S]{0,140}registerDiscoveryAbility\(c, d/.test(appSrc226));
}

// ---- SNG-225: the encounter pool is STARVED at generated locations — null danger reads as 0 (§3/§4a/§4b) ----
{
  // §4b: a MISSING dangerLevel floors to 1 (not 0), so it never silently guts the pool. An explicit value stands.
  check("225 §4b: dangerOf floors a NULL dangerLevel to 1 (a missing field is not the safest place)", dangerOf({ tags: [] }) === 1 && dangerOf({ dangerLevel: null }) === 1 && dangerOf({}) === 1);
  check("225 §4b: an EXPLICIT dangerLevel is honoured (0 stays 0 — a deliberate haven; 3 stays 3)", dangerOf({ dangerLevel: 0 }) === 0 && dangerOf({ dangerLevel: 3 }) === 3);

  // THE BUG, PROVEN: a minDanger:1 encounter was INELIGIBLE at a null-danger location; now it's eligible.
  const fight = { id: "raiders", flavor: "fight", minDanger: 1, regions: ["*"] };
  check("225 §3: a minDanger:1 encounter is now ELIGIBLE at a null-danger location (the pool un-starves)", isEligible(fight, { tags: ["transitional"], regionId: "valley" }) === true);

  // §4a: deriveDangerLevel — inherit the neighbourhood, nudge by tags, floor 1, clamp 4.
  check("225 §4a: derive inherits the neighbourhood's danger (a road near a danger-2 town ≈ 2)", deriveDangerLevel({ tags: ["transitional"] }, { baseDanger: 2 }) === 2);
  check("225 §4a: a transit stub with no neighbourhood still floors to 1 (never null/0)", deriveDangerLevel({ tags: ["transitional"] }) === 1);
  check("225 §4a: a RISKY tag lifts, a SAFE tag lowers, clamped 1..4", deriveDangerLevel({ tags: ["disputed"] }, { baseDanger: 2 }) === 3 && deriveDangerLevel({ tags: ["hearth"] }, { baseDanger: 2 }) === 1 && deriveDangerLevel({ tags: ["ruin", "wild"] }, { baseDanger: 4 }) === 4);

  // wiring: minted with a real danger + a load backfill heals existing null-danger gen-locations.
  const appSrc225b = readFileSync(join(root, "app.js"), "utf8");
  check("225 §4a: mintTransitLocation stamps a derived dangerLevel (never null again)", /dangerLevel: deriveDangerLevel\(\{ tags: \["transitional"\] \}, \{ baseDanger: here\?\.dangerLevel \}\)/.test(appSrc225b));
  check("225 §4a: a load BACKFILL heals any gen-location minted with null danger, from the region MEDIAN (Silas's Waygate → ~2)", /for \(const loc of Object\.values\(c\.generated\?\.location \|\| \{\}\)\)[\s\S]{0,160}loc\.dangerLevel = deriveDangerLevel\(loc, \{ baseDanger: regionMedian/.test(appSrc225b));

  // §4c (Erik's call): the REGION-lock is dropped — a region-anchored encounter can find any place its DANGER admits.
  const marchRaider = { id: "march-raider", flavor: "fight", minDanger: 2, regions: ["riven_marches"] };
  check("225 §4c: a region-anchored encounter is ELIGIBLE outside its region now (the world's dangers travel)", isEligible(marchRaider, { tags: ["transitional"], regionId: "valley", dangerLevel: 2 }) === true);
  check("225 §4c: but the DANGER gate still governs severity — that fight can't reach a danger-0 haven", isEligible(marchRaider, { tags: ["sanctuary"], regionId: "valley", dangerLevel: 0 }) === false);
  const crowdTheft = { id: "cutpurse", flavor: "theft", minDanger: 1, regions: ["*"], tags: ["crowd"] };
  check("225 §4c: the TAG soft-match still governs context — a cutpurse (wants a crowd) skips an empty road", isEligible(crowdTheft, { tags: ["transitional"], dangerLevel: 2 }) === false && isEligible(crowdTheft, { tags: ["crowd", "market"], dangerLevel: 2 }) === true);
  check("225 §4c: isEligible no longer hard-gates on region (the region field is data, not a lock)", /region-lock is DROPPED/.test(readFileSync(join(root, "engine/random_encounters.js"), "utf8")));
}

// ---- SNG-228: a PERSON must never become a destination — "catch Ossian" minted Ossian as a place ----
{
  const { personDestination } = await import("../engine/intent.js");
  const locs228 = { the_registry: { id: "the_registry", name: "the North Gate Registry" }, millbrook: { id: "millbrook", name: "Millbrook" } };

  // THE BUG: a freshly-NAMED person (not registered) — flagged by a TITLE and a person-only VERB — is rejected.
  const ossian = personDestination("Ossian", { label: "fly to the brick hall to catch Ossian", exactWords: "fly to the brick hall, catch Clerk-Warden Ossian before she leaves" }, { npcRegistry: {}, locations: locs228 });
  check("228 §3b: a person named in the words (title 'Clerk-Warden' + verb 'catch') is caught — not a place", ossian.isPerson === true);
  check("228: a person with no recoverable place is NOT a destination (no phantom person-place minted)", ossian.isPerson && ossian.destId === null);

  // a KNOWN NPC in the registry is a person too.
  const reg = { ossian: { name: "Ossian", statusNote: "at the North Gate Registry, deciding what reaches the committee" } };
  check("228 §3b: a travelTo matching a registered NPC is a person", personDestination("Ossian", { label: "go to Ossian" }, { npcRegistry: reg, locations: locs228 }).isPerson === true);
  // §3c: redirect to the person's PLACE when it's recoverable from their status.
  check("228 §3c: when a registered person's status names a known place, travel THERE (not to the person)", personDestination("Ossian", { label: "go to Ossian" }, { npcRegistry: reg, locations: locs228 }).destId === "the_registry");

  // NOT a false positive: a real PLACE reached by a place-verb ('find'/'reach') is NOT flagged as a person.
  check("228 GUARD: a real place with a PLACE-verb ('find the old mill') is not mistaken for a person", personDestination("the old mill", { label: "find the old mill", exactWords: "go and find the old mill" }, { npcRegistry: {}, locations: locs228 }).isPerson === false);
  check("228 GUARD: a plain new place name (no person signal) mints as a place", personDestination("Cairnhold", { label: "set out for Cairnhold" }, { npcRegistry: {}, locations: locs228 }).isPerson === false);

  // wiring: travelIntentOf calls the belt only when the trusted travelTo resolves to no real place.
  const appSrc228 = readFileSync(join(root, "app.js"), "utf8");
  check("228: travelIntentOf runs the person belt when a trusted travelTo can't place (rejects/redirects, never phantom-mints a person)", /const person = personDestination\(ref, action, \{ npcRegistry: character\.npcRegistry, locations: CONTENT\.locations \}\)/.test(appSrc228) && /if \(person\.isPerson\) return person\.destId \?/.test(appSrc228));
}

// ---- SNG-227: energy economy — the level discount no longer runs away; braids cost a premium ----
{
  const R = { leveling: { energyEfficiencyPerTenLevels: 1, rankEnergyDiscount: 1, minEnergyCostFraction: 0.5 }, energy: { defaultActionCost: 5 } };
  const ab8 = { id: "a8", energyCost: 8 };
  const cost = (level, rank) => effectiveEnergyCost(ab8, { level, abilities: [{ abilityId: "a8", level: rank }] }, R);

  // §3a: the CHARACTER-level discount is -1 per TEN levels — a base-8 skill never bottoms to the floor (4) from level.
  check("227 §3a: level discount is now per-TEN-levels — L1 rank1 = base 8 (fresh skills BITE)", cost(1, 1) === 8);
  check("227 §3a: L10 rank1 is NOT at the floor anymore (was 4; now 8 - level0 = 8)", cost(10, 1) === 8 && cost(15, 1) === 7);
  check("227 §3a: L20 rank1 costs near base (7), not the floor (4) — energy stays a resource all game", cost(20, 1) === 7);

  // §3c: freshly-learned bites; mastery (rank) earns it DOWN toward the 50% floor — the usage-discount is visible now.
  check("227 §3c: a fresh skill (rank 1) is expensive; ranking it up cheapens it (rank 3 = -2)", cost(1, 1) === 8 && cost(1, 3) === 6);
  check("227 §3b: the 50% floor still holds (base 8 → never below 4, earned via rank not dumped at L10)", cost(1, 5) === 4 && effectiveEnergyCost(ab8, { level: 50, abilities: [{ abilityId: "a8", level: 5 }] }, R) === 4);

  // §3d: a braid's BASE = priciest parent + half the cheaper — always > priciest, always < both sequentially.
  const { braidBaseCost } = await import("../engine/braids.js");
  check("227 §3d: braid base = priciest + ceil(cheaper/2) (8+10→14, 10+10→15, 6+8→11)", braidBaseCost([{ energyCost: 8 }, { energyCost: 10 }]) === 14 && braidBaseCost([{ energyCost: 10 }, { energyCost: 10 }]) === 15 && braidBaseCost([{ energyCost: 6 }, { energyCost: 8 }]) === 11);
  check("227 §3d GUARD: a braid is ALWAYS > its priciest parent, ALWAYS < running both parts sequentially", braidBaseCost([{ energyCost: 8 }, { energyCost: 10 }]) > 10 && braidBaseCost([{ energyCost: 8 }, { energyCost: 10 }]) < 18);
  check("227 §4: the braid fraction is tunable (a smaller share → a cheaper braid)", braidBaseCost([{ energyCost: 8 }, { energyCost: 10 }], 0.25) === 12);

  // wiring: buildBraidDef uses the premium rule; the knobs live in rules; the fraction threads from CONTENT.rules.
  const brSrc227 = readFileSync(join(root, "engine/braids.js"), "utf8");
  const appSrc227 = readFileSync(join(root, "app.js"), "utf8");
  const resSrc227 = readFileSync(join(root, "content/packs/core/rules/resolution.json"), "utf8");
  check("227 §3d: buildBraidDef + the discovery fallback both use braidBaseCost (a discovered braid is premium too, ties SNG-226)", (brSrc227.match(/braidBaseCost\(sources/g) || []).length >= 2);
  check("227 §4: the knobs are JSON-tunable (renamed PerTenLevels + a braid fraction) and threaded from CONTENT.rules", /"energyEfficiencyPerTenLevels"/.test(resSrc227) && /"braidCheaperParentFraction"/.test(resSrc227) && /braidFraction: CONTENT\.rules\?\.leveling\?\.braidCheaperParentFraction/.test(appSrc227));
}

// ---- SNG-229: the bestiary — LOADED (§2a) and ENCOUNTERABLE (§2b), a source of monsters for the fight pool ----
{
  // §2a: the bestiary is in the LOADED pack + on the manifest whitelist (was staged + inert).
  const bpath = join(root, "content/packs/valley/bestiary.json");
  const bestiary = JSON.parse(readFileSync(bpath, "utf8"));
  check("229 §2a: the bestiary is loaded content (moved out of po/staged_content) with a roster", Array.isArray(bestiary.roster) && bestiary.roster.length >= 6);
  const manifest = JSON.parse(readFileSync(join(root, "content/packs/valley/manifest.json"), "utf8"));
  check("229 §2a: the manifest WHITELISTS the bestiary (or it silently does not exist)", (manifest.provides.bestiary || []).includes("bestiary.json"));
  const stateSrc229 = readFileSync(join(root, "engine/state.js"), "utf8");
  check("229 §2a: loadContent loads it into CONTENT.bestiary + merges the synthesized monsters into the pool", /const bestiaryP = jSettled\(\(valley\.provides\.bestiary/.test(stateSrc229) && /bestiary, traditionMotivations,[^\n]*encounterFrameContent/.test(stateSrc229) && /bestiaryEncounters\(bestiary\)/.test(stateSrc229));

  // §2b: every creature becomes a danger-gated DUEL encounter — the fight pool finally has monsters.
  const monsters = bestiaryEncounters(bestiary);
  check("229 §2b: every roster creature becomes an encounter entry (a source of monsters for the pool)", monsters.length === bestiary.roster.length && monsters.every(m => /^beast_/.test(m.id) && m.opponent && m.routing === "duel"));
  check("229 §2b: tier gates danger — a riffraff is low-danger, an epic is danger-4 (rare, deadly)", monsters.some(m => m.minDanger === 1) && monsters.some(m => m.minDanger === 4) && monsters.every(m => m.opponent.threat > 0));
  check("229 §2b: region-free (SNG-225 §4c) + offered as a DUEL with a decline/flee path (SNG-002b)", monsters.every(m => (m.regions || []).includes("*") && m.avoidable === true && m.opponent.yieldAt > 0));
  check("229 §2b: the creature's look + which crafts answer it ride on the entry (GM narrates; player knows the pressures)", monsters.every(m => m.creatureId && Array.isArray(m.pressures) && typeof m.seed === "string" && m.seed.length > 0));

  // the synthesized monsters are actually ELIGIBLE in the world (ties SNG-225 — a danger-2 place gets a monster).
  const riff = monsters.find(m => m.minDanger === 1);
  check("229 §2b × SNG-225: a synthesized riffraff is eligible at an ordinary danger-2 place (a monster in the world)", isEligible(riff, { tags: ["transitional"], regionId: "valley", dangerLevel: 2 }) === true);
  check("229: an empty/absent bestiary yields no monsters (tolerant — the pool is unchanged)", bestiaryEncounters({}).length === 0 && bestiaryEncounters({ roster: [] }).length === 0);

  // ---- SNG-231 §3: the GM-offered path now draws from the POOL + bestiary, not just hand-authored seeds ----
  const table231 = { encounters: [
    { id: "d1", routing: "duel", flavor: "fight", minDanger: 1, weight: 1 },
    { id: "c1", routing: "challenge", flavor: "chase", minDanger: 2, weight: 1 },
    { id: "n1", routing: "narrative", flavor: "dangerous", minDanger: 1, weight: 1 },   // no def to start → not offerable
    { id: "big", routing: "duel", flavor: "fight", minDanger: 4, weight: 1 },           // over-danger
    { id: "beast_x", routing: "duel", flavor: "dangerous", minDanger: 1, weight: 1, seed: "a beast" }, // SNG-229 beast in the pool
  ] };
  const loc231 = { dangerLevel: 3, tags: [] };
  const elig231 = eligibleEncountersFor(table231, loc231).map(e => e.id).sort();
  check("231 §3: eligibleEncountersFor lists the STRUCTURED pool (duel/challenge incl. beast_), danger-gated; narrative/opposed + over-danger excluded",
    elig231.join(",") === "beast_x,c1,d1" && !elig231.includes("n1") && !elig231.includes("big"));
  check("231 §3: a calmer place surfaces fewer (danger-gated — the c1 chase (minDanger 2) drops at danger 1)",
    eligibleEncountersFor(table231, { dangerLevel: 1, tags: [] }).map(e => e.id).sort().join(",") === "beast_x,d1");
  check("231 §3: the list is capped (the prompt isn't flooded)",
    eligibleEncountersFor({ encounters: Array.from({ length: 20 }, (_, i) => ({ id: "x" + i, routing: "duel", flavor: "fight", minDanger: 0, weight: 1 })) }, loc231, { cap: 5 }).length === 5);
  const appSrc231 = readFileSync(join(root, "app.js"), "utf8");
  check("231 §3: listAvailableEncounters offers authored seeds AND the eligible pool (the two encounter systems now talk)",
    // CCODE-52: the call now carries the player's POWER (the pool revolves around it). CCODE-55: the table
    // argument moved from CONTENT.randomEncounters to encounterTable() — the ONE merge point that folds this
    // character's GENERATED creatures into the authored pool. The property this check protects — seeds AND
    // the eligible pool both reach the offer — is unchanged; only where the pool comes from moved.
    /eligibleEncountersFor\(encounterTable\(\), loc(,|\))/.test(appSrc231) && /don't duplicate a hand-seeded/.test(appSrc231)
    && /power: characterPower\(character/.test(appSrc231));
  check("231 §3: a GM-offered POOL id routes through fireEncounter (the decline/engage beat), not a silent no-op",
    // CCODE-55: reads encounterTable() rather than CONTENT.randomEncounters, so a GM-offered GENERATED
    // creature resolves here too — reading the raw pool would make every grown monster un-engageable.
    /const entry = \(encounterTable\(\)\?\.encounters \|\| \[\]\)\.find\(e => e\.id === choice\.encounterId\)/.test(appSrc231) && /if \(entry\) \{ await fireEncounter\(entry\); return; \}/.test(appSrc231));

  // §2: the intermittent op-commit throw is now ISOLATED per op-group AND named — so the turn (and every OTHER
  // op, crucially newEncounter → a duel starts) lands even when one op throws. This is the "duel won't start" fix.
  check("231 §2: applyStep ISOLATES each op-group (npcUpdates / codexUpdates / newEncounter / …) so one throw doesn't abort the rest",
    /function applyStep\(label, fn\)/.test(appSrc231) && /applyStep\("npcUpdates", \(\) => applyNpcUpdates/.test(appSrc231) && /applyStep\("codexUpdates"/.test(appSrc231) && /applyStep\("newEncounter"/.test(appSrc231));
  check("231 §2: a fresh NPC's newEncounter (the duel/fight) SURVIVES an npcUpdates throw — the abort-cascade is gone",
    /applyStep\("newEncounter", \(\) => \{ nd = sanitizeNewEncounter/.test(appSrc231));

  // CCODE-19: registering the invented def is necessary but NOT sufficient — a fight only STARTS when a choice
  // carries its encounterId. The GM rarely wires that choice, so the duel it narrated never began. Guarantee it:
  // inject a deterministic ENGAGE choice for the new encounter when nothing already engages it. THIS is what
  // finally makes "I can't get a fight/duel to start" go away — the isolation fix only kept the def alive.
  check("CCODE-19: a GM-invented encounter gets a deterministic ENGAGE choice injected (routes through onChoice path A)",
    /if \(nd && !character\.activeEncounter && !\(turn\.choices \|\| \[\]\)\.some\(c => c\.encounterId === nd\.id\)\)/.test(appSrc231)
    && /encounterId: nd\.id/.test(appSrc231) && /turn\.choices = \[\.\.\.inject, \.\.\.\(turn\.choices \|\| \[\]\)\]/.test(appSrc231));
  check("CCODE-19: NOT injected when the GM already wired a choice to this encounter (no duplicate engage button)",
    /!\(turn\.choices \|\| \[\]\)\.some\(c => c\.encounterId === nd\.id\)/.test(appSrc231));
  check("CCODE-19: a LETHAL invented fight also gets an explicit decline (rule 18 — offered, never imposed)",
    /if \(nd\.lethal\) inject\.push\(\{ label: "Step back/.test(appSrc231));
  check("231 §2: isolated failures are NAMED (which op-group) on the report + the turn + the aside — not just 'something didn't land'",
    /character\._applyFailures\?\.length/.test(appSrc231) && /result\.turn\._applyFailedOp = ops\.join/.test(appSrc231) && /the \$\{turn\._applyFailedOp[\s\S]*?\} step/.test(appSrc231));
  check("231 §2: affiliation enrichment is best-effort — a throw there never breaks the meet (the person is still registered)",
    /affiliation enrichment failed \(person still registered\)/.test(readFileSync(join(root, "engine/npcs.js"), "utf8")));

  // §2c: tradition_motivations is LOADED (its own type, not dead location-lore) and surfaced SELECTIVELY —
  // only the traditions in play this beat, each with its want + the creature its craft DREADS.
  const tmPath = join(root, "content/packs/valley/tradition_motivations.json");
  const tmDoc = JSON.parse(readFileSync(tmPath, "utf8"));
  check("229 §2c: the manifest WHITELISTS tradition_motivations (its own content type, not lore)", (manifest.provides.tradition_motivations || []).includes("tradition_motivations.json"));
  check("229 §2c: loadContent loads it into CONTENT.traditionMotivations (parallel to the bestiary loader)",
    /const traditionMotivationsP = jSettled\(\(valley\.provides\.tradition_motivations/.test(stateSrc229) && /traditionMotivations,[^\n]*encounterFrameContent/.test(stateSrc229));
  // the SELECTOR: bounded to who's in play, deduped, dread resolved to a creature name, villainy GM-eyes
  const dreadCreature = tmDoc.traditions.ashwarden?.dreads?.creature;
  const sel = traditionMotivationsForGM(tmDoc, ["ashwarden", "cogitant", "ashwarden", "not_a_tradition"], { bestiary, labelOf: id => id });
  check("229 §2c: surfaces ONLY in-play traditions, deduped, unknown ids dropped",
    (sel.match(/^- /gm) || []).length === 2 && sel.includes("ashwarden") && sel.includes("cogitant") && !sel.includes("not_a_tradition"));
  check("229 §2c: a tradition's WANT and the creature its craft DREADS both surface (the bestiary fear)",
    /wants:/.test(sel) && (!dreadCreature || sel.includes("DREADS")));
  check("229 §2c: villainy rides as a GM-EYES antagonist seed, never stated to the player as fact",
    !tmDoc.traditions.ashwarden?.villainy || /GM-eyes/.test(sel));
  check("229 §2c: empty when nothing is in play or the doc is absent (tolerant)",
    traditionMotivationsForGM(tmDoc, [], {}) === "" && traditionMotivationsForGM(null, ["ashwarden"], {}) === "");
  // wired into the GM context registry + rendered (not a dead export)
  const gmRegSrc229 = readFileSync(join(root, "engine/gm_registry.js"), "utf8");
  const gmSrc229 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("229 §2c: the selector is WIRED into the GM context (registry row + rendered block), not a dead export",
    /traditionMotiveDetail/.test(gmRegSrc229) && /traditionMotivationsForGM\(doc, ids/.test(gmRegSrc229) && /traditionMotiveDetail/.test(gmSrc229) && /WHY THESE TRADITIONS ACT/.test(gmSrc229));
}

// ---- SNG-230 Phase 1: the ENCOUNTER FRAME model — make a structured encounter obvious (kind + win + 3 exits) ----
{
  // KIND ← (def.type, flavor)
  check("230: encounterKind maps type+flavor → kind (duel→fight, challenge/chase→chase, challenge/dangerous→hazard, puzzle→puzzle)",
    encounterKind({ type: "duel" }) === "fight" && encounterKind({ type: "challenge", flavor: "chase" }) === "chase" &&
    encounterKind({ type: "challenge", flavor: "dangerous" }) === "hazard" && encounterKind({ type: "puzzle" }) === "puzzle" &&
    encounterKind({ type: "narrative" }) === null);

  // the frame descriptor: title + WIN CONDITION + meter + the THREE EXITS always present (the grammar)
  const chaseDef = synthesizeChallengeDef({ id: "x", flavor: "chase", stages: 3, seed: "runners in the cut-lane" });
  const fm = frameModel(chaseDef, { stageIndex: 1, stagesDone: ["s0"] }, null);
  check("230: frameModel yields kind + a stated win-condition + a meter + a stage",
    fm.kind === "chase" && typeof fm.winCondition === "string" && fm.winCondition.length > 0 && fm.meter.total === 3 && fm.meter.done === 1 && fm.stage.total === 3);
  check("230: the THREE EXITS are always present — defeat, flee, fail (the grammar §2.3)",
    fm.exits.length === 3 && fm.exits.map(e => e.role).join(",") === "defeat,flee,fail" && fm.exits.every(e => typeof e.means === "string" && e.means.length));
  check("230: defeat + flee are player-chooseable (wire to the existing [data-encact]: stage/abandon); fail is the outcome of losing (no button, its stakes surfaced)",
    fm.exits[0].action === "stage" && fm.exits[1].action === "abandon" && fm.exits[2].action === null && !!fm.failStakes);
  // a FIGHT's fail is a chooseable Yield (skill_battle already has the button)
  const fFight = frameExits("fight", {}, {});
  check("230: a FIGHT's fail is a chooseable Yield (all three fight exits are buttons)", fFight[2].action === "yield" && fFight[0].action === "strike" && fFight[1].action === "flee");
  // §Guard: an unframed (narrative) encounter yields no model
  check("230: an unframed encounter yields no frame model (null)", frameModel({ type: "narrative" }, {}, null) === null);

  // --- SNG-246 Fix D: the PLAYER-FACING receipt line (the mechanical truth SHOWN each round) ---
  {
    const fmt = JSON.parse(readFileSync(new URL("../content/packs/core/rules/encounter_receipt_line.json", import.meta.url), "utf8"));
    const fight = playerReceiptLine("fight", { degree: "success", actorEffect: "you hit for 2", meterFrom: 4, meterTo: 2, energyDelta: -3, healthDelta: 0, finishHint: "near_yield" }, fmt);
    check("246 D: a fight receipt shows degree + effect + foe hp before→after + finish-proximity", /✓ success/.test(fight) && /you hit for 2/.test(fight) && /foe 4→2 hp/.test(fight) && /near breaking/.test(fight));
    const hurt = playerReceiptLine("fight", { degree: "failure", actorEffect: "you miss", meterFrom: 4, meterTo: 4, energyDelta: -3, healthDelta: -2, finishHint: "you_hurt" }, fmt);
    check("246 D: a fight receipt shows health taken only when you took damage", /you −2 hp/.test(hurt) && /taking damage/.test(hurt));
    check("246 D: no health-taken segment when unharmed", !/hp · you −\d+ hp/.test(fight) && !/ · you −\d+ hp/.test(fight.replace(/foe \d+→\d+ hp/, "")));
    const puz = playerReceiptLine("puzzle", { degree: "success", actorEffect: "a piece falls into place", meterFrom: 1, meterTo: 2, finishHint: "progressing" }, fmt);
    check("246 D: a NON-fight kind reflects its OWN meter (puzzle = insight, not hp)", /🧩/.test(puz) && /insight 1→2/.test(puz) && !/hp/.test(puz));
    check("246 D: an unknown kind falls back to a generic legible line", /partial/.test(playerReceiptLine("mystery", { degree: "partial", meterFrom: 1, meterTo: 2, meterLabel: "z" }, fmt)));
    check("246 D: no degree → empty (nothing to show, never a broken line)", playerReceiptLine("fight", {}, fmt) === "" && playerReceiptLine("fight", { degree: null }, fmt) === "");
    check("246 D: the loaded format carries all 5 encounter kinds", ["fight", "chase", "standoff", "puzzle", "hazard"].every(k => fmt.byKind[k]?.line));
  }

  // Phase 1b (OQ1 = size by tier): weighty → takeover, small → banner
  check("230 P1b: frameSize routes by tier — regional/epic → takeover, riffraff/notable → banner",
    frameSize({ tier: "epic" }) === "takeover" && frameSize({ tier: "regional" }) === "takeover" &&
    frameSize({ tier: "riffraff" }) === "banner" && frameSize({ tier: "notable" }) === "banner");
  check("230 P1b: frameSize routes by danger when no tier — danger ≥ 3 → takeover, else banner",
    frameSize({ danger: 3 }) === "takeover" && frameSize({ danger: 4 }) === "takeover" && frameSize({ danger: 2 }) === "banner" && frameSize({ minDanger: 1 }) === "banner");
  check("230 P1b: with no size signal, a long (4-stage) challenge is a takeover; a short one a banner (safe default)",
    frameSize({ stages: [0, 0, 0, 0] }) === "takeover" && frameSize({ stages: [0, 0] }) === "banner" && frameSize({}) === "banner");

  // WIRED into play (not a dead/test-only export): app.js imports frameModel/frameSize, renders the header, and
  // routes takeover-vs-banner; the size signal is stamped onto the def at fire time.
  const appSrc230 = readFileSync(join(root, "app.js"), "utf8");
  check("230: frameModel + frameSize are WIRED into renderPlay (imported + header rendered + size-routed), not dead exports",
    /import \{ frameModel, frameSize.*\} from "\.\/engine\/encounterFrame\.js"/.test(appSrc230) && /const fm = frameModel\(d, e\.state/.test(appSrc230) && /class="enc-frame/.test(appSrc230));
  check("230 P1b: renderPlay routes takeover-vs-banner via frameSize; fireEncounter stamps the size signal (danger) on the def",
    /frameSize\(d, e\.state\) === "takeover"/.test(appSrc230) && /enc-frame-takeover/.test(appSrc230) && /offer\.def\.danger = dl/.test(appSrc230));

  // the frame is a LEGIBILITY LAYER, not a closed mini-game (Erik): the freefield + the GM stay the real
  // interaction — the model carries a cue and the render shows it, so the frame never reads as buttons-only.
  const fmCue = frameModel(chaseDef, { stageIndex: 1 }, null);
  check("230: every frame carries the freeform cue (the buttons are shortcuts; the GM resolves what you type against the stage)",
    typeof fmCue.freeform === "string" && fmCue.freeform === FRAME_FREEFORM_CUE && /describe your own move/i.test(fmCue.freeform));
  check("230: renderPlay renders the freeform cue in the frame (banner + takeover), keeping it a legibility layer",
    /class="enc-frame-cue"/.test(appSrc230) && /fm\.freeform/.test(appSrc230));

  // §6a: FRAMES CHAIN — the transition graph is the system. Fleeing a fight → a chase; failing that chase → a
  // fight (or fail). An exit with no transition just ends. Pure data + function (the flee→chase WIRING is next).
  check("230 §6a: frameTransition — fight+flee → chase, chase+fail → fight (the chaining graph)",
    frameTransition("fight", "flee") === "chase" && frameTransition("chase", "fail") === "fight");
  check("230 §6a: an exit with no chain just ends (hazard/flee, chase/flee → null)",
    frameTransition("hazard", "flee") === null && frameTransition("chase", "flee") === null && frameTransition("puzzle", "defeat") === null);
  // the chain is LEGIBLE in the frame — the exit names where it goes (play-wired via frameExits → frameModel)
  const fightExits = frameExits("fight", {}, {});
  check("230 §6a: a fight's FLEE exit is marked as chaining into a chase (chainTo + named in its meaning)",
    fightExits[1].role === "flee" && fightExits[1].chainTo === "chase" && /becomes The Chase/i.test(fightExits[1].means));
  const hazardExits = frameExits("hazard", { stages: [{}] }, {});
  check("230 §6a: an unchained exit is not annotated (hazard flee has no chainTo)", !hazardExits[1].chainTo && !/it becomes/i.test(hazardExits[1].means));

  // §6a BEHAVIOR: fleeing a fight becomes a real chase (chaseFromFight builds it), carrying _chainedFrom so a
  // caught chase drops back into the fight. Pure def-builder tested here; the app wiring is source-asserted.
  const fightDef230 = { id: "duel-raider", type: "duel", name: "A Road-Raider", opponent: { name: "the raider" }, danger: 3 };
  const chase230 = chaseFromFight(fightDef230);
  // SNG-247 Tier 2b: the chase is now an OPPOSED CONTEST (a duel whose flavor says ground is what's contested),
  // not a stage ladder — the same person who was swinging at you is running you down, with their own wind. What
  // this check has always protected is unchanged: it carries the PURSUER and the way back into the fight.
  check("230 §6a: chaseFromFight builds an opposed chase from the fight, carrying the pursuer + the fight to return to",
    chase230.type === "duel" && chase230.flavor === "chase" && chase230._chainedFrom?.kind === "fight" && chase230._chainedFrom.fightDefId === "duel-raider" && /raider/.test(chase230.name) && chase230.opponent?.name === "the raider" && chase230.danger === 3);
  check("230 §6a: the chase reads as a frame (kind chase, its own three exits) — the same frame machinery drives it",
    frameModel(chase230, { mode: "skill_battle", momentum: 0 }, null).kind === "chase" && encounterKind(chase230) === "chase");
  check("230 §6a WIRING: fleeing a fight starts a chase, and a caught chained chase re-enters the fight — GM-narrated",
    // SNG-247 Tier 2b: the gates read KIND, not `type` — a chase is a duel too now, so a bare type check would
    // have turned fleeing a CHASE into a chase-of-a-chase. And a chase is lost by being RUN DOWN, not only by
    // clicking away from it, so the drop-back fires from sbEnd as well.
    /beginChaseFromFight\(activeEnc\(\)\?\.def\)/.test(appSrc230) && /kindT === "fight" && choice\.encounterAction === "flee"/.test(appSrc230) && /kindT === "chase" && encT\.def\._chainedFrom\?\.kind === "fight"/.test(appSrc230) && /encounterKind\(def\) === "chase" && def\?\._chainedFrom\?\.kind === "fight"/.test(appSrc230) && /async function beginChaseFromFight/.test(appSrc230) && /async function beginFightFromChase/.test(appSrc230));
  check("230 §6a GUARD: the frame stays a legibility layer through the chain — the chase renders with the GM + freefield (no bespoke mini-loop)",
    /character\.activeEncounter = \{ defId: chase\.id, state: \{ \.\.\.startEncounter\(chase, \{ oppSheet: chaseSheet \}\)/.test(appSrc230) && /_morphedFrom: \{ kind: "fight"/.test(appSrc230) && /Do NOT resolve the chase — it plays out in its own frame/.test(appSrc230));

  // §6b/§7a: a SKILL can COLLAPSE (or morph) the frame — resolved along the degree bands, gated by collapsibility.
  check("230 §6b: frameCollapsible — riffraff/notable/regional + low danger can be one-beat-ended (regional only on a demolishing crit); an EPIC/danger-4 cannot",
    frameCollapsible({ tier: "riffraff" }) === true && frameCollapsible({ tier: "notable" }) === true && frameCollapsible({ tier: "regional" }) === true && frameCollapsible({ danger: 2 }) === true &&
    frameCollapsible({ tier: "epic" }) === false && frameCollapsible({ danger: 4 }) === false);
  check("230 §6c: collapseMode is FAMILY-driven — HARM finishes a fight/hazard, MOVE slips a chase, KNOW cracks a puzzle; wrong family → null",
    collapseMode(["HARM"], "fight") === "finish" && collapseMode(["MOVE"], "chase") === "escape" && collapseMode(["KNOW"], "puzzle") === "solve" &&
    collapseMode(["MOVE"], "fight") === null && collapseMode(["HARM"], "chase") === null && collapseMode([], "fight") === null);
  // Erik: EASIER vs weaker foes + MITIGATED below a finish — a tier-scaled floor, graded by degree.
  check("230 §7a: collapseFloor scales by foe — riffraff drops on 'success', notable/regional need a crit, an EPIC never collapses; Aevi's collapseEligibility layer wins when supplied",
    collapseFloor({ tier: "riffraff" }) === "success" && collapseFloor({ tier: "notable" }) === "crit_success" && collapseFloor({ tier: "regional" }) === "crit_success" && collapseFloor({ tier: "epic" }) === null && collapseFloor({ danger: 4 }) === null &&
    collapseFloor({ tier: "regional" }, { regional: { collapsible: false } }) === null && collapseFloor({ tier: "notable" }, { notable: { collapsible: true } }) === "crit_success");
  check("230 §7a: collapseResult COLLAPSES at/above the floor, MITIGATES below it (hard/partial), MORPHS on a whiff",
    collapseResult("success", { floor: "success" }) === "collapse" && collapseResult("success", { floor: "crit_success" }) === "hard" &&
    collapseResult("crit_success", { floor: null }) === "hard" && collapseResult("partial", { floor: "success" }) === "partial" &&
    collapseResult("failure", { floor: "success" }) === "morph" && collapseResult("crit_failure", { floor: "success" }) === "morph_bad");
  check("230 §7a: a riffraff collapses on a solid success; a notable does NOT (same roll) — easier vs weaker foes",
    collapseResult("success", { floor: collapseFloor({ tier: "riffraff" }) }) === "collapse" && collapseResult("success", { floor: collapseFloor({ tier: "notable" }) }) === "hard");
  check("230 §6b: swingDegree maps a skill-battle momentum swing to a degree (a big swing reads as a decisive blow)",
    swingDegree(7, 10) === "crit_success" && swingDegree(4, 10) === "success" && swingDegree(2, 10) === "partial" && swingDegree(0.5, 10) === "failure");
  check("230 §6b: frameModel surfaces collapsibility (the finisher gamble is on the table, legibly)",
    frameModel({ type: "duel", tier: "riffraff" }, {}, null).collapsible === true && frameModel({ type: "duel", tier: "epic" }, {}, null).collapsible === false);
  check("230 §6b WIRING: onChoice applies a finisher COLLAPSE on the non-skill-battle path (guard §89), reading family + degree + the foe's floor",
    /collapseMode\(familiesOfAbility\(fullCatalog\(\)\[choice\.abilityId\], FN_INDEX\), encounterKind\(enc\.def\)\)/.test(appSrc230) && /collapseResult\(resolution\.degree, \{ floor: collapseFloor\(enc\.def, frameContent\.collapseEligibility\) \}\)/.test(appSrc230) && /if \(res === "collapse"\)/.test(appSrc230) && /resolution\.collapse = \{ mode, result: "collapse"/.test(appSrc230));
  check("230 §6b WIRING: a decisive HARM finisher can END the SKILL-BATTLE early (Erik) — momentum swing → degree → floor, meter otherwise untouched",
    /collapseMode\(\[fam\], "fight"\) === "finish" && swing > 0 && collapseResult\(swingDegree\(swing, meterMax\), \{ floor: collapseFloor\(enc\.def, frameContent\.collapseEligibility\) \}\) === "collapse"/.test(appSrc230) && /outcome: "opponent_fell", state: \{ \.\.\.rr\.state, status: "ended" \}, _collapse: true/.test(appSrc230));
  check("230 §6b: the finisher gamble is surfaced in the frame (collapsible vs too-great)",
    /enc-frame-collapse/.test(appSrc230) && /A decisive finisher could end this in one beat/.test(appSrc230));

  // §7a MORPH: a botched finisher HARDENS the encounter — the GM narrates it (§89-safe: the mechanical failure
  // already bit via failureCost; no meter re-tune, no spawned fight).
  check("230 §7a: onChoice tags a whiffed finisher as a MORPH for the GM to narrate (not just a silent failure)",
    /res === "morph" \|\| res === "morph_bad"/.test(appSrc230) && /resolution\.collapse = \{ mode, result: res, craft \}/.test(appSrc230));
  const { encounterReceiptForGM: recFn } = await import("../engine/encounters.js");
  const rcCollapse = recFn({ type: "duel", round: 2, status: "ended" }, { name: "A Raider", opponent: { name: "the raider", health: 6 } }, { degree: "crit_success", collapse: { mode: "finish", result: "collapse", craft: "Cut the Thread" } }, { outcome: "opponent_fell", events: [] });
  const rcMorph = recFn({ type: "challenge", round: 2, status: "active", stagesDone: [], stageIndex: 0 }, { name: "Hard Ground", stages: [{ name: "cross" }] }, { degree: "failure", collapse: { mode: "finish", result: "morph_bad", craft: "Cut the Thread" } }, { events: [] });
  check("230 §7a: the receipt tells the GM to narrate the one-beat COLLAPSE (finisher landed) vs the botched finisher MORPH (it hardens, not over)",
    /FINISHER LANDED/.test(rcCollapse) && /Cut the Thread/.test(rcCollapse) && /FINISHER WHIFFED/.test(rcMorph) && /HARDENING/.test(rcMorph) && /NOT over/.test(rcMorph));
  check("230 §7a: no finisher note when there was no finisher (an ordinary round reads clean)",
    !/FINISHER/.test(recFn({ type: "duel", round: 1, status: "active" }, { name: "X", opponent: { name: "y", health: 5 } }, { degree: "success" }, { events: [] })));

  // §7b: a WARD FORBIDS a mechanic outright (a gate, not a modifier) — broken only by a demolishing roll.
  const wardedDef = { type: "duel", tier: "notable", wards: [{ denies: ["finish"], breakDC: 30, name: "the Death-Ward" }] };
  check("230 §7b: wardAgainst finds a ward that DENIES the mode (or a generic instant_end/collapse); no ward → not denied",
    wardAgainst(wardedDef, "finish").denied === true && wardAgainst(wardedDef, "finish").breakDC === 30 &&
    wardAgainst({ wards: [{ denies: ["instant_end"], breakDC: 5 }] }, "escape").denied === true && wardAgainst({ tier: "notable" }, "finish").denied === false);
  check("230 §7b: wardBroken only under a DEMOLISHING crit (margin ≥ breakDC); a plain success or a small-margin crit does not break it",
    wardBroken("crit_success", 40, 30) === true && wardBroken("crit_success", 20, 30) === false && wardBroken("success", 99, 30) === false);
  check("230 §7b: frameModel surfaces `warded` (a finisher can't end it unless shattered) — false absent a ward",
    frameModel(wardedDef, {}, null).warded === true && frameModel({ type: "duel", tier: "notable" }, {}, null).warded === false);
  const rcWarded = recFn({ type: "duel", round: 2, status: "active" }, { name: "The Kept", opponent: { name: "it", health: 8 } }, { degree: "crit_success", collapse: { mode: "finish", result: "warded", craft: "Cut the Thread", ward: "the Death-Ward" } }, { events: [] });
  check("230 §7b: the receipt tells the GM the ward FORBADE the instant-end (it could not apply — not merely resisted)",
    /FINISHER WARDED/.test(rcWarded) && /Death-Ward/.test(rcWarded) && /FORBADE the instant-end/.test(rcWarded));

  // §7c: the KIT VOIDS a challenge's PREMISE — trivial bypass (soft) or an opposed roll (hard, difficulty ≥ resistDC).
  const climb = { type: "challenge", flavor: "dangerous", trivializedBy: ["MOVE"] };
  const wardedClimb = { type: "challenge", flavor: "dangerous", trivializedBy: ["MOVE"], resistDC: 18, stages: [{ difficulty: 20 }] };
  check("230 §7c: trivializes — a MOVE/fly kit VOIDS a climb (trivial); a hard one (difficulty ≥ resistDC) is an opposed roll; a non-voiding kit → null",
    trivializes(climb, ["move"]) === "trivial" && trivializes(wardedClimb, ["move"]) === "opposed" && trivializes(climb, ["harm"]) === null && trivializes({ type: "challenge" }, ["move"]) === null);
  // integration: the ACTUAL Aevi layer — a ward ability id resolves through wardDenials; a premise type through challengePremises
  const frameContent230 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/encounter_frame_content.json"), "utf8"));
  check("230 §7b integration: a target tagged with Aevi's ward ability (the_kept_breath) DENIES a finish through the wardDenials layer",
    wardAgainst({ type: "duel", wards: ["the_kept_breath"] }, "finish", frameContent230.wardDenials).denied === true && wardAgainst({ type: "duel", wards: ["boundary_stone"] }, "finish", frameContent230.wardDenials).denied === false && wardAgainst({ type: "duel", wards: ["boundary_stone"] }, "escape", frameContent230.wardDenials).denied === true);
  check("230 §7c integration: a challenge naming Aevi's premise type (physical_ascent) is voided by a 'move' kit through challengePremises",
    trivializes({ type: "challenge", premise: "physical_ascent" }, ["move"], frameContent230.challengePremises) === "trivial" && trivializes({ type: "challenge", premise: "pattern_puzzle" }, ["reveal"], frameContent230.challengePremises) === "trivial" && trivializes({ type: "challenge", premise: "physical_ascent" }, ["harm"], frameContent230.challengePremises) === null);
  const rcTriv = recFn({ type: "challenge", round: 1, status: "ended", stagesDone: [], stageIndex: 0 }, { name: "The Wall", stages: [{ name: "climb" }] }, { degree: "trivial", trivialize: { craft: "Marrow's Wings", mode: "trivial", premise: "a sheer climb" } }, { outcome: "completed", events: [] });
  check("230 §7c: the receipt tells the GM the PREMISE was VOIDED — a narrated walk-around, do NOT grind the stages",
    /PREMISE VOIDED/.test(rcTriv) && /Marrow's Wings/.test(rcTriv) && /walk-around/.test(rcTriv) && /Do NOT grind the stages/.test(rcTriv));

  // WIRING (source-asserted): both are additive on the existing paths, and do nothing absent Aevi's content.
  check("230 §7b WIRING: the collapse path checks a denying ward FIRST — a held ward blocks the instant-end (onChoice + skill-battle)",
    /const ward = wardAgainst\(enc\.def, mode, frameContent\.wardDenials\)/.test(appSrc230) && /ward\.denied && !wardBroken\(resolution\.degree, margin, ward\.breakDC\)/.test(appSrc230) && /result: "warded"/.test(appSrc230) && /const ward = wardAgainst\(enc\.def, "finish", frameContent\.wardDenials\)/.test(appSrc230));
  check("230 §7c WIRING: onChoice trivializes a challenge when the kit voids its premise (trivial bypass or opposed roll)",
    /const triv = trivializes\(enc\.def, kitKeys, frameContent\.challengePremises\)/.test(appSrc230) && /triv === "trivial" \|\| \(triv === "opposed" && \["success", "crit_success"\]\.includes\(resolution\.degree\)\)/.test(appSrc230) && /resolution\.trivialize = \{ craft/.test(appSrc230));
}

// ---- SNG-168 §2: the world FEED — a scrapbook of shared turns, rating-lensed, NEVER canon ----
{
  const char168 = { id: "char-b", name: "Brooklyn", currentLocationId: "millbrook", playerKey: "player-b" };
  const turn168 = { narration: "Brooklyn braided light and shadow and the lane went quiet to watch.", momentArt: "data:img", scene: { setting: "The Low Lamp Inn" } };
  const post = buildFeedPost({ turn: turn168, character: char168, playerKey: "player-b", worldDay: 14, worldDateLabel: "World-day 14", rating: "PG-13", at: 1000 });
  check("168 §2: buildFeedPost carries the narration, image, character, place, world-date + the poster's RATING (the lens key)", post && /braided light/.test(post.narration) && post.image === "data:img" && post.characterName === "Brooklyn" && post.rating === "PG-13" && post.worldDay === 14 && !!post.id);
  check("168 §2: an empty turn yields no post (nothing to share)", buildFeedPost({ turn: { narration: "" }, character: char168, at: 2 }) === null);
  // Erik feedback: the words must NOT be cut off (a whole turn's narration fits), and an explicit image wins.
  const longNarr = "He finds the design Pell has in him. ".repeat(60); // ~2200 chars — was truncated at 1200
  check("168 §2 (fix): a whole turn's narration is NOT cut off (a long post carries in full)", buildFeedPost({ turn: { narration: longNarr }, character: char168, at: 3 }).narration.length > 2000);
  check("168 §2 (fix): the caller's chosen image wins (gallery fallback when turn.momentArt is missing)", buildFeedPost({ turn: { narration: "x", momentArt: null }, character: char168, image: "data:gallery", at: 4 }).image === "data:gallery");

  // appendFeedPost: merge-safe append, idempotent, capped (the pushMergedFile callback body).
  let store = appendFeedPost(null, post);
  store = appendFeedPost(store, post); // same turn again → no double-post
  check("168 §2: append is idempotent — re-posting the same turn is a no-op (one turn, one post)", store.posts.length === 1);
  check("168 §2: append is merge-safe against a fresh remote (concurrent writers never clobber)", appendFeedPost({ schemaVersion: 1, posts: [{ id: "other" }] }, post).posts.length === 2);

  // feedForViewer: reverse-chron + the RATING LENS (the same lens shared canon uses) applied on READ.
  const rPost = buildFeedPost({ turn: { narration: "a graphic scene", momentArt: "data:x" }, character: char168, rating: "R", at: 2000 });
  store = appendFeedPost(store, rPost);
  const adult = feedForViewer(store, { rating: { preset: "R" } });
  check("168 §2: an adult (R ceiling) sees every post in full, newest first (reverse-chron)", adult.length === 2 && adult[0].rating === "R" && adult.every(p => !p.lensed));
  const lowView = feedForViewer(store, { rating: { preset: "PG" } });
  const rSeen = lowView.find(p => p.rating === "R");
  check("168 §2: a post ABOVE the viewer's ceiling is LENSED — softened, image withheld (never leaks unfiltered)", (!rSeen) || (rSeen.lensed === true && rSeen.image === null && !/graphic scene/.test(rSeen.narration)));

  check("168 §2 GUARD: a feed post is NOT canon — the feed is its own file (FEED_PATH), never hydrated into CONTENT", FEED_PATH === "world/feed.json");
  // app wiring: the post control on a turn, the feed view, the merge-safe push, the read lens — and the guard.
  const appSrc168 = readFileSync(join(root, "app.js"), "utf8");
  check("168 §2: a per-turn POST control (sync-gated) + a Feed nav both wire to the feed", /id="post-to-feed"/.test(appSrc168) && /id="open-feed"/.test(appSrc168) && /postTurnToFeed\(turn\)/.test(appSrc168));
  check("168 §2: posting appends via pushMergedFile (merge-safe) to FEED_PATH, never CONTENT", /pushMergedFile\(FEED_PATH, \(remote\) => appendFeedPost\(remote, post\)/.test(appSrc168));
  check("168 §2: the feed VIEW pulls the shared file + lenses it on read (feedForViewer(store, profile))", /function renderFeed\(\)/.test(appSrc168) && /feedForViewer\(store \|\| \{\}, profile\)/.test(appSrc168) && /fetchRepoJSON\(FEED_PATH\)/.test(appSrc168));
}

// ---------- CCODE-55 / SNG-250 §4: the universal born-whole gate ----------
// The SNG-232 / SNG-238 §5c discipline: a gate never shown to go RED proves nothing. Every check below
// runs against the REAL contract file the engine ships, not a fixture — so a map edit that guts a rule
// turns these red rather than quietly disarming the gate in production.
{
  const { checkBorn, hasValue, contractedTypes, describeBorn, appliesTo } = await import("../engine/borncontract.js");
  const contract = JSON.parse(readFileSync(join(root, "content/packs/core/rules/consumer_required_subfields.json"), "utf8"));
  const VERBS = Object.values(JSON.parse(readFileSync(join(root, "content/packs/core/rules/function_vocabulary.json"), "utf8")).families || {})
    .flatMap(l => (Array.isArray(l) ? l : []).map(v => (typeof v === "string" ? v : v?.verb))).filter(Boolean);
  const vocabs = { "function_vocabulary.verbs": VERBS };
  const born = (e, t) => checkBorn(e, t, contract, { vocabs });

  // ---------- CCODE-87: the born-whole gate understands CONDITIONAL fields ----------
  // Erik: apply the Memory-spear lesson to generated items. A weapon owes a `damageType` - without one it
  // resolves as physical and cannot touch a thing that answers kinds. But a WHETSTONE owes nothing of the sort,
  // and a gate that flags a whetstone for missing a weapon field is crying wolf, which teaches people to ignore
  // it (the SNG-250 lesson). So a contract field may carry `appliesTo`, and the grammar is deliberately tiny:
  // a contract file is CONTENT, and content must never run code inside a gate every mint passes through.
  {
  const w = k => ({ id: "x", name: "n", kind: k, description: "d", consumable: false, bonusTags: ["strike"] });
  check("CCODE-87: a WEAPON with no damageType is now flagged - the Silas spear defect, caught at birth",
    born(w("weapon"), "item").missing.some(m => m.field === "damageType"));
  check("CCODE-87: the same weapon declaring physical is clean - plain steel IS an answer, silence is not",
    born({ ...w("weapon"), damageType: "physical" }, "item").verdict === "clean");
  check("CCODE-87: a TOOL is not asked for one (no crying wolf on a whetstone)",
    !born({ id: "x", name: "River Whetstone", kind: "tool", description: "d", consumable: false, bonusTags: ["hone"] }, "item")
      .missing.some(m => m.field === "damageType"));
  check("CCODE-87: an UNPARSEABLE appliesTo applies to nothing - a typo silences one field, never condemns a type",
    appliesTo("kind =? weapon", { kind: "weapon" }) === false && appliesTo("", {}) === false);
  check("CCODE-87: the grammar handles alternatives and negation",
    appliesTo("kind == weapon|armor", { kind: "armor" }) && appliesTo("kind != weapon", { kind: "tool" }))

  // ONE mechanism, every type (SNG-250 §5) — keyed by the map, with no per-type branch.
  check("SNG-250 §4: the gate is keyed by the MAP — every contracted type is gated by the same function",
    contractedTypes(contract).every(t => born({}, t).gated),
    "a declared type came back ungated — the gate is not actually map-driven");
  check("SNG-250 §4: an UNCONTRACTED type is reported ungated, never silently 'clean'",
    born({ id: "x" }, "nonesuch").gated === false);
  check("SNG-250 §5: a type added to the MAP ALONE is gated with no new gate code (the durable win)",
    (() => { const grown = { contentTypes: { ...contract.contentTypes, widget: { topLevel: [{ field: "sprocket", severity: "CRASH" }] } } };
      return checkBorn({ id: "w" }, "widget", grown, {}).verdict === "reject"; })(),
    "a newly declared type was not gated — adding a type would need engine changes, which §5 forbids");
  check("SNG-250: `ability` resolves to the `skill` contract (one contract, both names)",
    born({}, "ability").gated === true);

  // WHOLE — the topLevel half.
  check("SNG-250 §3 WHOLE: a creature with no id REJECTS (CRASH — random_encounters.js:59 filters it out of existence)",
    born({ name: "a shape" }, "creature").verdict === "reject");
  check("SNG-250 §3 WHOLE: a fully-authored creature passes clean (no false-flag on real content)",
    born({ id: "warpling_hare", name: "warpling hare", tier: "riffraff", class: "beast", pressures: ["HARM"], look: "a hare briefly two hares", danger: "it bites" }, "creature").verdict === "clean");
  check("SNG-250 §3: `false` and `0` count as PRESENT — a real value a consumer reads is not a hole",
    hasValue(false) && hasValue(0) && !hasValue("") && !hasValue([]) && !hasValue(null));

  // CONCRETE — the half presence-checking can never catch. This is the §3 thesis.
  const hollowSkill = { id: "deep_essence", name: "Deep Essence", functions: ["channel"], energyCost: 8, levelReq: 3, description: "It channels the essence of the deep.", notFor: "Anything else." };
  const hollow = born(hollowSkill, "skill");
  check("SNG-250 §3 CONCRETE: a skill with EVERY field present but an off-vocab verb is still flagged — the §3 thesis",
    hollow.missing.length === 0 && hollow.vague.some(v => v.id === "function-in-vocab"),
    "'channels the essence of the deep' passed the gate — wholeness alone cannot catch hollowness");
  check("SNG-250 §3 CONCRETE: an empty `functions` array is flagged (familiesOfAbility would engage nothing)",
    born({ ...hollowSkill, functions: [] }, "skill").vague.some(v => v.id === "function-in-vocab"));
  check("SNG-250 §3 CONCRETE: a real in-vocab verb passes clean",
    born({ ...hollowSkill, functions: ["strike"] }, "skill").verdict === "clean");
  check("SNG-250 §3 CONCRETE: an off-vocab creature tier is flagged (BEAST_TIER silently resolves it to `notable`)",
    born({ id: "c", name: "c", tier: "legendary", class: "b", pressures: ["HARM"], look: "l", danger: "d" }, "creature").vague.some(v => v.id === "tier-in-vocab"));
  check("SNG-250 §3 CONCRETE: an item with NEITHER hook (no bonusTags, no numeric effects) is flagged inert",
    born({ id: "i", name: "Old Trinket", kind: "misc", description: "It hums with old power.", consumable: false }, "item").vague.some(v => v.id === "effect-resolvable"));
  check("SNG-250 §3 CONCRETE: EITHER hook alone satisfies the item bar (gear via bonusTags, consumable via effects)",
    born({ id: "i", name: "Axe", kind: "weapon", description: "d", consumable: false, bonusTags: ["strike"], damageType: "physical" }, "item").verdict === "clean" &&
    born({ id: "j", name: "Tea", kind: "consumable", description: "d", consumable: true, effects: { energy: 10 } }, "item").verdict === "clean");
  check("SNG-250 §3 CONCRETE: a consumable whose effects are all ZERO is flagged — consumeItem destroys the stack for nothing",
    born({ id: "k", name: "Tea", kind: "consumable", description: "d", consumable: true, effects: { energy: 0 } }, "item").vague.some(v => v.id === "consumable-spends-to-something"));

  // The severity fold. A DEGRADED-only report MUST read as "thin" — it once read as "clean" (the
  // no-findings seed fell through rankOf to DEGRADED, so a DEGRADED finding was never worse than it),
  // and the live item path branches on `verdict !== "clean"`, so thin items were waved through in
  // exactly the case the gate exists for. The CI sweep hid it by reading missing/vague directly.
  check("SNG-250 §4: a DEGRADED-only report is THIN, not clean (the severity fold must rank 'no findings' lowest)",
    born({ id: "i", name: "Trinket", kind: "misc", description: "It hums.", consumable: false }, "item").verdict === "thin");
  check("SNG-250 §4: a clean record still reports clean, and worst is null",
    (() => { const r = born({ id: "i", name: "Axe", kind: "weapon", description: "d", consumable: false, bonusTags: ["strike"], damageType: "physical" }, "item"); return r.verdict === "clean" && r.worst === null; })());

  // Two authors, two shapes. The `concrete` block is an ARRAY of rule objects for creature/item/skill
  // and a field->rule MAP for arc; the gate normalizes both so neither author has to change style.
  check("SNG-250 §4: a `concrete` block authored as an OBJECT MAP is honoured, not ignored or fatal",
    (() => { const c2 = { contentTypes: { thing: { topLevel: [{ field: "id", severity: "CRASH" }], concrete: { tag: "nonEmptyArray", label: "nonEmptyString" } } } };
      const r = checkBorn({ id: "t", tag: [], label: "" }, "thing", c2, {});
      return r.vague.some(v => v.field === "tag") && r.vague.some(v => v.field === "label"); })(),
    "the object form was silently skipped — arc's rules would gate nothing while appearing to");
  check("SNG-250 §4: the real arc contract gates (arc was the one live generator with no contract)",
    born({ id: "a", name: "A" }, "arc").gated && contractedTypes(contract).includes("arc"));

  // Aevi's SEMANTIC layer (vagueMarkers) — the half no machine rule can decide.
  check("SNG-250 §3 SEMANTIC: a bare abstraction is flagged — 'wants respect' is not an actable want",
    born({ id: "x", name: "X", personality: {}, wants: ["respect"], fears: ["the unknown"], disposition: "d", appearance: "a" }, "npc")
      .vague.map(v => v.id).includes("vague-wants"));
  check("SNG-250 §3 SEMANTIC: a want with a concrete anchor passes — the marker must not fire on real content",
    born({ id: "y", name: "Y", personality: {}, wants: ["the forge her brother left, which Silas holds"], fears: ["being undone by the grain of this place"], disposition: "d", appearance: "a" }, "npc")
      .vague.length === 0);
  check("SNG-250 §3 SEMANTIC: it fires on IS-the-abstraction, never on merely CONTAINS one",
    born({ id: "z", name: "Z", personality: {}, wants: ["the respect of the guild that cast her out"], fears: ["f"], disposition: "d", appearance: "a" }, "npc")
      .vague.length === 0,
    "a value that merely contains a marker was flagged — this rule cannot be checked mechanically, so a false alarm is uncorrectable noise");

  // SNG-250 §7a (Erik): TIER THE GATE BY TYPE — "yes, but light". One more field read by the same logic.
  check("SNG-250 §7a: a HARD type escalates an EMPTY to REJECT — an un-fightable monster is worse than no monster",
    born({ id: "c", tier: "riffraff", class: "b", look: "l", danger: "d", pressures: ["HARM"] }, "creature").verdict === "reject",
    "a name-less creature (EMPTY) was kept — hard-tier hollowness breaks play and must not ship");
  check("SNG-250 §7a: a SOFT type keeps an EMPTY as THIN — a slightly thin item still reaches the player's hands",
    born({ id: "i", name: "Axe", kind: "weapon", consumable: false, bonusTags: ["strike"], description: "" }, "item").verdict === "thin");
  check("SNG-250 §7a: the tier comes from the CONTRACT, and an unset gateTier defaults to SOFT (never silently starts rejecting)",
    born({}, "creature").tier === "hard" && born({}, "item").tier === "soft" &&
    checkBorn({ id: "x" }, "thing", { contentTypes: { thing: { topLevel: [{ field: "n", severity: "EMPTY" }] } } }, {}).verdict === "thin");
  check("SNG-250 §7a: CRASH still rejects and DEGRADED still warns in BOTH tiers — the tier only moves EMPTY",
    born({ name: "x" }, "creature").verdict === "reject" &&
    born({ id: "i", name: "Trinket", kind: "misc", description: "hums", consumable: false }, "item").verdict === "thin");
  check("SNG-250 §7a: every contracted type declares a gateTier (an unset one silently plays soft)",
    contractedTypes(contract).every(t => ["hard", "soft"].includes(String(contract.contentTypes[t].gateTier || "").toLowerCase())),
    `no gateTier on: ${contractedTypes(contract).filter(t => !contract.contentTypes[t].gateTier).join(", ")}`);

  // Robustness: the gate sits inside a turn that must never die (generate.js's standing invariant).
  check("SNG-250 §4: the gate NEVER throws — null/garbage entity, absent contract, garbled rule all degrade quietly",
    (() => { try {
      checkBorn(null, "skill", contract, { vocabs }); checkBorn("nope", "item", contract, {}); checkBorn({}, "item", null, {});
      const bad = { contentTypes: { item: { topLevel: [{ field: "id", severity: "WAT" }], concrete: [{ id: "x", rule: "no_such_rule", field: "id" }] } } };
      return checkBorn({ id: "i" }, "item", bad, {}).verdict === "clean";  // unknown severity warns, unknown rule inert — never fatal
    } catch { return false; } })(),
    "a malformed contract or entity took the gate down — generation must never halt a turn");

  // The wiring: one function, both halves (SNG-250 §4 "authored and generated held to the same bar").
  const genSrc250 = readFileSync(join(root, "engine/generate.js"), "utf8");
  const ciSrc250 = readFileSync(join(root, "tests/content_ci.mjs"), "utf8");
  const appSrc250 = readFileSync(join(root, "app.js"), "utf8");
  check("SNG-250 §4: BOTH halves call the SAME gate — generate.js and content_ci both import checkBorn",
    /from "\.\/borncontract\.js"/.test(genSrc250) && /from "\.\.\/engine\/borncontract\.js"/.test(ciSrc250),
    "two implementations of one contract WILL drift (the CCODE-16 lesson)");
  check("SNG-250 §4: generate() REJECTS a CRASH-verdict record (never ships a hollow anything)",
    /born\.verdict === "reject"/.test(genSrc250));
  check("SNG-250 §4: a thin-but-kept record is STAMPED on _gen.contract so it stays findable for enrichment",
    /_gen\.contract = \{/.test(genSrc250));
  // Comment lines are stripped first — a prose mention of generate("arc", …) is not a call site, and
  // counting one would make this assertion fail for a documentation edit (or, worse, be "fixed" by
  // loosening it until it stopped biting).
  // A generate() call spans several lines (the deps object sits below the opening), so each site is
  // checked over a forward WINDOW rather than one line.
  const code250 = appSrc250.split("\n").filter(l => { const t = l.trim(); return !t.startsWith("//") && !t.startsWith("*"); });
  const ungated250 = [];
  code250.forEach((l, i) => {
    if (!/\bgenerate\(\s*["'a-z]/.test(l)) return;
    if (!code250.slice(i, i + 8).some(w => /\.\.\.genContractDeps\(\)/.test(w))) ungated250.push(l.trim().slice(0, 70));
  });
  check("SNG-250 §4: EVERY app generate() call site passes the contract (an ungated site mints ungated records)",
    code250.some(l => /\bgenerate\(\s*["'a-z]/.test(l)) && ungated250.length === 0,
    `these generate() call sites never pass ...genContractDeps() — they would mint UNGATED records while CI stays green: ${ungated250.join(" | ")}`);
  // CCODE-55: the two paths that actually MINT item/skill in play are gated. Neither goes through
  // generate() — items enter via characterDeltas.inventoryAdd -> addItem, abilities via newAbility ->
  // sanitizeNewAbility — so gating HERE gates the real producers rather than building second ones.
  const progSrc250 = readFileSync(join(root, "engine/progression.js"), "utf8");
  const gmSrc250 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("SNG-250 §3 BUGFIX: sanitizeNewAbility now MINTS `functions` — a GM ability is no longer born with zero families",
    /functions,/.test(progSrc250) && /verbVocab = null/.test(progSrc250),
    "every GM-generated ability would resolve to no family through familiesOfAbility — decorative by construction");
  check("SNG-250 §3: sanitizeNewAbility DROPS verbs the vocab cannot resolve (keeping them looks whole and resolves to nothing)",
    (() => { const p = sanitizeNewAbility({ name: "X", description: "d", functions: ["strike", "channel"] }, { verbVocab: ["strike", "ward"] });
      return p.functions.length === 1 && p.functions[0] === "strike"; })());
  check("SNG-250 §3: with no vocab injected, verbs pass through — never fail closed on a missing input",
    sanitizeNewAbility({ name: "X", description: "d", functions: ["strike"] }).functions.length === 1);
  check("SNG-250 §3: the GM op contract ASKS for functions from the closed verb vocab (seam_op_vocab_triples)",
    /"newAbility":[^\n]*"functions"/.test(gmSrc250) && /strike break hinder heal/.test(gmSrc250),
    "the engine reads a field the prompt never requests — the op triple is broken and functions arrive empty forever");
  check("SNG-250 §3: BOTH sanitizeNewAbility call sites inject the verb vocab (newAbility AND companion bondGrants)",
    (appSrc250.match(/sanitizeNewAbility\([^)]*verbVocab/g) || []).length === (appSrc250.match(/sanitizeNewAbility\(/g) || []).length);
  check("SNG-250 §3: a GM-invented ITEM is gated on the path that actually mints it (inventoryAdd -> addItem)",
    /checkBorn\(added, "item"/.test(appSrc250) && /consumable-spends-to-something/.test(appSrc250),
    "items do not go through generate(); ungated here means ungated everywhere");
  check("SNG-250 §3: a thin item is KEPT, never rejected — the fiction handed it over and §3 rates it DEGRADED",
    !/verdict === "reject"[^\n]*item/.test(appSrc250) && /added\._contract = \{/.test(appSrc250));

  // CCODE-55: CREATURE generation, and the seam that makes it mean anything. §3's bar for this type is the
  // strictest in the spec — "a whole monster is FIGHTABLE" — so minting one is only half the work.
  {
    const re = await import("../engine/random_encounters.js");
    const gen = await import("../engine/generate.js");
    check("SNG-250 §4: creature is a GEN_TYPE and its store is ensured on the character",
      gen.GEN_TYPES.includes("creature") && !!gen.ensureGenerated({}).generated.creature);
    check("SNG-250 §4: a derived creature schema exists (registering it is what OPENS the type)",
      existsSync(join(root, "schemas/creature.schema.json")) &&
      /if \(genCreature\) genSchemas\.creature = genCreature/.test(readFileSync(join(root, "engine/state.js"), "utf8")));
    // The stub is the fallback path; if IT is hollow the contract is reintroduced-by-the-back-door.
    const stub = gen.stubEntity("creature", { location: { name: "the Wend" } }, {});
    check("SNG-250 §3: even the STUBBED creature is born whole AND concrete (the fallback cannot smuggle a hollow monster back in)",
      born(stub, "creature").verdict === "clean", describeBorn(born(stub, "creature")));
    check("SNG-250 §3: the stub tiers as `riffraff`, not `notable` — BEAST_TIER's silent fallback IS notable, so a stub tiered notable is indistinguishable from a tier-less one",
      stub.tier === "riffraff");
    // THE SEAM. A generated creature must reach the pool, or it is minted and no fight can ever run.
    const charC = { generated: { creature: { "gen-thing": { id: "gen-thing", name: "the thing", tier: "notable", class: "beast", look: "l", danger: "d", pressures: ["HARM"] } } } };
    const grown = re.generatedCreatureEncounters(charC);
    check("SNG-250 §4 SEAM: a GENERATED creature becomes a real encounter entry (else it is minted un-fightable — the SNG-229 seam_bestiary_loaded failure, restated for generation)",
      grown.length === 1 && grown[0].routing === "duel" && grown[0].creatureId === "gen-thing" && grown[0].fromGenerated === true);
    check("SNG-250 §4 SEAM: a grown monster gets its threat/weight/minDanger from BEAST_TIER exactly as an authored one does (one difficulty curve, not two)",
      (() => { const authored = re.bestiaryEncounters({ roster: [{ id: "thing", name: "the thing", tier: "notable", class: "beast", look: "l", danger: "d", pressures: ["HARM"] }] })[0];
        return grown[0].opponent.threat === authored.opponent.threat && grown[0].minDanger === authored.minDanger && grown[0].weight === authored.weight; })());
    check("SNG-250 §4 SEAM: a generated id can never collide with an authored one in the pool",
      grown[0].id === "gen_beast_gen-thing" && grown[0].id !== re.bestiaryEncounters({ roster: [{ id: "gen-thing", name: "x", tier: "notable" }] })[0].id);
    check("SNG-250 §4 SEAM: no character / no generated creatures is a clean no-op (never throws into a turn)",
      re.generatedCreatureEncounters(null).length === 0 && re.generatedCreatureEncounters({}).length === 0);
    // SNG-250 §7b (Erik): SHARED-ON-SIGHT, overriding the per-character build.
    const canonMod = await import("../engine/canon.js");
    check("SNG-250 §7b: a creature promotes to shared canon ON SIGHT — no tier climb, no weight floor",
      canonMod.promotionCandidates({ generated: { creature: { a: { id: "a", name: "A", _gen: { type: "creature", tier: "fresh", engagementScore: 0, birthWeight: 1 } } } } }).length === 1,
      "a fresh creature was not a candidate — the valley's monsters stay private until someone meets one repeatedly");
    check("SNG-250 §7b: an NPC still CLIMBS (attention builds realness — the BATCH-9 §2 model is untouched)",
      canonMod.promotionCandidates({ generated: { npc: { n: { id: "n", name: "N", _gen: { type: "npc", tier: "fresh", engagementScore: 0, birthWeight: 1 } } } } }).length === 0);
    check("SNG-250 §7b: share-on-sight stays IDEMPOTENT — an already-promoted creature is not a candidate again",
      canonMod.promotionCandidates({ generated: { creature: { a: { id: "a", name: "A", _gen: { type: "creature", promotedWorldDay: 3 } } } } }).length === 0);
    check("SNG-250 §7b: shared creatures reach the pool through the SAME merge point, deduped against your own",
      /sharedCreaturePool\.length \? generatedCreatureEncounters\(/.test(appSrc250) && /theirs\.filter\(e => !seen\.has\(e\.id\)\)/.test(appSrc250),
      "your own creature returning through canon would appear twice in the pool");
    check("SNG-250 §7b: the LIVE-SCENE GUARD — the shared set is snapshotted only when no encounter is active",
      /if \(!activeEnc\(\)\) sharedCreaturePool = creatures;/.test(appSrc250),
      "the pool could change underneath a fight the player is already in");
    check("SNG-250 §4 SEAM: EVERY app read of the encounter pool goes through the ONE merge point",
      !/CONTENT\.randomEncounters\?\.encounters/.test(appSrc250) &&
      !/eligibleEncountersFor\(CONTENT\.randomEncounters/.test(appSrc250) &&
      /function encounterTable\(\)/.test(appSrc250) && /generatedCreatureEncounters\(character\)/.test(appSrc250),
      "a raw CONTENT.randomEncounters read is back — it silently excludes every grown monster, and nothing errors");
  }

  check("SNG-250 §5: the generatable set is DERIVED from genSchemas, not a hardcoded type literal",
    /GENERATABLE_TYPES = new Set\(Object\.keys\(CONTENT\.genSchemas \|\| \{\}\)\)/.test(appSrc250) &&
    /GENERATABLE_TYPES\.has\(type\)/.test(appSrc250) &&
    !/\["npc", "location", "arc"\]\.includes\(type\)/.test(appSrc250),
    "the allow-list is a literal again — a newly schema'd type would be silently vetoed and 'generation is open for X' would ship as a no-op");
  check("SNG-250 §4: boot NAMES any type whose two halves disagree (generatable-but-uncontracted / contracted-but-not-generatable)",
    /GENERATES BUT UNCONTRACTED/.test(appSrc250) && /function reportContractCoverage\(\)/.test(appSrc250));
  check("CCODE-55: the app feeds the gate the SAME verb index familiesOfAbility resolves against (no drifting copy)",
    /"function_vocabulary\.verbs": Object\.values\(FN_INDEX\?\.byFamily \|\| \{\}\)\.flat\(\)/.test(appSrc250));
  // The generation-only clamp the skill contract deliberately does NOT encode (authored costs run 1..14).
  check("CCODE-55: the 4..15 energyCost band stays a GENERATION clamp in sanitizeNewAbility, not a contract rule",
    /Math\.max\(4, Math\.min\(15, Number\(raw\.energyCost\) \|\| 8\)\)/.test(readFileSync(join(root, "engine/progression.js"), "utf8")) &&
    !JSON.stringify(contract).includes('"min": 4'),
    "the band leaked into the contract — it would flag 111 of 285 legitimately cheap authored abilities");
}

// ---------- SNG-252: the unified encounter ribbon + Moves worked back in ----------
{
  const appSrc252 = readFileSync(join(root, "app.js"), "utf8");
  const cssSrc252 = readFileSync(join(root, "style.css"), "utf8");
  const hints252 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/encounter_move_hints.json"), "utf8"));
  const copy252 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/encounter_ribbon_copy.json"), "utf8"));
  const coreMani252 = JSON.parse(readFileSync(join(root, "content/packs/core/manifest.json"), "utf8"));

  // §2a — the PREMISE CHECK. The spec diagnosed hazard's hue as "missing or incomplete in style.css". It is
  // neither: the hue is defined and .enc-frame reads it. Asserting that keeps the no-op from being "fixed"
  // later by someone re-reading the spec and adding a duplicate rule.
  check("SNG-252 §2a: hazard's stone hue EXISTS and the frame border reads it (the specced CSS gap is a no-op)",
    /\.enc-frame-hazard\s*{\s*--enc-hue:\s*#6f7b8c/.test(cssSrc252) &&
    /\.enc-frame\s*{[^}]*border:\s*1px solid var\(--enc-hue/.test(cssSrc252),
    "hazard's hue really is missing — then §2a is a real fix after all, not the no-op the build recorded");
  check("SNG-252 §2a: hazard resolves to a real frame kind, so it flies enc-frame-hazard like every other kind",
    (() => { const m = FRAME_KINDS && Object.keys(FRAME_KINDS); return !!(m && m.includes("hazard")); })());

  // §2b — ONE container. This is the actual fix for what Erik saw.
  check("SNG-252 §2b: BOTH sibling appends are gone — nothing about an engaged encounter renders outside the ribbon",
    !/main \+= encounterMovesPanel\(\)/.test(appSrc252) && !/main \+= skillBattlePanel\(\)/.test(appSrc252) &&
    /const movesHtml = \(st\.mode === "skill_battle"\) \? skillBattlePanel\(\) : \(movesShown \? encounterMovesPanel\(fm\) : ""\)/.test(appSrc252),
    "a panel is appended as a sibling again — the encounter reads as fragments, which is the whole bug. The skill-battle panel matters most: it IS the action set for fight/chase/standoff, the kinds the player meets most.");
  check("SNG-252 §2b: the ⚙ never hides a SKILL BATTLE's controls — collapse-for-space must not read as remove-the-controls",
    /const movesToggle = \(st\.mode === "skill_battle"\) \? ""/.test(appSrc252) &&
    !/\(st\.mode === "skill_battle"\)\s*\?\s*\(movesShown \? skillBattlePanel/.test(appSrc252),
    "collapsing the moves would leave the player in a fight with no visible way to act");
  // SNG-252b §2c superseded 252's flat order: the SCENE now leads and the exits go last and quietest.
  // header → subtitle → SCENE → where-you-stand → meter/receipt → moves+freeform → ways out.
  check("SNG-252b §2c: the ribbon orders by IMPORTANCE — the scene leads, the exits go last",
    /\$\{subtitleHtml\}/.test(appSrc252) && /enc-frame-scene/.test(appSrc252) && /enc-frame-stand/.test(appSrc252) &&
    /\$\{meterHtml\}\$\{receiptHtml\}\$\{cueHtml\}\$\{exitsHtml\}<\/div>/.test(appSrc252),
    "the ribbon is back to one flat weight — which is what left Erik lost in it");
  check("SNG-252b §2b: the SCENE renders inside the ribbon, and exactly once (never in both places)",
    /beatPlacedInRibbon = true; return `<div class="enc-frame-scene">/.test(appSrc252) &&
    /if \(!beatPlacedInRibbon\) main \+= beatHtml;/.test(appSrc252));
  check("SNG-252 §2b: the receipt PERSISTS on encounter state, so it stays visible instead of scrolling away",
    /rr\.state\._lastReceipt = resolution\.encReceiptLine/.test(appSrc252) && /st\._lastReceipt \? /.test(appSrc252));
  check("SNG-252 §2b: the floating receipt only renders once the encounter has ENDED (never inside AND outside the box)",
    /if \(r\.encReceiptLine && !activeEnc\(\)\)/.test(appSrc252),
    "the same readout renders in both places — 'fold it IN, not floating' means one of them has to go");
  check("SNG-252 §2b: the nested panels drop their own borders — a box inside a box is the fragmentation being removed",
    /\.enc-frame \.moves-panel,\s*\n\.enc-frame \.sb-panel\s*{\s*border: none/.test(cssSrc252),
    "a nested panel still draws its own frame, so the ribbon reads as two boxes instead of one");

  // §2c — moves shown by default, kind-aware, consequence-hinted, ward-aware.
  // REVERSED by SNG-252b §2a. 252 opened the moves by default — Erik's earlier ask — and seeing it built he
  // reversed it: ~5 full-width cards ate the screen before he had chosen to look. Collapsed is the default now,
  // and the affordance SUMMARISES what is behind it so folding it away costs no information.
  check("SNG-252b §2a: moves are COLLAPSED by default, behind an affordance that says what is in there",
    /let movesOpen = false;/.test(appSrc252) && /const movesShown = movesOpen;/.test(appSrc252) &&
    /function movesSummaryLine\(/.test(appSrc252) && /movesSummaryLine\(copy252\)/.test(appSrc252));
  check("SNG-252b §2a: the collapsed summary TALLIES by family in plain words ('4 reads, 1 strike'), never a bare '⚙ Moves'",
    /FAMILY_PLAIN_WORD/.test(appSrc252) && /\{summary\}/.test(JSON.stringify(copy252.collapsedMoves || {})),
    "a bare label would make the player open it just to find out what they have");
  check("SNG-252b §2d: a family blurb shared by every move in the group is hoisted to the GROUP header, once",
    /const famDoes = \[\.\.\.new Set\(/.test(appSrc252) && /const sharedDoes = famDoes\.length === 1/.test(appSrc252) &&
    /const does = sharedDoes \? "" :/.test(appSrc252),
    "five REVEAL moves each repeating 'reads THEM — sharpens the fog' buries the per-move line under identical ones");
  check("SNG-252b §2c: intensity + the action chain are TUCKED behind a turn-detail toggle that remembers its state",
    /<details class="sb-detail"\$\{sbDetailOpen \? " open" : ""\}/.test(appSrc252) &&
    /sbDetailOpen = d\.open/.test(appSrc252) &&
    (appSrc252.match(/\$\{sbStepTracker\(turn\)\}/g) || []).length === 1,   // CALL sites, not the definition
    "the step tracker renders twice, or the tuck forgets its state every round");
  check("SNG-252 §2c: picking a move no longer COLLAPSES the ribbon you are still standing in",
    !/movesOpen = false;\s*\n\s*onFreeform\(/.test(appSrc252));
  check("SNG-252 §2c: the family groups are ordered by the KIND's emphasis, with un-emphasised families kept (never dropped)",
    /const emphasis = Array\.isArray\(kindHints\.emphasis\)/.test(appSrc252) &&
    /FUNCTION_FAMILIES\.filter\(f => byFam\[f\]\?\.length && !emphasis\.includes\(f\)\)/.test(appSrc252),
    "a kind-aware order that DROPS families would hide crafts the player owns");
  check("SNG-252 §2c: a weak (off-currency) move stays CLICKABLE — moves are shortcuts, never a cage",
    /move-weak/.test(appSrc252) && !/weak[^\n]*disabled/.test(appSrc252) && /\.move-weak\s*{/.test(cssSrc252));
  check("SNG-252 §2c: a WARDED move reads disabled-with-reason, not offered-then-refused (SNG-230 §7b)",
    /function wardDenialFor\(/.test(appSrc252) && /move-warded" disabled title="\$\{esc\(ward\)\}/.test(appSrc252));
  check("SNG-252 §2c: the ways out are RELABELLED from the frame, and the primary is NOT filed under them",
    /const exitLabel = \(act, fallback\)/.test(appSrc252) && /x\.role !== "defeat"/.test(appSrc252),
    "rebuilding the exits from fm.exits files the 'defeat' primary (Push on / Strike / Press) under ways-out and wires a dead `strike` action");
  check("SNG-252 §2c: the moves take the frame's kind rather than recomputing it (one source, per seam_encounter_kind_single_source)",
    /function encounterMovesPanel\(fm = null\)/.test(appSrc252) && /const kind = fm\?\.kind \|\| encounterKind\(d\)/.test(appSrc252));

  // The content is REACHABLE — the SNG-247 promotion lesson: staged content the browser cannot fetch does not exist.
  check("SNG-252: both content files are PROMOTED to core rules and manifest-registered (staged = unreachable)",
    existsSync(join(root, "content/packs/core/rules/encounter_move_hints.json")) &&
    existsSync(join(root, "content/packs/core/rules/encounter_ribbon_copy.json")) &&
    ["encounter_move_hints", "encounter_ribbon_copy"].every(n => (coreMani252.provides?.rules || []).some(r => r.includes(n))));
  check("SNG-252: state.js LOADS both onto CONTENT (a registered file nothing reads is still dead content)",
    (() => { const s = readFileSync(join(root, "engine/state.js"), "utf8");
      return /loadRule\("encounter_move_hints"/.test(s) && /loadRule\("encounter_ribbon_copy"/.test(s) &&
             /moveHints: moveHintsDoc/.test(s) && /ribbonCopy: ribbonCopyDoc/.test(s); })());
  check("SNG-252: every framed kind has both an emphasis order and a subtitle (no kind renders hint-less)",
    Object.keys(FRAME_KINDS).every(k => Array.isArray(hints252.byKind?.[k]?.emphasis) && hints252.byKind[k].emphasis.length
      && typeof copy252.subtitle?.byKind?.[k] === "string" && copy252.subtitle.byKind[k].length > 0),
    `missing emphasis/subtitle for: ${Object.keys(FRAME_KINDS).filter(k => !hints252.byKind?.[k]?.emphasis || !copy252.subtitle?.byKind?.[k]).join(", ")}`);
  check("SNG-252: every emphasis list names only REAL function families (a typo'd family silently orders nothing)",
    Object.values(hints252.byKind).every(v => (v.emphasis || []).every(f => FUNCTION_FAMILIES.includes(f))),
    "an emphasis entry is not a function family — it would match no group and quietly do nothing");
}

// ---------- SNG-251: story-driven item evolution (prose + image + explicit mechanics + derived items) ----------
// Validated against Aevi's MEMORY WORKED EXAMPLE — the reference artifact the spec says the mechanism must be
// able to reproduce. An economy that cannot express the exemplar it was written for is the wrong economy.
{
  const ep = await import("../engine/earnedpower.js");
  const inv251 = await import("../engine/inventory.js");
  const memo = JSON.parse(readFileSync(join(root, "po/staged_content/memory_worked_example.json"), "utf8"));
  const appSrc251 = readFileSync(join(root, "app.js"), "utf8");
  const gmSrc251 = readFileSync(join(root, "engine/gm.js"), "utf8");
  const artSrc251 = readFileSync(join(root, "engine/art.js"), "utf8");
  // Silas as the worked example states him: L29, the relevant crafts at ability-rank 3.
  const silas = { level: 29, abilities: [{ abilityId: "palework", level: 3 }] };

  // §4 — the ECONOMY. Erik: the ceiling is a FUNCTION of level + craft rank, not a flat cap.
  const ceil29 = ep.grantCeiling(silas, 3), ceil1 = ep.grantCeiling({ level: 1 }, 0);
  check("SNG-251 §4: the grant ceiling SCALES with level + craft rank (not a flat cap) — evolution is the payoff for building crafts",
    ceil29.maxGrants > ceil1.maxGrants && ceil29.effectCap > ceil1.effectCap);
  check("SNG-251 §4: the ceiling can hold Aevi's Memory worked example — the exemplar the economy was written for",
    ceil29.maxGrants >= (memo.parentItem.grants || []).length,
    `Memory carries ${(memo.parentItem.grants || []).length} grants; the ceiling at L29/rank3 allows ${ceil29.maxGrants} — an economy that cannot express its own reference artifact is wrong`);
  check("SNG-251 §4: a level-1 character with no craft cannot mint a master's binding",
    ceil1.maxGrants === 1);

  // §4 — the RATE LIMIT. "~1 evolution attempt per day, capped by level/ability."
  const it251 = { name: "Memory" };
  check("SNG-251 §4: an item evolves about once a day — the second attempt the same day is refused, with a reason",
    ep.evolutionBudget(it251, 14, silas).canEvolve === true &&
    (ep.recordEvolution(it251, 14), ep.evolutionBudget(it251, 14, { level: 5 }).canEvolve === false) &&
    !!ep.evolutionBudget(it251, 14, { level: 5 }).why);
  check("SNG-251 §4: a NEW day frees it again (a rate limit, not a lifetime cap)",
    ep.evolutionBudget(it251, 15, silas).canEvolve === true);
  check("SNG-251 §4: an unknown world-day never blocks — never fail closed on a missing clock",
    ep.evolutionBudget({ name: "x" }, null, silas).canEvolve === true);

  // §2c — grants are EXPLICIT and CLAMPED. This is the heart of Erik's ask.
  const g = ep.sanitizeGrant(memo.parentItem.grants[2], ceil29);   // "The Shadow-Harm Strike"
  check("SNG-251 §2c: a real grant survives sanitisation with its effect, its source AND its stated bound intact",
    !!g && g.effect.length > 0 && g.from.length > 0 && g.clamp.length > 0);
  check("SNG-251 §2c: a grant with no EFFECT is refused — a named power that doesn't say what it does is the hollow flavour SNG-250 §3 bans",
    ep.sanitizeGrant({ name: "Ancient Power" }, ceil29) === null);
  check("SNG-251 §2c: a grant with no stated clamp still GETS one (an explicit power with no stated limit is power creep with better typography)",
    ep.sanitizeGrant({ name: "X", effect: "does a thing" }, ceil29).clamp.length > 0);
  const fold = ep.foldGrants([], memo.parentItem.grants, ceil29);
  check("SNG-251 §2c: Memory's four authored threads all land as grants under the real ceiling",
    fold.grants.length === memo.parentItem.grants.length && fold.refused.length === 0, JSON.stringify(fold.refused.map(x => x.name)));
  check("SNG-251 §2c: re-binding the SAME thread REPLACES it — a repeated evolution beat deepens, never stacks duplicates",
    ep.foldGrants(fold.grants, [memo.parentItem.grants[0]], ceil29).grants.length === fold.grants.length);
  const over = ep.foldGrants(fold.grants, [{ name: "Fifth", effect: "e" }, { name: "Sixth", effect: "e" }, { name: "Seventh", effect: "e" }], ep.grantCeiling({ level: 10 }, 1));
  check("SNG-251 §2c: past the ceiling a grant is REFUSED and RETURNED, never silently dropped — the player is told their item is full",
    over.refused.length > 0);

  // §2c — the mechanical sheet reaches BOTH the player and the GM.
  check("SNG-251 §2c: the item card shows the mechanical sheet — Erik's 'explicit about what that translates to in game mechanics', on the item",
    /item-grants/.test(appSrc251) && /item-grant-clamp/.test(appSrc251));
  check("SNG-251 §2c: the GM's inventory line carries the grants — otherwise the mechanics exist and the narrator cannot see them",
    inv251.inventoryForGM({ inventory: [{ name: "Memory", kind: "weapon", qty: 1, grants: [{ name: "Shadow-Harm Strike" }] }] }).includes("Shadow-Harm Strike"));
  check("SNG-251 §2c: gm.js no longer states the blanket 'does NOT grant new power' ban that left earned power nowhere to live",
    !/does NOT grant new power/.test(gmSrc251) && /no UNEARNED power/.test(gmSrc251));
  check("SNG-251: the op TRIPLE agrees — prompt contract, handler, and salvageable vocab all know deriveItem (seam_op_vocab_triples)",
    /"deriveItem":/.test(gmSrc251) && /"deriveItem"\]/.test(gmSrc251) && /deriveItem\(character, op,/.test(appSrc251));

  // §2b — the image re-mints. Half of what Erik reported.
  const evolving = { inventory: [{ name: "Spear", kind: "weapon", qty: 1, description: "A plain ash spear.", image: "http://old/pic.png" }] };
  const before251 = evolving.inventory[0].image;
  inv251.applyItemUpdates(evolving, [{ name: "Spear", description: "Four rune-threads seated and answering, the Weirmark drawn at the collar — nothing plain about it now.", grants: [{ name: "Anchored Read", effect: "reads the structure of what it touches" }] }],
    { ceiling: ceil29, foldGrants: ep.foldGrants });
  const after251 = evolving.inventory[0];
  check("SNG-251 §2b: a real evolution marks the image DIRTY and busts the cache key — the runed spear stops showing its runeless picture",
    after251.imageDirty === true && after251.imageStamp >= 1 && before251 === "http://old/pic.png");
  check("SNG-251 §2b: itemImage BYPASSES the stale pinned URL once dirty, and keys on the stamp",
    /if \(item\.image && !item\.imageDirty\) return item\.image;/.test(artSrc251) && /item\.imageStamp \? `\$\{item\.name\}#\$\{item\.imageStamp\}`/.test(artSrc251));
  check("SNG-251 §2b: an evolved item's authored imagePrompt WINS over the plain description, or the re-mint redraws the same spear",
    /subject\.imagePrompt/.test(artSrc251));
  const tweak = { inventory: [{ name: "Cup", kind: "misc", qty: 1, description: "A tin cup.", image: "u" }] };
  inv251.applyItemUpdates(tweak, [{ name: "Cup", provenance: "carried since the crossing" }], {});
  check("SNG-251 §2b (OQ2): a small tweak does NOT bust the image — only a real evolution re-mints",
    !tweak.inventory[0].imageDirty, "every provenance edit would spend an image generation");

  // §2d — DERIVED ITEMS, and the guard Erik corrected the spec on.
  const split = { inventory: [{ name: "Memory", kind: "weapon", qty: 1, description: "the iron spear" }] };
  const made = inv251.deriveItem(split, { parent: "Memory", name: memo.derivedItem.name, customName: memo.derivedItem.customName, description: memo.derivedItem.description, grants: memo.derivedItem.grants }, { ceiling: ceil29, foldGrants: ep.foldGrants, canDerive: ep.canDerive });
  check("SNG-251 §2d: a split makes a SECOND REAL ITEM in the pack — 'show the shadow twin as its own item I can call'",
    !!made && split.inventory.length === 2 && !!inv251.findItem(split, memo.derivedItem.customName || memo.derivedItem.name));
  check("SNG-251 §2d: the link is real in BOTH directions — the child knows its parent, the parent notes the split",
    made.item.derivedFrom === "Memory" && (made.parent.derived || []).length === 1);
  check("SNG-251 §2d: DERIVED IS NOT LESSER — the child gets its OWN grants under the SAME ceiling, never scaled down (Erik corrected the spec on exactly this)",
    (made.item.grants || []).length === (memo.derivedItem.grants || []).length &&
    !/reduced|lesser|weaker|\* *0?\.\d/.test(readFileSync(join(root, "engine/inventory.js"), "utf8").split("export function deriveItem")[1].split("\n}")[0]),
    "the derive path scales the child down somewhere — the 'echo at reduced strength' default is banned");
  // The bug this nearly shipped with, and the reason `distinct` exists. Kept as its own check because the
  // failure was SILENT and destructive: the split ate its own parent.
  check("SNG-251 §2d: a child NAMED FOR ITS PARENT does not get fuzzy-merged INTO the parent (namesMatch says they're the same thing)",
    split.inventory.length === 2 && split.inventory.every(i => i.qty === 1) &&
    !!inv251.findItem(split, "Memory") && inv251.findItem(split, "Memory").customName !== memo.derivedItem.customName,
    "the derive merged into the parent stack — the player would LOSE the parent item and get a doubled stack wearing the child's name");
  check("SNG-251 §2d: a derived item is born with its own picture (it is a new thing, not a re-skin)",
    made.item.imageDirty === true && made.item.imageStamp === 1);
  check("SNG-251 §2d: splitting is BOUNDED — an item cannot be split endlessly into a duplication engine",
    ep.canDerive({ derived: ["a", "b"] }).ok === false);

  // §2a — the trigger the ENGINE enforces. This is the root cause of Erik's report.
  check("SNG-251 §2a: the engine detects the evolution beat itself and hands the GM a HARD directive (itemUpdates is 1 of 114 MUSTs and drops under saturation)",
    /const itemEvolveDetail = \(\) =>|const itemEvolveDetail = \(\(\) =>/.test(appSrc251) &&
    /AN ITEM HAS BEEN CHANGED BY WHAT WAS JUST DONE/.test(gmSrc251));
  check("SNG-251 §2a: the trigger needs a verb of MAKING and a HELD item — narrow on purpose, because a false positive spends a hard directive on an ordinary turn",
    /bind\|bound\|binding\|seat/.test(appSrc251) && /said\.includes\(n\)/.test(appSrc251));
  check("SNG-251 §2a: the player can start an evolution themselves, and must CITE the fiction that earned it",
    /data-item-evolve/.test(appSrc251) && /What has \$\{displayName\(it\)\} been through/.test(appSrc251));
  check("SNG-251 §2a: the player path checks the daily budget BEFORE spending the turn, not after",
    /if \(!budget\.canEvolve\) \{ renderPlay/.test(appSrc251));
  check("SNG-251 §4: the rate limit bites only on the POWER — prose, name and provenance still evolve when the day is spent (rate-limiting storytelling would be the wrong lesson)",
    /const \{ grants, \.\.\.rest \} = op; return rest;/.test(appSrc251));
  check("SNG-251: ONE economy for every path — the GM's op, a derive, and the player's own action all pass through itemEvolveDeps",
    (appSrc251.match(/itemEvolveDeps\(/g) || []).length >= 3);
}

// ---------- ERIK'S BUG (2026-08-01, live): a bestiary monster fought as "the aggressor" ----------
// "wth is going on here? I thought i was supposed to be fighting rust nanites." He was. The engine had the
// creature the whole way — loaded, weighted, danger-gated, seeded with its own prose — and ANONYMISED it at
// the last hop, because the pool entry carried no `name` and no `opponent.name` and synthesizeDuelDef reads
// exactly those two. One missing pair of fields defeated SNG-229's whole purpose at the final step.
{
  const re251 = await import("../engine/random_encounters.js");
  const roster = JSON.parse(readFileSync(join(root, "content/packs/valley/bestiary.json"), "utf8")).roster || [];
  const gnats = roster.filter(c => c.id === "rust_choir_gnats");
  const entry = re251.bestiaryEncounters({ roster: gnats })[0];
  const def = re251.synthesizeDuelDef(entry);
  check("ERIK-BUG: a bestiary creature keeps its NAME as the encounter title — not the flavor map's 'Hard Ground'",
    def.name === "Rust-Choir Gnats", `got "${def.name}"`);
  check("ERIK-BUG: the foe is the CREATURE, never 'the aggressor'",
    def.opponent.name === "rust-choir gnats", `got "${def.opponent.name}"`);
  check("ERIK-BUG: the duel carries creatureId through, instead of downstream re-parsing it out of the def id",
    def.creatureId === "rust_choir_gnats");
  check("ERIK-BUG: EVERY roster creature is named in both places — no monster in the game fights anonymously",
    re251.bestiaryEncounters({ roster }).map(e => re251.synthesizeDuelDef(e))
      .every(d => d.name && d.name !== "Hard Ground" && d.opponent.name && d.opponent.name !== "the aggressor"),
    "some creature still synthesizes to the flavor title / the generic aggressor");
  check("ERIK-BUG: a non-creature entry is UNCHANGED — the generic fallbacks still apply where they belong",
    (() => { const d = re251.synthesizeDuelDef({ id: "x", flavor: "fight", opponent: { threat: 30 } });
      return d.name === "A Hostile Meeting" && d.opponent.name === "the aggressor" && d.creatureId === undefined; })());
  // The same path serves GENERATED creatures (SNG-250 §7b), so the fix covers them for free — assert it.
  check("ERIK-BUG: a GENERATED creature is named too (it rides the same synthesis path)",
    (() => { const g = re251.generatedCreatureEncounters({ generated: { creature: { thing: { id: "thing", name: "the pale thing", tier: "notable", class: "beast", look: "l", danger: "d", pressures: ["HARM"] } } } })[0];
      const d = re251.synthesizeDuelDef(g); return d.opponent.name === "the pale thing" && d.name === "The Pale Thing"; })());
}

// ---------- ERIK'S BUG (2026-08-01, live): "this is a weird result to exit the fight" ----------
// It was not weird — it was INVISIBLE. Momentum stopped being an exit at CCODE-38 ("momentum should be a
// MODIFIER mechanic, not the primary exit metric"); what ends a fight now is the PRESSURE counter, and
// `breakAtPressure` is 2. That counter was rendered NOWHERE, so the player watched the one meter that cannot
// end the fight and never saw the one that does — and a round reported as "neither gains — it's even" was
// followed by the fight ending, with the cause never stated.
{
  const appE = readFileSync(join(root, "app.js"), "utf8");
  const mom = JSON.parse(readFileSync(join(root, "content/packs/core/rules/skill_battle_system.json"), "utf8")).engine.momentum;
  check("ERIK-BUG: the PRESSURE counter — the thing that actually ends a fight — is rendered to the player",
    /class="sb-pressure"/.test(appE) && /driven back \$\{pip\(theirs, brk\)\}/.test(appE),
    "the exit condition is still invisible; the player can only watch momentum, which CCODE-38 made unable to end anything");
  check("ERIK-BUG: the pressure readout reads breakAtPressure from CONTENT, never a hardcoded 2",
    /momentum\?\.pressure\?\.breakAtPressure \?\? 2/.test(appE) && mom?.pressure?.breakAtPressure != null,
    "a hardcoded threshold would silently disagree with the dial Erik and Aevi tune");
  check("ERIK-BUG: an ending says WHY — a pressure-break is named, not left as a non-sequitur after 'it's even'",
    /brokeOnPressure/.test(appE) && /driven back \$\{brkAt\} times and will not come again/.test(appE));
  check("ERIK-BUG: the cause is read from the ROUND RESULT, not the pre-round state (which misses the tick that ended it)",
    /rr\?\.pressure\?\.opponent \|\| 0\) >= brkAt/.test(appE));
}

// ---------- ERIK'S BUG (2026-08-01, Machine log): every round reported "neither gains — it's even" ----------
// A roll of 1/95 (margin 102) against a margin of 25 was reported as an even exchange, and the meter as "4→4".
// `sbRoundReceipt` was handed the round's AFTER momentum as its BEFORE — the stray `(r.state?.momentum ?? 0) - 0`
// — so `swing = after - before` was ALWAYS 0. The receipt lied about every round of every fight, and because
// the GM narrates FROM those beats (both of which used beforeMom 0), the Action and the Bonus step read
// identically and inconsequentially: which is exactly "I'm never sure they are both narrated".
{
  const appMraw = readFileSync(join(root, "app.js"), "utf8");
  // Comments are stripped: the fix's own comment QUOTES the old broken call to explain it, and a naive
  // negative match would read that quotation as the bug still being present.
  const appM = appMraw.split("\n").filter(l => { const t = l.trim(); return !t.startsWith("//") && !t.startsWith("*"); }).join("\n");
  check("ERIK-BUG: the receipt is no longer handed the AFTER momentum as its BEFORE (swing can be non-zero again)",
    !/sbRoundReceipt\(r, d, \(r\.state\?\.momentum \?\? 0\) - 0/.test(appM) && /sbRoundReceipt\(r, d, beforeMom, false\)/.test(appM),
    "swing is pinned to 0, so every round reports 'neither gains — it's even' regardless of the rolls");
  check("ERIK-BUG: the transcript beat gets the REAL before-momentum, not a hardcoded 0 — the GM narrates from these",
    !/sbFightBeat\(r, d, 0, false\)/.test(appM) && /sbFightBeat\(r, d, beforeMom, false\)/.test(appM),
    "both steps report as even, so the Action and the Bonus read the same in the prose");
  check("ERIK-BUG: the machine log uses the same before-value, not the stale pre-TURN enc.state (wrong for the bonus step)",
    !/sbLogRound\(enc, d, r, enc\.state\.momentum \?\? 0, false\)/.test(appM) && /sbLogRound\(enc, d, r, beforeMom, false\)/.test(appM));
  check("ERIK-BUG: before-momentum is captured BEFORE activeEncounter is overwritten with the new state",
    (() => { const i = appM.indexOf("const beforeMom = character.activeEncounter?.state?.momentum");
      const j = appM.indexOf("character.activeEncounter = { defId: enc.def.id, state: r.state }");
      return i > 0 && j > i; })(),
    "captured after the write, it would read the new state and be pinned to 0 all over again");
  check("ERIK-BUG: all three reporters share ONE before-value, so receipt / log / beat cannot disagree",
    (appM.match(/, beforeMom, false\)/g) || []).length === 3);
}

// ---------- SNG-253 (engine half): the opponent's move vocabulary can be KIND-NATIVE ----------
// Scoped from the post-252 re-look Aevi asked for, and grounded in what the engine ACTUALLY declared rather
// than what the spec predicted: a standoff opponent declared "a hard strike" and held "a raised guard" — in a
// contest the ribbon had just told the player cannot hurt them — and a chase pursuer did the same.
{
  const sb253 = await import("../engine/skill_battle.js");
  const base = JSON.parse(readFileSync(join(root, "content/packs/core/rules/skill_battle_system.json"), "utf8")).engine;
  const cfg = JSON.parse(JSON.stringify(base));
  const names = o => sb253.synthesizeOpponentSheet(o, cfg).skills.map(s => s.name).join(" , ");

  // SUPERSEDED by SNG-253's content landing: this asserted that synthesis was UNCHANGED while no per-kind
  // archetypes existed, which was the right check for an engine half shipping ahead of its content. The
  // verb sets are authored now, so the durable claim is the FALLBACK: a kind nobody has authored must still
  // resolve exactly as it always did, or adding one kind silently changes every other.
  check("SNG-253: an UNAUTHORED kind still falls back to the default vocabulary (adding one kind cannot change the rest)",
    names({ name: "x", threat: 40, encounterKind: "no_such_kind" }) === names({ name: "x", threat: 40 }));
  cfg.opponentSheetSynthesis.archetypeSkills["kind:standoff"] = [{ function: "influence", name: "a pressed point" }, { function: "ward", name: "the held line" }];
  check("SNG-253: a per-kind archetype, once authored, gives the opponent KIND-NATIVE verbs",
    names({ name: "x", threat: 40, encounterKind: "standoff" }) === "a pressed point , the held line");
  check("SNG-253: an explicit tacticTag still WINS over the kind — it is the most specific thing an author can say about THIS opponent",
    names({ name: "x", threat: 40, encounterKind: "standoff", tacticTags: ["duelist"] }) === "the measured cut , the turned guard");
  check("SNG-253: the kind is THREADED from encounterKind(def), never re-derived inside the synthesizer (one source)",
    /function withKind\(opponent, def\)/.test(readFileSync(join(root, "app.js"), "utf8")) &&
    /const k = encounterKind\(def\)/.test(readFileSync(join(root, "app.js"), "utf8")) &&
    !/encounterKind\(/.test(readFileSync(join(root, "engine/skill_battle.js"), "utf8")));
  check("SNG-253: EVERY opponent-sheet synthesis call site threads the kind (a missed one silently keeps fight verbs)",
    (() => { const s = readFileSync(join(root, "app.js"), "utf8");
      const calls = s.match(/synthesizeOpponentSheet\(([^,]+),/g) || [];
      return calls.length > 0 && calls.every(c => /withKind\(/.test(c)); })(),
    "a call site passes the raw opponent — that encounter keeps the fight default no matter what Aevi authors");
  // The evidence that motivated the ticket, kept as a live assertion so nobody has to re-derive it.
  // The scope note this replaces said "update this check when the verb sets land". They landed, so it now
  // asserts what SNG-253 was FOR: a standoff opponent must not gather to STRIKE in a contest the ribbon has
  // just told the player cannot hurt them. That is the whole point, and it is checkable in the content.
  const authored = base.opponentSheetSynthesis?.archetypeSkills || {};
  check("SNG-253: per-kind opponent vocabularies are AUTHORED and reachable under .engine (not orphaned a level up)",
    Object.keys(authored).some(k => k.startsWith("kind:")),
    `archetypes present: ${Object.keys(authored).join(", ")} — a kind: set authored at the TOP level instead of inside .engine is dead content`);
  check("SNG-253: a STANDOFF opponent has no STRIKE in its vocabulary — the contest cannot hurt you, so it must not swing",
    !(authored["kind:standoff"] || []).some(m => /^(strike|break)$/.test(String(m.function))),
    JSON.stringify((authored["kind:standoff"] || []).map(m => m.function)));
}


// ---------- SNG-263 r4: the LIVE BALANCE DIALS are wired (Erik: dials should be tweakable AS I PLAY) ----------
// Erik's standing instruction: "ALL of these dials should/could be dev settings to have me tweak as I play
// to find the right feel... always keep in mind what dev and machine screens are available." A dial panel
// that silently stops applying is worse than none — he would turn a number, feel nothing, and conclude the
// mechanic is inert (the encounterRate lesson, on the tuning surface this time).
{
  const src = readFileSync(join(root, "app.js"), "utf8");
  check("SNG-263 dials: the override layer exists and is DEV-GATED (a player build has no override path)",
    /const DIALS_KEY = "singularity\.dials"/.test(src) && /function applyDevDials\(\)\s*\{\s*if \(!isDevMode\(\)/.test(src));
  check("SNG-263 dials: overrides are applied to the LOADED content right after loadContent()",
    /CONTENT = await loadContent\(\);\s*\n\s*applyDevDials\(\);/.test(src));
  check("SNG-263 dials: every dial is declared once, and the panel/apply/reset all read that one list",
    /const DEV_DIALS = \[/.test(src) && /DEV_DIALS\.map\(d =>/.test(src) && /for \(const d of DEV_DIALS\)/.test(src));
  check("SNG-263 dials: editing one re-applies and re-renders, so the NEXT roll uses it (no reload)",
    /\[data-dial\]/.test(src) && /writeDials\(over\); applyDevDials\(\); renderMachine\(\);/.test(src));
  check("SNG-263 dials: Reset restores the SHIPPED values, not a guess (baseline captured before any override)",
    /DIAL_BASELINE\[d\.path\] = dialGet\(CONTENT, d\.path\)/.test(src) && /writeDials\(\{\}\); applyDevDials\(\)/.test(src));
  // the dials must point at REAL paths — a typo'd path is a control with nothing on the other end
  const paths = [...src.matchAll(/\{ path: "([^"]+)"/g)].map(m => m[1]);
  const content = {
    rules: JSON.parse(readFileSync(join(root, "content/packs/core/rules/resolution.json"), "utf8")),
    skillBattle: JSON.parse(readFileSync(join(root, "content/packs/core/rules/skill_battle_system.json"), "utf8")),
    craftMechanics: JSON.parse(readFileSync(join(root, "content/packs/core/rules/craft_mechanics.json"), "utf8")),
  };
  const dead = paths.filter(p => p.split(".").reduce((o, k) => (o == null ? o : o[k]), content) === undefined);
  check("SNG-263 dials: every declared dial resolves to a real content value (no phantom control)",
    paths.length >= 10 && dead.length === 0, `dials pointing at nothing: ${dead.join(", ")}`);
}


// ---------- CCODE-85: NPCs HAVE DEEDS TOO (Erik) ----------
// reputation.js was never character-SPECIFIC - every function in it reads only `X.deeds`. What did not exist
// was a caller that passed an NPC and a reader that surfaced one, so the whole reputation machine pointed at
// exactly one person in the world. That is the bestiary gap's shape: a mechanism that works, aimed at one
// kind of thing. Aevi's arena finding is what it is for - an epic stops being a threat number and becomes a
// person whose record you have been hearing about for twenty sessions.
{
  const RULES_R = JSON.parse(readFileSync(join(root, "content/packs/core/rules/resolution.json"), "utf8"));
  const ch = { name: "Loki", npcRegistry: {}, currentLocationId: "crossing" };
  applyNpcUpdates(ch, [{ op: "meet", npcId: "vasska", name: "Vasska", role: "pit champion" }],
    { locationId: "crossing", communityId: "crossing", rules: RULES_R });
  const deeds = [
    { description: "won the Iron Circuit three years running", weight: 3, tags: ["valor", "skill"], communityId: "crossing" },
    { description: "crippled a challenger who had already yielded", weight: -2, tags: ["cruelty"], communityId: "crossing" },
    { description: "stood alone against a wight at the Deeping", weight: 3, tags: ["valor"], communityId: "deeping" },
  ];
  for (const d of deeds) applyNpcUpdates(ch, [{ op: "update", npcId: "vasska", deed: d }],
    { locationId: "crossing", communityId: d.communityId, rules: RULES_R });
  const v = ch.npcRegistry.vasska;

  check("CCODE-85: an NPC accumulates deeds through the same recordDeed the player uses (one ledger shape)",
    (v.deeds || []).length === 3 && v.deeds.every(d => "weight" in d && "spread" in d));
  check("CCODE-85: renownOf reads what they are KNOWN FOR, worst and best alike",
    renownOf(v, RULES_R)?.knownFor.includes("valor") && renownOf(v, RULES_R)?.knownFor.includes("cruelty"));
  check("CCODE-85: someone with NO record returns null - a nobody stays a nobody, not a renown-0 stat line",
    renownOf({ name: "a passerby" }, RULES_R) === null);

  // The half that keeps this honest: a reputation cannot outrun the news that carries it.
  check("CCODE-85: a record is HEARD only where the deed happened or spread to",
    renownHeardAt(v, "crossing", RULES_R)?.heardHere === true
    && renownHeardAt(v, "farhaven", RULES_R)?.heardHere === false);
  check("CCODE-85: and the LOCAL talk is the local deeds, not the whole record",
    (renownHeardAt(v, "crossing", RULES_R)?.localNotable || []).every(d => !/wight/.test(d)));

  // A writer nothing reads is the failure this codebase gates hardest against.
  const block = npcRegistryForGM(ch, { locationId: "crossing", sceneNpcNames: ["Vasska"], communityId: "crossing", rules: RULES_R });
  check("CCODE-85: the GM's NPC block CARRIES the renown (a record nobody reads is a record nobody has)",
    /RENOWN/.test(block) && /Iron Circuit/.test(block));
  const away = npcRegistryForGM(ch, { locationId: "crossing", sceneNpcNames: ["Vasska"], communityId: "farhaven", rules: RULES_R });
  check("CCODE-85: ...and says nothing about them where their record has not reached",
    !/RENOWN/.test(away));
  check("CCODE-85: an NPC with no deeds gets no renown line at all",
    !/RENOWN/.test(npcRegistryForGM(
      (() => { const c = { name: "Loki", npcRegistry: {} };
               applyNpcUpdates(c, [{ op: "meet", npcId: "pell", name: "Pell" }], { locationId: "crossing", rules: RULES_R }); return c; })(),
      { locationId: "crossing", sceneNpcNames: ["Pell"], communityId: "crossing", rules: RULES_R })));
}


;
}

// ---------- CCODE-89: the Great Coliseum's BLIND GRID (SNG-149, Aevi, Law 15) ----------
// Aevi authored the whole design and it sat as a design doc NOTHING READ for a fortnight, with three champion
// encounters already written against it. Every assertion here defends a rule that exists to stop a specialist
// steering toward their best ground - so a change that makes the grid kinder to a narrow competitor is
// breaking the mechanic, not tuning it.
{
  const { drawAxis, resolvePick, cellFor, readOfPick, championPick, drawBackgroundAxis } = await import("../engine/coliseum.js");
  const { buildFunctionIndex } = await import("../engine/functions.js");
  const GRID = JSON.parse(readFileSync(join(root, "content/packs/core/rules/coliseum_grid.json"), "utf8"));
  const IDX = buildFunctionIndex(JSON.parse(readFileSync(join(root, "content/packs/core/rules/function_vocabulary.json"), "utf8")));
  const cat = { a1: { functions: ["strike"] }, a2: { functions: ["break"] }, a3: { functions: ["ward"] },
                a4: { functions: ["heal"] }, a5: { functions: ["reveal"] }, a6: { functions: ["bind"] } };
  const narrow = { abilities: [{ abilityId: "a1", level: 3 }, { abilityId: "a2", level: 3 }] };
  const broad = { abilities: [{ abilityId: "a1", level: 2 }, { abilityId: "a3", level: 3 }, { abilityId: "a4", level: 2 }, { abilityId: "a5", level: 1 }, { abilityId: "a6", level: 2 }] };
  const seed = () => { let s = 5; return () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; }; };
  const rng = seed();
  const A = drawAxis(narrow, { catalog: cat, index: IDX, rng }), B = drawAxis(broad, { catalog: cat, index: IDX, rng });

  check("CCODE-89: every competitor brings FOUR slots - nobody enters with a short axis",
    A.length === 4 && B.length === 4);
  check("CCODE-89: at least one slot is always WILD, drawn from all eight including untrained families",
    A.some(s => s.from.startsWith("wild")) && B.some(s => s.from.startsWith("wild")));
  check("CCODE-89: all 36 cells are authored and every drawn pair resolves to one",
    GRID.cells.length === 36 && !!cellFor(A[0].family, B[0].family, GRID));

  // THE RULE THE WHOLE DESIGN RESTS ON.
  const legal = resolvePick({ axisA: A, axisB: B, pickA: B[0].family, pickB: A[0].family, grid: GRID });
  // ERIK'S CORRECTION: the two picks COMBINE into ONE matchup. It is not that you fight with one family
  // while they fight with the other - the pair NAMES a single contest both are in, judged by one criterion.
  // What the picks decide is which SEAT each takes in it.
  check("CCODE-89: a legal pick resolves to ONE shared contest, not two separate grounds",
    legal.ok && !!legal.matchup?.contest && legal.matchup.families.length === 2
    && !("aFightsOn" in legal) && !("bFightsOn" in legal));
  check("CCODE-89: the picks decide the SEATS, and neither competitor chose their own",
    legal.seats.a === A[0].family && legal.seats.b === B[0].family);
  check("CCODE-89: picking from your OWN axis is REFUSED, never coerced (coercion restores the steering)",
    resolvePick({ axisA: A, axisB: B, pickA: A[0].family, pickB: B[0].family, grid: GRID }).ok === false);

  // Aevi: "a specialist does not become harder to read; they become more exposed." Measured, not asserted.
  const untrained = (who) => { const r = seed(); let t = 0;
    for (let k = 0; k < 2000; k++) t += drawAxis(who, { catalog: cat, index: IDX, rng: r }).filter(s => s.from !== "practice").length;
    return t / 2000; };
  const nU = untrained(narrow), bU = untrained(broad);
  console.log(`      CCODE-89 measured — untrained columns per axis: 2-family specialist ${nU.toFixed(2)}/4 · 5-family competitor ${bU.toFixed(2)}/4`);
  check("CCODE-89: a SPECIALIST is measurably more exposed than a broad competitor (the whole point)",
    nU > bU, `${nU.toFixed(2)} vs ${bU.toFixed(2)}`);
  // CCODE-89b — THE CHAMPION'S PICK. Made by the ENGINE, never the narrator, for the same reason
  // opponentPolicy exists: a champion's read of you must not be whatever prose felt good this turn.
  const yourAxis = [{ family: "HARM", from: "practice", weight: 6 }, { family: "PROTECT", from: "practice", weight: 3 },
                    { family: "KNOW", from: "practice", weight: 1 }, { family: "MOVE", from: "wild", weight: 0 }];
  const pr = seed();
  check("CCODE-89b: a PROVING champion takes you at the thing you are known for (your deepest column)",
    championPick(yourAxis, { stance: "proving", rng: pr }).family === "HARM");
  check("CCODE-89b: a PROBING champion takes your WILDCARD - calling you hollow outside your specialty",
    championPick(yourAxis, { stance: "probing", rng: pr }).family === "MOVE");
  check("CCODE-89b: a CANNY champion takes neither your showpiece nor your gap",
    !["HARM", "MOVE"].includes(championPick(yourAxis, { stance: "canny", rng: pr }).family));
  check("CCODE-89b: with no wildcard to take, it still returns a pick rather than nothing",
    !!championPick(yourAxis.filter(s => s.from === "practice"), { stance: "probing", rng: pr })?.family);
  check("CCODE-89b: an empty axis is null, not a guess",  championPick([], { rng: pr }) === null);
  // THE BLINDNESS GUARANTEE: the champion's pick is a function of your AXIS and nothing else. If it could see
  // your choice, "simultaneous" would be a word rather than a fact - so the same axis must give the same pick
  // no matter what you named.
  {
    const a = championPick(yourAxis, { stance: "proving", rng: seed() });
    const b = championPick(yourAxis, { stance: "proving", rng: seed() });
    check("CCODE-89b: the champion's pick cannot depend on yours - blind means blind",
      a.family === b.family);
  }
  // CCODE-89d — THE SECOND GRID. Erik named the source: Stile's challenges in the Apprentice Adept books,
  // where the first grid picks the category and a second 4x4 inside it picks the actual contest. Aevi specced
  // the same: "the first grid asks what KIND of person you are; the second asks WHO YOU SPECIFICALLY HAVE BEEN."
  {
    const bio = { origin: "wright", background: "lineage_taught", rolesKnownFor: ["Post Master", "smith's hand"],
      deeds: [{ description: "named the Fell Pell", spread: ["crossing"] }, { description: "a thing nobody heard", spread: [] }] };
    const r2 = seed();
    const ax = drawBackgroundAxis(bio, { rng: r2 });
    check("CCODE-89d: the second axis is drawn from BIOGRAPHY - origin, background, roles, deeds",
      ax.length === 4 && new Set(ax.map(s => s.from)).size > 1);
    check("CCODE-89d: a deed that never SPREAD is not on it - the grid cannot know what the world does not",
      !ax.some(s => /nobody heard/.test(s.family)));
    check("CCODE-89d: a person with no history draws a SHORT axis (true about them, never padded)",
      drawBackgroundAxis({ origin: "valley" }, { rng: r2 }).length === 1);
    // The blind rule is the SAME rule - a grid is a grid, so resolvePick takes this axis unchanged.
    const innerCells = [{ id: "x", families: [ax[0].family, ax[1].family], name: "A Particular Afternoon", contest: "c" }];
    const both = resolvePick({ axisA: [ax[0]], axisB: [ax[1]], pickA: ax[1].family, pickB: ax[0].family, grid: { cells: innerCells } });
    check("CCODE-89d: the second grid resolves through the SAME blind machinery as the first",
      both.ok && both.seats.a === ax[0].family && both.seats.b === ax[1].family);
  }
  check("CCODE-89b: every stance explains ITSELF, so the receipt can say what argument they just made",
    ["proving", "probing", "canny"].every(s => typeof championPick(yourAxis, { stance: s, rng: pr })?.why === "string"));
  check("CCODE-89: the pick is a readable ARGUMENT about the opponent, not a bare choice",
    ["deepest", "middle", "wildcard"].includes(readOfPick(B[0].family, B)?.kind));
}

// --- SNG-269/2b: MINTING — the world refills what it loses -------------------------------------------
{
  const { worldRoster, mintFigure, affinitiesOf: affinitiesOfFn } = await import("../engine/worldtick.js");
  const srcOf = (f) => readFileSync(join(root, f), "utf8");
  const wtSrc = srcOf("engine/worldtick.js");
  const ws = {};
  const content = { legends: { roster: [{ id: "a", name: "Authored" }] } };
  check("2b: the roster reads authored AND minted figures through ONE helper",
    worldRoster(ws, content).length === 1
    && (mintFigure(ws, { tier: "notable", epithet: "the one who stepped in", worldDay: 5 }),
        worldRoster(ws, content).length === 2));
  check("2b: a minted figure is BORN WHOLE — id, tier, weight, and the reason they exist",
    (f => f.id && f.tier === "notable" && f.weight > 0 && f.origin !== undefined && f.legend?.tier === "notable")
      (ws.mintedFigures[0]));
  check("2b: a minted figure always has a NAME — a nameless one is skipped by every add() and never acts",
    !!ws.mintedFigures[0].name && ws.mintedFigures[0].provisional === true);
  check("2b: the roster cannot grow without bound", (() => {
    const w = {}; for (let i = 0; i < 12; i++) mintFigure(w, { cap: 4, epithet: "x" });
    return (w.mintedFigures || []).length === 4;
  })());
  // ⚠️ TWO SEPARATE WAYS THIS OBJECT WAS WRONG, both silent: the SHAPE (`living` wants `.arcId`) and the
  // KEY (`affinitiesOf` wants `.dir`). Assert against the real CONSUMER, not against what the field is
  // called — a care the care-reader rejects is not a care, however right it looks.
  check("2b: a minted figure's care is one `affinitiesOf` actually ACCEPTS (shape AND key)", (() => {
    const w = {}; const g = mintFigure(w, { arcAffinity: "arc-x", epithet: "e" });
    return g.arcAffinity?.arcId === "arc-x" && affinitiesOfFn(g).length === 1;
  })());
  check("2b: minted figures ENTER THE POPULATION (born into the roster but never acting is not being alive)",
    /mintedFigures \|\| \[\]\)\) \{[\s\S]{0,220}add\(f\.id, f\.name/.test(wtSrc));
  check("2b: minting is driven by DEATHS, not by abandonment (which grows with the roster and self-amplifies)",
    /const deaths = \[\.\.\.casualties\.filter\(c => c\.kind === "killed"\)/.test(wtSrc)
    && /\.\.\.strikes\.filter\(s => s\.outcome === "killed"\)/.test(wtSrc));
  check("2b: the arc-vacancy door reads an UNHELD arc, never the abandonment counter",
    /const held = \(leaning\[arcId\]\?\.pro\?\.length \|\| 0\)/.test(wtSrc) && !/if \(vacated\[arcId\]\) ws\.arcUnheldStreak/.test(wtSrc));
  check("2b: a minted figure who dies is still mournable — the death path reads the LIVING roster",
    /mintedFigures \|\| \[\]\)/.test(srcOf("engine/death.js")));
}

// --- SNG-269/2c: PROMOTION — tier is EARNED, not authored ---------------------------------------------
{
  const { advanceStandings, demoteFigure, tierOf, creditDeed: creditDeedFn } = await import("../engine/worldtick.js");
  const wtSrc2 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const ws = {}; const f = { id: "x", name: "Nobody", tier: "riffraff" };
  // SNG-279: the gate is DEEDS now, with time as a floor — so this must earn its rise, not merely wait.
  check("2c: an earned rung is an OVERRIDE in world state — content is read-only and shared",
    (advanceStandings(ws, [f], 0),
     creditDeedFn(ws, "x", "arcContestWon", { worldDay: 1 }),
     creditDeedFn(ws, "x", "arcContestWon", { worldDay: 2 }),
     advanceStandings(ws, [f], 200),
     ws.figureTier?.x === "notable" && f.tier === "riffraff" && tierOf(ws, f) === "notable"));
  check("2c: rising takes TIME AT RUNG — a figure seen once does not promote",
    (() => { const w = {}; const g = { id: "g", tier: "heroic" };
             advanceStandings(w, [g], 0); return !w.figureTier?.g; })());
  check("2c: the upper rungs also require WINS, not just survival",
    (() => { const w = {}; const g = { id: "g", tier: "heroic" };
             advanceStandings(w, [g], 0); advanceStandings(w, [g], 3000);
             return !w.figureTier?.g;   // 8 world-years but zero contests won
    })());
  check("2c: a new rung RESTARTS the clock AND the deed score (you do not carry either upward)",
    ws.figureTenure?.x?.tier === "notable" && ws.figureTenure.x.sinceDay === 200 && ws.figureTenure.x.deeds === 0);
  check("2c: demotion exists — without a way DOWN, promotion alone makes everyone mythic",
    (() => { const w = {}; const g = { id: "g", tier: "epic" };
             return demoteFigure(w, g, 10, "defeated_unavenged")?.to === "heroic" && tierOf(w, g) === "heroic"; })());
  // ⛔ SNG-431 §2 — …AND ONLY AN EVENT MAY CALL IT. Erik's ruling: authored tiers do not demote. The old
  // trigger was silence, which `SYSTEM_SPEC.md` does not authorise — its one demotion rule governs
  // PROPAGATION for generated entities, not RANK for authored figures with a `tierBirthWeight`.
  check("431/2: a rung cannot be taken without an event that took it",
    (() => { const w = {}; const g = { id: "g", tier: "epic" };
             return demoteFigure(w, g, 10) === null && demoteFigure(w, g, 10, "went quiet") === null
               && tierOf(w, g) === "epic"; })());
  check("2c: the mechanics read the EARNED rung, not the authored one (budget and rank both)",
    /const t = tierOf\(ws, f\);\s*\/\/ SNG-269\/2c: the EARNED rung/.test(wtSrc2)
    && /const t = tierOf\(ws, f\);\s*\/\/ SNG-269\/2c: earned rung/.test(wtSrc2));
  check("2c: contest wins are recorded for EVERY participant, not only the leader",
    /for \(const e of won\) \{ if \(ws\.figureTenure\[e\.f\.id\]\) ws\.figureTenure\[e\.f\.id\]\.wins\+\+; career\(ws, e\.f\.id\)\.wins\+\+; \}/.test(wtSrc2));
  check("2c: a minted figure's arcAffinity has the SHAPE `living` filters on, or it is invisible to the world",
    /arcAffinity: arcAffinity \? \{ arcId: arcAffinity/.test(wtSrc2));
}

// --- SNG-271: the three remaining items from Erik's fight log ------------------------------------------
{
  const appSrc271 = readFileSync(join(root, "app.js"), "utf8");
  check("271: a margin says WHICH WAY it went — `missed by 33` beats `(margin -33)` beside a roll of 98",
    /const marginText = m => \(Number\(m\) < 0 \? `missed by \$\{Math\.abs\(Number\(m\)\)\}` : `beat by/.test(appSrc271)
    && !/\(margin \$\{r\.you\.roll\.margin\}/.test(appSrc271));
  check("271: the round log takes its receipt as a PARAMETER, not from a shared display variable",
    /function sbLogRound\(enc, decl, rr, beforeMom, scouting, receipt = sbLastRoundReceipt\)/.test(appSrc271)
    && /receipt: receipt \|\| null/.test(appSrc271));
  check("271: a READ logs its OWN prose — not whatever the last strike left standing",
    /sbLogRound\(enc, decl, rr, character\.activeEncounter\.state\.momentum \?\? 0, true, t\.senseLine\)/.test(appSrc271));
  check("271: the log tells DELTAS from TOTALS (a -12 delta beside totals reads as negative health)",
    /this round Δhp \$\{r\.deltas\?\.health/.test(appSrc271) && /left: energy you/.test(appSrc271));
  check("271: and a negative health TOTAL is structurally unreachable — every write clamps at zero",
    (appSrc271.match(/character\.health = Math\.max\(0, Math\.min\(character\.maxHealth/g) || []).length >= 4
    && /opponentHealth = Math\.max\(0,/.test(readFileSync(join(root, "engine/skill_battle.js"), "utf8")));
}

// --- SNG-270: going after your own dead ---------------------------------------------------------------
{
  const { attemptRetrievals } = await import("../engine/worldtick.js");
  const { reachableDeadForGM, enterDeathState } = await import("../engine/death.js");
  const wtSrc3 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const mk = (diedDay) => {
    const ws = { epicStatus: { dead1: { status: "dead" } } };
    enterDeathState(ws.epicStatus.dead1, { diedDay, cause: "killed by someone" });
    const roster = [{ id: "dead1", name: "The Fallen", arcAffinity: { arcId: "a1", dir: 1 } },
                    { id: "kin1", name: "Their Ally", tier: "legendary", arcAffinity: { arcId: "a1", dir: 1 } }];
    return { ws, roster };
  };
  {
    const { ws, roster } = mk(0);
    const r = attemptRetrievals(ws, roster, roster.slice(1), 5, {}, { retrievalRate: 1 }, () => 0.01);
    check("270: somebody who shared a care goes after their dead — and at the threshold, gets them back",
      r.attempts[0]?.outcome === "return" && ws.epicStatus.dead1.status === "active");
    check("270: the retriever OWES A FRONT — attention spent in the dark is not spent on an arc",
      r.retrievers.has("kin1"));
  }
  {
    const { ws, roster } = mk(0);
    const r = attemptRetrievals(ws, roster, roster.slice(1), 5, {}, { retrievalRate: 1 }, () => 0.99);
    check("270: reaching and failing SINKS them — trying is the risk that makes leaving them a real choice",
      r.attempts[0]?.outcome === "fail" && ws.epicStatus.dead1.deathState.depthOverride > 0);
  }
  {
    const { ws, roster } = mk(0);
    // nobody shares a care → nobody comes
    roster[1].arcAffinity = { arcId: "somewhere-else", dir: 1 };
    const r = attemptRetrievals(ws, roster, roster.slice(1), 5, {}, { retrievalRate: 1 }, () => 0.01);
    check("270: a stranger does not go into the dark for you", r.attempts.length === 0);
  }
  {
    const { ws, roster } = mk(0);
    attemptRetrievals(ws, roster, roster.slice(1), 5, {}, { retrievalRate: 0 }, () => 0.5);
    check("270: the ASKER is recorded even when no NPC reaches this pass — that is what makes it a quest",
      ws.retrievalWanted?.[0]?.byName === "Their Ally");
    const seen = reachableDeadForGM({ worldState: ws, npcRegistry: {} },
      { legends: { roster } }, 5);
    check("270: the GM is told WHO WANTS THEM BACK, not merely that someone is dead",
      seen?.[0]?.wantedBy === "Their Ally");
  }
  check("270: the dead are looked up in the FULL roster — `living` excludes them by definition",
    /const dead = roster\.find\(f => f\.id === id\)/.test(wtSrc3));
  check("270: the GM block frames the asker as a quest-giver, not atmosphere",
    /WANTING THEM BACK, that person is a quest-giver/.test(readFileSync(join(root, "engine/gm.js"), "utf8")));
}

// --- SNG-272: THE WORLD-SIM CHAIN, GATED -------------------------------------------------------------
// The verification ledger (tests/verification_ledger.mjs) asked each of Erik's asks "what proves this?" and
// found NOTHING behind the whole world-simulation chain — attention, tiered budgets, real-dice contests,
// the engaged/working split, casualties, tier-gap lethality, strikes and guards. Two weeks of the
// most-worked-on system in the game, entirely ungated. These are the missing gates.
{
  const wt = await import("../engine/worldtick.js");
  const wsrc = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const care = (arcId, dir = 1, weight = 1) => ({ arcId, dir, weight });

  // CCODE-106 — responsiveness: an arc running AGAINST you pulls harder.
  check("272/106: a figure pushes HARDER on an arc that has run against them", (() => {
    const f = { id: "f", arcAffinities: [care("quiet", 1), care("losing", 1)] };
    const ws = { arcNetPush: { quiet: 0, losing: -40 } };
    const { spent } = wt.spendAttention(f, ws, { budget: 1 });
    return spent[0]?.care.arcId === "losing";
  })());

  // CCODE-111 — attention is a DECISION, and the seat you leave is NAMED rather than silently dropped.
  check("272/111: a figure with more cares than budget LEAVES one, and the seat it left is named", (() => {
    const f = { id: "f", arcAffinities: [care("a"), care("b"), care("c")] };
    const { spent, unattended } = wt.spendAttention(f, {}, { budget: 1, personalShare: 0 });
    return spent.length === 1 && unattended.length === 2;
  })());

  // CCODE-112 — tiered budgets, and Erik's ganging-up falling out of the arithmetic.
  // ⚠️ `personalShare: 0` ISOLATES THE VARIABLE. SNG-275 reserves part of every budget for a figure's own
  // life, so these read the arc split only — the personal claim has its own gates below.
  check("272/112: budget is TIERED — a legend holds more fronts than a heroic", (() => {
    const f = { id: "f", arcAffinities: [care("a"), care("b"), care("c")] };
    const legend = wt.spendAttention(f, {}, { budget: 2, personalShare: 0 }).spent.length;
    const heroic = wt.spendAttention(f, {}, { budget: 0.5, personalShare: 0 }).spent.length;
    return legend === 2 && heroic === 1;
  })());
  check("272/112: a fractional budget buys whole fronts first, then a share of one", (() => {
    const f = { id: "f", arcAffinities: [care("a"), care("b"), care("c")] };
    const { spent } = wt.spendAttention(f, {}, { budget: 2.5, personalShare: 0 });
    return spent.length === 3 && spent[0].share === 1 && spent[1].share === 1
      && Math.abs(spent[2].share - 0.5) < 1e-9;
  })());
  check("272/112: four heroics outweigh one legend — ganging up is arithmetic, not a rule", (() => {
    const f = { id: "f", arcAffinities: [care("a")] };
    const legend = wt.spendAttention(f, {}, { budget: 2, personalShare: 0 }).spent[0].share;
    const heroic = wt.spendAttention(f, {}, { budget: 0.5, personalShare: 0 }).spent[0].share;
    return heroic * 4 > legend;
  })());

  // CCODE-113 — the contest is ROLLED with the player's own dice, not decided by comparing weights.
  check("272/113: an arc contest rolls REAL battleRounds, not a weight comparison",
    /battleRound\(/.test(wsrc) && /export function contestArc/.test(wsrc));
  check("272/113: the same weights can produce EITHER winner — the outcome is not predetermined", (() => {
    const sbEng = JSON.parse(readFileSync(join(root, "content/packs/core/rules/skill_battle_system.json"), "utf8")).engine;
    const pro = { id: "p", name: "Pro", legend: { weight: 6 } };
    const con = { id: "c", name: "Con", legend: { weight: 6 } };
    const winners = new Set();
    let seed = 1; const rng = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
    for (let i = 0; i < 60; i++) {
      const r = wt.contestArc({ pro, con, sb: sbEng, rules, steps: {}, rng });
      if (r && r.winner) winners.add(r.winner);
    }
    return winners.size === 2;
  })());

  // CCODE-115 — most people work at a thing; some fight over it. The heavier side draws allies in.
  // SNG-300: the quota became a PER-FIGURE roll, so the assertion moves from the mechanism to the outcome —
  // most still work, a minority still fight, and now WHICH figures depends on who they are.
  check("272/115: most figures WORK at an arc; a minority FIGHT over it",
    /const engageRate = Number\.isFinite\(cfg\.directEngagementRate\)/.test(wsrc)
    && /\(rng\(\) < engageOf\(e\.f\) \? engaged : working\)\.push\(e\)/.test(wsrc));
  check("272/115: a heavier figure draws in allies until the sides are comparable",
    /while \(bw < aw \* 0\.75 && qq\.length\)/.test(wsrc) && /while \(aw < bw \* 0\.75 && pq\.length\)/.test(wsrc));
  check("272/115: working is the safe small option — a fight moves an arc more, or less than nothing",
    /const workMult = Number\.isFinite\(cfg\.indirectPushMult\)/.test(wsrc));

  // CCODE-117/118 — fights cost something, through ONE injury model, and the tier gap sets the toll.
  // ⚠️ SNG-431 §3 added the ability index as a fourth argument. The claim is "one injury model", not "this
  // call takes three parameters" — a gate spelled as an exact call signature fails when the call grows.
  check("272/117: an arc fight can COST something — one injury model, not two",
    /casualtyRate/.test(wsrc) && /resolveEpicClash\(wf, e\.f, rng/.test(wsrc));
  check("272/118: the tier GAP decides how many a victor cuts down",
    /const reachByGap = cfg\.casualtyReachByGap/.test(wsrc));

  // SNG-269a — what LOSING costs depends on who beat you, not on a flat roll.
  check("272/269: what losing COSTS depends on the rank gap, not a flat roll", (() => {
    if (!/const lethal = gap >= 0 \? 0\.12 \* \(1 \+ gap\)/.test(wsrc)) return false;
    const kindsOf = (a, b) => {
      const out = new Set();
      let seed = 7; const rng = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
      for (let i = 0; i < 600; i++) out.add(wt.resolveEpicClash(a, b, rng).kind);
      return out;
    };
    const big = { id: "L", name: "L", tier: "legendary", legend: { weight: 9 } };
    const small = { id: "h", name: "h", tier: "heroic", legend: { weight: 1 } };
    return kindsOf(big, small).has("killed");
  })());

  // SNG-270a / SNG-303b — the quiet work and the crusade.
  //
  // ⚠️ THESE TWO USED TO BE REGEXES AGAINST worldtick.js, AND THAT IS WHY THE BUG SURVIVED. Both matched
  // happily for the mechanic's entire life while the striker was drawn from the WRONG POOL — `engaged`
  // instead of `working` — which gave a figure a duel and a knife in the same pass and locked the concealment
  // traditions out of the mechanic built for them. A source pattern proves a line was typed. `planStrike` is
  // extracted precisely so the DECISION can be called, and these now call it.
  {
    const mk = (id, over = {}) => ({ f: { id, tradition: over.tradition || "valley_craft", weight: over.weight ?? 5,
      wantArcId: over.wantArcId || null, ...over.f }, share: 1, urgency: over.urgency ?? 1, care: { arcId: "A", dir: "pro" } });
    // ⚠️ `rng` is called TWICE — once to fire the strike, once for the guard. A "never" rng does not produce
    // an un-intercepted strike, it produces NO strike, and `plan` comes back null. I wrote that first and the
    // block threw on `null.interceptChance`, taking every check after it with it.
    const always = () => 0;                       // fires the strike, and the guard turns it aside

    // 1. THE STRIKER IS NOT IN THE MELEE. A side with everyone engaged and nobody working sends no one.
    const noWorkers = wt.planStrike({ attackers: { engaged: [mk("fighter")], working: [] },
      defenders: { engaged: [], working: [mk("mark")] }, arcId: "A", rng: always });
    const fromWorking = wt.planStrike({ attackers: { engaged: [mk("fighter")], working: [mk("quiet")] },
      defenders: { engaged: [], working: [mk("mark")] }, arcId: "A", rng: always });
    check("272/270: the striker comes from the WORKING pool — a side that is all melee sends nobody",
      noWorkers === null && fromWorking?.sender?.f?.id === "quiet");

    // 2. A strike still reaches the back line — the mark is a WORKER, never a fighter.
    check("272/270: a strike reaches the population combat structurally cannot",
      fromWorking?.mark?.f?.id === "mark");

    // 3. A guard can turn it aside, and the guard is a defender who is not the mark.
    const guarded = wt.planStrike({ attackers: { engaged: [], working: [mk("s")] },
      defenders: { engaged: [], working: [mk("mark", { weight: 9 }), mk("shield")] }, arcId: "A", rng: always });
    check("272/270: a guard can INTERCEPT a strike, and standing still is its own cost",
      guarded?.guarded === true && guarded.guard.f.id === "shield" && guarded.mark.f.id === "mark");

    // 4. SNG-303b — DISPOSITION IS READ. A tradition at 0 never sends anyone, however urgent.
    const cfg0 = { byTradition: { stillhold: 0 } };
    check("303b: a tradition with strikes disposition 0 sends nobody",
      wt.planStrike({ attackers: { engaged: [], working: [mk("s", { tradition: "stillhold" })] },
        defenders: { engaged: [], working: [mk("m")] }, arcId: "A", strikeCfg: cfg0, rng: always }) === null);

    // 5. THE TWO KINDS EXIST, and the crusade only fires on the arc the crusader most wants.
    const cCfg = { kindByTradition: { blazeborn: "crusade" } };
    const wrongArc = wt.planStrike({ attackers: { engaged: [], working: [mk("z", { tradition: "blazeborn", wantArcId: "OTHER" })] },
      defenders: { engaged: [], working: [mk("m")] }, arcId: "A", strikeCfg: cCfg, rng: always });
    const rightArc = wt.planStrike({ attackers: { engaged: [], working: [mk("z", { tradition: "blazeborn", wantArcId: "A" })] },
      defenders: { engaged: [], working: [mk("m")] }, arcId: "A", strikeCfg: cCfg, rng: always });
    check("303b: a crusade fires ONLY on the arc the crusader most wants (offence is distance from what you want)",
      wrongArc === null && rightArc?.kind === "crusade");
    // ⚠️ AEVI'S SHAPE, AT AEVI'S PATH. She authored `{quiet:[...], crusade:[...], either:[...]}` at
    // `arcResponse.kindByTradition`; this module read `{tradition:"quiet"}` at `arcResponse.strikes.
    // kindByTradition` — a miss on BOTH path and shape, so 910 strikes produced 0 crusades against a fully
    // authored table. The READER moved, because a list-per-kind is how a person writes this and it can say
    // `either`, which a tradition→kind map cannot express at all.
    {
      const { loadContentHeadless: lch } = await import("./headless_content.mjs");
      const liveContent = await lch();
      const live = wt.normalizeStrikeKinds(liveContent.rules?.arcResponse || {});
      const vals = Object.values(live);
      check("303c: the AUTHORED strike kinds reach the engine — both shape and path",
        Object.keys(live).length >= 20 && vals.filter(v => v === "crusade").length > 0 && vals.filter(v => v === "quiet").length > 0);
      // both shapes, so neither author nor reader has to remember which one this file uses
      check("303c: kind→[traditions] and tradition→kind both normalize to the same answer",
        wt.normalizeStrikeKinds({ kindByTradition: { crusade: ["blazeborn"] } }).blazeborn === "crusade"
        && wt.normalizeStrikeKinds({ strikes: { kindByTradition: { blazeborn: "crusade" } } }).blazeborn === "crusade");
      check("303c: authoring notes (_note, _reasoning) are not mistaken for traditions",
        !("_note" in wt.normalizeStrikeKinds({ kindByTradition: { _note: "x", quiet: ["umbral"] } })));
      // ⛔ `either` is resolved by circumstance, not a coin: they declare over what they most want.
      const k = { somatic: "either" };
        // ⚠️ AND THE COVERAGE REPORT MUST AGREE WITH THE MECHANIC. `strikeCoverage` read the old path and the
      // old shape, so after the reader moved it kept printing "no tradition is authored as a crusader, the
      // declared kind never fires" while 279 crusades per run were firing. A report that contradicts the
      // thing it reports on is worse than none — it is aimed at the person deciding whether to author.
      check("303c: the coverage report AGREES with the reader — no crusader claim while crusades fire", (() => {
        const cov = wt.strikeCoverage(liveContent.rules?.arcResponse || {}, liveContent.legends?.roster || []);
        const declaring = Object.values(live).filter(v => v === "crusade" || v === "either").length;
        return cov.bothKindsLive === (declaring > 0) && cov.crusadeTraditions > 0;
      })());
        check("303c: an `either` tradition DECLARES over the arc it most wants and goes quiet elsewhere",
        wt.strikeKindFor({ tradition: "somatic", wantArcId: "A" }, k, { arcId: "A" }) === "crusade"
        && wt.strikeKindFor({ tradition: "somatic", wantArcId: "B" }, k, { arcId: "A" }) === "quiet");
    }

    check("303b: an unauthored tradition is QUIET — the shipped behaviour, not an invented crusade",
      fromWorking?.kind === "quiet");

    // 6. THE METHOD MEANS SOMETHING: you can stand in front of what you can see coming.
    const q = wt.planStrike({ attackers: { engaged: [], working: [mk("a")] },
      defenders: { engaged: [], working: [mk("m"), mk("g")] }, arcId: "A", rng: always });
    const c = wt.planStrike({ attackers: { engaged: [], working: [mk("b", { tradition: "blazeborn", wantArcId: "A" })] },
      defenders: { engaged: [], working: [mk("m"), mk("g")] }, arcId: "A", strikeCfg: cCfg, rng: always });
    check("303b: a DECLARED crusade is easier to intercept than a knife nobody knew about",
      c.interceptChance > q.interceptChance);

    // 7. EXPOSURE HAS TEETH: a known striker is worth reaching for, over a heavier unknown one.
    const plain = wt.planStrike({ attackers: { engaged: [], working: [mk("a")] },
      defenders: { engaged: [], working: [mk("big", { weight: 8 }), mk("known", { weight: 5 })] }, arcId: "A", rng: always });
    const withExp = wt.planStrike({ attackers: { engaged: [], working: [mk("a")] },
      defenders: { engaged: [], working: [mk("big", { weight: 8 }), mk("known", { weight: 5 })] },
      arcId: "A", exposure: { known: { untilDay: 999 } }, rng: always });
    check("303b: an EXPOSED figure is preferred as a mark — a failed quiet strike identifies you",
      plain.mark.f.id === "big" && withExp.mark.f.id === "known");

    // 8. COMMITMENT: a crusade collapses every other care, which is what creates the vacancies.
    const wsC = { crusades: { z: { arcId: "A", dir: "pro" } } };
    const many = { id: "z", arcAffinities: [{ arcId: "A", dir: "pro" }, { arcId: "B", dir: "con" }, { arcId: "C", dir: "pro" }] };
    check("303b: a crusader's cares collapse to the one arc — every other front becomes a vacated seat",
      wt.currentCares({}, many).length === 3 && wt.currentCares(wsC, many).length === 1
      && wt.currentCares(wsC, many)[0].arcId === "A" && wt.currentCares(wsC, many)[0].dir === "pro");
    // ⚠️ AND THE SHAPE IS THE ONE `affinitiesOf` ACCEPTS. A crusade care missing `dir` is filtered straight
    // back out and the whole commitment cost silently does not happen — that exact mistake, on that exact
    // field, has been made three times in this file.
    check("303b: a malformed crusade record does NOT silently replace a figure's real cares",
      wt.currentCares({ crusades: { z: { arcId: "A" } } }, many).length === 3);
  }

  // SNG-304 — THE HOLDING STREAK. Erik: "a streak of holding could give an edge… something that builds to a
  // point. It would get dropped down if interrupted." Aevi's `heldTheLine`, and it is the answer to SNG-300's
  // finding that six of seven deed sources needed a fight and the seventh paid for sacrifice, never for work.
  {
    check("304: a hold builds an edge, and it BUILDS TO A POINT",
      wt.holdEdge(0) === 1 && Math.abs(wt.holdEdge(1) - 1.1) < 1e-9 && Math.abs(wt.holdEdge(5) - 1.5) < 1e-9
      && wt.holdEdge(50) === wt.holdEdge(5));
    check("304: the cap and the per-pass edge are content dials, not constants",
      Math.abs(wt.holdEdge(2, { perPass: 0.25, cap: 2 }) - 1.5) < 1e-9 && wt.holdEdge(9, { perPass: 0.1, cap: 0.2 }) === 1.2);

    // ⚠️ TWO DIFFERENT LOSSES, TWO DIFFERENT PRICES — the distinction Aevi drew explicitly.
    const ws = { careHeld: { a: { arc1: 5, arc2: 3 } } };
    wt.halveHold(ws, "a");
    check("304: being DRIVEN OFF halves the hold — it does not wipe it",
      ws.careHeld.a.arc1 === 2 && ws.careHeld.a.arc2 === 1);
    check("304: halving an unknown figure is a no-op, not a crash", (() => {
      try { wt.halveHold({}, "nobody"); wt.halveHold(null, "x"); return true; } catch { return false; }
    })());

    // ⚠️ AND IT MUST BE PAID AT THE ONE PLACE EVERY WOUND GOES THROUGH. Wiring it at the call sites means the
    // next way of hurting somebody silently does not pay it — which is how a rule stops applying to the
    // newest thing in the game. A stalemate drove nobody anywhere and must NOT halve.
    const wsW = { careHeld: { L: { arc1: 4 } }, epicStatus: {} };
    wt.applyEpicClashOutcome(wsW, { id: "W", name: "W" }, { id: "L", name: "L" }, "wounded", 10);
    const wsS = { careHeld: { L: { arc1: 4 } }, epicStatus: {} };
    wt.applyEpicClashOutcome(wsS, { id: "W", name: "W" }, { id: "L", name: "L" }, "stalemate", 10);
    check("304: a wound halves the loser's hold; a stalemate drove nobody anywhere and does not",
      wsW.careHeld.L.arc1 === 2 && wsS.careHeld.L.arc1 === 4);

    // ⚠️ THE RELATIONSHIP, NOT THE NUMBER — my own instance of the class Aevi's red gate exposed. `=== 3`
    // locks a tuning value; what the design actually says is "holding a front for five passes is worth what
    // winning a contest is worth", which is a claim about EQUALITY and survives any retune of either.
    check("304: holding pays a DEED at all — the ledger had six combat sources and one for sacrifice",
      wt.DEED_WEIGHTS.heldTheLine > 0 && wt.DEED_WEIGHTS.heldTheLine === wt.DEED_WEIGHTS.arcContestWon);

    // ⚠️ THE DEFAULT IS AEVI'S SPEC AS WRITTEN, not my inference from it. I built the repeating version first
    // and measured it: `heldTheLine` became 41% of all deed credits against arcContestWon's 11%, and the mean
    // rise rate went to 78% for everyone, because a 185-pass hold pays 37 times. Her one-shot version closes
    // the same gap at 2% of credits. The choice is a dial; the DEFAULT is what she actually wrote.
    check("304: a hold pays ONCE by default — Aevi's spec, not the stronger reading of it",
      wt.holdDeedDue(5) === true && wt.holdDeedDue(10) === false && wt.holdDeedDue(4) === false);
    check("304: …and `deedRepeats` turns the repeating version back on",
      wt.holdDeedDue(10, 5, true) === true && wt.holdDeedDue(15, 5, true) === true && wt.holdDeedDue(7, 5, true) === false);
    check("304: a zero or negative streak never pays", wt.holdDeedDue(0) === false && wt.holdDeedDue(-3, 5, true) === false);
  }

  // SNG-306 — THE PRICE OF STANDING HIGH. Erik: "between arc pushes there are ever present assassination
  // risks — duel to the death challenges etc. we can use these to keep the Mythicals under control."
  {
    const f = (id, tier) => ({ id, name: id, tier });
    const tierFn = x => x.tier;
    const cfg = { challengeByTier: { mythic: 1, legendary: 1, epic: 0.5, heroic: 0, notable: 0, riffraff: 0 } };
    const pool = [f("M", "mythic"), f("L", "legendary"), f("E", "epic"), f("H", "heroic"), f("R", "riffraff")];

    check("306: a rung with rate 0 is never called out — the ceiling is a dial, not a constant",
      wt.planChallenge({ figure: f("H", "heroic"), pool, tierOf: tierFn, cfg, rng: () => 0 }) === null);

    // ⚠️ THE CHALLENGER COMES FROM BELOW. Someone must have something to GAIN — a peer or better has no
    // reason to call you out, and this is the whole shape of "standing high is what draws them".
    const p = wt.planChallenge({ figure: f("M", "mythic"), pool, tierOf: tierFn, cfg, rng: () => 0 });
    check("306: the challenger comes from BELOW — someone with something to gain",
      !!p && p.challenger.id === "L");

    // …and not from far below. `challengerReach` is the window; a riffraff does not call out a mythic.
    const far = wt.planChallenge({ figure: f("M", "mythic"), pool: [f("M", "mythic"), f("R", "riffraff")],
      tierOf: tierFn, cfg, rng: () => 0 });
    check("306: …but not from FAR below — a riffraff does not call out a mythic", far === null);

    // ⛔ DIRECTIVE SNG-280 — PROMINENCE, NOT MERIT. Two mythics who differ in every way that could be
    // moralised must be challenged identically. What draws a challenger is being worth beating.
    const saint = { id: "S", name: "S", tier: "mythic", tradition: "stillhold", alignment: "hero" };
    const horror = { id: "X", name: "X", tier: "mythic", tradition: "abyssal", alignment: "villain" };
    const rate = (who) => {
      let n = 0;
      for (let i = 0; i < 400; i++) {
        let c = 0; const rng = () => [(i % 20) / 20, 0.5][c++] ?? 0.5;
        if (wt.planChallenge({ figure: who, pool: [who, f("L", "legendary")], tierOf: tierFn, cfg, rng })) n++;
      }
      return n;
    };
    check("306: prominence draws the challenge, not merit — a saint and a horror at the same rung are equal",
      rate(saint) === rate(horror) && rate(saint) > 0);
  }

  // SNG-306b — ERIK: "the successors have home lands; it's just that the MOMENT mints them in the game."
  //
  // ⚠️ I GATED THE WRONG THING FIRST. Reading "they don't come from the field they died in" as "delete the
  // battlefield mint", I wrote `306b: nobody is born of the killing field itself` — and Erik's correction was
  // that people SHOULD be minted at the battle; what they need is a HOME they came from. That gate asserted
  // the opposite of the requirement and would have locked the mistake in, which is the worst thing a green
  // gate can do. Minting is when somebody ENTERS THE STORY, not when they come into existence.
  //
  // ⚠️ THIS ONE HAS TO RUN A WORLD, because the claim is about what a real run produces. It drives a short
  // seeded world with the casualty dial up (to guarantee deaths, and therefore mints) and inspects who
  // was born.
  {
    const { loadContentHeadless } = await import("./headless_content.mjs");
    const C = await loadContentHeadless();
    const bloody = { ...C, rules: { ...C.rules, arcResponse: { ...(C.rules.arcResponse || {}), casualtyRate: 0.5, mintRate: 1 } } };
    let s = 12345; const rng = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
    const ch = { name: "mintprobe", level: 6, clock: { day: 1 }, actionCount: 0, npcRegistry: {},
      quests: [], abilities: [], deeds: [], worldState: wt.initWorldState(1) };
    delete ch.worldState.lastTickWorldDay;
    const stub = async ({ entities }) => ({ developments: entities.map(e => ({ entityId: e.id, note: "x", outcome: "progress" })) });
    const t0 = Date.now();
    // ⛔ SNG-431 §3: the news is COLLECTED as it is produced, not read off `ws.news` afterwards. That log is
    // capped at 20 and keeps the LAST 20, so a fight early in a two-year run is evicted by ordinary chatter
    // — and a gate reading the tail then passes VACUOUSLY over an empty list. Four of mine did exactly that
    // before this line existed: `[].every(…)` is true, so "every fight names both figures" was green in a
    // world with no fights in it.
    const allNews = [];
    for (let d = 0; d < 730; d += 7) {  // ⚠️ REAL DAYS — world time is wall-clock-derived, not clock.day
      const out = await wt.advanceGeneratedOffscreen({ character: ch, content: bloody, evolveFn: stub, rng, now: t0 + d * 24 * 3600000 });
      for (const n of (Array.isArray(out) ? out : (out?.news || []))) allNews.push(n);
    }
    const minted = ch.worldState.mintedFigures || [];
    console.log(`      mint probe: ${minted.length} born, kinds: ${[...new Set(minted.map(m => m.originKind))].join(", ") || "(none)"}`);

    check("306b: a bloody world still mints — the probe reaches the code under test", minted.length > 0);
    // ⚠️ THE MOMENT MINTS THEM. Both birth events are real: the one who survived it and the one sent to take
    // the chair. A world that only produces successors has quietly decided the battlefield introduces nobody.
    check("306b: the moment mints them — BOTH the survivor and the successor are born into the story",
      minted.some(m => m.originKind === "casualty_survivor") && minted.some(m => m.originKind === "faction_leaderless"));
    // …and everyone knows where they are FROM. Tradition stands in for home until `homeLocation` is authored
    // on more than 5 of 66; the origin line names the truest thing available either way.
    check("306b: every figure the world mints from a death has a homeland — nobody comes from nowhere",
      minted.filter(m => m.originKind === "casualty_survivor" || m.originKind === "faction_leaderless")
        .every(m => !!m.homeland));
    // ⚠️ `m.origin`, NOT `m.wants`. These read `wants` because `wants` HELD the origin — which is the §1b
    // fault, not the contract. The field they were always about is `origin`, populated all along. ⛔ AND THE
    // ARTICLE IS THE PLACE'S, NOT THE TEMPLATE'S: "of the Ceaseless" but "of Millbrook", so a gate that
    // insists on "of the …" is asserting the bug it was written beside.
    check("306b: …and the origin line SAYS where, so a narrator can tell it without inventing one",
      minted.some(m => /^of .+; (survived|was standing|was with|watched)/.test(m.origin || ""))
      && minted.some(m => /^sent by .+ to take up/.test(m.origin || "")));
    // ⚠️ AND IT SAYS **HOW**. Erik: "'walked away from it' is ambiguous" — and in a world where abandoning a
    // front is a real mechanic, it reads as desertion rather than survival. The engine knows which of the
    // three ways the figure died, so the line names it: no minted origin may use the ambiguous phrasing.
    const survivors = minted.filter(m => m.originKind === "casualty_survivor");
    check("306b: a survivor's origin names WHAT they survived — never the ambiguous 'walked away from it'",
      survivors.length > 0 && survivors.every(m => !/walked away/.test(m.origin || ""))
      && survivors.every(m => /(survived the fighting|standing beside|was with|watched)/.test(m.origin || "")));

    // ── SNG-431 §1 — ONE NAMER. Aevi's three gates, plus the §1b faults, on this same live world. ────────
    // ⚠️ THE RULES ARE IMPORTED, NOT RE-SPELLED. `PLACEHOLDER_NAME` and `MINTED_NAME_MAX` come from the
    // module the WRITER uses; a gate carrying its own copy of the rule goes green while the writer drifts.
    const N431 = await import("../engine/names.js");
    console.log(`      namer: ${minted.filter(m => !m.provisional).length}/${minted.length} named — e.g. ${minted.slice(0, 3).map(m => m.name).join(" · ")}`);

    // ⛔ REGISTERED AND LOADED, PROVED THROUGH THE REAL BAG. The pools were authored at 5ba1c26f and reachable
    // by nothing: not in the manifest, so not merely unloaded — invisible one step earlier than CCODE-55 looks.
    // ── SNG-432 — THE ORIGIN SHARPENS THE BYNAME, now that the tone is marked. ───────────────────
    {
      const P432 = C.rules?.mintedNames || {};
      const toneOf = (trad, txt) => (P432.byname?.[trad] || []).find(b => b.text === txt)?.tone || null;
      // ⛔ A POOL ENTRY IS A STRING **OR** `{text, tone}`. This reader filtered on `typeof x === "string"`,
      // so the day Aevi marked all 146 bynames every pool read as EMPTY and NOBODY could be named — 36 of 36
      // figures provisional. Caught by the §1 gates, which is the entire reason they exist.
      check("432: a byname pool authored as {text, tone} still names people",
        (() => { const m = N431.mintedName({ tradition: "ashwarden", originKind: "casualty_survivor", pools: P432, rng: () => 0.1 });
          return !!m && /^\w+ the \w/.test(m.name); })(),
        "the pools changed shape and the reader must accept both");
      // Aevi: survivor → dark, successor → formal, vacancy → plain.
      const drew = (trad, ok) => { const t = []; for (let i = 0; i < 6; i++) { const m = N431.mintedName({ tradition: trad, originKind: ok, pools: P432, rng: () => (i * 0.17) % 1, taken: t.map(x => x.name) }); if (m) t.push(m); } return t; };
      // ⚠️ `.length > 0 &&` — `[].every(…)` is TRUE, so a namer that returned nothing at all would pass
      // every tone check below while naming nobody. That is the same vacuous pass §3 already caught once.
      const toneRun = (trad, ok, want) => { const d = drew(trad, ok); return d.length > 0 && d.every(m => toneOf(trad, m.byname) === want); };
      check("432: a survivor is named for what it COST, a successor for the OFFICE they now hold",
        toneRun("ashwarden", "casualty_survivor", "dark") && toneRun("ashwarden", "faction_leaderless", "formal")
        && toneRun("ashwarden", "vacancy_filled", "plain"),
        `survivor=${drew("ashwarden", "casualty_survivor").map(m => m.byname).join("/")}`);
      // ⛔ PREFER, NOT REQUIRE (Aevi): "a tradition-correct name of the WRONG tone beats a generic one of the
      // right tone every time." Umbral has no `formal` entry at all, so a successor there must still be
      // UMBRAL — never one of the `_default` pool's three.
      const umbralTexts = new Set((P432.byname?.umbral || []).map(b => b.text));
      check("432: …and a tradition with no entry of that tone falls back INSIDE itself, never to _default",
        (P432.byname?.umbral || []).every(b => b.tone !== "formal")
        && drew("umbral", "faction_leaderless").length > 0
        && drew("umbral", "faction_leaderless").every(m => umbralTexts.has(m.byname)),
        `umbral successors drew: ${drew("umbral", "faction_leaderless").map(m => m.byname).join(", ")}`);
      // ⚠️ AND AN UNEVEN DISTRIBUTION IS AUTHORED, NOT A GAP. Aevi: "churnfolk are all plain and that is
      // correct — a people of improvised everything do not hold offices and do not brood. If a tone split ever
      // comes out even across traditions, something has been generated rather than authored."
      check("432: churnfolk are all plain — the distribution is authored and must not be evened out",
        (P432.byname?.churnfolk || []).length > 0 && (P432.byname.churnfolk).every(b => b.tone === "plain"));
      const tones = {};
      for (const list of Object.values(P432.byname || {})) for (const b of list) tones[b.tone] = (tones[b.tone] || 0) + 1;
      console.log(`      tones: ${JSON.stringify(tones)} across ${Object.keys(P432.byname || {}).length} traditions`);
      check("432: every byname carries a tone — an unmarked one silently never gets preferred",
        Object.values(P432.byname || {}).every(list => list.every(b => ["dark", "formal", "plain"].includes(b.tone))),
        `unmarked: ${Object.entries(P432.byname || {}).flatMap(([k, l]) => l.filter(b => !b.tone).map(b => k + ":" + b.text)).slice(0, 3).join(", ")}`);
    }

    check("431/1a: the name pools are REACHABLE — in the manifest, loaded, and merged into `rules`",
      !!C.rules?.mintedNames?.given && !!C.rules?.mintedNames?.byname,
      `rules.mintedNames = ${JSON.stringify(Object.keys(C.rules?.mintedNames || {}))}`);

    // ⚠️ AND THE ASSERTION IS WHAT THIS PATH CAN ACTUALLY GET WRONG. Written as Aevi's disclaimer regex
    // alone, no mutation of the mint could redden it — the mint has never produced the word "unknown"; the
    // disclaimers are the GM path's, and that gate is proved on the GM path. What THIS path gets wrong is
    // shipping the fallback or the epithet in the name field, so the census says so and stays falsifiable.
    const unnamedIsh = (m) => N431.PLACEHOLDER_NAME.test(m.name || "") || m.name === "someone newly spoken of" || m.name === m.epithet;
    check("431/1: nobody the world mints is left holding a fallback, an epithet or a disclaimer for a name",
      minted.length > 0 && !minted.some(unnamedIsh),
      `offenders: ${minted.filter(unnamedIsh).map(m => m.name).slice(0, 3).join(" | ")}`);

    // ⛔ `provisional: true` WAS THE ENGINE FLAGGING ITS OWN GAP AND NOTHING READ IT (Aevi) — the same shape
    // as `parentUnresolved` in SNG-397. Something came back to author, so the flag must now be false.
    check("431/1: no roster figure is still `provisional` after a tick",
      minted.length > 0 && minted.every(m => !m.provisional),
      `${minted.filter(m => m.provisional).length} of ${minted.length} still provisional`);

    check("431/1: no minted name runs over 40 characters — a name that long is a sentence",
      minted.length > 0 && minted.every(m => (m.name || "").length <= N431.MINTED_NAME_MAX),
      `longest: ${minted.map(m => m.name || "").sort((a, b) => b.length - a.length)[0]}`);

    // ⛔ AND IT IS A NAME, NOT A CAPTION OR A SUBTITLE — Erik's shape, which Aevi got wrong twice before he
    // named it: NAME + THE + SHORT NOUN PHRASE. No verb, no "who", no clause. The battlefield-shout test.
    // ⚠️ AND THE GATE IS HERS, NOT A STRICTER ONE OF MINE. My first cut allowed two words after "the" and
    // went red on "Orla the No Fixed Anchor" — a byname SHE AUTHORED, and her rule says "two or three
    // words". A gate that fails on the content it polices is asserting my taste, not the standard. The
    // load-bearing half is the second clause: no verb, no "who", no comma — that is what made v1 a caption
    // and v2 a subtitle, and the 40-char gate above already holds the length.
    const SHOUTABLE = /^[A-Z][\w'’-]*( [A-Z][\w'’-]*)? the [\w'’-]+( [\w'’-]+){0,2}$/;
    // ⚠️ AND NO "NO VERB" HEURISTIC. My first attempt at it was `\w+(ed|ing)` and it went red on "the
    // Scarred", "the Burning Truth", "the No Fixed Anchor" — participles used as ADJECTIVES, which is what
    // half the corpus is and what "Gandalf the White" is. What actually separated Aevi's v1 and v2 from a
    // name was the RELATIVE CLAUSE: "the one WHO outlived…", "Sera Voight, WHO SHOULD HAVE DIED FIRST".
    const CLAUSE = /\b(who|which|that|when|after|because)\b|[,;:—]/i;
    check("431/1: a minted name is NAME + THE + SHORT NOUN PHRASE — shoutable, not a caption or a subtitle",
      minted.length > 0 && minted.every(m => SHOUTABLE.test(m.name || "") && !CLAUSE.test(m.name || "")),
      `not shoutable: ${minted.filter(m => !SHOUTABLE.test(m.name || "") || CLAUSE.test(m.name || "")).map(m => m.name).slice(0, 3).join(" | ")}`);

    // ⛔ NOBODY CARRIES A NAME SOMEONE ELSE ALREADY HAS. A pool draw with no dedupe is two Sera the Ashvows.
    check("431/1: two minted figures never end up with the same name",
      new Set(minted.map(m => String(m.name).toLowerCase())).size === minted.length,
      `${minted.length - new Set(minted.map(m => String(m.name).toLowerCase())).size} collision(s)`);

    // §1b — the three other faults in the same record.
    check("431/1b: `wants` holds a WANT, not the origin sentence",
      minted.length > 0 && minted.every(m => m.wants && m.wants !== m.origin && !/^(of |sent by |stepped into |survived |was |watched |took up )/.test(m.wants)),
      `offenders: ${minted.filter(m => !m.wants || m.wants === m.origin).map(m => m.wants).slice(0, 2).join(" | ")}`);
    check("431/1b: the origin line shows a player NAMES, NOT IDS — and never a double article",
      minted.length > 0 && minted.every(m => !/\b[a-z][a-z0-9]*_[a-z0-9]+\b/.test(m.origin || "") && !/\bthe the\b/i.test(m.origin || "")),
      `offenders: ${minted.filter(m => /\b[a-z][a-z0-9]*_[a-z0-9]+\b/.test(m.origin || "") || /\bthe the\b/i.test(m.origin || "")).map(m => m.origin).slice(0, 2).join(" | ")}`);
    // ⛔ THE EPITHET STAYS — as `epithet`, where it belongs (Aevi). It was never wrong, only mis-filed.
    check("431/1b: the epithet the event produced is KEPT, in its own field",
      minted.length > 0 && minted.every(m => !!m.epithet),
      `${minted.filter(m => !m.epithet).length} figure(s) lost their epithet`);

    // ── SNG-431 §2 — THE LADDER RUNS BOTH WAYS. Measured on this same world. ────────────────────────────
    // ⛔ THE MEASUREMENT IS THE GATE. Aevi's finding was a COUNT — heroic ×6, epic ×2, legendary ×1 demoted,
    // zero promotions — so a gate asserting "demotion is possible" would restate the bug. It asserts the
    // shape of the ladder over a real run instead.
    const RANK = { riffraff: 0, notable: 1, heroic: 2, epic: 3, legendary: 4, mythic: 5 };
    const born = (f) => f.tier ?? f.legend?.tier;
    const rosterNow = wt.worldRoster(ch.worldState, bloody);
    const moved = rosterNow.map(f => ({ f, from: born(f), to: ch.worldState.figureTier?.[f.id] }))
      .filter(x => x.from && x.to && x.to !== x.from);
    const up = moved.filter(x => RANK[x.to] > RANK[x.from]).length;
    const down = moved.filter(x => RANK[x.to] < RANK[x.from]).length;
    console.log(`      ladder: ${up} up · ${down} down · ${Object.keys(ch.worldState.figureDormant || {}).length} dormant · ${Object.keys(ch.worldState.figureWokeDay || {}).length} woke`);
    check("431/2: the ladder goes UP more than it goes down — 9 falls and 0 rises is the bug",
      up > down, `${up} up vs ${down} down`);

    // ⛔ SILENCE MAKES A FIGURE DORMANT, NOT LESSER — the spec's own rule, correctly applied. They keep the
    // rank; they stop costing the tick anything.
    const lossLog = ch.worldState.tierLossLog || [];
    check("431/2: every rung that was lost was taken by an EVENT, and the event is on the record",
      lossLog.length > 0 && lossLog.every(l => wt.DEMOTION_EVENTS.includes(l.reason)),
      `reasons seen: ${JSON.stringify([...new Set(lossLog.map(l => l.reason))])}`);
    check("431/2: a dormant figure keeps the rank they had — dormancy is not a demotion",
      Object.entries(ch.worldState.figureDormant || {}).every(([id, d]) =>
        !ch.worldState.figureTier?.[id] || ch.worldState.figureTier[id] === d.tier
        || lossLog.some(l => l.id === id)),
      `${Object.keys(ch.worldState.figureDormant || {}).length} dormant`);

    // ⛔ AND DORMANT IS NOT A GRAVE. On a probe with no player attention at all, NOT ONE figure ever woke —
    // the wake condition read the news, and a dormant figure does not act, so it can never appear in the
    // news that would wake it. A death opening a seat is the world's own door.
    check("431/2: dormancy has a door out — attention brings them back at the rank they kept",
      Object.keys(ch.worldState.figureWokeDay || {}).length > 0,
      `${Object.keys(ch.worldState.figureDormant || {}).length} asleep, none ever woke`);

    // ⛔ AND THE THING DORMANCY IS FOR: THEY DROP OUT OF THE TICK. "Never deleted… drops out of world-tick
    // and proactive GM reference" is the spec's own wording, and nothing gated it — deleting the
    // `!isDormant` filter from `living` left every check above green, because they all measure RANK and this
    // one is about SPENDING. A dormant figure's arc push may not move.
    {
      const pushOf = (id) => ch.worldState.epicArcPushes?.[id]?.push;
      const asleep = Object.keys(ch.worldState.figureDormant || {});
      const before = Object.fromEntries(asleep.map(id => [id, pushOf(id)]));
      await wt.advanceGeneratedOffscreen({ character: ch, content: bloody, evolveFn: stub, rng, now: t0 + 1470 * 24 * 3600000 });
      const stillAsleep = asleep.filter(id => ch.worldState.figureDormant?.[id]);
      const moved2 = stillAsleep.filter(id => !Object.is(pushOf(id), before[id]));
      check("431/2: a dormant figure drops OUT OF THE TICK — the world stops spending on them",
        stillAsleep.length > 0 && moved2.length === 0,
        `${moved2.length} of ${stillAsleep.length} dormant figures still pushed an arc`);

      // ⛔ AND A DIRECTION IS A SIGNED NUMBER. This gate exists because the one above went red on real code
      // and I nearly wrote it off as a `!==` quirk: two figures compared NaN-to-NaN. They were NaN because
      // eight authored rows spell `dir` as `"+"`/`"-"`, and `"-" * weight` is NaN — a permanently dead push,
      // AND `"+" > 0` is false, so a figure authored to push FOR a thing was counted against it.
      const pushes = Object.entries(ch.worldState.epicArcPushes || {});
      check("431/2: no figure carries a dead arc push — a direction is a signed number, whatever it was spelled",
        pushes.length > 0 && pushes.every(([, v]) => Number.isFinite(v?.push)),
        `${pushes.filter(([, v]) => !Number.isFinite(v?.push)).length} of ${pushes.length} pushes are not finite: ${pushes.filter(([, v]) => !Number.isFinite(v?.push)).map(([k]) => k).slice(0, 3).join(", ")}`);
      // ⚠️ AND THE CENSUS ABOVE CANNOT PROVE THE NORMALISER, because the eight rows are fixed now — with
      // clean content there is nothing left for it to normalise, so deleting it changes nothing that probe
      // can see. The contract needs bad data on purpose.
      check("431/2: …and a sign-spelled direction still pushes the right way, at the reader",
        (() => {
          const w = {};
          const plus = wt.applyEpicArcPush(w, { id: "p", arcAffinity: { arcId: "A", dir: "+", weight: 2 } }, 1);
          const minus = wt.applyEpicArcPush(w, { id: "m", arcAffinity: { arcId: "A", dir: "-", weight: 2 } }, 1);
          return Number.isFinite(plus?.push) && plus.push > 0 && Number.isFinite(minus?.push) && minus.push < 0;
        })(),
        "a '+' or '-' in the dir field must not become NaN, and must not land on the wrong side");
      check("431/2: …and an unreadable direction is left alone rather than dropped",
        wt.dirSign("+") === 1 && wt.dirSign("pro") === 1 && wt.dirSign("-") === -1 && wt.dirSign("con") === -1
        && wt.dirSign(-2) === -2 && wt.dirSign("banana") === 0 && wt.dirSign(NaN) === 0
        && wt.affinitiesOf({ arcAffinities: [{ arcId: "A", dir: "banana" }] }).length === 1);
    }

    // ── SNG-431 §3 — FIGHTS ARE CLICKABLE. "0 OF 20 NEWS ITEMS CARRY IDS." ──────────────────────────────
    // ⛔ The measurement IS the gate, on the same live world. The death path was already correct and the
    // `wounded`/`checked`/`stalemate` paths pushed BARE STRINGS — and every fight on Erik's screen is one of
    // those three.
    {
      const stored = allNews.concat(ch.worldState.news || []);
      const fights = stored.filter(n => n.kind === "clash" || n.kind === "death");
      // ⚠️ EVERY GATE BELOW REQUIRES A FIGHT TO EXIST. `[].every(…)` is true, so without this the whole
      // section reports green on a world where nothing ever fought — which is precisely the state the
      // ticket is about.
      const someFights = fights.length > 0;
      const named = (id, bag) => bag?.[id]?.name || null;
      const roster431 = wt.worldRoster(ch.worldState, bloody);
      console.log(`      fights: ${fights.length}/${stored.length} news items` + (fights[0]
        ? ` — e.g. at ${named(fights[0].locationId, C.locations) || "?"} with ${named(fights[0].abilityId, C.abilities) || "?"}` : ""));

      check("431/3: a fight reaches the news AS a fight — a sentence and a tier is what 0-of-20 looked like",
        someFights, `${stored.length} news items, none of them a clash or a death`);
      check("431/3: every fight names BOTH figures, so the item can be opened back into the battle",
        someFights && fights.every(n => (n.winnerId || n.killerId) && (n.loserId || n.victimId)),
        `${fights.filter(n => !((n.winnerId || n.killerId) && (n.loserId || n.victimId))).length} carry no ids`);
      // ⛔ WHERE AND WITH WHAT — the two fields that make the picture possible. `homeLocation` is on 70/70
      // roster figures and every one resolves; 26 of the roster's 29 traditions have an ability pool.
      check("431/3: …and WHERE it happened, resolving to a real place",
        someFights && fights.every(n => n.locationId && C.locations?.[n.locationId]),
        `${fights.filter(n => !n.locationId).length} with no place; ${fights.filter(n => n.locationId && !C.locations?.[n.locationId]).length} unresolvable`);
      // ⚠️ A RATCHET AGAINST THE POOLS, NOT AN ABSOLUTE. Three of the roster's 29 traditions have NO
      // abilities authored (harmonic_radiant, precursor_nanite_cold_noesis, valley_craft_administration), so
      // their fights honestly record a place and no power. An invented ability id would be worse than an
      // absent one — the prompt builder would draw a craft nobody in the world has. So the gate is: every
      // fight whose winner's tradition HAS a pool records one from it, and the gap is REPORTED with a number.
      const idx431 = wt.abilityIndexOf(bloody);
      const couldName = fights.filter(n => {
        const w = roster431.find(f => f.id === (n.winnerId || n.killerId));
        return (idx431[w?.tradition || w?.legend?.tradition] || []).length > 0;
      });
      const missing431 = couldName.filter(n => !n.abilityId || !C.abilities?.[n.abilityId]);
      const poolless = fights.length - couldName.length;
      console.log(`      powers: ${couldName.length - missing431.length}/${couldName.length} named; ${poolless} fought by a tradition with no abilities authored`);
      check("431/3: …and WITH WHAT — every fight whose winner HAS a craft pool records one from it",
        someFights && missing431.length === 0,
        `${missing431.length} droppable, ${poolless} genuinely pool-less`);
      // ⛔ AND THE POWER IS THE WINNER'S OWN CRAFT. The resolver rolls its own winner while the arc-fight
      // site FORCES the contest's winner and uses the roll only for severity — so a signature picked inside
      // the resolver came from whoever the dice favoured. Measured before the fix: "The Hundred Hands bested
      // The Thornmother … with Bark and Briar", a rootkin craft in a somatic fighter's hands.
      const mismatched = fights.filter(n => {
        const w = roster431.find(f => f.id === (n.winnerId || n.killerId));
        const trad = w?.tradition || w?.legend?.tradition;
        return trad && C.abilities?.[n.abilityId] && C.abilities[n.abilityId].tradition !== trad;
      });
      check("431/3: …and the power is the winner's OWN craft, not whoever the dice happened to favour",
        someFights && mismatched.length === 0,
        mismatched.slice(0, 2).map(n => `${n.winnerId} used ${C.abilities[n.abilityId]?.tradition}`).join(" | "));
      // ⚠️ AND IT IS STABLE. A fight re-opened must be the SAME fight, or the picture changes every time.
      check("431/3: the same fight names the same power every time — the news item is a handle, not a roll",
        (() => { const idx = wt.abilityIndexOf(bloody);
          const a = { id: "x", tradition: "somatic" }, b = { id: "y", tradition: "rootkin" };
          return wt.signatureOf(a, b, idx) === wt.signatureOf(a, b, idx)
            && wt.signatureOf(a, b, idx) !== wt.signatureOf(b, a, idx); })());
      // ⛔ AND NO FIGHT ARRIVES AS "[object Object]" — the failure `clashNewsItem` exists to prevent, which
      // was latent at the fourth site for every death and would have become every clash.
      check("431/3: no fight line was flattened into '[object Object]' on its way to the news",
        someFights && stored.every(n => !/\[object Object\]/.test(String(n.text || ""))));

      // ⛔ THE CENSUS, NOT A SAMPLE. "A fight reaches the news" stayed GREEN when I mutated ONE of the three
      // outcomes back to a bare string, because the other two still arrived structured and the count was
      // still above zero. A gate on "at least one" cannot see three quarters of a feature go missing. So:
      // ANY line that READS like a fight must BE one. The wording is the engine's own, from the four
      // templates in `applyEpicClashOutcome`.
      // ⚠️ AND IT IS PER-OUTCOME, NOT A WORD-MATCH ON PROSE. My first attempt matched "bested" in the text
      // and could not tell a fight line from §2's "X was bested, and nobody has stood over Y" — a gate that
      // reads sentences keeps colliding with every sentence written near it, and it failed to redden when I
      // mutated one outcome back to a bare string. The four outcomes are DATA. Assert the data.
      const seenOutcomes = new Set(fights.map(n => n.outcome || (n.kind === "death" ? "killed" : "?")));
      const WANTED = ["killed", "wounded", "stopped", "stalemate"];
      check("431/3: ALL FOUR outcomes arrive structured — wounded, checked and stalemate are the ones Erik sees",
        someFights && WANTED.every(o => seenOutcomes.has(o)),
        `saw ${JSON.stringify([...seenOutcomes])}, missing ${WANTED.filter(o => !seenOutcomes.has(o)).join(", ")}`);

      // ⛔ AND THE STAMPER IS THE CHOKEPOINT. SNG-400 taught `stampNews` to carry the facts and TWO hand-
      // rolled copies inside `advanceGeneratedOffscreen` were never switched over — they kept four fields and
      // dropped every id, which is what Aevi actually measured. A UNIT check, because the stored log is
      // capped at 20 and a gate reading its tail passes vacuously the day no fight survives the cap.
      check("431/3: the one stamper carries a clash's facts — the four-field copy is what lost them",
        (() => { const r = wt.stampNews({ text: "x", kind: "clash", outcome: "wounded", winnerId: "w", loserId: "l",
                                          locationId: "loc", abilityId: "ab" }, { worldDay: 3 });
          return r.kind === "clash" && r.outcome === "wounded" && r.winnerId === "w" && r.loserId === "l"
            && r.locationId === "loc" && r.abilityId === "ab"; })());
      {
        const wsrc431 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
        const writes = (wsrc431.match(/ws\.news = \[\.\.\.ws\.news, \.\.\.stamped\]/g) || []).length;
        const viaStamp = (wsrc431.match(/const stamped = news\.map\([^)]*=> stampNews\(/g) || []).length;
        check("431/3: …and every writer of the news log goes through it — no second, thinner stamper",
          writes > 0 && viaStamp === writes, `${writes} writers, ${viaStamp} of them via stampNews`);
      }
    }
  }

  // SNG-309 — WHAT HAPPENS WHEN THE PLAYER GOES DOWN. Erik: "we should also just make sure all the
  // encounters could get you killed… you wake up and the aggressor is gone with your gear, your companion
  // revives you, you were slain by an assassin, but your party was able to bring you back after 27 days."
  {
    const IC = await import("../engine/incapacitation.js");
    const DM = await import("../engine/death.js");
    IC.wireDeathModel(DM);
    const rolls = (fn, n = 3000) => { let s = 1; const rng = () => (s = (s * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
      const out = {}; for (let i = 0; i < n; i++) { const o = fn(rng); out[o] = (out[o] || 0) + 1; } return out; };
    const roll = (ctx) => rolls(rng => IC.incapacitationOutcome({ ...ctx, rng }).outcome);

    // ⚠️ EVERY AGGRESSOR CAN KILL. Erik's ask, and the thing that was NOT true before: 2 of 19 encounter defs
    // carried `lethal`, so a player could be killed by a boar or a greatcat and by nothing else in the game.
    const kinds = ["beast", "duelist", "raider", "assassin", "hazard", "_default"];
    check("309: every kind of aggressor can kill you — no zero in the slain column",
      kinds.every(k => (roll({ aggressor: { aggressorKind: k } }).slain || 0) > 0));

    // …but they are not all the same. An assassin came to finish you; a duelist came to win.
    const assassin = roll({ aggressor: { aggressorKind: "assassin" } });
    const duelist = roll({ aggressor: { aggressorKind: "duelist" } });
    check("309: an assassin kills far more often than someone who came to win a duel",
      assassin.slain > duelist.slain * 3 && duelist.spared > duelist.slain);

    // A declared-lethal encounter is deadlier — and `lethalOfferClamp` is why that is never a surprise.
    const plain = roll({ aggressor: { aggressorKind: "beast" }, encounter: {} });
    const lethal = roll({ aggressor: { aggressorKind: "beast" }, encounter: { lethal: true } });
    check("309: a declared-lethal encounter is deadlier than the same fight undeclared",
      lethal.slain > plain.slain);

    // ⚠️ NO COMPANION MEANS NOBODY REVIVES YOU — not a smaller chance, none. A revive with nobody present
    // would be the engine inventing a rescuer, which is the same error class as inventing a figure's brother.
    check("309: with nobody there, `revived` is impossible — not merely unlikely",
      !roll({ aggressor: { aggressorKind: "beast" }, companions: [] }).revived);
    check("309: a companion who can reach you is what makes waking up likely",
      (roll({ aggressor: { aggressorKind: "beast" }, companions: [{ id: "pell", name: "Pell" }] }).revived || 0) > 0);
    check("309: …and the revival names WHO, so the narration is about a person",
      IC.incapacitationOutcome({ aggressor: { aggressorKind: "beast" }, companions: [{ id: "pell", name: "Pell" }],
        rng: () => 0 }).reviver === "Pell");

    // Being left where you fell costs you what you were carrying — Erik's "the aggressor is gone with your gear".
    const inv = [{ name: "a" }, { name: "b" }, { name: "c" }, { name: "d" }];
    const left = IC.incapacitationOutcome({ character: { inventory: inv }, aggressor: { aggressorKind: "raider" },
      rng: () => 0.35 });
    check("309: waking where you fell costs you gear; being revived does not", (() => {
      const rev = IC.incapacitationOutcome({ character: { inventory: inv }, aggressor: { aggressorKind: "beast" },
        companions: [{ id: "p", name: "P" }], rng: () => 0 });
      return left.outcome === "left_for_dead" && left.gearTaken.length === 2 && rev.gearTaken.length === 0;
    })());

    // ⛔ THE WHOLE POINT: DEATH IS THE SAME LADDER EVERY FIGURE IS ON. Erik: "you were slain by an assassin,
    // but your party was able to bring you back to life after 27 days." That sentence is `death.js` already.
    const slainPlan = { slain: true, kind: "assassin" };
    const you = { name: "You", clock: { day: 100 } };
    DM.enterDeathState(you, IC.playerDeathState(slainPlan, { worldDay: 100 }));
    check("309: a slain player enters the SAME death state as any figure — a depth, not a boolean",
      you.status === "dead" && you.deathState?.diedDay === 100 && you.deathState.sealed === false);
    // An assassin who hid the body starts you in the deep dark — `deathDepth` forces >= 2 on `lost`.
    check("309: an assassin who hid the body starts you deeper than falling in front of your own party",
      DM.deathDepth(you, 101, {}) === 2
      && DM.deathDepth((() => { const p = { name: "P" }; DM.enterDeathState(p, IC.playerDeathState({ slain: true, kind: "duelist" }, { worldDay: 100 })); return p; })(), 101, {}) === 0);

    // ⚠️ AND THE 27 DAYS ARE REAL. Erik's exact sentence: "your party was able to bring you back to life
    // after 27 days." Retrievable then, and it is the CLOCK that eventually closes the road.
    //
    // ⚠️ MY FIRST VERSION OF THIS ASSERTED THAT TIME ALONE SEALS YOU, AND IT WENT RED — correctly. Days
    // never seal a death in `deathDepth`; the `deepenDeaths` PASS does, and that pass walked the roster and
    // the NPC registry and stopped there. So a dead player would have sat at their starting depth forever:
    // never sinking, never sealing, permanently retrievable. Putting the player on the ladder was only half
    // the job — the clock had to reach them too, or "your party can still come" races nothing.
    const fair = { name: "P" };
    DM.enterDeathState(fair, IC.playerDeathState({ slain: true, kind: "duelist" }, { worldDay: 100 }));
    check("309: your party can still reach you 27 days later",
      DM.isRetrievable(fair, 127, {}) === true && DM.isSealed(fair, 127, {}) === false);
    check("309: and the CLOCK is what closes that road — days alone never do, the deepening pass does",
      DM.isSealed(fair, 100 + 121, {}) === false
      && (DM.deepenDeaths([fair], 100 + 121, {}).length === 1) && DM.isSealed(fair, 100 + 121, {}) === true);

    // ⛔ ONLY A SEALED DEATH ENDS THE STORY. The roster refused to load anyone with `character.dead`, which
    // made every death final and contradicted the model the rest of the game runs on.
    const stillOut = { name: "Q" };
    DM.enterDeathState(stillOut, IC.playerDeathState({ slain: true, kind: "duelist" }, { worldDay: 100 }));
    check("309: a retrievable death does NOT end the story; a sealed one does",
      IC.deathStopsPlay(stillOut, 127, {}) === false && IC.deathStopsPlay(fair, 221, {}) === true
      && IC.deathStopsPlay({ name: "alive" }) === false);
    check("309: …and the roster line says WHERE they are, not just that they fell",
      /near dark|threshold|deep dark/.test(IC.deathLine(stillOut, 127, {}))
      && /sealed/.test(IC.deathLine(fair, 221, {})));
  }

  // SNG-322 — THE BAND DECIDES THE LETHAL FLAG. Aevi authored `rules.threat` (5 bands, each carrying
  // `lethal`/`warn`) onto 62 encounters, and NOTHING IN THE ENGINE READ IT — `def.lethal` was still hand-set
  // on exactly 2 defs. That is CCODE-52's whole point, and the sixth writer/reader miss of the week.
  {
    const EN = await import("../engine/encounters.js");
    const { loadContentHeadless: lch2 } = await import("./headless_content.mjs");
    const live = await lch2();
    const R = live.rules;

    check("322: the authored threat ladder REACHES the engine", (R.threat?.bands || []).length >= 3);
    // ⚠️ `def.threat` is a BAND ID; `def.opponent.threat` is a 10–70 difficulty number. Same word, two
    // things, and the band reader must never touch the number.
    check("322: the band reader reads the BAND, never the difficulty number",
      EN.threatBandOf({ threat: "grave" }, R)?.id === "grave"
      && EN.threatBandOf({ opponent: { threat: 55 } }, R) === null
      && EN.threatBandOf({ threat: 55 }, R) === null);

    // A warned band makes an encounter lethal-for-offer WITHOUT anyone hand-setting a flag.
    const graveId = (R.threat.bands.find(b => b.warn === true) || {}).id;
    const calmId = (R.threat.bands.find(b => b.warn !== true) || {}).id;
    check("322: a WARNED band makes an encounter lethal-for-offer with no hand-set flag",
      !!graveId && EN.isLethalEncounter({ threat: graveId }, R) === true);
    check("322: …and an unwarned band does not — but an explicit def.lethal still wins",
      !!calmId && EN.isLethalEncounter({ threat: calmId }, R) === false
      && EN.isLethalEncounter({ threat: calmId, lethal: true }, R) === true);

    // The offer clamp: marked, never trivial, and a Decline forced into the list.
    const clamped = EN.lethalOfferClamp(
      [{ label: "Face it", encounterId: "x", trivial: true }],
      { x: { id: "x", threat: graveId } }, R);
    check("322: a banded encounter is marked, made non-trivial, and a Decline is forced into the list",
      clamped[0].trivial === false && /⚠/.test(clamped[0].label)
      && clamped.some(c => !c.encounterId && /decline/i.test(c.label)));
    // ⛔ AEVI'S GUARD, KEPT: the warning is about ODDS, not about death. Labelling `grave` "lethal stakes"
    // while `fair` says nothing implies an even match cannot kill you, which is false.
    check("322: the label names the BAND — the warning is about odds, not a promise about death",
      !/lethal stakes/.test(clamped[0].label));

    // ⚠️ AND THE NUMERIC READER MUST NOT SWALLOW THE BAND. `Number("trivial")` is NaN, which `|| 0` turns
    // silently into zero. Nothing broke (these entries carried no numeric threat before), but a numeric
    // reader pointed at a string field is a trap waiting for whoever changes either side.
    const src = readFileSync(join(root, "engine/random_encounters.js"), "utf8");
    check("322: the difficulty reader takes only a real number, never a band string",
      /typeof v === "number" && Number\.isFinite\(v\)/.test(src));
  }

  // SNG-310 — SOMEBODY IS OUT TO GET YOU. Erik: "yes the player can be struck, but that event is a GM
  // narrated encounter. The fact that someone is out to get you triggers it though."
  {
    // ⛔ THE LOAD-BEARING ASSERTION: the engine MARKS and never RESOLVES. Every other strike settles offscreen
    // through resolveEpicClash because both parties are offscreen; one aimed at the player cannot, because
    // resolving it would decide a fight the player was never in. That is Design Law 1, and it is the whole
    // difference between "the world can reach you" and "the world plays you".
    const src310 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    const block = src310.slice(src310.indexOf("if (mark.f.id === PLAYER_MARK_ID)"), src310.indexOf("const outcome = applyEpicClashOutcome(ws, sender.f, mark.f"));
    check("310: a strike aimed at the PLAYER is recorded, never resolved — the engine marks, the GM narrates",
      block.length > 0 && /pendingStrikes/.test(block) && !/resolveEpicClash|applyEpicClashOutcome/.test(block));

    check("310: an unmarked player has no threat at all — silence, not an empty object",
      wt.threatToPlayer({}) === null && wt.threatToPlayer({ pendingStrikes: [] }) === null);

    // ⚠️ THE TWO KINDS DIVERGE, AND IT FALLS OUT OF THE MODEL: a crusade is DECLARED, a knife is not.
    const declared = wt.threatToPlayer({ pendingStrikes: [
      { arcId: "A", kind: "crusade", sender: "s1", senderName: "The Burning Certainty", announced: true, worldDay: 10 }] });
    const quiet = wt.threatToPlayer({ pendingStrikes: [
      { arcId: "A", kind: "quiet", sender: "s2", senderName: "Nobody You Know", announced: false, worldDay: 10 }] });
    check("310: a CRUSADE against the player names its sender — being told is what a crusade IS",
      declared.known.length === 1 && declared.known[0].sender === "The Burning Certainty" && declared.unseen === 0);
    check("310: a QUIET strike is counted but names nobody — they learn it when it arrives",
      quiet.marked === true && quiet.count === 1 && quiet.known.length === 0 && quiet.unseen === 1);

    // ⛔ THE SEED CARRIES WHAT MAKES IT COST SOMETHING. `assassin` is the highest slain weight in the
    // incapacitation table, and the threat band puts a warning and a forced Decline in front of it — so a
    // GM who brings this to a head gets the consequence machinery for free rather than improvising it.
    const IC310 = await import("../engine/incapacitation.js");
    const EN310 = await import("../engine/encounters.js");
    const { loadContentHeadless: lch310 } = await import("./headless_content.mjs");
    const C310 = await lch310();
    const seed = declared.seed;
    check("310: the seed is an ASSASSIN — finishing you was the errand, and the ladder knows what that costs",
      seed.aggressorKind === "assassin"
      && IC310.aggressorKind({ aggressorKind: seed.aggressorKind }, {}) === "assassin");
    check("310: …and the seed is WARNED — a band that forces a label and a Decline into the offer",
      EN310.isLethalEncounter({ threat: seed.threat }, C310.rules) === true);

    // A resolved threat stops being one — otherwise the player is marked forever by one old errand.
    check("310: a resolved threat clears — nobody is hunted forever by a closed errand",
      wt.threatToPlayer({ pendingStrikes: [{ arcId: "A", announced: true, resolved: true }] }) === null);
  }

  // SNG-311 — AND SOMEONE MAY STAND OVER YOU. Erik: "if you get marked for a strike, you can also be chosen
  // as warranting a guardian, or several… feels very VIP and end game, but could be mid game too."
  {
    const ws311 = { pendingStrikes: [{ arcId: "A", kind: "quiet", announced: false, resolved: false }], epicStatus: {} };
    const roster311 = [
      { id: "leg", name: "The War-Ender", tier: "legendary", arcAffinities: [{ arcId: "A", dir: "pro" }] },
      { id: "not", name: "A Notable", tier: "notable", arcAffinities: [{ arcId: "A", dir: "pro" }] },
      { id: "else", name: "Elsewhere", tier: "epic", arcAffinities: [{ arcId: "B", dir: "pro" }] },
    ];

    // ⛔ NOBODY STANDS OVER AN UNMARKED PERSON. A guardian who appears without a threat is the engine
    // inventing a rescuer — the same error class as inventing a figure's brother.
    check("311: an unmarked player draws no guardian at all",
      wt.guardiansFor({}, roster311, 0) === null && wt.guardiansFor({ pendingStrikes: [] }, roster311, 0) === null);

    const g = wt.guardiansFor(ws311, roster311, 0);
    // The retrieval rule, pointed at the living: somebody who stood on the same side of something.
    check("311: a guardian is someone who SHARES the fight the strike is about — never a stranger",
      g.guardians.length > 0 && g.guardians.every(x => x.shares === "A")
      && !g.guardians.some(x => x.id === "else"));
    // ⚠️ HIGHEST RUNG FIRST — this is where "very VIP" comes from, and it is arithmetic, not flavour.
    check("311: the highest rung comes first — a legend standing still for you is the expensive version",
      g.guardians[0].id === "leg");
    // ⛔ AND IT IS NOT FREE PROTECTION. The cost line is what stops it being played as safety.
    check("311: the cost is NAMED — a guardian is a front somebody is not pushing",
      /standing still/.test(g.cost) && /not pushing/.test(g.cost));

    // An absence is a SITUATION, not a blank. Distinguishing "nobody came" from "not marked" is what lets
    // the GM play the emptiness instead of quietly manufacturing a rescuer.
    const alone = wt.guardiansFor(ws311, [{ id: "x", name: "X", tier: "epic", arcAffinities: [{ arcId: "Z", dir: "pro" }] }], 0);
    check("311: marked with nobody who shares it reports the ABSENCE, not null",
      alone && alone.marked === true && alone.guardians.length === 0 && /nobody who shares/.test(alone.note));

    // The dead do not stand over anyone.
    const wsDead = { ...ws311, epicStatus: { leg: { status: "dead" } } };
    check("311: the dead do not guard — effectiveEpicStatus is the same gate the rest of the world uses",
      !wt.guardiansFor(wsDead, roster311, 0).guardians.some(x => x.id === "leg"));
  }

  // SNG-327 — KIN AND INTERESTS ARE AUTHORED NOW, so the SHAPE CONTRACT needs a gate before it can be broken.
  //
  // ⚠️ `personalPursuitOf` reads kin as `typeof k === "string" ? k : k?.line`. Aevi authored `{line: "..."}`
  // and every entry reaches the reader — but the next one written as `{name, relation}` would be silently
  // dropped: no error, no warning, the figure simply has less of a life than the file says. That is the
  // fifth door of the PromisedButUnread family (a content field the engine cannot read), and it is at its
  // most dangerous in a pool, because a partially-readable list still LOOKS like it works.
  //
  // ⛔ SO THIS GATES REACHABILITY, NOT PRESENCE: every authored entry must come back out of the consumer.
  {
    const { loadContentHeadless: lch327 } = await import("./headless_content.mjs");
    const C327 = await lch327();
    const R327 = (C327.legends?.roster || []).filter(f => f?.id);
    // the reader's own extraction, replicated from personalPursuitOf so the two cannot drift apart silently
    const kinLines = f => (Array.isArray(f?.kin) ? f.kin : []).map(k => (typeof k === "string" ? k : k?.line)).filter(Boolean);
    const intLines = f => (Array.isArray(f?.interests) ? f.interests : []).filter(v => typeof v === "string" && v.trim());
    const authored = (k) => R327.reduce((n, f) => n + (Array.isArray(f[k]) ? f[k].length : 0), 0);
    const reaching = (fn) => R327.reduce((n, f) => n + fn(f).length, 0);

    check("327: every authored `kin` entry is READABLE by personalPursuitOf — none silently dropped",
      authored("kin") > 0 && reaching(kinLines) === authored("kin"));
    check("327: every authored `interests` entry is readable too",
      authored("interests") > 0 && reaching(intLines) === authored("interests"));

    // …and behaviourally: a kin line actually comes OUT. Counting is not proof that the pool is reachable.
    check("327: a kin line actually comes out of the consumer, not merely past the filter", (() => {
      const f = R327.find(x => kinLines(x).length);
      if (!f) return false;
      const pool = new Set(kinLines(f));
      let seed = 7; const rng = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
      for (let i = 0; i < 400; i++) if (pool.has(wt.personalPursuitOf(f, rng))) return true;
      return false;
    })());

    // ⛔ AND THE GATE MUST BE ABLE TO FAIL. A shape the reader cannot take has to be caught, or this check
    // is a green light over an unread field — the exact thing it exists to prevent.
    check("327: …and a kin entry in an unreadable shape WOULD be caught", (() => {
      const bad = { id: "x", kin: [{ name: "a brother", relation: "kin" }] };
      return kinLines(bad).length === 0 && wt.personalPursuitOf(bad, () => 0) === null;
    })());
  }

  // SNG-329 — `[object Object]` MINTED INTO THE SAVE AS A PLACE. Found IN PLAY by Erik on the first real
  // play-leg (Splarf), traced by Aevi. `moveTo.location` could arrive as an OBJECT; `String(ref)` turned it
  // into literal text, slugged it to `gen-object-object`, TITLE-CASED it to "[Object Object]", and wrote it
  // to `character.generated.location` — persisting, reloading, and feeding its own descriptionSeed back to
  // the GM as context.
  {
    const ST = await import("../engine/state.js");

    // ⛔ THE COERCION. Every shape the GM actually returns must yield a STRING or null — never `String(obj)`.
    check("329: a nested `{location:{id}}` yields the id, not the text of an object",
      ST.locationRefToString({ location: { id: "the_pass", name: "The Pass" } }) === "the_pass"
      && ST.locationRefToString({ location: "the_pass" }) === "the_pass"
      && ST.locationRefToString("the_pass") === "the_pass");
    check("329: an unnameable reference returns NULL — never the string '[object Object]'",
      ST.locationRefToString({}) === null && ST.locationRefToString({ location: {} }) === null
      && ST.locationRefToString(null) === null && ST.locationRefToString("  ") === null);

    // ⚠️ THE DETECTOR MUST BE CASE-INSENSITIVE, WHICH IS THE WHOLE REASON THIS SURVIVED. The mint
    // title-cases, so the damage is spelled "[Object Object]" on disk. My own first scan looked for the
    // lowercase form and reported ZERO corrupt records across three infected saves.
    check("329: the artefact is caught in BOTH spellings — title-cased on disk, lowercase in fresh JS",
      ST.isCoercedObjectArtefact("[Object Object]") === true
      && ST.isCoercedObjectArtefact("[object Object]") === true
      && ST.isCoercedObjectArtefact("The Pass") === false);

    // ⛔ AND THE REPAIR IS NARROWER THAN THE MINT'S REFUSAL. `isCoercedObjectName` also catches a MISSING
    // name — right for refusing a write, wrong for a migration that DELETES. The wide version removed a
    // legitimate SNG-216 fixture, which is how I found out; reconcile's own law is "never removes".
    check("329: the repair check is narrower than the mint check — a nameless record is NOT deleted",
      ST.isCoercedObjectName(undefined) === true && ST.isCoercedObjectArtefact(undefined) === false
      && ST.isCoercedObjectName("") === true && ST.isCoercedObjectArtefact("") === false);

    // The migration itself: drops the artefact, moves the player out, keeps everything real.
    const RC = await import("../engine/reconcile.js");
    const step = RC.CHARACTER_STEPS.find(x => x.id === "repair-coerced-object-locations");
    const c = { currentLocationId: "gen-object-object", knownPlaces: ["gen-object-object", "real"],
      generated: { location: {
        "gen-object-object": { id: "gen-object-object", name: "[Object Object]", connections: ["the_crossing"] },
        "real": { id: "real", name: "The Low Lamp Inn" },
        "nameless": { id: "nameless" },
      } } };
    step.apply(c);
    check("329: the repair drops the artefact, keeps real places, and leaves a nameless one alone",
      !c.generated.location["gen-object-object"] && !!c.generated.location.real && !!c.generated.location.nameless);
    check("329: …and it does not strand the player inside the place it just removed",
      c.currentLocationId === "the_crossing" && !c.knownPlaces.includes("gen-object-object"));
    // IDEMPOTENT — reconcile's first law.
    const before = JSON.stringify(c);
    step.apply(c);
    check("329: running the repair twice changes nothing", JSON.stringify(c) === before);

    // ⚠️ AND THE REAL SAVES ARE CLEAN OF IT AT HEAD — the check that would have caught this in the first
    // place, and the one that proves the repair has somewhere to run.
    // ⛔ AND EVERY MINT ROUTES THROUGH ONE GUARDED WRITE. I fixed the path the defect report named, Erik
    // played, and `[object Object]` came back — caught by this very gate. There was a SECOND mint
    // (`mintWaygate`) doing the same `String(ref)` on the same kind of value, and I had not swept for
    // siblings. Second time this week a report named one site and there were two. The guard is on the WRITE
    // now, so a third path is covered without anyone remembering this.
    {
      const appSrc329 = readFileSync(join(root, "app.js"), "utf8");
      // ⚠️ THIS GATE COUNTED WRITES AND DID NOT LOCATE THEM, WHICH IS HOW IT PASSED OVER A BROKEN FIX.
      // My edit replaced the FIRST occurrence of the write — which was inside the helper I had just
      // inserted — so `commitGeneratedLocation` lost its write and CALLED ITSELF (infinite recursion),
      // while `mintTransitLocation` kept its raw unguarded one. Exactly one write existed, so `=== 1`
      // was true and green. Counting is not locating; the check must name the function it lives in.
      const lines329 = appSrc329.split(String.fromCharCode(10)).map(l => l.replace(String.fromCharCode(13), ""));
      const owner = (needle) => {
        const at = lines329.findIndex(l => l.includes(needle));
        if (at < 0) return null;
        for (let k = at; k >= 0; k--) if (/^function /.test(lines329[k])) return lines329[k].trim();
        return null;
      };
      check("329b: the ONLY write to generated.location lives inside the guard, not merely exists once",
        (appSrc329.match(/generated\.location\[[a-zA-Z]+\] = rec/g) || []).length === 1
        && /^function commitGeneratedLocation/.test(owner("generated.location[id] = rec") || ""));
      // ⛔ AND THE GUARD MUST NOT CALL ITSELF. A self-recursive commit blows the stack the first time a
      // waygate is minted in play — a crash no headless test can reach, because app.js does not run here.
      check("329b: the guard does not recurse into itself", (() => {
        const at = lines329.findIndex(l => l.startsWith("function commitGeneratedLocation"));
        if (at < 0) return false;
        for (let k = at + 1; k < lines329.length && lines329[k] !== "}"; k++) {
          if (lines329[k].includes("commitGeneratedLocation(")) return false;
        }
        return true;
      })());
    }
    check("329: no shipped save carries a place minted from a coerced object", (() => {
      const walk = (d) => readdirSync(d, { withFileTypes: true })
        .flatMap(e => e.isDirectory() ? walk(join(d, e.name)) : [join(d, e.name)]);
      let files = [];
      try { files = walk(join(root, "characters")).filter(f => f.endsWith(".json")); } catch { return true; }
      for (const f of files) {
        let j; try { j = JSON.parse(readFileSync(f, "utf8")); } catch { continue; }
        const ch = j.character || j;
        for (const rec of Object.values(ch?.generated?.location || {})) {
          if (ST.isCoercedObjectArtefact(rec?.name)) { console.log(`      still corrupt: ${f}`); return false; }
        }
      }
      return true;
    })());
  }

  // SNG-330 — THE TRAVEL BUTTON VANISHED ON A PLACE THE PLAYER HAD WALKED TO. Found in play by Erik,
  // traced by Aevi. The map read ONE array (here's own `connections`) and never asked whether the
  // DESTINATION lists here — harmless for authored content, fatal for minted places, because the reciprocal
  // edge was written onto AUTHORED content, which is shared and never saved.
  {
    const ST330 = await import("../engine/state.js");
    const locs = { crossing: { id: "crossing", connections: ["ford"] }, ford: { id: "ford", connections: ["crossing"] },
      // the minted shape: it lists `crossing`, and crossing does NOT list it back (that edge was lost on reload)
      "gen-the-pass": { id: "gen-the-pass", connections: ["crossing"] } };

    check("330: an edge in EITHER direction is a road — the destination listing here is enough",
      ST330.canTravelBetween("crossing", "gen-the-pass", locs) === true
      && ST330.canTravelBetween("gen-the-pass", "crossing", locs) === true);
    check("330: an unconnected place is still unreachable — symmetry is not permissiveness",
      ST330.canTravelBetween("ford", "gen-the-pass", locs) === false
      && ST330.canTravelBetween("crossing", "nowhere", locs) === false
      && ST330.canTravelBetween("crossing", "crossing", locs) === false);
    // ⛔ THE PERSISTING TWIN: a road the player made themselves, written where it survives a reload.
    check("330: a player-made edge in `placeEdges` counts, in either direction",
      ST330.canTravelBetween("ford", "gen-the-pass", locs, { ford: ["gen-the-pass"] }) === true
      && ST330.canTravelBetween("gen-the-pass", "ford", locs, { ford: ["gen-the-pass"] }) === true);

    // The repair: every edge a save asserts from one side is restored on the other. Derived, never invented.
    const RC330 = await import("../engine/reconcile.js");
    const step330 = RC330.CHARACTER_STEPS.find(x => x.id === "restore-lost-place-edges");
    const c330 = { generated: { location: { "gen-the-pass": { id: "gen-the-pass", connections: ["crossing"] } } } };
    step330.apply(c330);
    check("330: the repair puts back the return road from what the save already asserts",
      (c330.placeEdges?.crossing || []).includes("gen-the-pass"));
    const snap330 = JSON.stringify(c330);
    step330.apply(c330);
    check("330: …and running it twice changes nothing", JSON.stringify(c330) === snap330);
    check("330: the repair INVENTS no road — a save with no generated places gains no edges", (() => {
      const empty = { generated: { location: {} } };
      step330.apply(empty);
      return !empty.placeEdges || Object.keys(empty.placeEdges).length === 0;
    })());

    // ⛔ AND THERE IS NO CAP AT ALL NOW. Erik: "that doesn't seem to serve a purpose." It was 80 against an
    // atlas of 118, so a well-travelled character silently forgot the oldest place they knew — and `isKnown`
    // gates naming, description and map labelling, so somewhere from their first hour became "an unknown
    // place" again. Raising it above the atlas was the smaller half of the answer.
    //
    // ⚠️ THE DISTINCTION THIS GATE EXISTS TO HOLD: a cap on a LOG is housekeeping; a cap on KNOWLEDGE is
    // data loss wearing the same syntax. `knownPlaces` is not a record of where you have been — it is the
    // set of facts about what this character KNOWS, and every entry changes what the game will say to them.
    {
      const appSrc330 = readFileSync(join(root, "app.js"), "utf8");
      check("330b: knownPlaces has NO cap — knowledge a player earned is never evicted",
        /knownPlaces = \[\.\.\.character\.knownPlaces, id\];/.test(appSrc330)
        && !/knownPlaces = \[\.\.\.character\.knownPlaces, id\]\.slice\(/.test(appSrc330));
    }
  }

  // SNG-331 — ⚠️ THE RULE RESOLVER MATCHED A SUBSTRING OF THE PATH, SO A RULE LOADED THE WRONG FILE.
  //
  // `rulePath` was `.find(r => r.includes(name))`, and `"rules/location_affinities.json".includes("ties")`
  // is TRUE — "affini**ties**". location_affinities is registered earlier, so `loadRule("ties")` returned
  // IT, and `rules.ties` was the location-affinities table from the day Aevi authored the ties file.
  //
  // ⛔ THE NASTIEST DOOR IN THE PromisedButUnread FAMILY SO FAR: registered ✓ loaded ✓ destructured into the
  // right name ✓ merged ✓ — and it was THE WRONG FILE. Every check built for this family asks whether the
  // wiring REACHES something. None asked whether it reached the RIGHT something. The content was never
  // unread; it was read past.
  {
    const { loadContentHeadless: lch331 } = await import("./headless_content.mjs");
    const C331 = await lch331();
    const rulesDir = join(root, "content/packs/core/rules");
    const sig = (o) => (o && typeof o === "object"
      ? Object.keys(o).filter(k => !k.startsWith("_")).sort().slice(0, 5).join(",") : String(o));
    // ⛔ arcResponse and resolution are intentionally NOT whole-file (one is an inner block, the other IS
    // the rules bag) — named here rather than silently skipped, so the exemption is visible.
    const byDesign = new Set(["arcResponse", "resolution"]);
    const wrong = [];
    for (const f of readdirSync(rulesDir).filter(x => x.endsWith(".json"))) {
      const key = f.replace(/\.json$/, "").replace(/_([a-z])/g, (_, c) => c.toUpperCase());
      if (byDesign.has(key)) continue;
      const loaded = C331.rules?.[key];
      if (loaded === undefined) continue;                    // not merged into `rules` — a different question
      const file = JSON.parse(readFileSync(join(rulesDir, f), "utf8"));
      if (sig(loaded) !== sig(file)) wrong.push(`${key}: loaded[${sig(loaded)}] file[${sig(file)}]`);
    }
    for (const w of wrong) console.log(`      ${w}`);
    check("331: every merged rules key holds the CONTENT OF ITS OWN FILE, not a substring match", !wrong.length);

    // …and the collision itself, asserted directly, so a future short name cannot reintroduce it.
    check("331: `ties` resolves to ties.json — not to location_affinities.json, which contains it",
      Array.isArray(C331.rules?.ties?.kinTriggers) && C331.rules.ties.kinTriggers.length > 0
      && !("tagAliases" in (C331.rules.ties || {})));

    // ⛔ AND THE PROPERTY, NOT TODAY'S INSTANCE. A source-pattern check on `rulePath` would prove a line was
    // typed; this proves the manifest cannot hide another collision. For EVERY registered rule, the first
    // path a substring search would return must be that rule's own file — the exact condition that made
    // `ties` load location_affinities, checked across all 51 rather than the one that bit.
    {
      const manifest = JSON.parse(readFileSync(join(root, "content/packs/core/manifest.json"), "utf8"));
      const regs = manifest.provides?.rules || [];
      const collide = [];
      for (const path of regs) {
        const name = path.split("/").pop().replace(/\.json$/, "");
        const substringWinner = regs.find(r => r.includes(name));
        if (substringWinner !== path) collide.push(`${name} → ${substringWinner}`);
      }
      for (const c of collide) console.log(`      substring collision: ${c}`);
      // The collisions may EXIST (a short name inside a long one is legal); what must hold is that the
      // resolver does not use substring matching, proved by every merged key matching its file above.
      check("331: known substring collisions are declared, and none of them changes what loads",
        collide.length === 0 || collide.every(c => c.startsWith("ties →")));
    }
  }

  // SNG-333 — DUNBAR'S NUMBER, AND MEETING SOMEONE AGAIN PROTECTS THEM. Erik: "150 known relationships…
  // we need the insertion order as a default, but if you interface with the NPCs then it should count those
  // interactions and keep the ones you meet more than once from dropping off."
  {
    const NP = await import("../engine/npcs.js");
    check("333: the circle is Dunbar's number, not an array bound", NP.REGISTRY_CAP === 150);

    // ⛔ THE RULE: least-met first, oldest-first among equals. Everyone met once is spent before anyone met twice.
    const reg = {
      once_old:  { id: "once_old",  met: 1, firstMet: { day: 1 } },
      once_new:  { id: "once_new",  met: 1, firstMet: { day: 50 } },
      twice:     { id: "twice",     met: 2, firstMet: { day: 2 } },
      many:      { id: "many",      met: 9, firstMet: { day: 3 } },
    };
    check("333: the least-met goes first, and the oldest breaks the tie",
      NP.evictionCandidate(reg) === "once_old");
    check("333: someone you met twice outlives everyone you met once", (() => {
      const r = { ...reg }; delete r.once_old; delete r.once_new;
      return NP.evictionCandidate(r) === "twice";     // only after the singles are gone
    })());

    // ⛔ KIN ARE NEVER CANDIDATES — Erik: "ones that tie to people should be saved as facts, like my player's
    // mother." Somebody's family is not an acquaintance the circle can afford to forget.
    check("333: kin are never evicted, and a registry of only kin refuses rather than drops one",
      NP.evictionCandidate({ mum: { id: "mum", met: 1, kin: "mother", firstMet: { day: 0 } } }) === null);
    check("333: with kin present, the evictable stranger goes instead",
      NP.evictionCandidate({ mum: { id: "mum", met: 1, kin: "mother", firstMet: { day: 0 } },
                             guy: { id: "guy", met: 1, firstMet: { day: 9 } } }) === "guy");
    check("333: an empty circle has nobody to evict", NP.evictionCandidate({}) === null);

    // SNG-334 — ⛔ AND THE TIE BECOMES A PINNED FACT. Erik: "ones that tie to people should be saved as
    // facts — like my player's mother, or Pell's father."
    const kinN = { id: "pell_da", name: "Oren", role: "the ferryman at the Crossing" };
    NP.advanceBond(kinN, { bondType: "family" }, null, 4);
    check("334: a FAMILY bond marks the person as kin — the field the circle already protects",
      kinN.kin === "family" && NP.evictionCandidate({ [kinN.id]: kinN }) === null);
    check("334: …and it yields a fact worth pinning, naming what the fiction actually said",
      /Oren is family — the ferryman at the Crossing\./.test(NP.kinFact(kinN)));
    // ⛔ NEVER INVENTS THE RELATION. If the GM only said "family", the fact says family and no more.
    const vague = { id: "x", name: "Someone" };
    NP.advanceBond(vague, { bondType: "family" }, null, 1);
    check("334: it never invents HOW they are kin — that would be the engine writing canon",
      NP.kinFact(vague) === "Someone is family." && NP.kinFact({ id: "y", name: "Stranger" }) === null);
    check("334: a `sworn` bond is kin too — a bond you both chose",
      (() => { const sw = { id: "s", name: "Vaskar" }; NP.advanceBond(sw, { bondType: "sworn" }, null, 1);
               return sw.kin === "sworn" && /sworn to you/.test(NP.kinFact(sw)); })());
  }

  // SNG-335 — SAVE AN IMAGE WHERE NO LINK CAN EXPIRE. Erik: "add an option to save an image locally — that
  // would preserve it even if the url vanishes." Removing the cap (SNG-332) keeps the ENTRY forever, but an
  // entry is a URL: if the host expires it the record survives and the picture does not.
  {
    const AR = await import("../engine/art.js");
    // ⚠️ THE FILENAME IS THE WHOLE VALUE OF A SAVED FILE. `image_47.png` in a downloads folder is junk.
    check("335: the file is named from the caption the player already read",
      AR.imageFileName("The Low Lamp Inn — the common room at dusk", "location", "png")
        === "singularity-the-low-lamp-inn.png");
    check("335: …and falls back to the KIND rather than to nothing",
      AR.imageFileName("", "portrait", "jpg") === "singularity-portrait.jpg"
      && AR.imageFileName("   ", "beast") === "singularity-beast.png");
    check("335: a caption of pure punctuation still yields a usable name",
      /^singularity-image\.png$/.test(AR.imageFileName("!!! ???", "")));
    // The extension: content-type wins, the URL is the fallback, png is the floor.
    check("335: the extension follows the content-type, then the url, then png",
      AR.imageExtFor("x/y", "image/jpeg") === "jpg"
      && AR.imageExtFor("https://h/a/b.webp?sig=1") === "webp"
      && AR.imageExtFor("https://h/no-extension") === "png");
    // ⛔ AND THE BYTES MUST NEVER REACH THE SAVE. Base64 in the gallery would be ~1.3× the image against a
    // ~5MB localStorage budget the save ALSO syncs to GitHub — a few kept images would break SAVING, which
    // is a worse failure than a dead link.
    const appSrc335 = readFileSync(join(root, "app.js"), "utf8");
    check("335: the download writes to disk and never inlines the image into the character",
      /URL\.createObjectURL\(blob\)/.test(appSrc335) && /revokeObjectURL/.test(appSrc335)
      && !/gallery.*data:image\/|addGalleryImage\([^)]*base64/.test(appSrc335));
  }

  // SNG-339 — TWO BONUS TERMS THAT COULD NEVER FIRE. Aevi, from Erik's play: a level-1 character sits at
  // 40% on a routine action, and "a walking disaster" was his phrase. She traced it to `character.skills`
  // being read and written by nothing.
  //
  // ⚠️ IT IS WORSE THAN SHE FOUND: `action.skillId` has no writer EITHER, and no vocabulary was ever defined
  // for it. The term was not dormant — it was STRUCTURALLY UNREACHABLE, costing up to 10 points a rank to
  // every character in the game's history including a level-29 one.
  {
    const INV = await import("../engine/inventory.js");
    const R339 = { baseChance: { skillBonus: 10, skillBonusCap: 20 } };

    check("339: training keys on the ACTION TAGS the game already has — not a ninth vocabulary",
      INV.skillBonus({ skills: { stealth: 2 } }, ["stealth"], R339).bonus === 20
      && INV.skillBonus({ skills: { stealth: 2 } }, ["negotiate"], R339).bonus === 0);
    check("339: an untrained character gets nothing, and says so without throwing",
      INV.skillBonus({}, ["stealth"], R339).bonus === 0
      && INV.skillBonus({ skills: {} }, [], R339).trained.length === 0);
    // ⚠️ BEST SKILL ONLY. Being trained in three things that touch one action is not three times as good at
    // it — a summing version makes a broad character strictly better than a deep one at everything, which is
    // the opposite of what a skill is for.
    check("339: the BEST training counts, never the sum of everything that touches the action",
      INV.skillBonus({ skills: { stealth: 1, quiet: 1, careful: 1 } }, ["stealth", "quiet", "careful"], R339).bonus === 10);
    check("339: …and it is capped, so no rank ladder outruns the curve",
      INV.skillBonus({ skills: { stealth: 9 } }, ["stealth"], R339).bonus === 20);
    check("339: it names what helped, so the receipt can say why",
      INV.skillBonus({ skills: { climb: 3 } }, ["climb"], R339).trained[0] === "climb 3");

    // ⛔ §4 — AND THE ZERO MUST BE VISIBLE. `add()` drops a 0-valued term, so a character with no training
    // and no gear saw NO LINES for either — which reads as "does not apply to me" rather than "you have
    // nothing here". That silence is part of why this survived; an explicit zero is the anti-recurrence.
    const { successChance } = await import("../engine/resolve.js");
    const { loadContentHeadless: lch339 } = await import("./headless_content.mjs");
    const C339 = await lch339();
    const ctx339 = { character: { attributes: { practical: 2 }, subAttributes: {}, alignment: {} },
      action: { attribute: "practical", intentTags: ["scout"], difficulty: 0 },
      location: null, rules: C339.rules, equipmentBonus: 0, skillBonus: 0 };
    successChance(ctx339);
    const labels = (ctx339._breakdown?.components || []).map(c => c.label);
    check("339 §4: an untrained, unequipped character SEES both zero terms rather than two silent omissions",
      labels.includes("training") && labels.includes("equipment"));

    // §1 — THE GRANT SHAPE Aevi asked for: a flat map of ACTION TAG -> RANK per background/tradition, on the
    // same vocabulary the gear already matches, so a trade's training and a trade's tools agree by construction.
    const R1 = { startingSkills: { grantCap: 2,
      byBackground: { orphan: { stealth: 1, quiet: 1 } },
      byTradition: { umbral: { stealth: 1 } } } };
    check("339 §1: background and tradition both grant, and ranks add across them",
      INV.startingSkills({ backgroundId: "orphan", traditionId: "umbral" }, R1).stealth === 2);
    check("339 §1: …but the grant is CAPPED — creation makes you good, never finished",
      INV.startingSkills({ backgroundId: "orphan", traditionId: "umbral" },
        { startingSkills: { ...R1.startingSkills, grantCap: 1 } }).stealth === 1);
    // ⛔ INVENTS NOTHING. An unlisted background grants nothing rather than a guess — papering over a missing
    // table would hide the exact gap this ticket exists to surface.
    check("339 §1: an unlisted background grants NOTHING rather than a guess",
      Object.keys(INV.startingSkills({ backgroundId: "nobody" }, R1)).length === 0
      && Object.keys(INV.startingSkills({}, {})).length === 0);
    check("339 §1: authoring notes in the table are not mistaken for skills",
      !("_note" in INV.startingSkills({ backgroundId: "x" }, { startingSkills: { byBackground: { x: { _note: "hi", climb: 1 } } } })));

    // §3 — IT GROWS BY DOING, and it counts USES not successes: rewarding only success would make the
    // already-good better and leave the struggling character exactly where this ticket found them.
    const learner = {};
    for (let i = 0; i < 25; i++) INV.practiceSkill(learner, ["stealth"], { startingSkills: { usesPerRank: 25, maxRank: 2 } });
    check("339 §3: training is gainable in play — 25 uses is rank 1",
      learner.skills.stealth === 1 && learner.skillUses.stealth === 25);
    for (let i = 0; i < 200; i++) INV.practiceSkill(learner, ["stealth"], { startingSkills: { usesPerRank: 25, maxRank: 2 } });
    check("339 §3: …and it stops at maxRank, so practice never outruns the curve",
      learner.skills.stealth === 2);

    // SNG-339b — ⚠️ THE GRANT ONLY FIRED AT CREATION, AND EVERY EXISTING CHARACTER ALREADY EXISTS. Erik asked
    // for Splarf to stop failing; Splarf was made before the tables existed, so the feature reached him not
    // at all. Same shape as `personal-arc-backfill`: a save from before a feature gains what it is owed.
    {
      const RC339 = await import("../engine/reconcile.js");
      const step = RC339.CHARACTER_STEPS.find(x => x.id === "grant-starting-training");
      const rules339 = { startingSkills: { grantCap: 2, byBackground: { orphan: { stealth: 1, survival: 1 } } } };
      const existing = { name: "Splarf", background: "orphan", skills: {} };
      step.apply(existing, { content: { rules: rules339 } });
      check("339b: an existing character is granted the training they came with, on next load",
        existing.skills.stealth === 1 && existing.skills.survival === 1);
      // ⛔ NEVER LOWERS WHAT PLAY HAS EARNED — reconcile's own law is additive-only.
      const practised = { name: "Veteran", background: "orphan", skills: { stealth: 2 } };
      step.apply(practised, { content: { rules: rules339 } });
      check("339b: …and it never lowers a rank that play has already earned",
        practised.skills.stealth === 2 && practised.skills.survival === 1);
    }
  }

  // SNG-340 — WHY AN APTITUDE STAYS. Aevi's model: durability is not one property, it is three questions
  // that `fadingAptitudes` had collapsed into one — provenance, reinforcement, and one-way.
  {
    const PP = await import("../engine/playerprofile.js");
    const APT = [
      { id: "shadow", tendency: "stealth", threshold: 5 },
      { id: "naive", axis: "inverse", oneWay: true, worldlinessComponents: ["deception"], worldlinessCeiling: 3 },
    ];
    const R340 = { aptitudeKeepMargin: 1, aptitudeReinforcement: { 2: 2, 3: 4 }, aptitudePermanentAt: 4 };

    // ⛔ PROVENANCE. Erik: a background aptitude says WHERE YOU CAME FROM. You do not drift out of having
    // been an orphan — so it survives a tendency that has collapsed to nothing.
    const born = { aptitudes: ["shadow"], grantedAptitudes: ["shadow"], tendencies: { stealth: 0 } };
    check("340: a BACKGROUND aptitude never fades, whatever the tendencies do",
      PP.deriveAptitudes(born, APT, R340).includes("shadow")
      && PP.aptitudeSource(born, "shadow") === "background");
    check("340: …and it is never shown as FADING — a warning about something that will not happen",
      !PP.fadingAptitudes(born, APT, R340).has("shadow"));

    // An EARNED one is a reading of the present, and fading when it stops being true is correct.
    const drifted = { aptitudes: ["shadow"], grantedAptitudes: [], tendencies: { stealth: 0 } };
    check("340: an EARNED aptitude still fades on drift — that behaviour was right and is kept",
      !PP.deriveAptitudes(drifted, APT, R340).includes("shadow"));

    // ⚠️ REINFORCEMENT — Erik: "repeatedly earned attributes stick around longer too." This is what makes it
    // a model rather than an exception: provenance gives permanence at creation, reinforcement EARNS it.
    const twice = { aptitudes: ["shadow"], grantedAptitudes: [], tendencies: { stealth: 3 }, aptitudeEarnCount: { shadow: 2 } };
    const once = { aptitudes: ["shadow"], grantedAptitudes: [], tendencies: { stealth: 3 }, aptitudeEarnCount: { shadow: 1 } };
    check("340: re-earning widens the keep-margin — the same drift loses it once, keeps it twice",
      !PP.deriveAptitudes(once, APT, R340).includes("shadow")
      && PP.deriveAptitudes(twice, APT, R340).includes("shadow"));
    check("340: four earnings is permanence you EARNED, not inherited",
      PP.reinforcementMargin({ aptitudeEarnCount: { shadow: 4 } }, "shadow", R340) === Infinity
      && PP.deriveAptitudes({ aptitudes: ["shadow"], grantedAptitudes: [], tendencies: { stealth: 0 },
           aptitudeEarnCount: { shadow: 4 } }, APT, R340).includes("shadow"));

    // ⛔ ONE-WAY IS NARROWER THAN IT READS: not "never fades" but "once faded, NEVER RE-EARNED". Reading it
    // as permanence — which Aevi's SNG-339 spec did, and I repeated — gets the behaviour exactly backwards.
    const lost = { aptitudes: [], grantedAptitudes: ["naive"], aptitudesLost: ["naive"], tendencies: {} };
    check("340: a one-way aptitude the world took is UNREACHABLE, even by a later grant",
      !PP.deriveAptitudes(lost, APT, R340).includes("naive")
      && PP.isForeverLost(lost, "naive") === true);

    // §4 — and the player can SEE why, per the zero-terms lesson.
    check("340: the readout says WHY it is sticking — provenance, reinforcement, or gone for good",
      /does not fade/.test(PP.aptitudeStandingLine(born, "shadow", R340))
      && /harder to lose/.test(PP.aptitudeStandingLine(twice, "shadow", R340))
      && /who you are now/.test(PP.aptitudeStandingLine({ aptitudeEarnCount: { shadow: 5 } }, "shadow", R340))
      && /does not give this one back/.test(PP.aptitudeStandingLine(lost, "naive", R340))
      && PP.aptitudeStandingLine(once, "shadow", R340) === null);
  }

  // SNG-341 — A QUEST STAGE HAS A REQUIREMENT NOW. Erik, from play: "it progressed basically 1 stage per
  // beat… if you can learn, obtain, and deliver the required objectives in 3 beats it's not really a quest."
  //
  // ⚠️ THE CAUSE: `condition` is PROSE and nothing ever parsed it, so a stage was complete when someone SAID
  // it was. Three beats finished a three-stage quest because the structure was never load-bearing.
  {
    const Q = await import("../engine/quests.js");
    const ch = {
      inventory: [{ id: "filtration_log", name: "Filtration Log" }],
      knownPlaces: ["the_crossing"],
      npcRegistry: { fendt: { id: "fendt", name: "Fendt" } },
      codex: { topics: { "the_marked_period": { title: "The Marked Period" } } },
      encounterLog: [{ id: "the_sealed_door", won: true }],
    };
    const met = (requires, ctx) => Q.stageRequirementsMet(ch, { requires }, ctx);

    // ⛔ NO REQUIREMENTS = MET. Every quest authored before this has none; refusing them would break every
    // live quest in every save to enforce a rule their content never agreed to.
    check("341: a stage with no requires[] is still satisfiable — old quests are not broken by a new rule",
      met([]).met === true && met(undefined).met === true && met([]).unrequired === true);

    // Each kind reads state the game ALREADY tracks — nothing new is recorded to make this work.
    check("341: obtain reads inventory · reach reads knownPlaces · speak reads the registry · learn reads the codex",
      met([{ kind: "obtain", what: "Filtration Log" }]).met
      && met([{ kind: "reach", what: "the_crossing" }]).met
      && met([{ kind: "speak", what: "Fendt" }]).met
      && met([{ kind: "learn", what: "The Marked Period" }]).met
      && met([{ kind: "resolve", what: "the_sealed_door" }]).met);
    check("341: …and each REFUSES when the thing is not true",
      !met([{ kind: "obtain", what: "a sword" }]).met
      && !met([{ kind: "reach", what: "the_maw" }]).met
      && !met([{ kind: "speak", what: "Nobody" }]).met
      && !met([{ kind: "learn", what: "a secret" }]).met);

    // ⚠️ DELIVER IS TWO FACTS AND THE ENGINE CAN ONLY SEE ONE HONESTLY: the item is GONE and the person is
    // met. Checking "you had it" would require a history nothing keeps.
    check("341: deliver requires the item to be GONE and the recipient known",
      !met([{ kind: "deliver", item: "Filtration Log", to: "Fendt" }]).met      // still holding it
      && met([{ kind: "deliver", item: "a letter", to: "Fendt" }]).met);        // handed over

    // ⛔ THE REFUSAL NAMES WHAT IS MISSING, so a GM can turn it into a scene. "cannot advance" is a wall;
    // "the clerk still has not seen the filing" is playable.
    const short = met([{ kind: "obtain", what: "a sword", hint: "you still do not have the blade" }]);
    check("341: a refusal NAMES what is missing rather than just saying no",
      short.missing.length === 1 && /do not have the blade/.test(short.missing[0]));

    // ⛔ `beats` IS SITUATIONAL, NOT THE DEFAULT — Erik: "don't make beats a standard go-to." And it counts
    // from when the STAGE became current, or a late stage inherits a debt it never incurred and opens
    // already satisfied.
    check("341: beats counts from when the stage became current, not from the quest's start",
      !met([{ kind: "beats", what: 3 }], { beatsOnStage: 1 }).met
      && met([{ kind: "beats", what: 3 }], { beatsOnStage: 3 }).met);

    // An engine that does not understand a kind must not block a quest on it.
    check("341: an unknown requirement kind never blocks — forward-compatible with content we have not built",
      met([{ kind: "sacrifice_a_goat", what: "billy" }]).met);

    // AND THE GATE ITSELF: evidence alone is no longer enough.
    const c2 = { actionCount: 0, quests: [{ id: "q", structured: true, status: "active", stageIndex: 0,
      stages: [{ id: "s1", requires: [{ kind: "obtain", what: "a sword" }] }, { id: "s2" }] }] };
    const refused = Q.advanceStructuredQuest(c2, { questId: "q", stageId: "s1", evidence: "I found it, honest" });
    check("341: a stage cannot be talked closed — evidence without the requirement is refused",
      refused.ok === false && refused.why === "requirements-unmet" && refused.missing.length === 1);
    c2.inventory = [{ name: "a sword" }];
    const allowed = Q.advanceStructuredQuest(c2, { questId: "q", stageId: "s1", evidence: "took it off the rack" });
    check("341: …and passes once the world actually agrees",
      allowed.ok === true && c2.quests[0].stageIndex === 1);

    // ⚠️ AND THE GM MUST SEE THE GAP, or it keeps trying to close a stage the engine keeps refusing — and to
    // the player that is indistinguishable from a stuck quest. Naming it turns the refusal into the scene.
    const c3 = { actionCount: 0, quests: [{ id: "q", structured: true, status: "active", stageIndex: 0,
      title: "The Filing", stakes: "a name cleared", stages: [
        { id: "s1", objective: "find the log", condition: "obtain the filtration log",
          requires: [{ kind: "obtain", what: "Filtration Log", hint: "you still do not have the log" }] }] }] };
    const block = Q.structuredQuestsForGM(c3, {});
    check("341: the GM prompt names what is STILL NEEDED, so a refusal becomes playable",
      /STILL NEEDED/.test(block || "") && /do not have the log/.test(block || ""));
    c3.inventory = [{ name: "Filtration Log" }];
    check("341: …and says nothing once the requirement is met — no noise on a stage that can close",
      !/STILL NEEDED/.test(Q.structuredQuestsForGM(c3, {}) || ""));
  }

  // SNG-341b — THE OTHER THREE LEGS. Aevi authored and registered `rules/quest_structure.json`; it reached
  // nothing. loadRule + destructure (same array) + merge + surface.
  //
  // ⛔ THIS IS THE HALF THAT MAKES SNG-341 REAL. `requires[]` made stage dependency POSSIBLE; only the prompt
  // makes it HAPPEN — a generated quest with three independent stages still reads as three errands even with
  // a requirement on each.
  {
    const { loadContentHeadless: lch341b } = await import("./headless_content.mjs");
    const C341 = await lch341b();
    const qs = C341.rules?.questStructure;
    check("341b: quest_structure REACHES rules — registered was only one of four legs",
      !!qs && !!qs.theRule && !!qs.stageChain && !!qs.routeReveal);

    // ⚠️ AND IT MUST LAND IN THE PROMPT, not merely in `rules`. A loaded-but-unread rule is the same bug one
    // layer up, which is the whole reason this ticket existed.
    const GM341 = await import("../engine/gm.js");
    const tiers = GM341.buildTiers({
      character: { name: "T", attributes: {}, quests: [] }, location: { id: "here", name: "Here" }, region: null, lore: null,
      rules: C341.rules, resolution: null, playerInput: "", recentTurns: [], timeLabel: "",
    });
    const prompt = JSON.stringify(tiers);
    check("341b: the STAGE CHAIN law lands in the GM prompt — stage N+1 must need what stage N produced",
      /STAGE CHAIN/.test(prompt) && /NEED SOMETHING THE STAGE BEFORE IT PRODUCED/i.test(prompt));
    // ⛔ Erik: "it gave away some things with the greyed out approaches." A label is an option; a reason is a
    // discovery, and printing the reason before the stage that earns it spends the discovery early.
    check("341b: the ROUTE REVEAL rule lands too, with the right/wrong examples that make it actionable",
      /ROUTES/.test(prompt) && /RIGHT:/.test(prompt) && /WRONG \(do not do this\):/.test(prompt));
    check("341b: …and the quest LAW itself — if you cannot name the cost of ignoring it, it is not a quest",
      /not a quest/i.test(prompt) && /errand/i.test(prompt));
    // A world with the rule absent must not throw — content can always be missing.
    check("341b: a missing quest_structure is silent, never a crash",
      (() => { try { GM341.buildTiers({ character: { name: "T", attributes: {}, quests: [] }, rules: {},
        location: { id: "here", name: "Here" }, region: null, lore: null, resolution: null, playerInput: "", recentTurns: [], timeLabel: "" }); return true; }
        catch { return false; } })());
  }

  // SNG-343 — GENERATED QUEST TEXT WAS SEVERED AT 200 CHARS, IN THE SAVE. Found in play by Erik: Splarf's
  // routes ended mid-word — "it will be slow, inglorious, and m". Six severed strings in one save.
  //
  // ⚠️ WORSE THAN A DISPLAY CAP: both slices ran at STORE time, so the rest was never written down and no
  // re-render brings it back. And it is SNG-152 §5e's own bug in a file that sweep never covered — same cut,
  // same number, same discovery route: a player read it on screen.
  {
    const PA = await import("../engine/personalArc.js");
    const long = "The clerk who signed it is still alive and still working, and the reason the signature was "
      + "accepted has never been written down anywhere that anyone outside the office could read it, which "
      + "is precisely why nobody has ever been able to contest the thing properly.";
    check("343: the fixture is long enough to have been cut by the old cap", long.length > 200);

    // ⛔ BEHAVIOURAL, NOT A SOURCE PATTERN. The store path itself must not sever — a regex over the file
    // would prove a line was deleted, not that the text survives the round trip.
    const arc = PA.sanitizePersonalArc(
      { name: "A", premise: "p", stakes: "s",
        stages: [{ objective: long }],
        routes: { answer: long } },
      { name: "T", background: "orphan" }, {});
    check("343: a long stage objective survives storage WHOLE — no cut, no ellipsis",
      arc.stages[0].objective === long);
    check("343: …and so does a long route",
      Object.values(arc.routes)[0] === long);
    check("343: nothing in the stored arc is exactly 200 characters ending mid-word", (() => {
      const strings = [...arc.stages.map(x => x.objective), ...Object.values(arc.routes)];
      return !strings.some(t => typeof t === "string" && t.length === 200 && !/[.!?"'’”)\]]\s*$/.test(t));
    })());

    // THE REPAIR: six strings are already severed in a live save and cannot be recovered.
    const RC343 = await import("../engine/reconcile.js");
    const step343 = RC343.CHARACTER_STEPS.find(x => x.id === "flag-severed-quest-prose");
    const cut = "x".repeat(193) + " and th";                       // 200, ends mid-word
    const whole = "y".repeat(199) + ".";                           // 200, ends properly
    const c343 = { quests: [{ id: "q", stages: [{ id: "s1", objective: cut }, { id: "s2", objective: whole }],
      routes: { answer: cut, name: whole } }] };
    step343.apply(c343);
    check("343: the repair flags a severed string and leaves a legitimately-200 one alone",
      c343.quests[0].stages[0]._severed === true && !c343.quests[0].stages[1]._severed
      && c343.quests[0]._severedRoutes.includes("answer") && !c343.quests[0]._severedRoutes.includes("name"));

    // ⛔ AND THE FLAG IS FOR THE GM, NOT A SCAR SHOWN TO THE PLAYER. "[truncated]" on screen says the game is
    // broken and leaves the sentence just as broken; telling the GM lets it finish the thought in play,
    // which is the only route back to a whole quest that exists.
    const Q343 = await import("../engine/quests.js");
    const block = Q343.structuredQuestsForGM({ actionCount: 0, quests: [{ id: "q", structured: true,
      status: "active", stageIndex: 0, title: "T", stakes: "s", _severedRoutes: ["answer"],
      stages: [{ id: "s1", objective: cut, _severed: true }] }] }, {});
    check("343: the GM is told the text was cut and to restate it whole, rather than quote the fragment",
      /CUT SHORT BY A STORAGE FAULT/.test(block || "") && /restate the objective whole/.test(block || "")
      && /routes were also cut short/.test(block || ""));
  }

  // SNG-359 — BACKLASH NARRATION + CONSERVE. Aevi authored 23 per-ability `backlash` lines and 23
  // `conserveSuppresses` lines, and NOT ONE reached the prompt.
  //
  // ⛔ THE GM WAS HANDED A NUMBER AND A SHRUG: "BACKLASH (engine-applied): -4 health, -10 energy — narrate
  // the cost", plus a generic list of suggestions (resonance-burn, light-scald, a nosebleed). That is what
  // you write when you do not know WHICH craft slipped. "The green takes YOU as readily as them" is what
  // the craft's author knows and the engine cannot invent.
  {
    const { loadContentHeadless: lch359 } = await import("./headless_content.mjs");
    const C359 = await lch359();
    const gmSrc359 = readFileSync(join(root, "engine/gm.js"), "utf8");
    const appSrc359 = readFileSync(join(root, "app.js"), "utf8");

    const authored = Object.values(C359.abilities).filter(a => a.backlash);
    check("359: the authored backlash content is loaded and non-empty", authored.length >= 20);
    check("359: …and the GM block emits the AUTHORED line, not only the numbers",
      /WHAT THE BACKLASH OF \$\{String\(resolution\.backlashText\.name\)/.test(gmSrc359));
    check("359: …and tells the narrator to use it INSTEAD of a generic burn",
      /narrate THIS, not a generic burn/.test(gmSrc359));

    // ⚠️ THERE ARE TWO BACKLASH DOORS — a crit-failure and a SURGE that slips. Wiring only the one I found
    // first would have left half the backlashes in the game still narrated from the generic list.
    check("359: BOTH backlash doors carry the authored line (crit-failure AND surge)",
      (appSrc359.match(/resolution\.backlashText = backlashLineFor\(/g) || []).length === 2);
    check("359: …and a craft that authors none falls back cleanly rather than inventing one",
      /return null;/.test(appSrc359.slice(appSrc359.indexOf("function backlashLineFor"), appSrc359.indexOf("function backlashLineFor") + 600)));

    // ⛔ CONSERVE IS PROSE, SO IT GOES TO THE NARRATOR — the open question Aevi left me. An engine clamp
    // would have to guess WHICH mechanical term it clamps, and would be wrong for most of the 23:
    // "the snare stays at bind only", "no bite, on anyone, including you" — these are statements about
    // fiction, not a numeric suppression the engine could apply.
    check("359: a CONSERVE use hands the craft's own suppression line to the narrator",
      /intensity === "conserve"/.test(appSrc359) && /conserveSuppresses/.test(appSrc359) && /CONSERVED \u2014 this use is held back/.test(gmSrc359));
    check("359: …and it is handed over whether or not anything backlashed — it describes the USE, not a failure",
      /if \(usesAbility && intensity === "conserve"\)/.test(appSrc359));
  }

  // SNG-365 — THE RATE SUB CONSUMERS. Four of the eight subs are `kind: "rate"`, and SNG-356 left them
  // deliberately unwired: a rate is READ where it applies, and banking one into a stored field would be
  // the writer-with-no-reader bug inverted. Four sites, one reader.
  {
    const { loadContentHeadless: lch365b } = await import("./headless_content.mjs");
    const C365 = await lch365b();
    const { successChance, critProfile } = await import("../engine/resolve.js");
    const { senseTier } = await import("../engine/sense.js");
    const { renownOf } = await import("../engine/reputation.js");
    const { rateValue } = await import("../engine/ladder.js");
    const mk = (subs) => ({ attributes: { physical: 3, social: 3 }, subAttributes: subs, alignment: {}, energy: 50, attunement: 2 });
    const roll = (ch, act) => successChance({ character: ch, action: act, location: null, rules: C365.rules });

    check("365: one reader serves every rate sub, so four sites cannot drift about what a rank is worth",
      rateValue(C365.rules.subAttributeLadder, mk({ agility: 12 }), "agility") > 0
      && rateValue(C365.rules.subAttributeLadder, mk({ strength: 12 }), "strength") === 0);   // a POOL sub is not a rate

    // agility → defence, at the site the defence aptitude already fires
    check("365: agility raises DEFENCE, and only on a defending action",
      roll(mk({ agility: 12 }), { attribute: "physical", subAttribute: "strength", tags: ["defend"], difficulty: "normal" })
        > roll(mk({ agility: 1 }), { attribute: "physical", subAttribute: "strength", tags: ["defend"], difficulty: "normal" })
      && roll(mk({ agility: 12 }), { attribute: "physical", subAttribute: "strength", tags: [], difficulty: "normal" })
        === roll(mk({ agility: 1 }), { attribute: "physical", subAttribute: "strength", tags: [], difficulty: "normal" }));

    check("365: wits raises the CRIT-SUCCESS dial",
      critProfile({ character: mk({ wits: 12 }), action: {}, rules: C365.rules }).successChance
        > critProfile({ character: mk({ wits: 1 }), action: {}, rules: C365.rules }).successChance);

    // ⛔ ERIK RATIFIED THAT INSIGHT SUMS with earned attunement rather than taking a max — attunement is what
    // practice gave you, insight is what you are, and a max() would make the smaller of the two free.
    check("365: insight SUMS with earned attunement (ratified), it does not replace it",
      senseTier({ character: mk({ insight: 12 }), action: {}, location: null, rules: C365.rules })
        > senseTier({ character: mk({ insight: 1 }), action: {}, location: null, rules: C365.rules }));

    // ⛔ PRESENCE HAS TWO CONSUMERS, NOT ONE (ratified).
    check("365: presence raises social BEARING — its first consumer",
      roll(mk({ presence: 12 }), { attribute: "social", subAttribute: "rapport", tags: [], difficulty: "normal" })
        > roll(mk({ presence: 1 }), { attribute: "social", subAttribute: "rapport", tags: [], difficulty: "normal" }));
    // ⛔ AND THE ANTI-DOUBLE-DIP, ratified: the bearing term fires EXCEPT when presence is the sub actually
    // rolled — there the ladder is already paying through the roll column, and paying twice for one rank.
    const tickSrc365 = readFileSync(join(root, "engine/resolve.js"), "utf8");
    check("365: …but NOT when presence is the rolled sub — one rank is never paid twice",
      /action\.subAttribute !== "presence"/.test(tickSrc365));

    const hero = (p, w) => ({ subAttributes: { presence: p }, deeds: [{ description: "d", weight: w, spread: ["a", "b"] }] });
    check("365: presence widens RENOWN — its second consumer",
      Math.abs(renownOf(hero(12, 3), C365.rules).reach) > Math.abs(renownOf(hero(1, 3), C365.rules).reach));
    // ⛔ AEVI WAS EXPLICIT: do not inherit a `d.weight > 0` guard — renown is NOT merit-signed, so a
    // high-presence villain becomes notorious FASTER. Magnitude, never merit, read through the person.
    check("365: …unsigned — a high-presence villain becomes notorious faster, not slower",
      Math.abs(renownOf(hero(12, -3), C365.rules).reach) > Math.abs(renownOf(hero(1, -3), C365.rules).reach));
  }

  // SNG-358 — POST. Erik: "He has 2 warden stations and a pregnant wife and a smithy… you have fortresses,
  // party members, businesses, etc at mid to late game." Built to the shape Aevi accepted from my review.
  {
    const { loadContentHeadless: lch358 } = await import("./headless_content.mjs");
    const C358 = await lch358();
    const { addHolding, advanceHolding, holdingNews, unstewardedHoldings, holdingsForGM, HOLDING_KINDS, CONDITIONS } = await import("../engine/holdings.js");
    const { runWorldTick } = await import("../engine/worldtick.js");
    const { worldCount } = await import("../engine/worldtime.js");

    // ⛔ A CONDITION THAT MOVES BOTH WAYS, NOT A COUNTER TO A TERMINUS — the whole reason a holding could
    // not simply be an assignment. `advanceAssignment` is monotonic with a terminal `done`, which would
    // have retired a post at the moment its steward succeeded.
    const h = addHolding({}, { id: "p", name: "Raven's Home", kind: "post", steward: "cassiel" });
    advanceHolding(h, "problem", 1); const dipped = h.condition;
    advanceHolding(h, "progress", 2);
    check("358: a holding's condition moves BOTH ways — it recovers, it does not complete",
      CONDITIONS.indexOf(h.condition) > CONDITIONS.indexOf(dipped) && h.condition !== "done");
    check("358: …and it never acquires a terminal state", !("progress" in h) && CONDITIONS.includes(h.condition));

    // ⚠️ ONE STEP PER PASS. My first formula double-penalised an unkept holding — "holding" straight past
    // "strained" to "failing" in one tick. A decline the player cannot see coming is a rug-pull, and the
    // point of four rungs is that it SLIDES.
    const un = addHolding({}, { id: "f", name: "The Forge", kind: "enterprise", steward: null });
    const seq = [];
    for (let i = 0; i < 3; i++) { advanceHolding(un, "problem", i); seq.push(un.condition); }
    check("358: an UNKEPT holding slides one rung per pass, never two", seq[0] === "strained" && seq[1] === "failing");
    // ⛔ …and it can never THRIVE, because nobody is there to make it. This is what makes a holding a claim
    // on your attention rather than scenery.
    const un2 = addHolding({}, { id: "g", kind: "enterprise", steward: null });
    for (let i = 0; i < 5; i++) advanceHolding(un2, "progress", i);
    check("358: …and cannot climb past 'holding' while it has no keeper", un2.condition === "holding");

    // ⛔ HOUSEHOLD IS NOT A KIND, BY DESIGN. Aevi: "stake and obligation, never a stat line." Putting it in
    // this table is the first step toward it acquiring `condition: thriving` — the sentence about a family
    // the game must never say.
    check("358: `household` is not a holding kind, and cannot be added as one",
      !HOLDING_KINDS.includes("household") && addHolding({}, { id: "h", kind: "household" }) === null);

    // A departed steward leaves the post behind — expressible only because SNG-355 made departure a status.
    check("358: a holding whose keeper has left is reported as unkept",
      unstewardedHoldings({ holdings: [h] }, []).length === 1 && unstewardedHoldings({ holdings: [h] }, ["cassiel"]).length === 0);
    check("358: the GM is told what you hold, who keeps it, and how it fares",
      /Raven's Home \(post, .*kept by cassiel\)/.test(holdingsForGM({ holdings: [h] }) || ""));

    // ⛔ HOLDINGS TURN ON THEIR OWN PASS. My first cut sat them INSIDE advanceDelegatedWork, behind its
    // `!due.length` early return — so a holding only moved if an ASSIGNMENT happened to be due at the same
    // moment. That is SNG-366's exact shape reintroduced one function over: a thing that should turn on its
    // own clock, sitting behind an unrelated gate, silent and green.
    const ch = { worldState: { lastTickDay: 14, eventStages: {}, spectrumDrift: {}, assignments: {} }, clock: { day: 14 }, npcRegistry: {}, holdings: [] };
    addHolding(ch, { id: "x", name: "The Forge", kind: "enterprise", steward: null });
    ch.holdings[0].lastMovedWorldCount = worldCount() - 100;
    const r = await runWorldTick({ character: ch, content: C358, currentDay: 14, advanceAssignments: async () => ({ advancements: [] }) });
    check("358: a holding advances with NO delegated work due and the character clock unmoved",
      r.ticked === true && ch.holdings[0].condition !== "holding");
    check("358: …and only a CHANGE of condition is news — a holding that goes on holding is not an event",
      holdingNews({ condition: "holding", name: "X" }, "holding") === null);
  }

  // SNG-367 — 33 OF 34 PORTRAITS LED WITH THE LITERAL "a person", which is why every figure rendered as
  // the same woman. ⛔ THE CAUSE IS A FALLBACK THAT NEVER RETURNS FALSY: `formOf()` returns "a person"
  // when form/lineage/appearance are absent, and it sat THIRD in the chain — so `description`, `role` and
  // `name` were unreachable for anyone without an authored form, which is almost everyone.
  {
    const { npcPromptSeed } = await import("../engine/art.js");
    const aes = { people: "grey, plainly dressed, unhurried. Hands calm and clean." };

    check("367: an NPC with only a role no longer leads with 'a person'",
      !npcPromptSeed({ name: "Aldric", role: "Smokehouse operator" }, {}).startsWith("a person,"));
    check("367: …the people layer leads when nothing about the body is authored",
      npcPromptSeed({ name: "Aldric", role: "Smokehouse operator" }, {}, { aesthetic: aes }).startsWith("grey, plainly dressed"));

    // ⛔ AEVI'S RULE, AND IT IS THE LOAD-BEARING ONE: "an authored form must win over the tradition layer —
    // that is what stops an Ent rendering human."
    const ent = npcPromptSeed({ name: "Barkfoot", form: "a towering treefolk of bark and heartwood", role: "warden" }, {}, { aesthetic: aes });
    check("367: an AUTHORED form wins over the people layer — this is what stops an Ent rendering human",
      ent.startsWith("a towering treefolk"));
    // ⚠️ …and the people layer is not discarded, it changes job: subject → register. An Ent of the
    // ashwardens is still an Ent, rendered grey and unhurried.
    check("367: …and the people layer survives as REGISTER rather than being dropped",
      /of a people who read as: grey, plainly dressed/.test(ent));

    check("367: a person with no people does not borrow one's face",
      !/of a people who read as/.test(npcPromptSeed({ name: "X", form: "a tall woman" }, {}, {})));

    // The ctx must actually reach the seed — the parameter existing is not the same as a caller passing it.
    const artSrc = readFileSync(join(root, "engine/art.js"), "utf8");
    const appSrc367 = readFileSync(join(root, "app.js"), "utf8");
    check("367: assembleImagePrompt carries ctx through to the npc seed, as the ability path already did",
      /npcPromptSeed\(subject, ctx\.character \|\| \{\}, ctx\)/.test(artSrc));
    // ⛔ SNG-367b — THE SECOND PORTRAIT DOOR, FOUND BY ERIK IN PLAY. The whois card seeded its image from
    // `known.lines[0]`, which is the TIER LINE ("heroic — a name in their own country"): a statement about
    // RENOWN with nothing in it about a face. So every world figure was drawn from a sentence about fame
    // and came back as the same person, however famous. Counting the doors is not finding them — I fixed
    // the NPC path and left this one.
    const whoisSrc = readFileSync(join(root, "engine/whois.js"), "utf8");
    check("367b: whoIs hands the portrait a BODY and a PEOPLE, not the tier line",
      // ⚠️ ASSERTS THE REQUIREMENT, NOT THE EXPRESSION. This pinned `appearance: fig.appearance`, and
      // 367c legitimately improved the chain to prefer the AUTHORED imagePrompt. What must hold is that a
      // body and a people reach the portrait — not the order of a fallback.
      /tradition: fig\.tradition/.test(whoisSrc) && /appearance: fig\./.test(whoisSrc));
    check("367b: …and the card no longer seeds the image from lines[0]",
      !/appearance: known\.lines\?\.\[0\]/.test(appSrc367));
    // ⚠️ AND THE AESTHETIC MUST RIDE INSIDE promptOpts — my first fix passed it as a top-level option, where
    // assembleImagePrompt never sees it. A parameter in the wrong bag is indistinguishable from no
    // parameter at all, and the card would have looked fixed while rendering exactly as before.
    // ⛔ SNG-367c — ALL 70 AUTHORED FIGURES CARRY AN `imagePrompt` WRITTEN FOR EXACTLY THIS, and the card
    // read none of them. "A rootkin standing exactly on the treeline where thick green meets open ground,
    // looking neither way. Dappled light, a carved staff, a decision refused for years." That is a
    // portrait. The tier line it was using is a sentence about fame.
    const { loadContentHeadless: lch367c } = await import("./headless_content.mjs");
    const C367c = await lch367c();
    const roster367 = C367c.legends?.roster || [];
    check("367c: every authored world figure carries an imagePrompt — the portrait was always there",
      roster367.length > 0 && roster367.every(f => f.imagePrompt));
    // ⚠️ RE-AIMED (CCODE-173): the property is that an AUTHORED description outranks anything derived
    // (`form`, the name, the tier line). Which authored field leads changed; that it leads did not.
    check("367c/173: …and whoIs hands an AUTHORED description to the portrait, ahead of anything derived",
      /appearance: fig\.(?:appearance|imagePrompt) \|\| fig\.(?:imagePrompt|appearance) \|\| fig\.form/.test(whoisSrc));

    // ⚠️ GENDER IS STATED EXPLICITLY SO THE GENERATOR CANNOT DEFAULT — SNG-143's own reason (the
    // Pell-rendered-male fix). The seed has always had the line; the whois card never supplied a value.
    const { npcPromptSeed: seed367 } = await import("../engine/art.js");
    check("367c: a gender, when known, reaches the portrait seed",
      /a woman/.test(seed367({ id: "x", name: "N", role: "r", appearance: "a figure", gender: "a woman" }, {}, {})));
    check("367c: …and the card passes it through", /gender: known\.gender \|\| undefined/.test(appSrc367));

    // ⚠️ ASSERT THE PROPERTY, NOT THE SPELLING. This pinned the literal argument list, so SNG-399b's
    // life-or-death seed choice broke a gate about the AESTHETIC riding through — a gate failing for a
    // reason unrelated to what it protects. What matters is that promptOpts carries the aesthetic.
    // ⚠️ RE-AIMED (CCODE-164). This pinned the LITERAL argument list, so adding `keeps:` alongside
    // `aesthetic:` broke a gate about the people-layer for a reason that had nothing to do with it — the
    // third time a gate in this file has failed on the spelling of a line instead of the property it
    // protects. It now asserts what it is actually for: the aesthetic reaches promptOpts.
    check("367b: …and the people layer rides inside promptOpts, where assembleImagePrompt can read it",
      /promptOpts: \{[^}]*aesthetic: aesW/.test(appSrc367));

    check("367: …and the npc image call supplies the tradition aesthetic",
      /npcAesthetic\(n\)/.test(appSrc367) && /aesthetic: aes367/.test(appSrc367));
  }

  // SNG-366 — DELEGATED WORK MOVES ON WORLD DAYS. Erik ratified: character days are PLAYER-ADVANCED and
  // therefore gameable — spam rest to fast-forward your steward, or refuse to rest to freeze the world.
  //
  // ⛔ AEVI FOUND WHY THE FIX IS TINY: `advanceAssignment()` has ALWAYS written `lastMovedWorldCount =
  // worldCount()`. The stamp was there from the start; THE GATE NEVER READ IT. It gated on `elapsed >= 3`
  // character days, under an `elapsed <= 0` early return Silas has been parked on for 915 actions.
  {
    const { loadContentHeadless: lch366 } = await import("./headless_content.mjs");
    const C366 = await lch366();
    const { runWorldTick, advanceDelegatedWork } = await import("../engine/worldtick.js");
    const { worldCount } = await import("../engine/worldtime.js");
    const nc = worldCount();
    const mk = (lastMoved, n = 1) => {
      const a = {};
      for (let i = 0; i < n; i++) a["x" + i] = { id: "x" + i, npcId: "n" + i, npcName: "Steward " + i, charge: "charge " + i, status: "working", progress: 0, stampedAtWorldCount: lastMoved, lastMovedWorldCount: lastMoved };
      return { worldState: { lastTickDay: 14, eventStages: {}, spectrumDrift: {}, assignments: a }, clock: { day: 14 }, npcRegistry: {} };
    };
    const adv = async ({ assignments }) => ({ advancements: assignments.map((a, i) => ({ assignmentId: a.id, outcome: i === 0 ? "done" : i === 1 ? "problem" : "progress", note: "moved" })) });

    // ⛔ SILAS'S EXACT LIVE STATE: clock day 14, lastTickDay 14 → elapsed 0 → the early return. Work must
    // advance anyway, because the world does not wait for the player to sleep.
    const stale = mk(nc - 100);
    const r = await runWorldTick({ character: stale, content: C366, currentDay: 14, advanceAssignments: adv });
    check("366: delegated work advances even when the CHARACTER clock has not moved",
      stale.worldState.assignments.x0.progress > 0 && r.ticked === true);

    // ⚠️ GATED PER-ASSIGNMENT, so one delegated an hour ago does not ride along with one delegated last week.
    const fresh = mk(nc);
    await runWorldTick({ character: fresh, content: C366, currentDay: 14, advanceAssignments: adv });
    check("366: …and a charge delegated moments ago does NOT advance — the gate is per-assignment",
      fresh.worldState.assignments.x0.progress === 0);

    // ⛔ CATCH-UP GETS A DIGEST. Aevi: a month away is ~10 intervals, and ten separate progress notices
    // would feel WORSE than the silence they replace — a wall of small news is how a player learns to skip it.
    const many = mk(nc - 100, 4);
    const r2 = await runWorldTick({ character: many, content: C366, currentDay: 14, advanceAssignments: adv });
    check("366: a catch-up of several charges reports as ONE digest, not a wall of notices",
      r2.news.length === 1 && /charges moved/.test(r2.news[0].text) && r2.news[0].section === "yours");
    const one = mk(nc - 100, 1);
    const r3 = await runWorldTick({ character: one, content: C366, currentDay: 14, advanceAssignments: adv });
    check("366: …while a single charge still gets its own full line", r3.news.length === 1 && /has finished/.test(r3.news[0].text) && r3.news[0].section === "yours");

    // ⚠️ ONLY THIS BLOCK WAS LIFTED. Repointing the whole tick at world time would change events, drift and
    // deed-spread all at once, on no evidence — the opposite of sim-before-tweak.
    const tickSrc = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    // ⚠️ ASSERTS THE INVARIANT, NOT THE LINE. This pinned the exact text of the early-return, and SNG-358
    // legitimately changed it when holdings joined the world-time passes. What must stay true is the
    // SHAPE: world-gated work runs ABOVE the character-day gate, and the gate still exists so events,
    // drift and deed-spread keep their own cadence.
    // ⚠️ …AND NOT THE DISTANCE EITHER. The `{0,300}` window above was a pinned measurement wearing an
    // invariant's clothes: four lines of SNG-368 commentary between the call and the gate pushed them apart
    // and turned it red without anything moving. ORDER is the invariant — the call comes BEFORE the gate.
    check("366: only the world-time passes were lifted above the early return — the rest keeps character cadence",
      (() => { const body = tickSrc.slice(tickSrc.indexOf("export async function runWorldTick"));
        const call = body.indexOf("await advanceDelegatedWork("), gate = body.indexOf("if (elapsed <= 0) return { ticked:");
        return call > -1 && gate > call && /for \(const \{ eventId, stage \}/.test(body.slice(gate)); })());
    // ⚠️ And it reports what MOVED, not what was worth SAYING — a quiet `progress` prints no line by design,
    // and inferring "nothing happened" from "no news" is the same error as reading absence as evidence.
    // ⚠️ MATCHED ON `moved: moved.length` ALONE, not the whole return literal. Pinning the exact line went
    // red the moment SNG-364 mapped the news array to add a section — a gate describing the shape of a
    // count should not care what its sibling field looks like.
    check("366: the tick reports what MOVED, never inferring it from whether there was news",
      /moved: moved\.length/.test(tickSrc) && !/moved: news\.length/.test(tickSrc));
  }

  // ══ SNG-368 — THE THREE NEWS SECTIONS (Erik). Three sections, three EXISTING sources; nothing new is
  // generated. ⛔ It was blocked on SNG-366 and SNG-363 and Erik named the failure in advance: "sectioning
  // first shows an empty middle and a flooded third" — `yours` came from delegated work that had never
  // advanced for anyone in play, and `elsewhere` from cross-character events with no distance gate.
  {
    const wt364 = await import("../engine/worldtick.js");
    check("368: there are exactly three sections, and they are named in content order, not invented per call",
      Array.isArray(wt364.NEWS_SECTIONS) && wt364.NEWS_SECTIONS.length === 3
      && wt364.NEWS_SECTIONS.map(s => s.id).join(",") === "world,yours,elsewhere"
      && wt364.NEWS_SECTIONS.every(s => typeof s.title === "string" && s.title.length > 4));
    // ⛔ THE SECTION IS ASSIGNED AT THE SOURCE. A classifier reading prose would file "Cassiel has finished
    // the rebuild" under whichever heading its keywords matched today and drift the first time anyone
    // rewrote the line. The pass that produced the news already knows which of the three it is.
    check("368: a source-tagged entry keeps its section",
      wt364.stampNews({ text: "word from far off", section: "elsewhere" }, { day: 1 }).section === "elsewhere");
    check("368: an UNTAGGED entry falls to `world` — the section that is never empty, not a new orphan heading",
      wt364.stampNews("something stirs", { day: 1 }).section === "world");
    check("368: an entry claiming a section that does not exist is corrected, not trusted",
      wt364.stampNews({ text: "x", section: "sidebar" }, { day: 1 }).section === "world");
    check("368: stamping preserves what the digest already carried — text, day, worldDay, tier, impactsLocal",
      (() => { const r = wt364.stampNews({ text: "near thing", worldDay: 41, tier: "ambient", impactsLocal: true }, { day: 7, worldDay: 9 });
        return r.text === "near thing" && r.day === 7 && r.worldDay === 41 && r.tier === "ambient" && r.impactsLocal === true; })());
    // ⚠️ THE THREE PASSES EACH TAG THEIR OWN, and this is the check that the wiring exists rather than the
    // vocabulary alone — a section vocabulary nothing routes into is the writer-with-no-reader shape.
    const tick364 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    check("368: delegated work and holdings are tagged `yours` at the source",
      (tick364.match(/section: "yours"/g) || []).length >= 3);
    check("368: the deed spread and cross-character events are tagged `elsewhere`",
      (tick364.match(/section: "elsewhere"/g) || []).length >= 2);
    // ⚠️ AN EMPTY SECTION IS OMITTED AND A LONE SECTION SHOWS NO HEADINGS AT ALL — Erik's exact warning,
    // gated so it cannot regress into three labels over four lines.
    const app364 = readFileSync(join(root, "app.js"), "utf8");
    check("368: the renderer drops empty sections rather than printing a heading over nothing",
      /populated\s*=\s*NEWS_SECTIONS\.filter\(s => bySection\.get\(s\.id\)\.length\)/.test(app364));
    check("368: …and a digest with only ONE populated section renders exactly as it did before, unheaded",
      /populated\.length > 1/.test(app364));
  }

  // SNG-365 — Erik: "did you put in the 'Attainable' filter for what you can buy with how many skill points
  // you have? and we need to get more room in for the skill wheel..."
  //
  // ⛔ THE HONEST ANSWER WAS NO. SNG-348 put the buyable filter on the LEVEL-UP learn list, and the wheel is
  // the browse surface (SNG-218 §3: "the WHEEL is the browse surface"). I built it where the list was
  // rather than where the browsing happens.
  {
    const appSrc365 = readFileSync(join(root, "app.js"), "utf8");
    const cssSrc365 = readFileSync(join(root, "style.css"), "utf8");

    check("365: the wheel has an Attainable filter", /id="buy-filter"/.test(appSrc365) && /wheelBuyableFilter/.test(appSrc365));
    // ⚠️ IT COSTS NOTHING TO COMPUTE AND CANNOT DISAGREE WITH THE BUTTON. `nd.reachable` IS canLearnAbility,
    // which SNG-218 §1 made the ONE gate — level, domain, attribute, standing, capacity AND affordability.
    // A filter that recomputed affordability would be a second opinion on the same question, which is the
    // SNG-348 lesson; here the node already knew.
    check("365: …and it reads the ONE gate (nd.reachable), never its own arithmetic",
      /passBuy = !wheelBuyableFilter \|\| \(nd\.reachable && !nd\.owned\)/.test(appSrc365));
    check("365: …and it STACKS with the function and Suggested filters rather than replacing them",
      /passFn && passSug && passBuy/.test(appSrc365) && /wheelSuggestFilter \|\| wheelBuyableFilter/.test(appSrc365));
    check("365: …and clear resets it too — a filter you cannot turn off is a trap",
      /fn-filter-clear[\s\S]{0,200}wheelBuyableFilter = false/.test(appSrc365));

    // Room: the legend was three standing lines above the feature itself.
    check("365: the legend collapses behind a summary instead of standing above the wheel",
      /<details class="wheel-legend">/.test(appSrc365));
    // ⛔ 82vh WAS MEASURED AGAINST THE VIEWPORT, NOT AGAINST WHAT THE CHROME LEAVES — so the taller the
    // header grew, the further the wheel fell below the fold and the PAGE scrolled instead of the canvas.
    check("365: the canvas is bounded by the room actually left, not by the viewport alone",
      /height: min\(82vh, calc\(100vh - 190px\)\)/.test(cssSrc365));
  }

  // SNG-364 — Erik: "All of these NPCs need portraits. and the portrait needs to pop up from the new
  // tabs… just like when they fight or get killed."
  //
  // ⚠️ THE FIGURES A PLAYER MEETS ONLY IN A WORLD-TICK DIGEST ARE THE ONES WHO MOST NEED A FACE, because
  // they are never in a scene. Valen Sunwrack, the Thornmother, the Clockmother — the tick writes about
  // them constantly and they were a name and a sentence. The portrait machinery already existed; it was
  // simply never pointed at them.
  {
    const appSrc364 = readFileSync(join(root, "app.js"), "utf8");
    const whoisSrc = readFileSync(join(root, "engine/whois.js"), "utf8");
    // ⚠️ THE WINDOW IS SIZED TO THE FUNCTION, NOT GUESSED. A fixed 2600-char slice went red when SNG-367b
    // added twelve lines of comment ahead of the markup — a gate failing because the code it reads grew a
    // paragraph is a gate measuring the wrong thing. Cut at the next top-level function instead.
    const wStart = appSrc364.indexOf("function showWhoIs");
    const wEnd = appSrc364.indexOf(String.fromCharCode(10) + "function ", wStart + 10);
    const card = appSrc364.slice(wStart, wEnd > wStart ? wEnd : wStart + 6000);

    check("364: the who-is card renders a portrait for a FIGURE", /whoPortrait/.test(card) && /kind === "figure"/.test(card));
    // ⛔ SEEDED ON THE ID, NOT THE LABEL. These people acquire titles in play — "Valen Sunwrack, Who Left No
    // Shadow Standing" — and a face keyed to the displayed name would change the moment the world renamed
    // them, which quietly says this is a different person.
    // ⚠️ the seed is chosen between a living and a death key now (SNG-399b); BOTH are built from the
    // stable id, which is the property this gate exists to hold.
    // ⚠️ RE-AIMED (CCODE-171). It pinned `whois-${seed}` and the raw `codexId || id || label` fallback. The
    // property is that the seed is STABLE and derived from an id rather than a display name — which is now
    // MORE true, not less: it resolves to the canonical person first and keeps the old chain as fallback.
    check("364: …seeded on the stable id so the same figure keeps the same face",
      /seedKey: artSeed/.test(card) && /canonicalPersonId\(character, \{ entityId: known\.codexId \|\| known\.id/.test(card) && /known\.codexId \|\| known\.id \|\| known\.label/.test(card));
    check("364: …and whoIs returns that id, so the seed survives a rename", /kind: "figure", id, lines/.test(whoisSrc));
    // A card taller than the phone is the SNG-353 lesson, one screen over.
    check("364: …and the card scrolls, with the portrait and the text in the same scroll region",
      /overflow-y:auto[\s\S]{0,120}whoPortrait[\s\S]{0,200}help-short/.test(card));
    check("364: a portrait failure never breaks the card", /catch \{ \/\* a face is never worth breaking the card for \*\//.test(card));
  }

  // SNG-350 — TWO LIVE STRINGS, AND THE INVENTORY BEHIND THEM.
  //
  // Both skill-wheel screens said "Tap a node to learn or deepen it here" while the function beneath them
  // documents the deepen affordance as gone (SNG-349). The game was lying on two screens.
  {
    const appSrc350 = readFileSync(join(root, "app.js"), "utf8");
    check("350: no screen still offers to DEEPEN a craft by tapping — depth is earned by use",
      !/learn or deepen it here/.test(appSrc350));
    check("350: …and both replacements say where depth actually comes from",
      (appSrc350.match(/depth is earned by USE, never bought/g) || []).length === 2);

    // ⚠️ THE INVENTORY IS A REPORT, NOT A GATE, AND THAT IS AEVI'S CALL: "Count it, author nothing. The
    // copy half is mine." A gate here would make ME the arbiter of what counts as content, which is
    // precisely the half she reserved. What IS gated is that the tool exists and stays honest about being
    // a heuristic — a scope, not a work order.
    const invSrc = readFileSync(join(root, "tests/copy_coupling.mjs"), "utf8");
    check("350: the coupling inventory exists and applies AEVI'S test, not a tone judgement",
      /Could this string become FALSE if a value or rule/.test(invSrc));
    check("350: …and states plainly that it authors nothing", /Count it, author nothing/.test(invSrc));
  }

  // SNG-363 — CROSS-CHARACTER NEWS HAD NO DISTANCE AND NO SIGNIFICANCE GATE. Erik: "Why is Silas hearing
  // about something Splarf did? It's not huge news and they're far apart."
  //
  // ⛔ The filter was: not you · newer than last read · not hidden. `e.where` was read ONLY TO PRINT
  // "(near X)" — it never decided whether you heard it — and `slice(-5)` capped by RECENCY, so a burst of
  // small local events could crowd out a genuinely large one. Erik was describing the system as written.
  {
    const { loadContentHeadless: lch363 } = await import("./headless_content.mjs");
    const C363 = await lch363();
    const { ledgerBand, spreadNews, collapseLedgerEvents } = await import("../engine/worldtick.js");
    const R363 = {}, B363 = {};
    for (const loc of Object.values(C363.locations || {})) {
      const c = loc?.communityId, r = loc?.regionId || loc?.region || (c ? String(c).split(".")[0] : null);
      if (!c || !r) continue;
      (B363[r] ||= []).includes(c) || B363[r].push(c);
      R363[c] = r;
    }
    // ⛔ CALL spreadDeeds, DO NOT REIMPLEMENT IT — Aevi amended the spec to say so after my first version
    // invented its own thresholds (0.2 / 0.6). That was the invented-number failure the standing rule
    // exists to stop, AND the wrong model: SNG-281 already establishes that news TRAVELS, one hop per
    // pass, capped by magnitude. A distance band makes a far event instantly heard or never heard; the
    // spread makes it take TIME, which is what makes "word reaches you" a true sentence.
    const tickSrc363 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    check("363: the news gate CALLS spreadDeeds rather than reimplementing the spread",
      /import \{ spreadDeeds \}/.test(tickSrc363) && /spreadDeeds\(carrier,/.test(tickSrc363));
    check("363: …and no invented distance thresholds survive", !/thresholds\.sameRegion|t\.adjacent|t\.far/.test(tickSrc363));

    // The band is 1/2/3 — the same scale a deed's weight uses, not a scale of mine.
    check("363: magnitude is banded 1/2/3, the scale spreadDeeds already caps on",
      ledgerBand({ spectrumDeltas: {} }) === 1 && ledgerBand({ spectrumDeltas: { a: 0.7 } }) === 3);
    // ⚠️ Σ|spectrumDeltas| IS EMPTY IN PRACTICE (1 of 8 live entries), so the ACTOR'S TIER carries the
    // rest — Aevi's pointer that whois TIER_MEANING is already a distance ladder.
    check("363: …and a mythic actor's doings travel further than a nobody's (tier widens reach)",
      ledgerBand({ spectrumDeltas: {} }, { actorTier: "mythic" }) > ledgerBand({ spectrumDeltas: {} }, { actorTier: "riffraff" }));

    // ⛔ impactsLocal BYPASSES THE WHOLE MECHANISM — a DIRECTED consequence, escrow-confirmed by the
    // acting player (SNG-145). Making it wait for word of mouth would break a deliberate mechanism.
    const anywhere = Object.values(C363.locations || {}).find(l => l.communityId);
    const chD = { currentLocationId: anywhere.id, worldState: {} };
    const directed = spreadNews({ character: chD, content: C363, entries: [{ who: "o", at: "t", where: "nowhere-at-all", what: "x", impactsLocal: true }], regionOfCommunity: R363, communitiesByRegion: B363 });
    check("363: impactsLocal bypasses the spread entirely — it never waits for word of mouth", directed.length === 1);

    // An unplaceable event (pre-SNG-329 `gen-object-object` residue) has no origin to spread FROM. Judged
    // on magnitude, never deleted — a gate that drops what it cannot place quietly edits the world.
    const chU = { currentLocationId: anywhere.id, worldState: {} };
    const big = spreadNews({ character: chU, content: C363, entries: [{ who: "o", at: "t", where: "gen-object-object", what: "x", spectrumDeltas: { a: 0.9 } }], regionOfCommunity: R363, communitiesByRegion: B363 });
    const small = spreadNews({ character: chU, content: C363, entries: [{ who: "o", at: "t2", where: "gen-object-object", what: "y", spectrumDeltas: {} }], regionOfCommunity: R363, communitiesByRegion: B363 });
    check("363: an UNPLACEABLE event is judged on magnitude, not dropped", big.length === 1 && small.length === 0);

    // ⚠️ THE SPREAD STATE IS PER-CHARACTER, never on the shared ledger: whose ears a rumour has reached
    // is not a property OF the event, and the ledger is one file many players write.
    check("363: whose ears word has reached is per-character state, not written onto the shared ledger",
      /ws\.newsSpread/.test(tickSrc363) && !/e\.spread =/.test(tickSrc363));

    // §3 — one beat logged twice. Measured: the true double-log is FOUR MINUTES apart; the distinct pair at
    // the same place is a different world-day. The CLOCK separates them where prose cannot.
    const day = (n, atISO, what) => ({ who: "c1", where: "the_thinning", worldDay: n, at: atISO, what, tags: [] });
    const collapsed = collapseLedgerEvents([
      day(36, "2026-08-05T23:59:30Z", "The veil at The Thinning sealed itself after a failed bridge-attempt"),
      day(37, "2026-08-06T18:06:00Z", "The sealed veil at The Thinning opened and a messenger crossed through"),
      day(37, "2026-08-06T18:10:00Z", "The sealed veil at The Thinning opened by choice and allowed safe passage through"),
    ]);
    check("363: two tellings of one beat, minutes apart, collapse to one", collapsed.length === 2);
    check("363: …the survivor keeps the FULLER telling", /safe passage/.test(collapsed[1].what));
    check("363: …and a genuinely distinct earlier event at the same place SURVIVES", /sealed itself/.test(collapsed[0].what));
    // ⚠️ Aevi's constraint: a real escalation at one place in one day must survive. Hours apart ⇒ never collapsed.
    const escalation = collapseLedgerEvents([
      day(37, "2026-08-06T09:00:00Z", "The sealed veil at The Thinning opened and a messenger crossed through"),
      day(37, "2026-08-06T19:00:00Z", "The sealed veil at The Thinning opened and a messenger crossed through again"),
    ]);
    check("363: a real escalation hours apart is NEVER collapsed — collapse, never drop", escalation.length === 2);

    // ⚠️ Σ|spectrumDeltas| IS EMPTY IN PRACTICE — ONE of eight live entries carries any. That finding
    // stands and is why the ACTOR TIER carries the rest, but the continuous `ledgerWeight` it justified
    // is gone: the amended spec bands on 1/2/3, the scale spreadDeeds already caps on, and a second
    // weight scale of my own was exactly the invention Aevi told me not to make.
    check("363: a bandless entry still gets a usable band, since the spectral signal is usually absent",
      ledgerBand({ spectrumDeltas: {}, tags: [] }) >= 1);
  }

  // SNG-360 — SIX MERGE DECISIONS DUMPED ON THE PLAYER, AND THE REASON THERE WERE SIX.
  //
  // Erik: "the user can't make all these calls and WHY are there so many to begin with!! these need an
  // allocation upstream i think." He is right on both counts, and the second is the real bug.
  {
    const codexSrc = readFileSync(join(root, "engine/codex.js"), "utf8");
    const gmSrc360 = readFileSync(join(root, "engine/gm.js"), "utf8");
    const { codexForGM } = await import("../engine/codex.js");

    // ⛔ THE GM WAS ASKED FOR AN ID IT WAS NEVER SHOWN. The op contract says `topic (stable kebab id)`,
    // and codexForGM emitted the LABEL only — so the model could not reuse an existing topic even in
    // principle, and did the only thing available: invent a fresh headline every beat. Three topics grew
    // for one Veil, and the player was handed the reconciliation.
    const ch360 = { codex: { topics: { "the-veil": { id: "the-veil", label: "The Veil", kind: "mystery", facts: ["it tires"], links: [], updatedDay: 5 } } } };
    const block = codexForGM(ch360, {});
    check("360: the GM is shown each topic's ID, not just its label — it cannot reuse what it never sees",
      !!block && block.includes("[the-veil]"));
    check("360: …and is told a topic is a SUBJECT that accumulates facts, not a per-beat headline",
      /A CODEX TOPIC IS A SUBJECT THAT ACCUMULATES FACTS, NOT A HEADLINE/.test(gmSrc360));
    check("360: …with the real failure named concretely, so the instruction teaches by example",
      /Veil as Boundary-Agent/.test(gmSrc360));

    // The downstream judge already existed and its docstring already promised the right thing —
    // "unsure → the ONLY thing that reaches the player". The queue is the symptom; keep the promise honest.
    check("360: the judge's contract still says only an UNSURE pair reaches the player",
      /unsure[\s\S]{0,80}ONLY thing that reaches the player/.test(codexSrc));
  }

  // SNG-353 — THE COMPANIONS WERE FULLY AUTHORED AND ALMOST ENTIRELY INVISIBLE. Erik, in play: "I searched
  // codex but can't find what they do or the growing bond meaning… they don't have a popup info either."
  //
  // ⛔ HE DID NOT MISS IT. IT WAS NOT THERE. Twelve authored fields per companion, two and a half reachable.
  // ⚠️ This is the INVERSE of the bug we keep catching: SNG-339 found readers with no writers, SNG-342 found
  // registered files nothing loads. This is a WRITER WITH NO READER — and Aevi's point is the sharp one:
  // the consumer contract asserts that content supplies what consumers read, and NEVER that an authored
  // field has a consumer at all. A field nothing reads passes every gate we own.
  {
    const appSrc353 = readFileSync(join(root, "app.js"), "utf8");
    const { loadContentHeadless: lch353 } = await import("./headless_content.mjs");
    const C353 = await lch353();
    const comps = Object.values(C353.companions || {});

    // Every field the defect names must reach a surface. Asserted against the RENDERER, because "it is
    // authored" was already true — that was the whole bug.
    // ⚠️ No regex here on purpose: an escaped \b in this file has twice become a literal backspace
    // character through the authoring tooling. `includes` cannot be mangled, and the question is simply
    // whether the panel reads the field at all.
    const panelStart = appSrc353.indexOf("function showCompanionPanel");
    // ⛔ THE WINDOW IS THE FUNCTION, NOT A CHARACTER COUNT. This read `slice(panelStart, +6000)`, and
    // adding fourteen lines near the top of the panel pushed `c.persona`, `c.knowledge` and `c.boundaries`
    // out the far end — three gates went red on code that still rendered every one of them. That is the
    // FIFTH gate of mine to fail on a pinned position rather than a broken truth (a fixed count of
    // traditions, a fixed skillPointPerLevel, a fixed index in SALVAGEABLE_OPS, a fixed slice). ⚠️ A GATE
    // MAY ASSERT THE SHAPE OF A RULE, NEVER AN INCIDENTAL MEASUREMENT OF IT — a red light that means "the
    // file grew" teaches everyone to distrust red lights.
    const nextFn = appSrc353.indexOf("\nfunction ", panelStart + 1);
    const panelSrc = panelStart < 0 ? "" : appSrc353.slice(panelStart, nextFn > panelStart ? nextFn : undefined);
    check("353: the panel function exists at all", panelStart > 0);
    // ⚠️ UNROLLED ON PURPOSE. These were a loop with a TEMPLATE-LITERAL name, and the ledger's 272 guard
    // scans SOURCE for `check("…")` literals — so a gate whose name is constructed at runtime can be
    // claimed by a requirement and never found, which reads exactly like a deleted gate. A gate name has
    // to be a findable constant, the same lesson 272 already carries about not embedding data in it.
    check("353: `persona` reaches a surface (it was authored and rendered NOWHERE)", panelSrc.includes("c.persona"));
    check("353: `knowledge` reaches a surface (it was authored and rendered NOWHERE)", panelSrc.includes("c.knowledge"));
    check("353: `boundaries` reaches a surface (it was authored and rendered NOWHERE)", panelSrc.includes("c.boundaries"));
    check("353: `appearance` reaches a surface (it was authored and rendered NOWHERE)", panelSrc.includes("c.appearance"));
    check("353: `stages` reaches a surface (it was authored and rendered NOWHERE)", panelSrc.includes("c.stages"));

    check("353: boundaries render VERBATIM — never summarised",
      /comp-boundaries[\s\S]{0,200}esc\(c\.boundaries\)/.test(appSrc353));

    // ⛔ THE TWO TOOLTIPS WERE THE ONLY DELIVERY FOR role AND appearance, AND HOVER DOES NOT EXIST ON TOUCH.
    check("353: the panel opens from BOTH the company row and the codex — the codex is where Erik looked",
      (appSrc353.match(/data-companion=/g) || []).length >= 2);
    check("353: …and it is keyboard-reachable, not hover-only", /onkeydown[\s\S]{0,120}showCompanionPanel/.test(appSrc353));

    // §1 — the bond reads as PROGRESS, not a score. Every number was already computed and never said.
    const { companionStageThresholds, bondOf } = await import("../engine/companions.js");
    const c0 = comps.find(c => (c.stages || []).length > 1) || comps[0];
    const th = companionStageThresholds((c0.stages || []).length, C353.rules);
    check("353: the engine already knew the next threshold — it just never said it", th.length > 0);
    check("353: the badge reads bond x/max and names the next threshold",
      /bond \$\{b\.bond\}\/\$\{mx\}/.test(appSrc353) && /next \$\{nx\}/.test(appSrc353));

    // ⛔ ERIK'S RULING: NAME IT, SEAL THE REST. bondGrants was read at exactly ONE place — the moment it
    // fired — so "what does the growing bond mean" was authored per companion and unreachable until the
    // question stopped mattering. A reward the player cannot see is not an incentive, it is a surprise.
    const panel = appSrc353.slice(appSrc353.indexOf("function showCompanionPanel"), appSrc353.indexOf("function showCompanionPanel") + 6000);
    check("353: the bond gift is NAMED as a goal, with its threshold", /will teach you <strong>\$\{esc\(g\.name\)\}/.test(panel));
    check("353: …and SEALED — no grants text, no functions, no ranks leak into the panel",
      !/g\.description/.test(panel) && !/g\.functions/.test(panel) && !/g\.notFor/.test(panel));
    check("353: …and its ARRIVAL is the braid/mint celebration, not a status line",
      /showBraidMoment\(\{ \.\.\.def, kind: "bondGift"/.test(appSrc353) && /A BOND DEEPENS/.test(appSrc353));

    // Nothing new was authored — the ticket's own claim, worth holding to.
    check("353: no companion needed new content — every field already existed",
      comps.every(c => c.persona && c.boundaries && Array.isArray(c.knowledge)));
  }

  // SNG-355 — THE GM COULD NOT ADD OR REMOVE A PARTY MEMBER. ONLY A BUTTON COULD.
  //
  // Erik: "the story had let some of them depart while still remaining in my party." recruit() and
  // partCompany() both worked and were called from exactly two places, both btn.onclick behind a confirm().
  // The entity that NARRATES the story had no mechanism to record that it happened.
  {
    const { activeCompany, formerCompany, applyPartyOps, recruit, partCompany, trainerFor } = await import("../engine/company.js");
    const { reconcile } = await import("../engine/reconcile.js");

    // ⛔ DEPARTURE IS A STATUS, NOT A DELETE. It was `filter(m => m.npcId !== npcId)` — so someone who
    // travelled with you for twenty days and left was ERASED rather than remembered.
    const ch = { npcRegistry: { calvar: { name: "Calvar" } }, company: [] };
    recruit(ch, "calvar", { roles: ["ally", "trainer"], teaches: "somatic", day: 18 });
    partCompany(ch, "calvar", { day: 34, why: "turned back toward the March" });
    check("355: a departure KEEPS the record — history, not absence",
      formerCompany(ch).length === 1 && formerCompany(ch)[0].leftDay === 34 && formerCompany(ch)[0].departedWhy);
    check("355: …and joinedDay survives it, so 'travelled with you, days 18–34' is answerable",
      formerCompany(ch)[0].joinedDay === 18);

    // ⚠️ THE ONE REAL REGRESSION RISK AEVI NAMED: five call sites read character.company, and a former
    // member leaking into ANY present-tense answer is the whole bug in a new place.
    check("355: a departed member is not in the active company", activeCompany(ch).length === 0);
    check("355: …and their benefits stop the day they leave", trainerFor(ch).size === 0);

    // Rejoining reads the old record — what makes "the road may cross again" actionable.
    recruit(ch, "calvar", { roles: ["ally"], day: 50 });
    check("355: rejoining restores the PERSON, not a stranger with their name",
      activeCompany(ch).length === 1 && activeCompany(ch)[0].joinedDay === 18 && activeCompany(ch)[0].rejoinedDay === 50 && !activeCompany(ch)[0].leftDay);

    // ⛔ ENTRY NEEDS CONSENT, EXIT DOES NOT — asymmetric on purpose. Aevi: "a departure that requires the
    // player's permission is not a departure."
    const ch2 = { npcRegistry: { pell: { name: "Pell" }, siol: { name: "Siol" } }, company: [{ npcId: "pell", roles: ["ally"], joinedDay: 17 }] };
    const r = applyPartyOps(ch2, [{ op: "depart", npcId: "pell", why: "called home" }, { op: "join", npcId: "siol" }], { day: 40 });
    check("355: a GM DEPART applies immediately — the story's to decide", r.departed.length === 1 && activeCompany(ch2).every(m => m.npcId !== "pell"));
    check("355: a GM JOIN only PROPOSES — the player assents to a commitment", r.proposed.length === 1 && !activeCompany(ch2).some(m => m.npcId === "siol"));
    // ⚠️ Without this, a GM can "depart" a stranger and mint a departure record for someone who was never
    // in the party — history invented rather than kept.
    const before = ch2.company.length;
    applyPartyOps(ch2, [{ op: "depart", npcId: "nobody" }], { day: 41 });
    check("355: only someone ACTUALLY with you can depart — no invented history", ch2.company.length === before);

    // §1c — the teacher role, lost at recruit for every generated NPC.
    const gen = { npcRegistry: { "veth-ondra": { name: "Veth-Ondra", teaches: "threnodist" } }, company: [] };
    recruit(gen, "veth-ondra", { roles: ["ally"], teaches: null, day: 19 });
    check("355: a GENERATED npc keeps its teacher role at recruit (the authored catalog has no entry)",
      gen.company[0].teaches === "threnodist" && gen.company[0].roles.includes("trainer"));
    // …and the save that already lost it is repaired, through the ctx app.js really passes.
    const erik = { id: "e", reconcileVersion: 29, abilities: [], npcRegistry: { "veth-ondra": { name: "Veth-Ondra", teaches: "threnodist" } },
      company: [{ npcId: "veth-ondra", roles: ["ally"], teaches: null, joinedDay: 19 }] };
    reconcile(erik, "character", { content: {}, profile: {} });
    check("355: an EXISTING save gets the lost teacher role back on login",
      erik.company[0].teaches === "threnodist" && erik.company[0].roles.includes("trainer"));

    // The op is only real if all three doors know it — contract, handler, vocab (seam_op_vocab_triples).
    const gmSrc355 = readFileSync(join(root, "engine/gm.js"), "utf8");
    const appSrc355 = readFileSync(join(root, "app.js"), "utf8");
    check("355: partyOps exists in the contract, the vocab, AND the apply path",
      // ⚠️ MEMBERSHIP, NOT POSITION. This pinned partyOps to being FIRST in SALVAGEABLE_OPS, so adding
      // holdingOps ahead of it went red on a change that has nothing to do with the requirement. The rule
      // is that the op exists in all three places, not where it happens to sit in a list.
      /"partyOps":/.test(gmSrc355) && /SALVAGEABLE_OPS = \[[^\]]*"partyOps"/.test(gmSrc355) && /applyStep\("partyOps"/.test(appSrc355));
  }

  // SNG-356 — THE AUTHORED SUB-ATTRIBUTE LADDER, WIRED. Erik: "specify what each point up to 20 gets you
  // so we can better control the impact and the player can see it exactly."
  //
  // ⚠️ THE ROLL COLUMN SHIPPED ON THE HARNESS'S EVIDENCE, NOT ON A SAY-SO. Aevi gated it in her own file:
  // "a flat +10 on success chance from mid-game onward is a large change and I do not know that it is
  // right", with the failure condition named in advance — if the +10 pushes mid-game toward the 95%
  // ceiling, lower the per-rank values rather than abandon the bend. SNG-357 measured it against Silas's
  // real spread and zero of eight subs reach the ceiling on normal work. Erik then called it.
  {
    const { loadContentHeadless: lch356 } = await import("./headless_content.mjs");
    const C356 = await lch356();
    const { successChance } = await import("../engine/resolve.js");
    const { ladderGrantsOwed, applyLadderGrants, ladderRoll, poolSubs } = await import("../engine/ladder.js");
    const { spendSubPoint } = await import("../engine/progression.js");
    const { reconcile } = await import("../engine/reconcile.js");
    const L = C356.rules?.subAttributeLadder;

    // ⛔ SNG-342'S LESSON, AND THIS FILE IS THE CASE THAT PROVED IT: it sat REGISTERED in the manifest for
    // a day while nothing loaded it. Registration is not arrival, and a fallback is not a load.
    check("356: the ladder REACHES the rules — registered is not loaded", !!L);
    check("356: …and arrives whole — 20 roll ranks and 8 subs", Object.keys(L?.rollCumulative || {}).length === 20 && Object.keys(L?.subs || {}).length === 8);

    // The roll column is LIVE in the resolver — the authored number, not the retired formula.
    const at = (rank, band) => successChance({
      character: { attributes: { social: rank }, subAttributes: { presence: rank }, alignment: {}, energy: 50 },
      action: { attribute: "social", subAttribute: "presence", tags: [], difficulty: band }, location: null, rules: C356.rules });
    check("356: the resolver pays the AUTHORED roll column, not the soft-cap formula",
      at(6, "normal") === Number(L.rollCumulative["6"]) && at(9, "normal") === Number(L.rollCumulative["9"]));
    // ⚠️ THE BEND MOVED, WHICH IS THE WHOLE POINT (SNG-354: rank 4 is the TOP of early game, the wrong
    // place for diminishing returns). Gated as SHAPE — the bend exists and sits later than rank 4 — never
    // as the literal value, because the per-rank numbers are Erik's dial.
    const step = (r) => Number(L.rollCumulative[String(r)]) - Number(L.rollCumulative[String(r - 1)]);
    check("356: early ranks pay a FLAT rate — the bend is not at rank 4 any more", step(2) === step(4));
    check("356: …and the ladder bends later, once, downward", step(20) < step(2));
    check("356: rank 1 is unchanged from the old formula — early game was deliberately not touched",
      at(4, "normal") === 40);

    // ⛔ PAID AGAINST A HIGH-WATER MARK. `cumulative[rank]` is the TOTAL owed for standing there, so a naive
    // application re-adds the whole amount every pass and inflates a pool without limit.
    const owedChar = { subAttributes: { strength: 4, reason: 7 }, maxHealth: 170, health: 170, maxEnergy: 240, energy: 240 };
    const owed = ladderGrantsOwed(owedChar, L);
    check("356: an unpaid character is owed its ladder grants", owed.length === 2 && owed.every(g => g.amount > 0));
    applyLadderGrants(owedChar, L);
    // ⛔ I PINNED THE SPEC'S WORKED EXAMPLE (202/293) AND AEVI RETUNED THE LADDER WITHIN THE HOUR — ranks
    // 1-2 now grant nothing, "caught by the SNG-357 harness", which is the harness doing exactly its job.
    // These two went red on a CORRECT content change, in the same commit whose message said "gated as
    // SHAPE, never value". Third occurrence of the same mistake in this suite. The BEHAVIOUR is that the
    // pools rise by what the ladder says they rise by — so that is what is asserted, read from the content.
    const expectHealth = 170 + Number(L.subs.strength.cumulative["4"]);
    const expectEnergy = 240 + Number(L.subs.reason.cumulative["7"]);
    check("356: …and the amounts are exactly what the AUTHORED ladder says they are",
      owedChar.maxHealth === expectHealth && owedChar.maxEnergy === expectEnergy);
    check("356: the CURRENT pool rises with the max — a bigger bar already half-empty reads as a loss",
      owedChar.health === expectHealth && owedChar.energy === expectEnergy);
    const snapshot = JSON.stringify(owedChar);
    applyLadderGrants(owedChar, L);
    check("356: a second application grants NOTHING — idempotent by high-water mark", JSON.stringify(owedChar) === snapshot);

    // ⚠️ BOTH DOORS PAY, AND PAY THE SAME. A grant that only ever arrives via MIGRATION is one the player
    // never sees land — they would spend a point, watch nothing change, and read the ladder as a lie.
    const buyer = { subAttributes: { strength: 3, agility: 3, reason: 3, insight: 3, presence: 3, rapport: 3, craft: 3, wits: 3 },
      attributes: {}, pendingSubPoints: 1, maxHealth: 40, health: 40, maxEnergy: 100, energy: 100, ladderPaid: { strength: 3 } };
    spendSubPoint(buyer, "strength", C356.rules);
    check("356: buying a rank pays IN PLAY, not only on next login", buyer.maxHealth > 40 && buyer.health === buyer.maxHealth);

    // The retroactive pass, through the ctx app.js really passes — the SNG-345 lesson, applied again.
    const old356 = { id: "x", reconcileVersion: 28, abilities: [], subAttributes: { strength: 5 }, maxHealth: 50, health: 50, maxEnergy: 100, energy: 100 };
    reconcile(old356, "character", { content: C356, profile: {} });
    check("356: an EXISTING save is paid retroactively, through the ctx the app really passes",
      old356.maxHealth > 50 && old356.ladderPaid?.strength === 5);

    // ⛔ RATES ARE NOT GRANTS. Four subs are kind:"rate" — a modifier READ where it applies, not a number
    // banked into a field. Paying one into storage would be the writer-with-no-reader shape inverted.
    check("356: only POOL subs are paid — a rate is read at its site, never banked",
      poolSubs(L).length === 4 && poolSubs(L).every(([, d]) => d.kind === "pool")
      && ladderGrantsOwed({ subAttributes: { agility: 9, wits: 9 } }, L).length === 0);

    check("356: the roll column has ONE reader — resolver and readout cannot disagree about a rank's worth",
      ladderRoll(L, 9) === Number(L.rollCumulative["9"]));

    // ⛔ §1c RE-RUN — AND HALF THE LADDER PAID INTO NOTHING. Aevi asked me to re-run §1c after her rank-1-2
    // deflation (strength 4 now +16, not +32); it reproduces, and no pool more than doubles. But the table
    // showed Loki's companyCapacity 9 → 18 and equipmentBonusCap 4 → 8, and chasing those found that TWO OF
    // THE FOUR POOLS HAVE NO CONSUMER: `equipmentBonus` read the flat rules constant and ignored the field
    // the ladder writes, and `companyCapacity` is read by nothing at all. A grant the player earns, sees on
    // the sheet, and can never spend is worse than no grant — it is a promise the game breaks quietly.
    //
    // ⚠️ THIS GATE ASSERTS THE SHAPE, NEVER THE VALUE: every pool the ladder pays must be READ somewhere
    // outside ladder.js, or sit on the list below with a reason. It does not care what any number is.
    {
      const { readFileSync: rf356 } = await import("fs");
      // ⛔ SCAN CODE, NOT COMMENTARY — and I proved I needed this by reverting the fix and watching the gate
      // stay green: the COMMENT I had just written above the fix says `character.equipmentBonusCap`, and the
      // scan counted it as a consumer. A checker satisfied by the note that EXPLAINS the defect is the third
      // time this exact shape has appeared (import_integrity.mjs carries the other two).
      const LF356 = String.fromCharCode(10);
      const strip356 = (src) => src.split(LF356)
        .map(l => { const i = l.search(/(^|[^:"'`])\/\//); return i === -1 ? l : l.slice(0, i); })
        .join(LF356).replace(/\/\*[\s\S]*?\*\//g, " ");
      const consumers = strip356([
        rf356(join(root, "app.js"), "utf8"),
        ...readdirSync(join(root, "engine")).filter(f => f.endsWith(".js") && f !== "ladder.js")
          .map(f => rf356(join(root, "engine", f), "utf8")),
      ].join(LF356));
      // ⛔ DECLARED, WITH A REASON — not silently excused. `companyCapacity` has no site because THE ENGINE
      // HAS NO COMPANY SIZE LIMIT: what a cap would DO (refuse a join? strain the bond? cost upkeep?) is a
      // design decision and belongs to Erik, not to me inventing one to turn a light green.
      const UNCONSUMED = { companyCapacity: "no company size limit exists in the engine — what a cap DOES is Erik's call, not a wiring gap I get to close" };
      // ⚠️ IT MUST BE READ OFF A CHARACTER, and my first version of this line was a gate that could not go
      // red: it asked whether the name appeared anywhere, and `rules.baseChance.equipmentBonusCap` CONTAINS
      // the name — so the exact defect it was written to catch would have passed it green. Counting the
      // doors is not finding them, one more time.
      const unread = poolSubs(L).map(([, d]) => d.governs)
        .filter(f => !UNCONSUMED[f] && !consumers.includes(`character.${f}`) && !consumers.includes(`character?.${f}`));
      check("356 §1c: every POOL the ladder pays into is READ somewhere — a grant you cannot spend is a broken promise",
        unread.length === 0, unread.join(", "));
      check("356 §1c: the unconsumed pools are DECLARED with a reason, never silently excused",
        Object.entries(UNCONSUMED).every(([f, why]) => poolSubs(L).some(([, d]) => d.governs === f) && why.length > 30));
      // The wiring itself: the ladder-paid cap wins when it is higher, and the rules constant is the floor.
      const inv356 = await import("../engine/inventory.js");
      const tooled = { inventory: [{ name: "a fine hammer", bonusTags: ["craft"], evoStage: 6 }], equipmentBonusCap: 24 };
      const plain = { inventory: [{ name: "a fine hammer", bonusTags: ["craft"], evoStage: 6 }] };
      check("356 §1c: a craft-paid cap RAISES the ceiling the ladder promised — the field is finally read",
        inv356.equipmentBonus(tooled, ["craft"], rules).bonus > inv356.equipmentBonus(plain, ["craft"], rules).bonus);
      check("356 §1c: …and the rules constant is still the FLOOR — an unpaid character regresses by nothing",
        inv356.equipmentBonus(plain, ["craft"], rules).bonus === inv356.equipmentBonus({ ...plain, equipmentBonusCap: 0 }, ["craft"], rules).bonus);
    }
  }

  // SNG-352a — THE DERIVATION MUST BE LIVE, or this is the third repair rather than the last.
  //
  // Aevi: "the verb list is hand-maintained and must agree with function_vocabulary.json — your own comment
  // says it was already repaired once for exactly this drift. Derive it from the vocabulary file rather
  // than fixing it a third time." ⛔ BUT "I DERIVED IT" IS A CLAIM LIKE ANY OTHER. A derivation that stops
  // tracking its source looks identical to a hardcoded list from the outside — which is exactly how the
  // hand-list survived two repairs. So this asserts the LINK, not the values.
  {
    const auditSrc = readFileSync(join(root, "tests/wiring_audit.mjs"), "utf8");
    const vocab = JSON.parse(readFileSync(join(root, "content/packs/core/rules/function_vocabulary.json"), "utf8"));
    const harm = (vocab.families?.HARM || []).map(f => String(f.verb));

    check("352a: the HARM family is READ from the vocabulary, not retyped in the audit",
      /FN_VOCAB\.families\?\.HARM/.test(auditSrc) && !/\["strike", "break", "hinder"\]/.test(auditSrc));
    check("352a: …and claimsCombat keys on the harm FUNCTIONS, never on a challengeType",
      /claimsCombat = \(a\) => \(a\.functions \|\| \[\]\)\.some\(f => HARM_FUNCTIONS\.has/.test(auditSrc)
      && !/claimsCombat[\s\S]{0,200}challengeTypes/.test(auditSrc));

    // ⚠️ THE ACTUAL LIVENESS TEST: add a verb to the canon and the audit must already know it. Anything
    // less proves the code MENTIONS the file, not that it FOLLOWS it.
    const withNewVerb = { ...vocab, families: { ...vocab.families, HARM: [...(vocab.families.HARM || []), { verb: "sunder", definition: "Cleave a thing apart." }] } };
    const derived = new Set((withNewVerb.families.HARM || []).map(f => String(f.verb)));
    check("352a: a NEW harm verb in the canon is picked up with no second place to edit",
      derived.has("sunder") && harm.every(v => derived.has(v)));

    // ⛔ AND A DEFENSIVE ABILITY IS NEVER ASKED TO TEACH OFFENCE. This is the false assertion the gate was
    // making: a ward tagged DEFEND "claimed combat" and failed for not wounding anyone. 23 of 42 offenders
    // were flagged this way — prism_sight, darksight, resonant_anchor, perfect_motion.
    const wardLike = { id: "t", functions: ["shield", "ward"], challengeTypes: ["DEFEND", "FIGHT"], tree: [{ rank: 1, grants: "Raise a ward that holds against what comes." }] };
    const claims = (a) => (a.functions || []).some(f => new Set(harm).has(String(f)));
    check("352a: a ward tagged DEFEND/FIGHT does NOT claim combat — challengeTypes say WHERE, functions say WHAT",
      claims(wardLike) === false);
    const strikeLike = { id: "t2", functions: ["strike"], challengeTypes: [], tree: [{ rank: 1, grants: "You hit them." }] };
    check("352a: …while a strike-function ability still does", claims(strikeLike) === true);
  }

  // SNG-349 — Erik: "but skill points aren't used to deepen a craft anymore." Correct, and FIVE separate
  // strings said otherwise, including one I had just written.
  //
  // ⛔ THE WORST OF THEM FIRED EXACTLY WHEN THE PLAYER ASKS WHAT THEIR POINTS ARE FOR: at capacity, the
  // screen said "new points now deepen what you know." At capacity you cannot LEARN (that is what capacity
  // means) and you cannot BUY depth (it is earned) — so the one moment the message matters, it named the
  // only thing points cannot do. What is actually true: they BANK, because the cap rises +1 per level.
  {
    const appSrc349 = readFileSync(join(root, "app.js"), "utf8");
    const treeSrc349 = readFileSync(join(root, "engine/skilltree.js"), "utf8");
    const progSrc349 = readFileSync(join(root, "engine/progression.js"), "utf8");

    // ⚠️ GATED ON THE CLAIM, NOT ON THE WORDING. "deepen" is a fine word — the crafts DO deepen. What must
    // never return is the claim that POINTS do it. So the pattern is points-near-deepen, not "deepen".
    const claimsPointsDeepen = /points?\s+(?:now\s+)?deepen|deepen\s+(?:owned\s+)?(?:skills?|crafts?)\s*(?:with|using|by\s+spending)|spend.{0,20}(?:to\s+)?deepen/i;
    const offenders = [];
    for (const [file, src] of [["app.js", appSrc349], ["engine/skilltree.js", treeSrc349]]) {
      for (const line of src.split(/\r?\n/)) {
        if (line.trim().startsWith("//") || line.trim().startsWith("*")) continue;   // commentary may DESCRIBE the old rule
        if (claimsPointsDeepen.test(line)) offenders.push(`${file}: ${line.trim().slice(0, 90)}`);
      }
    }
    for (const o of offenders) console.log(`      claims points deepen a craft: ${o}`);
    check("349: no player-facing string claims skill points DEEPEN a craft — depth is earned by use",
      offenders.length === 0, offenders.join(" · "));

    // The true statement has to actually be present, or "no lie" is satisfied by saying nothing at all.
    check("349: …and the at-capacity message says what IS true — the points BANK until the next level",
      /bank/i.test(appSrc349) && /at capacity/i.test(appSrc349));

    // ⛔ AND THE DEAD PRICE IS GONE. `rankRows` computed a rankCost and a `canRank` reading `sp >= rankCost`
    // — a purchase that has not existed since ability-arch v2, rendered nowhere, and a standing invitation
    // to re-wire a paid deepen. A calculation that describes a rule is not evidence the rule exists.
    // ⚠️ COMMENT-AWARE, like the check above — my own explanatory comment NAMES the dead expression
    // it removed, and a whole-file regex flagged it. A gate that cannot tell code from commentary about
    // code will punish the person who documented the fix.
    const LF349 = String.fromCharCode(10);   // no escape survives this file's tooling intact
    const codeOnly349 = appSrc349.split(LF349).filter(l => {
      const t = l.trim();
      return !(t.startsWith("//") || t.startsWith("*") || t.startsWith("/*"));
    }).join(LF349);
    check("349: the level-up screen no longer PRICES a rank it cannot sell",
      !/const rankCost = learnPointCost/.test(codeOnly349) && !/sp >= rankCost/.test(codeOnly349));

    // ⚠️ THE ONE LIVE SINK. If a second one ever appears, this goes red and someone has to say so out loud.
    const sinks = (progSrc349.match(/character\.skillPoints = \(character\.skillPoints \|\| 0\) - |character\.skillPoints -= /g) || []).length;
    check("349: skill points still have exactly the sinks we think they have (learn, and the untriggered rank path)",
      sinks === 2, `${sinks} decrement sites in progression.js`);
    check("349: …and LEARNING is the only one the app can reach — nothing in app.js calls rankUpAbility",
      !/\brankUpAbility\s*\(/.test(appSrc349));
  }

  // SNG-348 — Erik: "it seems like the costs have risen… even my tertiary or primary seem to have most
  // costing 2 skill points… can we add a filter for buyable so I can see what I can get."
  //
  // ⚠️ THE COST IS NOT A BUG, AND THE GATE RECORDS THAT so the question stays answered. cost = tierPrice ×
  // distance, and tierPrice is the ability's OWN levelReq (SNG-260 §D — Erik: "a Tier-II costs 2, a
  // Tier-III costs 3. Power costs more."). So a Tier-II costs 2 IN YOUR PRIMARY DOMAIN, at zero distance —
  // nothing to do with the cross-class multiplier. Tier-II is simply the modal tier in the catalog.
  {
    const { loadContentHeadless: lch348 } = await import("./headless_content.mjs");
    const C348 = await lch348();
    const { learnPointCost, skillGraphModel } = await import("../engine/skilltree.js");
    const cap348 = C348.skillCapacity;
    const inDomain = { penalty: 1, allowed: true, band: "home" };
    const t1 = Object.values(C348.abilities).find(a => (a.levelReq || 1) === 1 && a.powerSystem !== "baseline");
    const t2 = Object.values(C348.abilities).find(a => (a.levelReq || 1) === 2);
    const who = { domains: { primary: "harmonic" }, skillPoints: 1, abilities: [], level: 9 };

    check("348: at ZERO domain distance a Tier-I costs 1 — the floor is not the complaint",
      learnPointCost(t1, who, cap348, inDomain) === 1);
    check("348: …and a Tier-II costs 2 IN YOUR OWN DOMAIN — tier is the price, not cross-class distance",
      learnPointCost(t2, who, cap348, inDomain) === 2);

    // ⛔ THE FILTER MUST READ THE SAME NUMBER THE PURCHASE CHARGES. A filter that computes its own price is
    // a second opinion on one question, and the two drift the first time either moves — the exact shape
    // that put SIX copies of this calculation in the codebase before learnPointCost collapsed them.
    const model = skillGraphModel(C348.abilities, C348.emergence, who, {
      attributeGates: C348.attributeGates, skillCapacity: cap348, branchForks: C348.branchForks,
      preds: { verdictFor: () => inDomain },
    });
    const node2 = model.nodes.find(n => n.id === t2.id);
    check("348: the node model carries the SAME cost the purchase charges — never a second opinion",
      node2.cost === learnPointCost(t2, who, cap348, inDomain));

    // ⚠️ AVAILABLE ≠ BUYABLE, WHICH IS THE WHOLE REQUEST. A node can pass every gate and still be out of
    // reach on price, and the wheel showed Erik exactly that: a field of open crafts he could not buy.
    const openButUnaffordable = model.nodes.filter(n => !n.owned && !n.locked && !n.affordable);
    check("348: a craft can be OPEN and still not BUYABLE — the two are different questions",
      openButUnaffordable.length > 0 && openButUnaffordable.every(n => n.buyable === false));
    check("348: buyable ⊆ affordable, always", model.nodes.filter(n => n.buyable).every(n => n.affordable));
    check("348: …and buyable never includes a LOCKED craft", model.nodes.filter(n => n.buyable).every(n => !n.locked && !n.foreclosed));

    // With more points, strictly more becomes buyable — the filter tracks the purse rather than a snapshot.
    const rich = { ...who, skillPoints: 99 };
    const richModel = skillGraphModel(C348.abilities, C348.emergence, rich, {
      attributeGates: C348.attributeGates, skillCapacity: cap348, branchForks: C348.branchForks,
      preds: { verdictFor: () => inDomain },
    });
    const poorCount = model.nodes.filter(n => n.buyable).length;
    const richCount = richModel.nodes.filter(n => n.buyable).length;
    check("348: more points ⇒ strictly more buyable — affordability tracks the purse", richCount > poorCount,
      `${poorCount} at 1 point vs ${richCount} at 99`);

    // The UI: one function answers "can I get this?", and the count shows BEFORE the toggle is used.
    const appSrc348 = readFileSync(join(root, "app.js"), "utf8");
    check("348: the filter and the row ask ONE function, so they cannot disagree",
      /const learnState = ab =>/.test(appSrc348) && /learnable\.filter\(ab => !learnState\(ab\)\.blocked\)/.test(appSrc348));
    check("348: the chip shows the count BEFORE you toggle it — 'N of M' answers the question without a click",
      /buyableAll\.length\} of \$\{learnable\.length\}/.test(appSrc348));
    check("348: …and says something useful when the answer is ZERO, rather than showing an empty list",
      /nothing in reach yet/.test(appSrc348));
  }

  // SNG-347 — A DESCRIPTION IS NOT A NAME. Erik's newly-minted NPC arrived as "someone tending the
  // waystation fire—shelter-keeper, traveler" and the ribbon announced it IN BOLD, as an identity.
  //
  // ⛔ THE HINT WAS THE NAME. stubEntity read `context.hint` — the generateRequest's description of WHAT TO
  // MAKE, whose own contract example is "a tollhand at the lower gate" — and used it verbatim, cut at
  // exactly 60 characters. ⚠️ SNG-199 ALREADY FIXED THIS CLASS on the registry path ("a descriptive CLAUSE
  // is not a name"); the generate mint never got the guard, so it walked in the other door.
  {
    const { isDescriptiveNotName } = await import("../engine/state.js");
    const { stubEntity, livingWorldForGM } = await import("../engine/generate.js");
    const { prettifyNpcName } = await import("../engine/npcs.js");

    const BAD = ["someone tending the waystation fire—shelter-keeper, traveler", "a tollhand at the lower gate", "the quiet one", "a presence in the valley"];
    const GOOD = ["Cevaine", "The Ashen Warden", "Siol", "Mara Thren", "Warden Holt"];
    check("347: a description in the name slot is REFUSED", BAD.every(isDescriptiveNotName), BAD.filter(n => !isDescriptiveNotName(n)).join(" · "));
    check("347: …and a real name is not — including an epithet-name like 'The Ashen Warden'",
      GOOD.every(n => !isDescriptiveNotName(n)), GOOD.filter(isDescriptiveNotName).join(" · "));

    // ⛔ WHY THIS IS ITS OWN CHECK AND NOT A REUSE OF prettifyNpcName: that function's "already
    // human-shaped" test requires a capital letter, so an all-lowercase description falls through to the
    // SLUG-PRETTIFIER and is TITLE-CASED into something that LOOKS like a name and is nonsense. A cosmetic
    // pass standing where a validator belongs does not merely fail to fix the input — it launders it.
    const laundered = prettifyNpcName("someone tending the waystation fire");
    check("347: the cosmetic prettifier LAUNDERS this input — which is why a validator is needed",
      /^[A-Z]/.test(laundered) && isDescriptiveNotName("someone tending the waystation fire"));

    // The stub keeps the description AS a description and marks the person unnamed. It must never invent
    // a name: its own contract is "never fabricates specifics it wasn't given", and a name is one.
    const stub = stubEntity("npc", { hint: "someone tending the waystation fire, shelter-keeper", location: { id: "way", name: "The Waystation" } });
    check("347: the stub marks an unnamed person UNNAMED rather than naming them from the hint", stub.nameProvisional === true);
    check("347: …and keeps the hint as a DESCRIPTION, so nothing is lost", !!stub.description);
    check("347: …and never cuts it mid-word (the SNG-181/343 raw slice)", !/\w$/.test(stub.name) || stub.name.length < 60);
    const named = stubEntity("npc", { hint: "Cevaine", location: { id: "way", name: "The Waystation" } });
    check("347: a stub given a real name is NOT marked provisional", !named.nameProvisional);

    // ⚠️ THE GM MUST BE TOLD. The stub cannot invent a name, so the only route to a real one is the
    // telling — and a GM that is not told will keep using the description as though it were an identity,
    // which is how it hardens into canon.
    const ch347 = { generated: { npc: { n1: { id: "n1", name: "someone tending the waystation fire", description: "someone tending the waystation fire", nameProvisional: true, role: "shelter-keeper", homeLocation: "way", _gen: { type: "npc", tier: "fresh", weight: 1, bornDay: 1 } } } } };
    const block = livingWorldForGM(ch347, { locationId: "way", day: 1 });
    check("347: the GM is told the person is NOT YET NAMED, and told to name them in play",
      !!block && /NOT YET NAMED/.test(block));

    // The one already in Erik's save — marked, never renamed (inventing a name writes canon he never read).
    const { reconcile } = await import("../engine/reconcile.js");
    const save = { id: "s", reconcileVersion: 27, abilities: [], generated: { npc: { n2: { id: "n2", name: "someone tending the waystation fire—shelter-keeper, traveler", _gen: { type: "npc", tier: "fresh", weight: 1, bornDay: 1 } } } } };
    reconcile(save, "character", { content: {}, profile: {} });
    const fixed = save.generated.npc.n2;
    check("347: an ALREADY-MINTED description is marked unnamed on login", fixed.nameProvisional === true);
    check("347: …and is NOT renamed — inventing a name would write canon the player never heard",
      fixed.name === "someone tending the waystation fire—shelter-keeper, traveler" && !!fixed.description);

    // The ribbon must not bold a description as a name.
    const appSrc = readFileSync(join(root, "app.js"), "utf8");
    check("347: the world-grows ribbon renders a provisional name as PROSE, never bolded as an identity",
      /nameProvisional[\s\S]{0,200}yet to learn a name/.test(appSrc));
  }

  // SNG-346 — ERIK'S SYMMETRIC DIFFICULTY SCALE. Aevi: "the insight is that EASY BECOMES A BONUS rather
  // than the absence of a penalty" — a flat base lifts every band equally, so easy and hard stay 15 apart
  // however high you push it. Widening the spread was the actual fix, and it needs no base at all.
  //
  // ⚠️ GATED ON STRUCTURE, NOT ON TUNING. Which numbers sit on the ladder is Erik's dial (SNG-280), and a
  // gate asserting `easy === 15` goes red the moment he turns it — that mistake has been made twice in this
  // suite already. What IS structural: the ordering must be monotonic, every door must agree, and the
  // legacy vocabulary must keep its exact meaning.
  {
    const { loadContentHeadless: lch346 } = await import("./headless_content.mjs");
    const C346 = await lch346();
    const { successChance, normalizeDifficulty, DIFFICULTY_BANDS } = await import("../engine/resolve.js");
    const { sanitizeIntent } = await import("../engine/gm.js");
    const rules346 = C346.rules;
    const who = { attributes: { social: 4 }, subAttributes: { presence: 4 }, alignment: {}, energy: 50 };
    const at = (d) => successChance({ character: who, action: { attribute: "social", subAttribute: "presence", tags: [], difficulty: d }, location: null, rules: rules346 });

    check("346: the band table REACHES the rules", !!rules346.difficultyBands
      && DIFFICULTY_BANDS.every(b => typeof rules346.difficultyBands[b] === "number"));

    // ⛔ THE ORDERING IS THE REQUIREMENT. "Easy is a bonus" means easy must be strictly BETTER than normal —
    // which is the whole design, and is unsayable in the old three-band vocabulary.
    const ladder = DIFFICULTY_BANDS.map(at);
    check("346: the ladder is STRICTLY MONOTONIC — very easy > easy > normal > hard > very hard",
      ladder.every((v, i) => i === 0 || v < ladder[i - 1]), ladder.join(" > "));
    check("346: easy is a BONUS, not the absence of a penalty — it beats normal",
      at("easy") > at("normal") && at("very_easy") > at("easy"));
    check("346: …and the spread is EVEN, so the ladder is learnable in one look",
      new Set([at("very_easy") - at("easy"), at("easy") - at("normal"), at("normal") - at("hard"), at("hard") - at("very_hard")]).size === 1);

    // ⛔ THE LEGACY VOCABULARY KEEPS ITS EXACT MEANING. The old 0/15/30 IS the negative half of the new
    // scale, so no in-flight turn and no save changes meaning — this is why the migration is safe.
    check("346: legacy 0/15/30 map onto the new ladder with NO change of meaning",
      normalizeDifficulty(0) === "normal" && normalizeDifficulty(15) === "hard" && normalizeDifficulty(30) === "very_hard");
    check("346: an OPPOSED threat stays a number — a raider's 35 is not a band, and is never rounded onto the ladder",
      normalizeDifficulty(35) === 35 && at(35) < at("normal"));

    // ⛔ ALL FOUR DOORS, BECAUSE THREE WOULD HAVE EATEN IT. sanitizeIntent read `Number(raw.difficulty)`,
    // so a band became NaN and fell to 0 = normal — every easy task silently flattened to neutral, which is
    // EXACTLY the drift this spec exists to fix. Counting doors is not finding them: the field is read by
    // the intent sanitizer, two prompt contracts, and gambit's step validator.
    const sane = sanitizeIntent({ label: "scout for supplies", difficulty: "easy" }, { abilities: [] }, "scout");
    check("346: the intent sanitizer PRESERVES a band — it used to coerce it to NaN then 0", sane.difficulty === "easy");
    check("346: …and still refuses malformed input (a stray string can never reach the dice)",
      sanitizeIntent({ label: "x", difficulty: "banana" }, { abilities: [] }, "x").difficulty === "normal");
    const gambitSrc = readFileSync(join(root, "engine/gambit.js"), "utf8");
    check("346: gambit steps use the SAME normalizer — a plan cannot price a task differently from an action",
      gambitSrc.includes("normalizeDifficulty(steps[i]?.difficulty)"));

    // ⚠️ THE PROMPT IS HALF THE FEATURE. Aevi: left as-is this "ships a five-band scale the narrator can
    // only address three bands of, and every task that should have been +15 gets tagged 0."
    const gmSrc = readFileSync(join(root, "engine/gm.js"), "utf8");
    check("346: the GM's vocabulary names ALL FIVE bands — it could only say three",
      ["very easy", "easy", "normal", "hard", "very hard"].every(b => gmSrc.includes(`"${b}"`)));
    check("346: …and carries the calibration rule that stops the one-way drift to 'normal'",
      /nothing is opposing the character, it is NOT normal/i.test(gmSrc));
    check("346: …and teaches by example, including the call that misfired on Erik",
      /scouting for supplies/i.test(gmSrc));
  }

  // SNG-345 — THE MARTIAL FLOOR. Erik: "every character can defend itself, no build required." The content
  // said so on 2026-07-07, carried an engineNote naming the implementation, and NOTHING READ IT until the
  // SNG-342 sweep listed it as a real gap. Splarf reached level 1 with no defense that didn't cost a build.
  {
    const { loadContentHeadless: lch345 } = await import("./headless_content.mjs");
    const C345 = await lch345();
    const { grantMartialKit, baselineAbilityIds, isBaselineAbility, formKitFor, martialAbilityRecords } =
      await import("../engine/martial.js");
    const { breadthUsed, atCapacity } = await import("../engine/skilltree.js");
    const martial = C345.rules?.martialPaths;

    check("345: martial_paths REACHES the rules — the file is loaded, not merely registered", !!martial);
    check("345: …and arrives non-empty — 4 baseline abilities and at least one form kit",
      (martial?.baselineDefense?.kit || []).length === 4 && (martial?.formKits?.kits || []).length > 0);

    // ⛔ GRANTED IS NOT USABLE. The recurring failure in this codebase is content that exists and
    // silently does not (SNG-229 bestiary, SNG-226 discoveries): an ability id on the sheet that resolves
    // to no record renders as a blank row the player cannot choose. So the CATALOG is checked, not the grant.
    const missing = baselineAbilityIds(martial).filter(id => !C345.abilities?.[id]);
    check("345: every baseline ability RESOLVES IN THE CATALOG — granted is not the same as usable",
      missing.length === 0, `${missing.join(", ")} granted but absent from CONTENT.abilities`);
    const recs = Object.values(martialAbilityRecords(martial));
    check("345: …and each is BORN WHOLE — name, description, notFor, zero cost, level 1 (SNG-250 §3)",
      recs.every(r => r.name && r.description && r.notFor && r.energyCost === 0 && r.levelReq === 1));

    // The floor is granted, idempotent, and does not re-grant on a second login.
    const fresh = { abilities: [], level: 1 };
    const g1 = grantMartialKit(fresh, martial);
    const g2 = grantMartialKit(fresh, martial);
    check("345: a character with nothing is granted the whole floor", g1.granted.length === 4);
    check("345: …and a second pass grants NOTHING — reconcile runs on every login", g2.granted.length === 0);

    // ⛔ THE CAP BUG THAT WOULD HAVE BROKEN EVERY NEW CHARACTER. Level-1 breadth cap is 2; the floor is
    // 4. If the free kit counted as chosen breadth, every character would be born at DOUBLE capacity and
    // able to learn nothing until level 5 — the same failure `native` already caused once.
    check("345: the free kit does NOT consume build capacity", breadthUsed(fresh) === 0);
    check("345: …so a level-1 character holding the whole floor can still learn",
      atCapacity({ ...fresh, level: 1 }, C345.skillCapacity) === false);
    check("345: a baseline ability is recognised as baseline, and an authored one is not",
      isBaselineAbility(baselineAbilityIds(martial)[0], martial) === true
      && isBaselineAbility("prism_sight", martial) === false);

    // ⚠️ FORM PROSE IS NOT AN ENUM. character.form is free text, so a form kit is resolved by an
    // UNAMBIGUOUS alias match — and my first version used `includes`, where the alias "ent" matched
    // "gentle", "present", "different", handing a bark-and-timber kit to any human described politely.
    // That is SNG-331's `ties` bug (matching `location_affinities`) reintroduced one file over.
    check("345: an explicit character.formKit wins over prose",
      formKitFor({ formKit: "ent", form: "a quiet human" }, martial).kit?.form === "ent");
    check("345: form prose matches on WORD BOUNDARIES, never substrings",
      formKitFor({ form: "a gentle, patient, different sort of present company" }, martial).kit === null);
    check("345: …and a real Ent still matches",
      formKitFor({ form: "a towering treefolk of bark and heartwood" }, martial).kit?.form === "ent");
    // ⛔ AND THE STEP RUNS WITH THE CTX THE APP ACTUALLY PASSES. I wrote `ctx.rules.martialPaths` first;
    // app.js passes `{ content: CONTENT, profile }` and carries no `rules`, so the step would have run on
    // every login, found undefined, returned silently, and gated green — PromisedButUnread, in the commit
    // closing PromisedButUnread. Testing the function in isolation would NOT have caught it; only running
    // the step through the caller's real ctx shape does.
    {
      const { reconcile } = await import("../engine/reconcile.js");
      const old = { id: "pre-345", abilities: [], level: 1, reconcileVersion: 26 };
      reconcile(old, "character", { content: C345, profile: { tendencies: {}, aptitudes: [] } });
      const ids = new Set((old.abilities || []).map(a => a.abilityId));
      const owed = baselineAbilityIds(martial).filter(id => !ids.has(id));
      check("345: an EXISTING save gains the floor on login, through the ctx app.js really passes",
        owed.length === 0, `still missing after reconcile: ${owed.join(", ")}`);
      check("345: …and the granted records are flagged baseline, so they never eat build capacity",
        (old.abilities || []).filter(a => a.baseline).length === 4);
    }

    const entKit = grantMartialKit({ abilities: [], form: "a towering treefolk of bark and heartwood" }, martial);
    check("345: an Ent is granted the floor AND its form kit — Erik's branch-club", entKit.granted.length > 4 && entKit.kit === "ent");
  }

  // SNG-342 — THE GATE THAT WOULD HAVE CAUGHT MY OWN REGRESSION.
  //
  // My SNG-331 resolver fix (match the exact filename, so `loadRule("ties")` stops matching
  // `location_affini-TIES.json`) silently emptied emergence: there is no `rules/emergence.json` — the
  // content lives in `emergence_recipes.json`, which ONLY the substring matcher found. 21 recipes and a
  // branch template fell through to `loadRule("emergence", {recipes: [], branchTemplates: {}})`, its own
  // fallback, and EVERY GATE STAYED GREEN for ten versions — because every gate asked whether the file
  // was declared, registered, and well-formed. None asked whether the content ARRIVED.
  //
  // ⛔ A FALLBACK IS NOT A LOAD. Reachable is not the same as arrived. The whole class of "resolver
  // silently returns nothing" is invisible until something asserts the payload is non-empty at the far end.
  {
    const { loadContentHeadless: lch342 } = await import("./headless_content.mjs");
    const C342 = await lch342();
    const arrivals = {
      "emergence.recipes":              (C342.emergence?.recipes || []).length,
      "emergence.branchTemplates":      Object.keys(C342.emergence?.branchTemplates || {}).length,
      "rules.ties.kinTriggers":         Object.keys(C342.rules?.ties?.kinTriggers || {}).length,
      "rules.questStructure":           Object.keys(C342.rules?.questStructure || {}).length,
    };
    const empty = Object.entries(arrivals).filter(([, n]) => n === 0).map(([k]) => k);
    for (const [k, n] of Object.entries(arrivals)) if (n === 0) console.log(`      ARRIVED EMPTY (fell to fallback): ${k}`);
    check("342: a rule that loads must ARRIVE NON-EMPTY — a fallback is not a load", empty.length === 0,
      `${empty.join(", ")} resolved to nothing and fell back silently`);
  }

  // SNG-268 — the rotating window and the backlog: nobody waits forever, nobody loses their beats.
  check("272/268: the offscreen batch ROTATES so no one waits forever", /offscreenCursor/.test(wsrc));
  check("272/268: a legend always gets a seat in the batch", /legend seat|legendSeat/i.test(wsrc));
  check("272/268: a figure outside the batch STACKS its beats instead of losing them", /offscreenBacklog/.test(wsrc));
}

// --- SNG-272: the two P0/P1 gates the ledger also found missing --------------------------------------
{
  const appL = readFileSync(join(root, "app.js"), "utf8");
  const encR = JSON.parse(readFileSync(join(root, "content/packs/core/rules/encounters.json"), "utf8"));
  check("272/266: an unknown encounter type falls back to `default` rather than paying zero",
    /const t = encXp\[enc\.def\.type\] \|\| encXp\.default \|\| \{\}/.test(appL) && Number(encR.default && encR.default.winXp) > 0);
  check("272/271: a downed player does not take a bonus action",
    /if \(!ended && checkIncapacitation\(character\)\)/.test(appL));
}

// --- SNG-272: the ledger cannot drift from the suite -------------------------------------------------
// `tests/verification_ledger.mjs` proves itself when it runs — but a ledger nobody runs is the same rumour
// in a nicer format. This guard is static and costs nothing: every gate the ledger CLAIMS must exist here,
// and every `272/` gate here must be CLAIMED there. Drift in either direction fails the normal test run.
{
  const ledgerSrc = readFileSync(join(root, "tests/verification_ledger.mjs"), "utf8");
  const mySrc = readFileSync(join(root, "tests/smoke.mjs"), "utf8");
  // Parse the `gates: [...]` arrays, not a prefix. The first version matched only `272/` and covered 20 of
  // 51 claims — so a `2c:` or `270:` gate could be deleted and only a manual ledger run would notice, which
  // is exactly the gap this guard exists to close.
  const gateBlocks = [...ledgerSrc.matchAll(/gates:\s*\[([\s\S]*?)\]/g)].map(m => m[1]);
  const claimed = gateBlocks.flatMap(b => [...b.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(m => m[1]));
  // ⚠️ SNG-342: "this suite" is now TWO files. The ledger may cite a content_ci gate (that is where the
  // content-integrity checks live), and reading only smoke.mjs reported those as MISSING — a red gate
  // accusing the ledger of claiming something imaginary, when the gate was real and green one file over.
  // ⛔ Kept as a WHITELIST of two named files, not a directory sweep: "every .mjs in tests/" would let a
  // requirement point at a scratch harness and call itself verified.
  // ⚠️ AND SNG-399b MAKES IT THREE, for the reason SNG-342 made it two: the general "an authored
  // *ImagePrompt with no reader" guard lives in wiring_audit — the right home for the
  // writer-with-no-reader family — and a requirement citing it was reported MISSING while the gate sat
  // green one file over. Still a whitelist of NAMED files, never a directory sweep.
  // ⚠️ wiring_audit builds some check names as TEMPLATE literals (a count rides in the text), so the
  // name is matched up to the first interpolation — enough for the ledger's substring citation.
  const ciSrc = readFileSync(join(root, "tests/content_ci.mjs"), "utf8");
  const waSrc = readFileSync(join(root, "tests/wiring_audit.mjs"), "utf8");
  const present = [
    ...[...(mySrc + ciSrc).matchAll(/check\("((?:[^"\\]|\\.)*)"/g)].map(m => m[1]),
    ...[...waSrc.matchAll(/check\(`([^`$]*)/g)].map(m => m[1].trim()),
    ...[...waSrc.matchAll(/check\("((?:[^"\\]|\\.)*)"/g)].map(m => m[1]),
  ];
  const missing = claimed.filter(c => !present.some(p => p === c || p.startsWith(c)));
  const own = present.filter(c => c.startsWith("272/"));
  const orphans = own.filter(c => !claimed.includes(c));
  const unclaimed = present.filter(c => !claimed.includes(c));
  // ⚠️ DETAILS GO TO THE LOG, NOT INTO THE CHECK NAME. Embedding the missing names here put a gate’s name
  // INSIDE another check’s name, and the ledger matches by substring — so a single gate appeared to match two
  // checks and tripped the ambiguity guard. A check name has to be a stable identifier, not a report.
  if (missing.length) console.log(`      MISSING from the suite: ${missing.join(" | ")}`);
  check(`272: every gate the ledger claims exists in this suite (${claimed.length} claimed)`,
    claimed.length > 0 && missing.length === 0);
  if (orphans.length) console.log(`      UNCLAIMED by the ledger: ${orphans.join(" | ")}`);
  check(`272: every 272/ gate in this suite is claimed by the ledger (${own.length} present)`,
    orphans.length === 0);
}

// --- SNG-275: the arcs do not get all of somebody ----------------------------------------------------
{
  const wt2 = await import("../engine/worldtick.js");
  const c = (arcId, dir = 1, weight = 1) => ({ arcId, dir, weight });
  const quiet = { arcNetPush: {} };

  check("272/275: a share of every figure is NOT the arcs' to spend", (() => {
    const f = { id: "f", arcAffinities: [c("a"), c("b")] };
    const r = wt2.spendAttention(f, quiet, { budget: 2, personalShare: 0.5 });
    return r.personal === 1 && r.spent.length === 1;
  })());

  check("272/275: at personalShare 0 the old behaviour is bit-identical (the dial degrades safely)", (() => {
    const f = { id: "f", arcAffinities: [c("a"), c("b")] };
    const r = wt2.spendAttention(f, quiet, { budget: 2, personalShare: 0 });
    return r.personal === 0 && r.spent.length === 2;
  })());

  check("272/275: a CRISIS borrows the personal claim — and the borrowing is RECORDED, not free", (() => {
    const f = { id: "f", arcAffinities: [c("burning", 1, 2)] };
    const onFire = { arcNetPush: { burning: -60 } };
    const r = wt2.spendAttention(f, onFire, { budget: 1, personalShare: 0.5, crisisPull: 1.5 });
    return r.neglected === true && r.personal === 0;
  })());

  check("272/275: an ordinary pass is NOT a crisis (or neglect would mean nothing)", (() => {
    const f = { id: "f", arcAffinities: [c("a")] };
    const r = wt2.spendAttention(f, quiet, { budget: 1, personalShare: 0.5, crisisPull: 1.5 });
    return r.neglected === false && r.personal === 0.5;
  })());

  // ⛔ THE ENGINE DOES NOT INVENT A LIFE. An unauthored figure gets no fabricated family.
  check("272/275: personal time reads AUTHORED content and invents nothing", (() => {
    const bare = wt2.personalPursuitOf({ id: "x", name: "X", wants: "something", role: "Master" });
    const written = wt2.personalPursuitOf({ id: "y", personalVerbs: ["mends the long net"] }, () => 0);
    return bare === null && written === "mends the long net";
  })());

  check("272/275: the CONTENT GAP is measured, not papered over",
    /ws\.personalCoverage = \{ lived: livesLived, onThePage: livesOnThePage/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));

  // SNG-275 — and the dials are REACHABLE at last.
  check("272/275: the world-sim dials are AUTHORED, not just read (21 of them ran on fallbacks)", (() => {
    const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
    const a = doc.arcResponse || {};
    const needed = ["perPoint", "attentionByTier", "personalShare", "crisisPull", "directEngagementRate",
                    "indirectPushMult", "casualtyRate", "casualtyReachByGap", "strikeRate",
                    "guardInterceptChance", "mintRate", "mintCap", "vacancyStreakForMint",
                    "retrievalRate", "retrievalOddsByDepth", "retrievalCooldownDays"];
    return needed.every(k => a[k] !== undefined) && !!doc.tierLadder?.promotion?.epic;
  })());
  check("272/275: the tier table carries BOTH names for the same rung (one name drops 28 figures)", (() => {
    const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
    const t = doc.arcResponse.attentionByTier;
    return t.heroic === t.regional && t.heroic !== undefined;
  })());
}

// --- SNG-272 (Aevi): a record nothing FINDS ----------------------------------------------------------
{
  const appBg = readFileSync(join(root, "app.js"), "utf8");
  const bgDoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/backgrounds.json"), "utf8"));
  const bgs = bgDoc.backgrounds || bgDoc;

  check("272/bg: every authored background id is snake_case (the whole defect was one hyphen)",
    Array.isArray(bgs) && bgs.length > 0 && bgs.every(b => /^[a-z0-9_]+$/.test(b.id)));

  check("272/bg: every background still carries the mechanics the sheet promises",
    bgs.every(b => Array.isArray(b.affinity) && Array.isArray(b.grantsAptitudes)));

  check("272/bg: a legacy hyphenated id is REPAIRED on read, so existing saves heal",
    /const normalised = String\(id\)\.replace\(\/-\/g, "_"\)/.test(appBg));

  // ⚠️ THE REAL DEFECT WAS `|| {}` — a miss that renders a plausible sentence instead of failing.
  check("272/bg: a total miss is LOUD, not a plausible sentence",
    /matches NO authored background/.test(appBg));

  check("272/bg: the tooltip goes through the ONE reader, not a second private lookup",
    !/\(CONTENT\.backgrounds \|\| \[\]\)\.find\(b => b\.id === id\) \|\| \{\}/.test(appBg));
}

// --- SNG-276: THE WORLD tab — who is doing what to your arcs -----------------------------------------
{
  const wt3 = await import("../engine/worldtick.js");
  const { worldTabHtml } = await import("../engine/worldtab.js");
  const appW = readFileSync(join(root, "app.js"), "utf8");
  const cssW = readFileSync(join(root, "style.css"), "utf8");

  const content = { greaterArcs: [{ id: "a1", name: "The Bleed", currentStage: 1,
    stages: [{ stage: 1, name: "Drift", publicFace: "something is loose" }] }],
    legends: { roster: [{ id: "big", name: "The Burning Certainty" }, { id: "small", name: "Neth" }] } };
  const ch = {
    npcRegistry: { small: { id: "small", name: "Neth" } },   // met Neth, only heard of the other
    codex: { topics: {} },
    worldState: {
      epicArcPushes: { big: { arcId: "a1", push: 5.5 }, small: { arcId: "a1", push: -1 } },
      arcCasualties: [{ arcId: "a1", winner: "big", loser: "small", kind: "wounded" }],
      arcStrikes: [{ arcId: "a1", target: "small", sender: "big", outcome: "guarded", guard: "small" }],
      arcContests: { a1: { duels: 2, worked: 30 } },
      arcVacancies: { a1: 3 },
      arcRetrievals: [{ arcId: "a1", deadId: "small", byId: "big", outcome: "return" }],
      neglectedLives: [{ id: "big", name: "The Burning Certainty" }],
      retrievalWanted: [{ deadId: "small", deadName: "Neth", byId: "big", byName: "The Burning Certainty", depth: 1, waiting: true }],
    },
  };
  const view = wt3.arcPeopleView(ch, content);
  const a = view[0];

  check("272/276: the arcs carry WHO is pushing them, by name and by side",
    a.forIt[0]?.name === "The Burning Certainty" && a.againstIt[0]?.name === "Neth");
  check("272/276: a name you have MET is marked apart from one you have only heard",
    a.againstIt[0]?.known === true && a.forIt[0]?.known === false);
  check("272/276: the stage reads by NAME, never as a raw number (show the state, not the machine)",
    a.stageName === "Drift" && !/\d\.\d{3}/.test(a.stageName));
  // ⛔ AND IT IS NOT THE PUSH. `push` saturates at the cap, so within a world-year every figure on an arc
  // holds the same number and any banding of it prints one phrase beside every name — which is what the
  // first three versions did. The band reads AUTHORED care weight, which actually varies.
  check("272/276: the phrase beside a name reads authored CARE, not the saturated push",
    typeof a.forIt[0]?.lean === "string" && /life’s work|bone|stake/.test(a.forIt[0].lean));
  check("272/276: …and it DISCRIMINATES — different care weights read differently", (() => {
    const c2 = JSON.parse(JSON.stringify(content));
    c2.legends.roster[0].arcAffinity = { arcId: "a1", dir: 1, weight: 3 };
    c2.legends.roster[1].arcAffinity = { arcId: "a1", dir: -1, weight: 1 };
    const v2 = wt3.arcPeopleView(ch, c2);
    return v2[0].forIt[0].lean !== v2[0].againstIt[0].lean;
  })());
  check("272/276: casualties, strikes and retrievals all resolve to NAMES",
    a.casualties[0]?.loser?.name === "Neth" && a.strikes[0]?.target?.name === "Neth"
    && a.retrievals[0]?.dead?.name === "Neth");
  check("272/276: the seats that emptied and the fights that happened are both surfaced",
    a.vacancy === 3 && a.contest?.duels === 2);

  // ⛔ The tab composes `worldArcsPublic`, which withholds each arc's sealed `truth`. It must not leak it.
  check("272/276: the tab inherits spoiler discipline — the arc's sealed truth is never on it",
    a.publicFace === "something is loose" && a.truth === undefined);

  const foot = wt3.worldPeopleFooter(ch, content);
  check("272/276: who is NOT going home, and who is being reached for, are world-level facts",
    foot.neglected[0]?.name === "The Burning Certainty" && foot.wanted[0]?.dead === "Neth" && foot.wanted[0]?.waiting === true);

  check("272/276: the tab exists, is wired, and is styled",
    /id="tab-world"/.test(appW) && /function renderWorldTab\(\)/.test(appW) && /\.wt-arc \{/.test(cssW));
  // SNG-276: the markup lives in `engine/worldtab.js` now, so read it THERE — and better, EXECUTE it: this
  // is the whole reason the template was extracted out of app.js.
  check("272/276: an empty world says so rather than rendering a blank page", (() => {
    const html = worldTabHtml({ arcs: [], foot: {}, name: "Nobody", tabBar: () => "", esc: s => String(s ?? "") });
    return /The world has not moved yet/.test(html) && wt3.arcPeopleView({}, {}).length === 0;
  })());
  check("272/276: the tab RENDERS — executed against real state, not pattern-matched against its source", (() => {
    const html = worldTabHtml({ arcs: view, foot, name: "Probe", tabBar: () => "", esc: s => String(s ?? "") });
    return html.length > 400 && html.includes("Neth") && html.includes("The Burning Certainty")
      && !/undefined|NaN|\[object/.test(html);
  })());
}

// --- SNG-279: promotion on DEEDS, and DIRECTIVE SNG-280 -------------------------------------------
{
  const wt4 = await import("../engine/worldtick.js");
  const wsrc4 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const ladderDoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));

  // ⛔ DIRECTIVE SNG-280 — THE LOAD-BEARING ONE. Everything contested and won scores the same, whichever
  // direction it points. A Maw who levers three rivals rises exactly as fast as a guard who stops three.
  check("272/279: no moral weighting — strike and guard score IDENTICALLY (DIRECTIVE SNG-280)",
    wt4.DEED_WEIGHTS.strikeLanded === wt4.DEED_WEIGHTS.guardIntercept
    && wt4.DEED_WEIGHTS.strikeSurvived === wt4.DEED_WEIGHTS.guardIntercept
    && wt4.DEED_WEIGHTS.arcContestWon === wt4.DEED_WEIGHTS.guardIntercept);
  check("272/279: …and the authored weights agree with the engine (a content edit cannot smuggle a value in)",
    (() => { const w = ladderDoc.tierLadder?.deedWeights || {};
      return w.strikeLanded === w.guardIntercept && w.strikeSurvived === w.arcContestWon; })());

  check("272/279: a deed is CREDITED and remembered with what it was", (() => {
    const ws = {}; wt4.creditDeed(ws, "f", "arcContestWon", { worldDay: 5 });
    const t = ws.figureTenure.f;
    return t.deeds === 3 && t.deedLog[0].by === "arcContestWon";
  })());

  check("272/279: promotion needs BOTH the floor and the deeds", (() => {
    const cfg = { promotion: { heroic: { to: "epic", years: 0.2, deeds: 6 } }, worldYearDays: 365 };
    const f = { id: "h", tier: "heroic" };
    const early = {}; wt4.advanceStandings(early, [f], 0, cfg);
    for (let i = 0; i < 3; i++) wt4.creditDeed(early, "h", "arcContestWon", { worldDay: 1 });
    const noFloor = wt4.advanceStandings(early, [f], 10, cfg).length;      // deeds yes, floor no
    const late = {}; wt4.advanceStandings(late, [f], 0, cfg);
    const noDeeds = wt4.advanceStandings(late, [f], 300, cfg).length;      // floor yes, deeds no
    return noFloor === 0 && noDeeds === 0;
  })());

  // ⚠️ THE BUG THAT MADE EVERY PROMOTION IMPOSSIBLE: creditDeed opens a tenure record with no tier, and
  // advanceStandings treated that placeholder as "the rung changed", wiping the deeds it had just counted.
  check("272/279: a deed credited BEFORE standings does not reset the tenure it counts toward", (() => {
    const ws = {};
    wt4.creditDeed(ws, "x", "arcContestWon", { worldDay: 1 });
    wt4.advanceStandings(ws, [{ id: "x", tier: "heroic" }], 2, { promotion: {}, worldYearDays: 365 });
    return ws.figureTenure.x.deeds === 3;   // survived the pass
  })());

  check("272/279: a rise says WHAT they did, and names the player when they caused it", (() => {
    const cfg = { promotion: { heroic: { to: "epic", years: 0, deeds: 3 } }, worldYearDays: 365 };
    const ws = {}; const f = { id: "h", name: "H", tier: "heroic" };
    wt4.advanceStandings(ws, [f], 0, cfg);
    wt4.creditDeed(ws, "h", "guardIntercept", { worldDay: 1, playerInvolved: true });
    const r = wt4.advanceStandings(ws, [f], 5, cfg)[0];
    return !!r && typeof r.why === "string" && r.why.length > 4 && r.causedByPlayer === true;
  })());

  check("272/279: the news carries the attribution and the player credit",
    /You are why\./.test(wsrc4) && /causedByPlayer: !!r\.causedByPlayer/.test(wsrc4));

  // Demotion had TWO unreachable conditions before this landed; both read as 0.0 falls in the sweep.
  check("272/279: falling reads an OUT-OF-ACTION streak, not “owns no cares” (which is never true)",
    /ws\.outOfAction\[f\.id\] = \(st === "wounded" \|\| st === "stopped"\)/.test(wsrc4)
    && !/if \(affinitiesOf\(f\)\.length\) continue;/.test(wsrc4));

  check("272/279: the ladder is SWEPT, and the sweep exists to re-derive it",
    ladderDoc.tierLadder?.promotion?.epic?.deeds === 70
    && existsSync(join(root, "tests/deed_ladder_sweep.mjs")));
}

// --- SNG-281: news travels (the writer `spread` never had) ------------------------------------------
{
  const { spreadDeeds } = await import("../engine/reputation.js");
  const G = { communitiesByRegion: { valley: ["v.a","v.b","v.c"], mason: ["m.x","m.y"] },
              regionOfCommunity: { "v.a":"valley","v.b":"valley","v.c":"valley","m.x":"mason","m.y":"mason" } };
  const mk = (weight) => ({ deeds: [{ communityId: "v.a", weight, description: "a thing", spread: [] }] });
  const soak = (b) => { let s = 5; const rng = () => (s = (s*1103515245+12345) % 2147483648) / 2147483648;
    for (let i = 0; i < 60; i++) spreadDeeds(b, { ...G, rng, rate: 1 }); return b.deeds[0].spread; };

  check("272/281: a deed now SPREADS — the field had a reader and no writer since it was introduced",
    soak(mk(1)).length > 0);
  check("272/281: reach is set by MAGNITUDE — a small deed stays local, a large one crosses regions", (() => {
    const small = soak(mk(1)), big = soak(mk(3));
    return small.length < big.length && !small.some(c => c.startsWith("m.")) && big.some(c => c.startsWith("m."));
  })());
  // ⛔ DIRECTIVE SNG-280: a deed does not travel further for being admirable.
  check("272/281: an atrocity travels exactly as far as a rescue of the same size (SNG-280)",
    soak(mk(3)).length === soak(mk(-3)).length);
  check("272/281: a deed is never heard twice in the same place",
    (() => { const s = soak(mk(3)); return new Set(s).size === s.length; })());
  check("272/281: the world tick is the writer, and a hop scores toward promotion",
    /spreadDeeds\(bearer, \{ communitiesByRegion/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8"))
    && /creditDeed\(ws, f\.id, "spreadPerHop"/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-282: the player travels too, and a resolved quest is a deed --------------------------------
{
  const { resolveStructuredQuest } = await import("../engine/quests.js");
  const { spreadDeeds } = await import("../engine/reputation.js");
  const mkQ = (xp) => ({ id: "c", name: "C", deeds: [],
    quests: [{ id: "q1", structured: true, status: "active", title: "The Medicine Road",
      outcomes: [{ id: "held", name: "the road stayed open", effects: [{ kind: "xp", xp }] }] }] });

  check("272/282: a resolved quest RECORDS A DEED (it used to be written on the quest and nowhere else)", (() => {
    const ch = mkQ(50);
    resolveStructuredQuest(ch, "q1", "held", { communityId: "valley.millbrook", worldDay: 5 });
    const d = ch.deeds[0];
    return !!d && /Medicine Road/.test(d.description) && d.communityId === "valley.millbrook"
      && d.tags.includes("quest");
  })());

  // ⛔ DIRECTIVE SNG-280: the weight is the SIZE of the outcome, never a verdict on it.
  check("272/282: a resolution’s weight is its MAGNITUDE — a bigger outcome travels further, not a nicer one", (() => {
    const big = mkQ(50), small = mkQ(5);
    resolveStructuredQuest(big, "q1", "held", { communityId: "v.a" });
    resolveStructuredQuest(small, "q1", "held", { communityId: "v.a" });
    return big.deeds[0].weight > small.deeds[0].weight;
  })());

  check("272/282: the description is WHAT HAPPENED (the outcome’s own name), not a judgement of it", (() => {
    const ch = mkQ(30);
    resolveStructuredQuest(ch, "q1", "held", { communityId: "v.a" });
    return ch.deeds[0].description.includes("the road stayed open");
  })());

  check("272/282: a quest still resolves even if the deed cannot be written",
    /a quest must resolve even if the record cannot be written/.test(readFileSync(join(root, "engine/quests.js"), "utf8")));

  check("272/282: the resolve call site passes WHERE, or the deed has nowhere to travel from",
    /communityId: hereNow\(\)\?\.communityId \?\? null/.test(readFileSync(join(root, "app.js"), "utf8")));

  // ⚠️ CORRECTED. The player was ALREADY spread by `runWorldTick` (v0.5.0, three tests below gate it); I
  // added a second model without finding the first. The gate now asserts there is exactly ONE writer per
  // bearer rather than asserting my duplicate exists.
  // SNG-289 (Erik): ONE model, graded by weight, for the player and for figures alike. The all-at-once
  // block is gone — so there must be no second writer, and `spreadDeeds` must be the only one.
  check("272/282: there is exactly ONE spread model, and it is the graded one",
    (() => { const w = readFileSync(join(root, "engine/worldtick.js"), "utf8");
      return !/deed\.spread = \[/.test(w) && (w.match(/spreadDeeds\(/g) || []).length >= 2; })());

  check("272/282: …and spreadDeeds genuinely does not care what kind of bearer it is handed", (() => {
    const player = { name: "P", deeds: [{ communityId: "v.a", weight: 2, description: "x", spread: [] }] };
    let s = 3; const rng = () => (s = (s*1103515245+12345) % 2147483648) / 2147483648;
    spreadDeeds(player, { communitiesByRegion: { valley: ["v.a","v.b"] }, regionOfCommunity: { "v.a":"valley","v.b":"valley" }, rng, rate: 1 });
    return player.deeds[0].spread.length === 1;
  })());
}

// --- SNG-273: a stage CHANGES THE WORLD, not a sentence -----------------------------------------------
{
  const AE = await import("../engine/arceffects.js");
  const appA = readFileSync(join(root, "app.js"), "utf8");
  const arcsDoc = JSON.parse(readFileSync(join(root, "content/packs/valley/lore/greater_arcs.json"), "utf8"));
  const allArcs = arcsDoc.greaterArcs || arcsDoc.arcs || [];
  const content = { greaterArcs: allArcs };

  check("272/273: every authored stage effect is REACHABLE by the reader",
    AE.activeArcEffects(content, {}, () => 2).length > 0);

  check("272/273: a stage changes what a CRAFT costs, and says which arc did it", (() => {
    const eff = AE.activeArcEffects(content, {}, () => 2);
    const note = AE.craftCostNote(12, eff, { crossDomain: true });
    return !!note && note.adjusted > 12 && /Poles/.test(note.text);
  })());

  // ⛔ THE DESIGN RULE: a stage changes THE WORLD, never taxes the sheet. A craft the world is not touching
  // must cost exactly what it always did.
  check("272/273: a craft the world is NOT touching is unchanged (no blanket tax)", (() => {
    const eff = AE.activeArcEffects(content, {}, () => 2);
    return AE.craftCostNote(12, eff, { tradition: "nothing_at_all", crossDomain: false }) === null;
  })());

  // AND NOT EVERY STAGE IS DECAY — or every arc reads as a misery meter.
  check("272/273: some stages make things EASIER (an arc advancing is not always bad news)", (() => {
    let cheaper = false;
    for (let s = 1; s <= 4; s++) for (const e of AE.activeArcEffects(content, {}, () => s))
      if (e.kind === "craftCost" && Number(e.mult) < 1) cheaper = true;
    return cheaper;
  })());

  check("272/273: the cost is explained AT THE POINT OF USE, not on a tab",
    /craftCostNote\(energyCost, arcEffectsNow\(\)/.test(appA) && /pendingArcCostNote = note/.test(appA));
  check("272/273: …and on the World tab in plain words",
    /effects: effectsInPlainWords\(arcEffectsNow\(\)\)/.test(appA)
    && /wt-effect/.test(readFileSync(join(root, "engine/worldtab.js"), "utf8")));
  check("272/273: the encounter POOL leans with the world, at every draw site", (() => {
    const appSrcB = readFileSync(join(root, "app.js"), "utf8");
    const wired = (appSrcB.match(/arcBias: encounterBias\(arcEffectsNow\(\)\)/g) || []).length;
    const draws = (appSrcB.match(/pickEncounter\(/g) || []).length;
    return wired === draws && draws >= 3;   // every draw, or the world tilts some encounters and not others
  })());
  check("272/273: the roads and the mood are wired too",
    /travelCostFactor\(arcEffectsNow\(\)\)/.test(appA) && /arcMoods: npcMoodLines\(arcEffectsNow\(\)\)/.test(appA)
    && /arcMoodDetail/.test(readFileSync(join(root, "engine/gm.js"), "utf8")));

  // ⚠️ An effect kind with no consumer must be VISIBLE as such, not silently inert.
  // ⚠️ THE MECHANISM, NOT TODAY'S EXAMPLE. This gate used to assert `EFFECT_CONSUMERS.priceShift === null` —
  // so when SNG-302 GAVE priceShift a consumer, a gate went red for the good news. A gate that fails when a
  // gap is closed is measuring the gap, not the rule; the rule is "a kind with no consumer is marked inert",
  // and it has to hold for whichever kind that happens to be. A synthetic kind keeps it honest either way.
  check("272/273: an effect kind with NO consumer is declared, not left looking live", (() => {
    const live = AE.effectsInPlainWords([{ kind: "npcMood", shift: "wary", arcName: "A", stageName: "s" }]);
    const dead = AE.effectsInPlainWords([{ kind: "npcMood", shift: "wary", arcName: "A", stageName: "s" }]
      .map(e => ({ ...e })));
    // every kind the register knows must resolve to a truthy consumer or be flagged inert — no third state
    const kinds = Object.keys(AE.EFFECT_CONSUMERS);
    const consistent = kinds.every(k => AE.EFFECT_CONSUMERS[k] === null || typeof AE.EFFECT_CONSUMERS[k] === "string");
    return consistent && live[0]?.inert === false && dead.length === 1;
  })());
  // …and the marking is DERIVED from the register, so a kind that gains a consumer stops being marked
  // without anyone having to remember. Proved by flipping a real entry in a copy.
  check("272/273: the inert flag reads the consumer register rather than naming a kind", (() => {
    const src = readFileSync(join(root, "engine/arceffects.js"), "utf8");
    return /inert:\s*!EFFECT_CONSUMERS\[e\.kind\]/.test(src);
  })());
  check("272/302: priceShift now HAS a consumer, and the register says so",
    typeof AE.EFFECT_CONSUMERS.priceShift === "string" && /economy/.test(AE.EFFECT_CONSUMERS.priceShift));
}

// --- SNG-288: seven roads to mythic -------------------------------------------------------------------
{
  const wt5 = await import("../engine/worldtick.js");
  const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const PATHS = doc.tierLadder.mythicPaths;

  check("272/288: all seven roads are authored and reachable by the engine", PATHS.length === 7);

  // ⚠️ THE CAREER, NOT THE RUNG. tenure deeds/losses reset on promotion; these paths describe a whole life.
  check("272/288: the paths read a CAREER that survives promotion", (() => {
    const ws = {};
    wt5.career(ws, "f").deeds = 500; wt5.career(ws, "f").losses = 40;
    const t = (ws.figureTenure ||= {}); t.f = { tier: "legendary", sinceDay: 0, deeds: 0, losses: 0 };
    return wt5.mythicPathFor(ws, "f", PATHS) !== null;   // qualifies on career despite a zeroed rung
  })());

  check("272/288: THE SURVIVOR requires a BAD record — a careful figure cannot walk it", (() => {
    const survivor = PATHS.find(p => p.id === "the_survivor");
    const ws = {}; const c = wt5.career(ws, "f");
    c.deeds = 250; c.losses = 0; c.deaths = 0;   // spotless — must NOT qualify as the survivor
    const spotless = wt5.mythicPathFor(ws, "f", [survivor]);
    c.losses = 30;
    const scarred = wt5.mythicPathFor(ws, "f", [survivor]);
    return spotless === null && scarred?.id === "the_survivor";
  })());

  check("272/288: a death disqualifies THE SURVIVOR (never once killed is the point)", (() => {
    const ws = {}; const c = wt5.career(ws, "f");
    c.deeds = 250; c.losses = 30; c.deaths = 1;
    return wt5.mythicPathFor(ws, "f", [PATHS.find(p => p.id === "the_survivor")]) === null;
  })());

  // ⛔ DIRECTIVE SNG-280 — without THE FEARED the top rung silently selects for virtue.
  check("272/288: THE FEARED is reachable, so the top rung does not select for virtue", (() => {
    const feared = PATHS.find(p => p.id === "the_feared");
    const ws = {}; const c = wt5.career(ws, "f"); c.deeds = 200;
    const bearer = { deeds: Array.from({ length: 24 }, (_, i) => ({ weight: -3, spread: [`c${i}`] })) };
    return wt5.mythicPathFor(ws, "f", [feared], bearer)?.id === "the_feared";
  })());
  check("272/288: …and THE KEPT sits at the same order of difficulty (neither is the real one)", (() => {
    const f = PATHS.find(p => p.id === "the_feared").condition.deeds;
    const k = PATHS.find(p => p.id === "the_kept").condition.deeds;
    return Math.abs(f - k) <= 60;
  })());

  check("272/288: WHICH ROAD was walked is recorded, not just that they arrived",
    /path: viaPath\?\.id \|\| null/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-287: generative titles ----------------------------------------------------------------------
{
  const T = await import("../engine/titles.js");
  const doc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/titles.json"), "utf8"));
  const P = doc.patterns;
  const opts = (ws) => ({ ws, patterns: P, arcNames: { a1: "the Bleed" }, traditionNames: { ashwarden: "the Ashwardens" } });
  const wsWith = (log) => ({ figureTenure: { f: { deedLog: log } }, figureCareer: { f: { retrieved: 0 } } });

  check("272/287: a title is built from the RECORD — an arc actually turned becomes a name", (() => {
    const b = { id: "f", tradition: "ashwarden", deeds: [{ communityId: "valley.thornwake", weight: 3 }, { communityId: "valley.thornwake", weight: 2 }] };
    return T.titleFor(b, opts(wsWith([{ by: "stageMoved", arcId: "a1" }])))?.title === "Who Turned the Bleed";
  })());

  // ⚠️ THE RULE THAT KEEPS THEM HONEST. No record, no name — a title that reaches for a slot with no
  // source is not flattering, it is false.
  check("272/287: nothing recorded means NO title (a world where everyone has an epithet has none)",
    T.titleFor({ id: "z", deeds: [] }, opts({})) === null);
  check("272/287: no arc moved means no {ARC} title — the pattern is skipped, not guessed at", (() => {
    const b = { id: "f", tradition: "ashwarden", deeds: [{ communityId: "valley.thornwake", weight: 3 }, { communityId: "valley.thornwake", weight: 2 }] };
    const t = T.titleFor(b, opts(wsWith([])));
    return t !== null && !/Turned/.test(t.title);
  })());

  // ⛔ DIRECTIVE SNG-280: which noun lands is read off the SIGN of the record, never approval.
  check("272/287: the same pattern names a hard record and a soft one, and the Maw gets a name too", (() => {
    const hard = { id: "f", deeds: [{ communityId: "v.thornwake", weight: -3 }, { communityId: "v.thornwake", weight: -3 }] };
    const soft = { id: "f", deeds: [{ communityId: "v.thornwake", weight: 3 }, { communityId: "v.thornwake", weight: 3 }] };
    const h = T.titleFor(hard, opts(wsWith([])))?.title, s = T.titleFor(soft, opts(wsWith([])))?.title;
    return /Knife/.test(h || "") && /Mercy/.test(s || "");
  })());
  check("272/287: a MIXED record resolves to neither noun (not known for one thing → not told you are)", (() => {
    const mixed = { id: "f", deeds: [{ communityId: "v.thornwake", weight: 3 }, { communityId: "v.thornwake", weight: -3 }] };
    const t = T.titleFor(mixed, opts(wsWith([])));
    return !/Knife|Mercy/.test(t?.title || "");
  })());

  // ⚠️ Slots the spec asks for that nothing can fill are NAMED, not silently absent.
  // SNG-294: two of the three were then BUILT ({FOE}) or RE-SOURCED ({CRAFT}→{TAG}). Only {ROAD} remains,
  // and it remains because the world has locations rather than named routes — not because it was forgotten.
  check("272/287: a slot with no source is declared, not left looking live",
    T.unusablePatterns(P).length === 0 && Object.keys(T.UNFILLABLE_SLOTS).length === 1);

  check("272/287: a title is spoken when the world finds one, and remembered",
    /r\.title = named\.title/.test(readFileSync(join(root, "engine/worldtick.js"), "utf8")));
}

// --- SNG-295 + SNG-294: who turned it, and the three slots ------------------------------------------
{
  const wt6 = await import("../engine/worldtick.js");
  const T2 = await import("../engine/titles.js");
  const wsrc6 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const tdoc = JSON.parse(readFileSync(join(root, "content/packs/core/rules/titles.json"), "utf8"));

  // SNG-295 — Erik ruled on all four questions; these are the four rulings.
  check("272/295: only the side it moved TOWARD is credited — nobody who leaned against it",
    /const wentUp = now > before;[\s\S]{0,200}const movers = wentUp \? \(leaning\[arcId\]\?\.pro/.test(wsrc6));
  check("272/295: and only those who WON — presence is not turning (the bug this fixes)",
    /if \(!winners\.has\(e\.f\.id\)\) continue;/.test(wsrc6));
  check("272/295: REVERSING counts as turning (the title says you moved it, not which way)",
    /const wentUp = now > before/.test(wsrc6) && /: \(leaning\[arcId\]\?\.con \|\| \[\]\)/.test(wsrc6));
  check("272/295: emptying the front counts — a strike that removed a defender turned it too",
    /removedDefender\[arcId\] \|\|= new Set\(\)\)\.add\(sender\.f\.id\)/.test(wsrc6));
  check("272/295: those who leaned WITH it and won nothing still get the smaller credit",
    /creditDeed\(ws, e\.f\.id, "heldThroughCrisis"/.test(wsrc6));

  // SNG-294 — the three slots, as Aevi ruled each one.
  check("272/294: {FOE} is BUILT — the hardest thing they put down, by rung not recency",
    /if \(!c\.bestFoe \|\| band > \(c\.bestFoe\.band \?\? -1\)\)/.test(wsrc6));
  check("272/294: {CRAFT} was RE-SOURCED to {TAG}, not built — a tag is what the WORLD noticed", (() => {
    const ids = tdoc.patterns.map(p => p.id);
    return ids.includes("the_tag") && !ids.includes("the_craft") && !!tdoc.tagEpithets?.raise;
  })());
  check("272/294: an UNMAPPED tag yields no title rather than a coined one", (() => {
    const rec = { deeds: [{ tags: ["nobody_has_a_word_for_this"] }, { tags: ["nobody_has_a_word_for_this"] }, { tags: ["nobody_has_a_word_for_this"] }], tagEpithets: {} };
    return T2.SLOT_SOURCES.TAG(rec) === null;
  })());
  check("272/294: {ROAD} ships as Warden of {PLACE} — the world has locations, not named routes", (() => {
    const ids = tdoc.patterns.map(p => p.id);
    return ids.includes("warden_of_place") && !ids.includes("warden_of_road")
      && Object.keys(T2.UNFILLABLE_SLOTS).length === 1 && !!T2.UNFILLABLE_SLOTS.ROAD;
  })());
  check("272/294: every authored pattern is now fillable", T2.unusablePatterns(tdoc.patterns).length === 0);

  // ⚠️ Order can starve a fillable pattern. Reported, not enforced — order is authorship.
  check("272/294: order-sensitivity is REPORTED, and the flagged patterns still demonstrably fire", (() => {
    const flagged = T2.orderSensitivePatterns(tdoc.patterns).map(x => x.id);
    const o = { ws: { figureTenure: { f: { deedLog: [] } }, figureCareer: { f: {} } }, patterns: tdoc.patterns,
      tagEpithets: tdoc.tagEpithets, arcNames: {}, traditionNames: {} };
    const wanderer = { id: "f", deeds: [{ communityId: "a.one", weight: 2, tags: ["raise"] },
      { communityId: "b.two", weight: 2, tags: ["raise"] }, { communityId: "c.three", weight: 2, tags: ["raise"] }] };
    return flagged.length > 0 && T2.titleFor(wanderer, o)?.title === "The Raiser";
  })());
}

// --- SNG-296 (WORK ORDER v2 Track C): the item generator ---------------------------------------------
{
  const G = await import("../engine/generate.js");
  const INV = await import("../engine/inventory.js");
  const appI = readFileSync(join(root, "app.js"), "utf8");
  const schema = JSON.parse(readFileSync(join(root, "schemas/item.schema.json"), "utf8"));

  check("272/296: `item` is a generation type", G.GEN_TYPES.includes("item"));
  check("272/296: SHIELD is a kind of its own — the catalog had none and guard crafts are 19 of the defensive logics",
    (schema.properties.kind.enum || []).includes("shield"));

  // ⚠️ BORN WHOLE MEANS IT CAN AFFECT A ROLL. A described item with no bonusTags is flavour text.
  check("272/296: the schema REQUIRES the mechanical hook, not just a description",
    (schema.required || []).includes("bonusTags") && schema.properties.bonusTags.minItems >= 1);

  // The whole point: a generated item must reach the CATALOG, or nothing can re-link it to its bonuses.
  check("272/296: a generated item is hydrated into the item catalog",
    /generatedRecords\(c, "item"\)\) if \(!CONTENT\.items\[rec\.id\]\) CONTENT\.items\[rec\.id\] = rec/.test(appI));

  // …and end to end: a generated shield in the bag changes a guard roll.
  check("272/296: a generated shield actually changes a guard roll (the consumer Aevi thought was missing)", (() => {
    const rules = { baseChance: { equipmentBonus: 5, equipmentBonusCap: 10, equipmentBonusTopN: 1 } };
    const bearer = { inventory: [{ id: "gen-shield", name: "a plain shield", kind: "shield", bonusTags: ["guard", "protect"] }] };
    const helped = INV.equipmentBonus(bearer, ["guard"], rules);
    const unrelated = INV.equipmentBonus(bearer, ["persuade"], rules);
    return helped.bonus > 0 && helped.helpers.length === 1 && unrelated.bonus === 0;
  })());
}

// --- SNG-297: a minted figure is born with a life ---------------------------------------------------
{
  const wt7 = await import("../engine/worldtick.js");
  const doc7 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const pools = doc7.mintedFigures;

  const mk = () => { const ws = {};
    return { ws, f: wt7.mintFigure(ws, { tier: "riffraff", arcAffinity: "arc_a", secondArc: "arc_b",
      originKind: "casualty_survivor", pools, epithet: "e", rng: () => 0.1 }) }; };

  check("272/297: a minted figure has MORE THAN ONE care — it can hold two fronts and abandon one",
    mk().f.arcAffinities.length === 2);
  check("272/297: the second care is DERIVED from circumstance and OPPOSES the first (they inherit the argument)",
    (() => { const a = mk().f.arcAffinities; return a[0].arcId === "arc_a" && a[1].arcId === "arc_b" && a[1].dir !== a[0].dir; })());
  check("272/297: it has a wantArcId — something to be for when nothing is on fire",
    mk().f.wantArcId === "arc_a");
  check("272/297: it has a LIFE off-arc, drawn from its own origin event",
    (() => { const v = mk().f.personalVerbs; return v.length > 0 && pools.personalVerbsByOrigin.casualty_survivor.includes(v[0]); })());

  // ⛔ THE POOLS DO NOT INVENT A LIFE — the engine’s own rule, held by the content too.
  check("272/297: with no pools authored it gets NO fabricated life (silence over invention)",
    (() => { const ws = {}; const f = wt7.mintFigure(ws, { arcAffinity: "a", epithet: "e", rng: () => 0.1 });
      return Array.isArray(f.personalVerbs) && f.personalVerbs.length === 0; })());

  // Aevi asked for a gate so this cannot recur. A RATCHET rather than a hard failure: the 66 AUTHORED figures
  // have no personal pool either, so a hard gate would fail on content that predates the field — but the
  // count may never grow, which is the part that stops it recurring.
  check("272/297: every MINTED figure is born whole, and the count of thin ones may only go down", (() => {
    const ws = {};
    for (let i = 0; i < 12; i++) wt7.mintFigure(ws, { arcAffinity: `arc_${i}`, secondArc: "arc_x",
      originKind: "vacancy_filled", pools, epithet: `e${i}`, rng: () => 0.3 });
    const thin = (ws.mintedFigures || []).filter(f => !(f.arcAffinities?.length >= 1 && f.wantArcId && f.personalVerbs?.length));
    return thin.length === 0;
  })());
}

// --- SNG-298: NPCs change their minds ---------------------------------------------------------------
{
  const wt8 = await import("../engine/worldtick.js");
  const wsrc8 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const f = () => ({ id: "n", arcAffinities: [{ arcId: "bleed", dir: -1, weight: 2 }] });

  check("272/298: an attempt on their life over an arc they hold makes them DIG IN",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "bleed" }] }).cares.find(c => c.arcId === "bleed").weight === 3);
  check("272/298: …and over an arc they had no opinion on, they GAIN one",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "poles" }] }).cares.some(c => c.arcId === "poles"));

  // ⛔ DIRECTIVE SNG-280 — the player cannot farm allies by being agreeable.
  check("272/298: a DISLIKED player recruits the opposite side just as reliably", (() => {
    const liked = wt8.evolveCares(f(), { playerArcs: [{ arcId: "storm", dir: 1 }], relationship: 3 });
    const disliked = wt8.evolveCares(f(), { playerArcs: [{ arcId: "storm", dir: 1 }], relationship: -3 });
    const a = liked.cares.find(c => c.arcId === "storm"), b = disliked.cares.find(c => c.arcId === "storm");
    return a.dir === 1 && b.dir === -1;
  })());
  check("272/298: knowing the player does NOT flip someone already leaning the other way", (() => {
    const r = wt8.evolveCares(f(), { playerArcs: [{ arcId: "bleed", dir: 1 }], relationship: 5 });
    return r.cares.find(c => c.arcId === "bleed").dir === -1;   // still theirs
  })());

  check("272/298: a care left untended fades — without erosion everyone ends up caring about everything",
    wt8.evolveCares(f(), { idleArcs: ["bleed"] }).cares.find(c => c.arcId === "bleed").weight === 1);
  check("272/298: …but erosion NEVER empties them (a figure with no cares drops out of the world)",
    wt8.evolveCares({ id: "x", arcAffinities: [{ arcId: "a", dir: 1, weight: 1 }] }, { idleArcs: ["a"] }).cares.length === 1);
  check("272/298: a figure cannot end up caring about everything",
    wt8.evolveCares(f(), { struckOnArcs: [{ arcId: "p1" }, { arcId: "p2" }, { arcId: "p3" }, { arcId: "p4" }, { arcId: "p5" }],
      cfg: { maxCares: 4 } }).cares.length <= 4);

  // ⚠️ THE WIRE THAT MAKES IT REAL: attention must read the EVOLVED cares, or the shift is announced and ignored.
  check("272/298: the pass spends attention on the cares as they are NOW, not as authored",
    /const fNow = \{ \.\.\.f, arcAffinities: currentCares\(ws, f\) \}/.test(wsrc8)
    && /spendAttention\(fNow,/.test(wsrc8));
  check("272/298: the change is told in the arc’s NAME, not its id",
    /nameOfArc\(hard\.arcId\)/.test(wsrc8) && /nameOfArc = \(id\)/.test(wsrc8));
}

// --- SNG-299: who is that, and where do I read more -------------------------------------------------
{
  const W = await import("../engine/whois.js");
  const appW2 = readFileSync(join(root, "app.js"), "utf8");
  const content = { greaterArcs: [{ id: "a1", name: "The Bleed", stages: [{ stage: 2, name: "Strain", publicFace: "it shows at the edges", truth: "SEALED — must never reach a player" }] }] };
  const roster = [{ id: "n", name: "Neth", tradition: "ashwarden", role: "Master", wants: "that none die unattended" }];
  const ws = { figureTier: { n: "legendary" }, figureTitles: { n: { title: "Whom the Ashwardens Named", slots: {} } },
    figureCares: { n: [{ arcId: "a1", dir: -1, weight: 2 }] }, arcStageSeen: { a1: 2 } };
  const ctx = { ws, content, character: { codex: { topics: {} } }, roster };

  check("272/299: a figure answers with their rung, their title and what they are caught up in NOW", (() => {
    const k = W.whoIs("n", "figure", ctx);
    return /Whom the Ashwardens Named/.test(k.lines[0]) && k.lines.some(l => /legendary/.test(l))
      && k.lines.some(l => /The Bleed/.test(l));
  })());

  // ⛔ THE SEALED TRUTH IS NOT THE PLAYER’S TO READ FROM A POPUP.
  check("272/299: an arc gives its publicFace and NEVER its sealed truth", (() => {
    const k = W.whoIs("a1", "arc", ctx);
    return /it shows at the edges/.test(k.lines.join(" ")) && !/SEALED/.test(JSON.stringify(k));
  })());

  check("272/299: a term explains itself", /lasted/.test(W.whoIs("legendary", "tier", ctx).lines[0]));

  // ⚠️ NOTHING KNOWN → NO LINK. A popup that says "a figure of the valley" promises a lookup and shrugs.
  check("272/299: an unknown name returns null rather than a composed description",
    W.whoIs("nobody", "figure", ctx) === null && W.whoIs("no_such_arc", "arc", ctx) === null);

  check("272/299: the codex button appears only where a codex page EXISTS", (() => {
    const without = W.whoIs("n", "figure", ctx);
    const with_ = W.whoIs("n", "figure", { ...ctx, character: { codex: { topics: { n: { label: "Neth" } } } } });
    return without.codexId === null && with_.codexId === "n";
  })());

  check("272/299: the index prefers the LONGEST name, so a full name beats the surname inside it", (() => {
    const idx = W.knownIndex({ roster: [{ id: "n", name: "Neth, Who Has Buried More" }, { id: "m", name: "Neth" }] });
    return idx[0].name.length > idx[idx.length - 1].name.length;
  })());

  // ══ SNG-369 — THE PEOPLE YOU HAVE MET. ⛔ Erik, in play: Sorel underlined and Teva not, in one sentence.
  // Sorel is linked because she happened to earn a CODEX TOPIC — not because she is registered — and this
  // index never read `npcRegistry` at all. Measured across the live saves: 53 of 110 people the players
  // have met were clickable. ⚠️ And `showWhoIs` has handled `kind === "npc"` for the portrait since
  // SNG-367: the door was built, the corridor to it was not. Registration is not arrival.
  {
    const npcs369 = [
      { id: "cassiel-ord", name: "Cassiel Ord", role: "Keeper of the warden post", description: "A lean man in a grey coat." },
      { id: "morning-shepherd", name: "Shepherd", role: "Smallholder shepherd, trade track south" },
      { id: "cookhouse-boy", name: "Boy (name unknown)", role: "Sweeping the cookhouse" },
      { id: "veth", name: "Veth (Stillwater) Ondra", role: "Former warden, traveling companion" },
      { id: "sorel", name: "Sorel", role: "Spice-broker, Edge District contact" },
    ];
    const idx369 = W.knownIndex({ npcs: npcs369 });
    const has = (n) => idx369.some(e => e.name === n && e.kind === "npc");
    check("369: a person you have MET is linkable from the registry, with no codex page required", has("Cassiel Ord") && has("Sorel"));
    // ⛔ A NAME THAT MERELY RESTATES WHAT THEY DO IS NOT A NAME. The guard is deliberately narrow: only a
    // ONE-WORD name that appears inside its own role can put a who-is button on ordinary prose.
    check("369: a one-word placeholder named for its own role is NOT linked — no button on ordinary prose", !has("Shepherd"));
    check("369: …and a parenthetical that SAYS the name is unknown is not linked either", !has("Boy (name unknown)"));
    // ⚠️ AND THE GUARD MUST NOT EAT A REAL PERSON. My first cut rejected every parenthetical and dropped
    // "Veth (Stillwater) Ondra" — an aka — alongside the placeholder.
    check("369: …but a real person with an aka survives the parenthetical rule", has("Veth (Stillwater) Ondra"));
    // ⚠️ ONE ENTRY PER NAME, RICHEST SOURCE FIRST. The same person legitimately appears in two sources, and
    // two entries made the linker's earliest-then-longest tie-break arbitrary.
    const dupe = W.knownIndex({ roster: [{ id: "fig", name: "Sorel" }], npcs: npcs369 });
    check("369: a name in two sources yields ONE entry, and the richer source wins",
      dupe.filter(e => e.name === "Sorel").length === 1 && dupe.find(e => e.name === "Sorel").kind === "figure");
    const card = W.whoIs("cassiel-ord", "npc", { ws: {}, content: {}, character: { npcRegistry: Object.fromEntries(npcs369.map(n => [n.id, n])) }, roster: [] });
    check("369: whoIs answers for someone you have met — role and description, not 'the world knows nothing'",
      card && card.kind === "npc" && card.lines.length >= 2 && /Keeper of the warden post/.test(card.lines[0]));
    // ⚠️ NEVER SILENT FOR SOMEONE STANDING IN THE ROOM: a registered person with nothing authored still
    // gets an honest line, because the card exists to say you know them.
    const bare = W.whoIs("x", "npc", { ws: {}, content: {}, character: { npcRegistry: { x: { id: "x", name: "Teva" } } }, roster: [] });
    check("369: …and a registered person with NOTHING recorded still gets a card, not a null",
      bare && bare.kind === "npc" && bare.lines.length === 1);
    check("369: the card carries what a PORTRAIT needs — the npc branch of showWhoIs was built and unreached",
      "appearance" in card && "gender" in card && "role" in card);
  }

  // ══ SNG-370 — THE GENDER REPAIR CONTROL REACHES EVERY PERSON. ⛔ It read `.slice(0, 30)` in registry
  // order and Silas knows 34 people, so four could not be reached by the tool that exists to fix them —
  // and they were the most RECENTLY met, i.e. the ones just seen rendered wrong. Measured: 35 of the 110
  // people across the live saves carry neither gender nor pronouns, so their portrait gender is a guess.
  {
    const appG = readFileSync(join(root, "app.js"), "utf8");
    const start = appG.indexOf("Set a person's gender");
    // ⚠️ BOUNDED BY THE BLOCK, NOT BY 2400 CHARACTERS. I wrote this gate with a fixed slice an hour after
    // writing three separate comments about gates that pin a position instead of a truth — the same habit
    // reappearing inside the fix for it. The repair screen is a run of `cs-block` sections, so the block
    // ENDS where the next one begins; adding a paragraph here must not turn this red.
    const end = appG.indexOf(`<div class="cs-block"`, start);
    const block = start < 0 ? "" : appG.slice(start, end > start ? end : undefined);
    check("370: the gender repair list is not capped — a cap on a repair tool is a repair you cannot perform",
      start > 0 && !/npcRegistry\)\.slice\(0,\s*\d+\)/.test(block));
    check("370: …and the people with NO gender are listed first, because they are who the control is for",
      /const unset = all\.filter\(n => !n\.gender && !n\.pronouns\)/.test(block) && /\[\.\.\.unset,/.test(block));
    check("370: …and the screen SAYS how many are unrecorded rather than leaving it to be noticed",
      /have no gender recorded/.test(block));
  }

  // The DOM pass: text nodes only, every match, and never inside an existing control.
  check("272/299: names are linked by walking TEXT NODES, never by rewriting rendered HTML",
    /createTreeWalker\(root, NodeFilter\.SHOW_TEXT/.test(appW2) && /SKIP\.has\(el\.tagName\)/.test(appW2));
  check("272/299: EVERY name in a sentence is linked, not just the first",
    /while \(cursor < text\.length\)/.test(appW2) && /at === best\.at && e\.name\.length > best\.e\.name\.length/.test(appW2));
  check("272/299: the pass runs for every screen, from chrome(), and can never take one down",
    /try \{ linkifyKnown\(app\); \} catch/.test(appW2));
}

// --- SNG-300: who seeks a fight ----------------------------------------------------------------------
{
  const wsrcE = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  const docE = JSON.parse(readFileSync(join(root, "content/packs/core/rules/arc_response.json"), "utf8"));
  const eng = docE.engagement;

  check("272/300: engagement is a property of the FIGURE, not a quota on the side",
    /\(rng\(\) < engageOf\(e\.f\) \? engaged : working\)\.push\(e\)/.test(wsrcE));
  // ⚠️ A GATE MUST NOT ASSERT A TUNING VALUE. This pair used to require `marcher > stillhold * 5` and to name
  // both traditions by hand — so when Erik overturned the design (stillhold 0.15 → 1.1, because reading
  // "peace tradition" as "does not participate" was the moralising bias inverted), a gate went RED FOR THE
  // RIGHT CHANGE. That is close to the worst thing a gate can do: it defends yesterday's numbers against
  // today's decision, and the pressure it creates is to weaken the check rather than to think.
  //
  // The INVARIANT it was really guarding is "the table is DIFFERENTIATED, not flat". That survives any
  // retuning, names no tradition, and still fails on the thing it exists to catch.
  check("272/300: it is keyed on tradition, and the table is authored", (() => {
    const v = Object.values(eng?.byTradition || {}).map(Number);
    return v.length >= 20 && v.every(x => Number.isFinite(x) && x > 0);
  })());
  check("272/300: engagement is DIFFERENTIATED — the table is not flat", (() => {
    const v = Object.values(eng.byTradition).map(Number).filter(Number.isFinite);
    const lo = Math.min(...v), hi = Math.max(...v);
    // ⛔ TWO TESTS, BECAUSE A RATIO ALONE IS NOT ENOUGH. Aevi proposed `hi >= lo * 1.35`, which is right and
    // catches a wholly flat table — but it also PASSES on 27 traditions at 1.0 and one outlier at 1.4, which
    // is flat in every way that matters. The distinct-value count is what actually measures differentiation.
    return hi >= lo * 1.35 && new Set(v).size >= 5;
  })());
  check("272/300: nobody is guaranteed to never fight, and nobody fights every pass",
    /Math\.max\(lo, Math\.min\(hi, engageRate/.test(wsrcE) && eng.min > 0 && eng.max < 1);
  check("272/300: an unlisted tradition is unchanged, not penalised",
    /engageCfg\.byTradition\?\.\[t\] != null\) \? Number\(engageCfg\.byTradition\[t\]\) : 1/.test(wsrcE));
}

// --- SNG-302: the economy, and the consumer priceShift waited for ------------------------------------
{
  const EC = await import("../engine/economy.js");
  const econ = JSON.parse(readFileSync(join(root, "content/packs/core/rules/economy.json"), "utf8"));
  const at = (regionId, item, effects = []) => EC.priceOf(item, regionId, { economy: econ, effects });
  const region = (Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions))[0];
  const goods = Object.keys(region.goods)[0];

  check("272/302: the economy is registered, loaded AND destructured from the right Promise.all",
    /loadRule\("economy", null\)/.test(readFileSync(join(root, "engine/state.js"), "utf8"))
    && /if \(economyRule\) rules\.economy = economyRule/.test(readFileSync(join(root, "engine/state.js"), "utf8")));

  // ⚠️ ERIK’S CORRECTION IS THE MODEL: need dominates, and `none` is a hard zero.
  check("272/302: `need: none` is a HARD ZERO however scarce the thing is", (() => {
    const rows = Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions);
    const dead = rows.find(r => Object.values(r.goods || {}).some(g => g[0] === "none"));
    if (!dead) return false;
    const g = Object.entries(dead.goods).find(([, v]) => v[0] === "none")[0];
    const p = at(dead.regionId, { worth: "precious", goods: g });
    return p.price === 0 && p.unwanted === true;
  })());
  check("272/302: scarcity MODULATES an existing need, it never creates one", (() => {
    const rows = Array.isArray(econ.regions) ? econ.regions : Object.values(econ.regions);
    const dead = rows.find(r => Object.values(r.goods || {}).some(g => g[0] === "none" && g[1] !== "abundant"));
    if (!dead) return true;   // no such row authored — nothing to prove against
    const g = Object.entries(dead.goods).find(([, v]) => v[0] === "none")[0];
    return at(dead.regionId, { worth: "irreplaceable" }).refused || at(dead.regionId, { worth: "valuable", goods: g }).price === 0;
  })());

  // ⛔ THE IRREPLACEABLE IS REFUSED, NOT PRICED HIGH.
  check("272/302: an irreplaceable item is REFUSED a price rather than given a big one", (() => {
    const p = at(region.regionId, { worth: "irreplaceable" });
    return p.refused === true && p.price === null;
  })());

  // SNG-273 → SNG-302: the effect kind that had no consumer for weeks.
  check("272/302: a priceShift from an arc stage MOVES the local need", (() => {
    const before = EC.shiftNeed("ordinary", []).need;
    const after = EC.shiftNeed("ordinary", [{ kind: "priceShift", goods: "x", demandDelta: -1, arcName: "The Bleed" }], "x").need;
    return before === "ordinary" && after === "little";
  })());
  check("272/302: …and it cannot push need below none or above high", (() => {
    const floor = EC.shiftNeed("none", [{ kind: "priceShift", demandDelta: -3 }]).need;
    const ceil = EC.shiftNeed("high", [{ kind: "priceShift", demandDelta: 3 }]).need;
    return floor === "none" && ceil === "high";
  })());
  check("272/302: a shift for OTHER goods does not touch this item",
    EC.shiftNeed("ordinary", [{ kind: "priceShift", goods: "luxuries", demandDelta: -1 }], "medicines").need === "ordinary");

  // ⚠️ AND THE GAP IS DECLARED, not silently flat.
  check("272/302: the unreachable second axis is REPORTED rather than passing as a working price", (() => {
    const c = EC.economyCoverage(econ, [{ worth: "useful" }, { worth: "trivial" }]);
    return c.secondAxisLive === false && /no item carries a goods category/.test(c.note);
  })());
}

// --- SNG-302b: the real content loader must actually COMPLETE -----------------------------------------
// ⚠️ I put a diagnostic beside the economy merge that referenced `items` ~65 lines before `const items` is
// initialised. That is a temporal-dead-zone ReferenceError which takes the ENTIRE content load down at
// startup — the app would not boot — and `npm test` stayed GREEN through it, because nothing in the suite ran
// the real loader end to end. Everything downstream is worthless if this throws, so it is checked first now.
{
  let loaded = null, threw = null;
  try { const { loadContentHeadless } = await import("./headless_content.mjs"); loaded = await loadContentHeadless(); }
  catch (e) { threw = e; }
  // The name is a PLAIN LITERAL so the ledger’s drift guard can see it — it extracts double-quoted check
  // names, and a template literal is invisible to it. The error text goes to the log, where detail belongs.
  if (threw) console.log(`      loadContent threw: ${String(threw.message).slice(0, 160)}`);
  check("302b: the REAL loadContent() completes without throwing", !threw && !!loaded);
  check("302b: …and returns a world with content in it (a silent empty load is also a failure)",
    !!loaded && Object.keys(loaded.locations || {}).length > 0 && Object.keys(loaded.items || {}).length > 0
    && !!loaded.rules && Object.keys(loaded.rules).length > 20);
}

// --- SNG-303: the wiring is CHECKABLE, so it does not have to be remembered ---------------------------
// The same six lines of content wiring have failed three distinct ways: not registered (the zero-XP bug),
// registered but never loaded (Aevi's economy, caught by the check in under a minute), and loaded into a name
// belonging to a DIFFERENT `Promise.all` — which no prose check can catch, because positional destructuring
// has no names in it. The array and the name list are paired by COUNTING and nothing in the source says so.
{
  const { shapesOfSource, scanEngine } = await import("./wiring_shape.mjs");

  const shapes = scanEngine();
  const mismatched = shapes.filter(s => s.names !== s.entries);
  for (const m of mismatched) console.log(`      ${m.file}:${m.line} — ${m.names} names / ${m.entries} entries`);
  check("303: every Promise.all destructure pairs 1:1 with its awaited entries", shapes.length > 0 && mismatched.length === 0);

  // ⚠️ FALSIFY THE CHECKER. My own `loadRule("encounters")` once landed in `coliseumGrid`'s slot and pushed
  // the grid off the end of the array — with a fully green suite. This is that bug, planted, in one line.
  const planted = "const [a, b] = await Promise.all([one(), two(), three()]);";
  check("303: the checker goes RED on a planted extra entry (a gate that cannot fail is not a gate)",
    shapesOfSource(planted).some(s => s.names === 2 && s.entries === 3));

  // ⚠️ AND IT MUST NOT FIRE ON CORRECT CODE. My first version regex-matched `for (const [k, l] of …)` thirty
  // lines above the real block and reported 5 names against 22 entries — the CHECKER being wrong, not the
  // code. A measuring tool that cries wolf on good input teaches everyone to ignore it, which is worse than
  // having none. So the exact shape that fooled it is now a permanent check.
  const decoy = "for (const [k, l] of Object.entries(x)) { y(k, l); }\nconst [p, q] = await Promise.all([one(), two()]);";
  const dShapes = shapesOfSource(decoy);
  check("303: a preceding for-of destructure does not fool it into a false alarm",
    dShapes.length === 1 && dShapes[0].names === 2 && dShapes[0].entries === 2);
}

// ---- CCODE-158: a GM-initiated relocation the player never asked for is OFFERED, not imposed ----
// Erik's turn: "Take the opportunity to update Warden Coll on the status of the Water crisis." He was at
// the ridge; the beat put him in Coll's office two regions away. departureGateFor guards the door where
// the PLAYER asks to travel, BEFORE the GM is called. The moveTo applier is the other door and it had no
// gate at all — every guard in it was about WHERE, none about WHETHER.
{
  const { isConsequentialMove, departureGateFor } = await import("../engine/intent.js");
  // ⚠️ `edge` is CONNECTED to the ridge and in ANOTHER region — a road runs there, so only the
  // region-crossing clause can catch it. Without a connected cross-region place the not-connected
  // clause absorbs the case and the crossing test proves nothing (it did, at first).
  const locs424 = {
    ridge: { id: "ridge", name: "Threshold Post", regionId: "foothills", connections: ["mill", "edge"] },
    mill:  { id: "mill",  name: "Mill Gate",      regionId: "foothills", connections: ["ridge"] },
    edge:  { id: "edge",  name: "Edge District",  regionId: "radiant",   connections: ["ridge"] }
  };
  check("CCODE-158: a region crossing is a consequential move EVEN WHEN a road connects the two", isConsequentialMove("ridge", "edge", locs424) === true);
  check("CCODE-158: an adjacent step in the same region is NOT (a departure gate that nags is not a gate)", isConsequentialMove("ridge", "mill", locs424) === false);
  check("CCODE-158: a same-region place you are NOT connected to is a journey, not a step", isConsequentialMove("ridge", "orchard", { ...locs424, orchard: { id: "orchard", regionId: "foothills", connections: [] } }) === true);
  check("CCODE-158: an unresolvable destination FAILS CLOSED (the engine knows least, so it counts as real)", isConsequentialMove("ridge", "nowhere", locs424) === true && isConsequentialMove("ridge", null, locs424) === true);
  check("CCODE-158: standing still is not a move", isConsequentialMove("ridge", "ridge", locs424) === false);

  // the applier's actual decision, composed exactly as app.js composes it
  const unearned = (askedToTravel, dest, subParent = null, wgRoute = null) =>
    !!dest && dest !== "ridge" && !askedToTravel && !subParent && !wgRoute && isConsequentialMove("ridge", dest, locs424);
  check("CCODE-158 THE BUG: no travel intent + a region-crossing moveTo is REFUSED (Erik's exact shape)", unearned(false, "edge") === true);
  check("CCODE-158: the SAME move is allowed when the player actually asked to travel", unearned(true, "edge") === false);
  check("CCODE-158: an ordinary adjacent step is never refused", unearned(false, "mill") === false);
  check("CCODE-158: a sub-place and a waygate transit are never refused (they are not relocations)", unearned(false, "edge", "ridge") === false && unearned(false, "edge", null, { destId: "edge" }) === false);
  // ⚠️ RED BY CONSTRUCTION: before the fix the applier had NO whether-check at all, i.e. its effective
  // predicate was "never refuse". Pin that the gate distinguishes the two — a gate that passes under the
  // old behaviour is not a gate.
  const oldApplierPredicate = () => false; // what app.js effectively asked before CCODE-158
  check("CCODE-158: the gate goes RED under the pre-fix behaviour (no whether-check → never refused)", oldApplierPredicate() !== unearned(false, "edge"));

  // the departure gate still agrees with the shared predicate (one definition, two doors)
  const ch424 = { currentLocationId: "ridge" };
  check("CCODE-158: both doors share ONE definition — the gate fires on the crossing and not on the step",
    !!departureGateFor({ destId: "edge", name: "Edge District" }, ch424, locs424) && departureGateFor({ destId: "mill", name: "Mill Gate" }, ch424, locs424) === null);

  const appSrc424 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-158: the moveTo applier actually consults it, with all four clauses", /const unearnedMove =[\s\S]{0,320}!askedToTravel[\s\S]{0,200}!subParentId[\s\S]{0,60}!wgRoute[\s\S]{0,80}isConsequentialMove/.test(appSrc424));
  check("CCODE-158: a refused move OFFERS the road (_pendingArrival) instead of stranding the player", /refusedMove = true/.test(appSrc424) && /_pendingArrival = \{ ref: moveRef/.test(appSrc424) && /else if \(!refusedMove\)/.test(appSrc424));
  check("CCODE-158: the refusal is logged as an op outcome, so it is visible and not silent", /logOpOutcome\("moveTo", "refused-unearned"\)/.test(appSrc424));
  check("CCODE-158: the correction aside APPENDS — an aside that can be overwritten vanishes at random", /character\._correctionAside = \[character\._correctionAside, "Set right: "/.test(appSrc424));
  const gmSrc424 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-158: the moveTo contract forbids relocating a character whose action did not move them", /THE FICTION MAY NOT MOVE THEM UNLESS THEIR ACTION DID/.test(gmSrc424) && /that is a MESSAGE, not a journey/.test(gmSrc424));
}

// ---- CCODE-159: reaching someone who is ELSEWHERE is not travel (the third bucket) ----
{
  const { isSpeechAct, isRemoteContact } = await import("../engine/intent.js");
  const ERIK = "Take the opportunity to update Warden Coll on the status of the Water crisis and new warden stations.";
  check("CCODE-159 THE BUG: a light-verb wrapper no longer hides the governing verb", isSpeechAct(ERIK) === true);
  // ⚠️ RED BY CONSTRUCTION — the pre-fix belt, rebuilt here, on the same sentence. It read "Take" as the
  // governing verb and had no remote verbs at all, so it returned false and the turn became travel.
  const OLD_SPEECH = /^\s*(?:i(?:'?ll|'?m|'?d| will| am| would)?\s+(?:want to |going to |plan to |mean to |need to )?|let'?s\s+|we(?:'?ll| will)?\s+)?(announc\w*|tell\w*|say|saying|said|speak\w*|talk\w*|confid\w*|discuss\w*|propos\w*|promis\w*|mention\w*|explain\w*|suggest\w*|reassur\w*|admit\w*|confess\w*|declar\w*|inform\w*|warn\w*|ask|asking|asks|chat\w*|whisper\w*|shar\w*)\b/i;
  check("CCODE-159: the gate goes RED on the pre-fix belt (it read \"Take\" and missed \"update\" entirely)", OLD_SPEECH.test(ERIK.trim()) === false);
  check("CCODE-159: the remote half of the verb list is present", ["write to Coll", "send word to Mara", "brief the council", "report what I found", "relay the news"].every(s => isSpeechAct(s) === true));
  check("CCODE-159: a real departure is STILL a departure (the anchor was right, only blind)", ["head to the edge district", "travel to Millbrook", "walk to the mill and write to Coll"].every(s => isSpeechAct(s) === false));
  check("CCODE-159: the governing verb still wins — going somewhere and talking there is going", isSpeechAct("go to Millbrook and tell Pell the news") === false);
  check("CCODE-159: a named CHANNEL is remote contact", ["write to Coll on my shadow tablet", "send word to Mara by bird", "put it on the shadow-slate", "get word to Fendt via the relay"].every(s => isRemoteContact(s) === true));
  check("CCODE-159: ordinary travel is not remote contact", ["walk to the mill", "head south at dawn", "take the road to Cairnhold"].every(s => isRemoteContact(s) === false));
  const appSrc425 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-159: travelIntentOf suppresses a travelTo on a remote contact — unless real travel is also named", /isRemoteContact\(contactText\) && !TRAVEL_PHRASE\.test\(contactText\)/.test(appSrc425));
  const gmSrc425 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-159: the intent parser is TOLD the third case exists (a slate is not a road)", /REACHING SOMEONE WHO IS ELSEWHERE IS NOT TRAVEL/.test(gmSrc425) && /shadow-slates/.test(gmSrc425) && /light wrapper in front of the real verb/.test(gmSrc425));
}

// ---- CCODE-160: scene state is authoritative about the SITUATION, never about WHO SOMEONE IS ----
{
  const { reconcileSceneIdentity, sceneIdentityNote, sanitizeScene: sc426 } = await import("../engine/gm.js");
  const ERIK_SETTING = "Warden Coll's office in the Edge District warden post—stone walls, afternoon light through a high window. Coll behind her desk, Silas standing across from her with the shadow-sheet still in hand.";
  const reg426 = { coll: { id: "coll", name: "Warden Coll", gender: "man", pronouns: "he/him" } };
  check("CCODE-160: the defect is real and present in the input (else this gate proves nothing)", /\bher desk\b/.test(ERIK_SETTING) && /across from her\b/.test(ERIK_SETTING));
  const r426 = reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [{ name: "Warden Coll", state: "seated behind her desk, pen down" }], objects: [], threads: [] }, reg426);
  check("CCODE-160 THE BUG: the possessive is repaired against the record — 'her desk' → 'his desk'", /\bhis desk\b/.test(r426.scene.setting) && !/\bher desk\b/.test(r426.scene.setting));
  check("CCODE-160: the OBJECT form is repaired differently — 'across from her with' → 'from him with'", /across from him with\b/.test(r426.scene.setting));
  check("CCODE-160: the fix reaches every prose field, not just the setting", /\bhis desk\b/.test(r426.scene.npcsPresent[0].state));
  check("CCODE-160: it REPORTS what it repaired (a silent repair is an invisible bug)", r426.repaired.length >= 2 && r426.repaired.every(x => x.name === "Warden Coll"));
  // ⚠️ RED BY CONSTRUCTION: with the identity record absent, there is nothing to reconcile against and
  // the wrong pronoun survives — which is exactly the state the game shipped in.
  check("CCODE-160: the gate goes RED with no record to reconcile against (the pre-fix state)", /\bher desk\b/.test(reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [], objects: [], threads: [] }, {}).scene.setting));
  check("CCODE-160: an UNKNOWN pronoun is left alone — it repairs against a record, it does not guess", /\bher desk\b/.test(reconcileSceneIdentity({ setting: ERIK_SETTING, npcsPresent: [], objects: [], threads: [] }, { coll: { name: "Warden Coll" } }).scene.setting));
  // conservative by construction: two registered people in one sentence cannot be disambiguated
  const amb = reconcileSceneIdentity({ setting: "Coll behind her desk, Pell at the door with her hand on the frame.", npcsPresent: [], objects: [], threads: [] },
    { coll: { name: "Warden Coll", pronouns: "he/him" }, pell: { name: "Pell Ran Marsh", pronouns: "she/her" } });
  check("CCODE-160: it DECLINES an ambiguous string rather than guessing which 'her' is whose", amb.scene.setting.includes("Coll behind her desk") && amb.repaired.length === 0);
  check("CCODE-160: a they/them person is never rewritten (no mangled verb agreement)", reconcileSceneIdentity({ setting: "Ash behind her desk.", npcsPresent: [], objects: [], threads: [] }, { ash: { name: "Ash", pronouns: "they/them" } }).repaired.length === 0);
  check("CCODE-160: the note carries the record's own pronouns INTO the authoritative block", /Warden Coll is man, he\/him/.test(sceneIdentityNote({ npcsPresent: [{ name: "Warden Coll" }] }, reg426)));
  check("CCODE-160: reconcile survives a sanitizeScene round-trip and garbage input", reconcileSceneIdentity(sc426({ setting: ERIK_SETTING }), reg426).repaired.length >= 1 && reconcileSceneIdentity(null, reg426).scene === null);
  const gmSrc426 = readFileSync(join(root, "engine/gm.js"), "utf8");
  check("CCODE-160: the block no longer claims authority over identity, and says the record wins", /AUTHORITATIVE about the SITUATION/.test(gmSrc426) && /NOT authoritative about WHO ANYONE IS/.test(gmSrc426) && /the record is right and this text is a slip/.test(gmSrc426));
  check("CCODE-160: the render path reconciles before serving (heals a save already wedged)", /reconcileSceneIdentity\(sceneState, character\?\.npcRegistry/.test(gmSrc426));
  const appSrc426 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-160: and the WRITE path reconciles too, so the save stops carrying the error", /const rec = reconcileSceneIdentity\(sceneClean, character\.npcRegistry/.test(appSrc426));
  const corrSrc426 = readFileSync(join(root, "engine/corrections.js"), "utf8");
  check("CCODE-160: the one authoritative block finally has a repair op", /case "correctSceneState"/.test(corrSrc426));
  const cs = { activeScene: { sceneState: { setting: "Warden Coll's office.", threads: ["x"] } }, corrections: [] };
  const rr = applyStateOps(cs, [{ op: "correctSceneState", setting: "The ridge Threshold Post, afternoon.", why: "he never left the ridge" }], {});
  check("CCODE-160: correctSceneState rewrites the anchor and logs it", rr.applied.length === 1 && cs.activeScene.sceneState.setting === "The ridge Threshold Post, afternoon." && cs.corrections.some(x => x.kind === "sceneState"));
  // ⚠️ the empty-anchor guard must be tested WITH threads present, or the "needs setting and/or threads"
  // guard behind it absorbs the case and the first guard is never actually exercised (it did, at first).
  check("CCODE-160: it refuses an empty anchor and a no-op ask (a scene with no anchor is worse than a wrong one)",
    applyStateOps(cs, [{ op: "correctSceneState", setting: "   ", threads: ["still open"] }], {}).refused.length === 1
    && applyStateOps(cs, [{ op: "correctSceneState", setting: "   " }], {}).refused.length === 1
    && applyStateOps(cs, [{ op: "correctSceneState" }], {}).refused.length === 1);
  check("CCODE-160: it refuses when there is no active scene to repair", applyStateOps({ corrections: [] }, [{ op: "correctSceneState", setting: "somewhere" }], {}).refused.length === 1);
}

// ---- CCODE-161: the Shadow Tablet is a real object, under all the names people say for it ----
// Erik's ruling: the object is the Shadow Tablet; "shadow sheet" and "shadow slate" are alternates for
// the same thing. It was made in play and never emitted, so it lived as prose in two NPC records under
// two different names — and the intent parser, handed the inventory as the character's affordances,
// could not see the one thing that made "write to Coll" possible.
{
  const { reclaimEstablishedItems, resolveInventoryItem, normalizeInventory: norm427, fromCatalog: fc427 } = await import("../engine/inventory.js");
  const pack427 = JSON.parse(readFileSync(join(root, "content/packs/valley/items/shadow_tablet.json"), "utf8"));
  const cat427 = Object.fromEntries(pack427.items.map(i => [i.id, i]));
  const tablet = cat427.shadow_tablet;
  check("CCODE-161: the object is authored, canonically named, and carries Erik's alternates", tablet.name === "Shadow Tablet" && ["Shadow Sheet", "Shadow Slate"].every(a => (tablet.aliases || []).includes(a)));
  check("CCODE-161: it is registered in the pack manifest (an unlisted file is not content)", JSON.parse(readFileSync(join(root, "content/packs/valley/manifest.json"), "utf8")).provides.items.includes("items/shadow_tablet.json"));

  // THE BUG: authored aliases were dropped on the way into inventory — a writer with no reader.
  check("CCODE-161 THE BUG: fromCatalog carries authored aliases through to the instance", (fc427(tablet).aliases || []).includes("Shadow Slate"));
  check("CCODE-161: an item with no aliases gains no empty field (the shape stays clean)", !("aliases" in fc427({ id: "x", name: "Rock", kind: "misc" })));

  // the whole point of the alternates: a later mention under another name must not fork a second item
  const holder = { inventory: [fc427(tablet)] };
  check("CCODE-161: every name Erik allows collapses onto the ONE object", ["shadow sheet", "Shadow Slate", "shadow-sheet", "my shadow tablet"].every(s => resolveInventoryItem(holder, s, cat427)?.id === "shadow_tablet"));
  check("CCODE-161: a save holding an ALTERNATE as a bare string re-links to the real item", (() => { const d = { inventory: ["Shadow Slate"] }; norm427(d, cat427); return d.inventory[0].id === "shadow_tablet" && d.inventory[0].kind === "focus"; })());

  // the reclaim — trace-gated, and proved against Silas's ACTUAL save, not a fixture
  const silas = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
  check("CCODE-161: the defect is real in the live save (else this gate proves nothing)", !(silas.inventory || []).some(i => /shadow/i.test(i.name || "")) && JSON.stringify(silas.npcRegistry).toLowerCase().includes("shadow-slate"));
  const got = reclaimEstablishedItems(silas, cat427);
  check("CCODE-161 THE FIX: the trace in his own record gives the tablet back", got.length === 1 && got[0].id === "shadow_tablet" && !!got[0].trace);
  const held = (silas.inventory || []).find(i => i.id === "shadow_tablet");
  check("CCODE-161: and it arrives WHOLE — catalog kind, description and aliases, not a hollow stub", held && held.kind === "focus" && !!held.description && (held.aliases || []).includes("Shadow Sheet"));
  check("CCODE-161: idempotent — a second pass grants nothing", reclaimEstablishedItems(silas, cat427).length === 0);
  // ⚠️ the already-held check ALSO makes a second pass empty, so it masks the version flag entirely. The
  // case only the flag can answer: the player DROPS the thing. Without the flag it comes back on every
  // load — an item you threw away returning forever, which is the engine overruling the player.
  check("CCODE-161: an item the player DROPPED stays dropped (only the version flag can hold this)", (() => {
    const dropped = { ...silas, inventory: (silas.inventory || []).filter(i => i.id !== "shadow_tablet") };
    return reclaimEstablishedItems(dropped, cat427).length === 0;
  })());
  // ⚠️ REPAIR, NOT WISH: no trace in the record, no item. This is the line that keeps the pass honest.
  check("CCODE-161: a character whose story never had one gets NOTHING", reclaimEstablishedItems({ inventory: [], chronicle: ["walked to the mill"], npcRegistry: {} }, cat427).length === 0);
  check("CCODE-161: an item with no establishedBy block is never reclaimed by this pass", reclaimEstablishedItems({ inventory: [], chronicle: ["I carry a marcher blade everywhere"], npcRegistry: {} }, { marcher_blade: { id: "marcher_blade", name: "Marcher's Blade" } }).length === 0);
  // ⚠️ it must NOT ride the XP backfill's version — that would re-credit experience to every character
  const invSrc427 = readFileSync(join(root, "engine/inventory.js"), "utf8");
  // the invariant is about the XP backfill's version, not about the word appearing in a comment —
  // my first assertion failed on my own explanatory note, which is a checker being wrong, not the code.
  const bfSrc427 = readFileSync(join(root, "engine/backfill.js"), "utf8");
  check("CCODE-161: the reclaim has its OWN version flag, and the XP backfill's is untouched (a repair must not ride a wish's version number)",
    /ITEM_RECLAIM_VERSION/.test(invSrc427) && /itemReclaimVersion/.test(invSrc427)
    && /export const BACKFILL_VERSION = 1;/.test(bfSrc427) && !/reclaimEstablishedItems/.test(bfSrc427));
  const appSrc427 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-161: it runs on load and SAYS SO (a silent grant is indistinguishable from a bug)", /reclaimEstablishedItems\(c, CONTENT\.items\)/.test(appSrc427) && /the story gave you this and the ledger missed it/.test(appSrc427));
  const intentSrc427 = readFileSync(join(root, "engine/intent.js"), "utf8");
  check("CCODE-161: all three names are recognised as a remote channel (CCODE-159 agrees with the ruling)", /shadow\[-\\s\]\?\(\?:slate\|sheet\|tablet\)/.test(intentSrc427));
}

// ---- SNG-401: draw an NPC's picture again, WITHOUT destroying the one they have ----
// Aevi's spec, and §3 is the load-bearing rule: "a regenerate that silently replaces a face the player
// had grown used to is worse than no button. The player asked for another try, not for the old one to
// be deleted."
{
  const { regenerateImage, acceptImage, isGeneratedImage, setArtMode, addGalleryImage: addG401 } = await import("../engine/art.js");
  const artWas = localStorage.getItem("singularity.artMode");
  setArtMode("generate");
  const pell = () => ({ id: "pell", name: "Pell Ran Marsh", description: "a village blacksmith, file in hand", image: "ORIGINAL", relationship: 10 });

  // §3 — THE RULE. The record must be untouched by a draw.
  const p1 = pell();
  const drawn = regenerateImage(p1, "npc", { ratingLevel: 2, attempt: 1 });
  check("401 §3 THE RULE: a draw does NOT touch the record (the old face survives)", p1.image === "ORIGINAL" && !p1.imagePinned && !p1.imageSeedKey);
  check("401: …and it returns a real, different picture to look at beside it", !!drawn?.url && drawn.url !== "ORIGINAL" && /image\.pollinations/.test(drawn.url));

  // §2 — a re-roll is the SAME prompt with a NEW seed. Same seed would redraw the same face.
  const d2 = regenerateImage(pell(), "npc", { ratingLevel: 2, attempt: 2 });
  check("401 §2: same prompt, DIFFERENT seed — two attempts are two pictures", drawn.prompt === d2.prompt && drawn.url !== d2.url && drawn.seedKey !== d2.seedKey);
  check("401: attempt keys do not compound across re-rolls (r1 → r2, never r1#r2)", /#r2$/.test(d2.seedKey) && !/#r\d+#r/.test(regenerateImage({ ...pell(), imageSeedKey: drawn.seedKey }, "npc", { attempt: 3 }).seedKey));

  // §4 — THE FLOORS. A re-roll is not a way around the content ceiling, and minor-safety is absolute.
  const kid = { id: "wren", name: "Wren", description: "a child of the mill", isMinor: true };
  const kidDraw = regenerateImage(kid, "npc", { ratingLevel: 4, attempt: 1 });
  check("401 §4: minor-safety runs on a re-roll exactly as on a first mint", /child-safe|wholesome|no sexual/i.test(decodeURIComponent(kidDraw.url)));
  const gLow = regenerateImage(pell(), "npc", { ratingLevel: 0, attempt: 1 });
  const gHigh = regenerateImage(pell(), "npc", { ratingLevel: 4, attempt: 1 });
  check("401 §4: the viewer's ceiling still shapes the prompt (a re-roll cannot climb it)", decodeURIComponent(gLow.url).includes("family-friendly") && !decodeURIComponent(gHigh.url).includes("family-friendly"));

  // §3 "on accept" — NOW it lands, and the seed is remembered so the face stays stable.
  const p3 = pell();
  const ok = acceptImage(p3, { url: drawn.url, seedKey: drawn.seedKey });
  check("401 §3 on accept: the chosen picture becomes theirs and its seed is kept", ok && p3.image === drawn.url && p3.imageSeedKey === drawn.seedKey);
  check("401: accepting PINS — a chosen face is not re-drawn behind the player's back", p3.imagePinned === true);
  check("401: accept refuses an empty pick rather than blanking the record", acceptImage(p3, {}) === false && p3.image === drawn.url);

  // the pin has to be READ, or it is decoration. This is the bond-milestone pass's own guard.
  const appSrc401 = readFileSync(join(root, "app.js"), "utf8");
  check("401: the bond-portrait pass HONOURS the pin (else keeping buys you one milestone)", /if \(n\.imagePinned\) \{ n\._portraitTier = tier; continue; \}/.test(appSrc401));

  // §1 — provenance. Without it a button "can only re-fetch the same URL".
  const c401 = { gallery: [] };
  addG401(c401, { kind: "portrait", url: "u1", caption: "Pell Ran Marsh — devoted", subjectKind: "npc", subjectId: "pell" });
  addG401(c401, { kind: "moment", url: "u2", caption: "a moment" });
  const tileOf = u => c401.gallery.find(g => g.url === u);
  check("401 §1: a gallery tile now records WHOSE face it is", tileOf("u1").subjectId === "pell" && tileOf("u1").subjectKind === "npc");
  check("401 §1: a tile with no subject gains no empty fields (additive — old entries still work)", !("subjectId" in tileOf("u2")) && !("subjectKind" in tileOf("u2")));
  check("401 §1: the prompt is NOT stuffed into a DOM attribute (Aevi: they are long and spoiler-bearing)", !/data-regen-prompt/.test(appSrc401));
  check("401 §1: the lightbox carries provenance per item and the gallery path supplies it", /regen: galleryRegenFor\(g\)/.test(appSrc401) && /function galleryRegenFor/.test(appSrc401));
  // ⚠️ CORRECTED BY CCODE-166. I gated "EXACT, never fuzzy" — and exact was WRONG: it failed on "Cevaine of
  // the Seventh Measure" against a registry that says "Cevaine", so a real portrait of a known person had
  // no controls. What this gate was actually protecting is that a near-miss must never redraw the wrong
  // person, and that survives `namesMatch`, which needs a substantial whole-word hit. Aimed at the
  // property now instead of at one implementation of it.
  check("401/166: the caption fallback is CONSERVATIVE — a fuller name resolves, a vague description does not",
    /namesMatch\(n\.name, nm\)/.test(appSrc401));

  // §1 ACROSS THE WHOLE SURFACE — Aevi counted eight call sites, "all pass the same two fields".
  for (const [site, re] of [
    ["location banner", /data-lightbox="location" data-regen-kind="location" data-regen-subject=/],
    ["craft art", /data-lightbox="\$\{esc\(selImg\)\}" data-regen-kind="ability" data-regen-subject=/],
    ["braid moment", /class="braid-moment-art"[^`]*data-regen-kind="ability"/],
    ["item examine", /data-lightbox="item" data-regen-kind="item" data-regen-subject=/],
    ["moment art", /data-lightbox="moment" data-regen-kind="moment"/],
    ["character portrait", /data-lightbox="portrait" data-regen-kind="character"/]
  ]) check(`401 §1: the ${site} carries its provenance`, re.test(appSrc401));
  check("401 §1: the delegated handler reads the provenance off the img (no eight signatures changed)", /img\.dataset\.regenKind/.test(appSrc401) && /img\.dataset\.regenSubject/.test(appSrc401));
  check("401 §1: the FEED image is deliberately NOT regenerable — it is someone else's moment", /data-lightbox="feed"(?![^>]*data-regen-kind)/.test(appSrc401));

  // §2 THE SECOND BUTTON. Aevi: a re-roll on a wrong COMPOSITION returns the same wrong composition.
  check("401 §2: there is a REBUILD as well as a re-roll, and it takes new words", /data-lbrebuild/.test(appSrc401) && /Describe .* differently/.test(appSrc401) && /regenLightboxItem\(it, \+\+attempts, said\.trim\(\)\)/.test(appSrc401));
  check("401 §2: rebuild is hidden on an AUTHORED image (re-describing would discard the authoring)", /const canRebuild = canRegen && isGeneratedImage\(it\.url\)/.test(appSrc401));
  check("401 §2: an authored path is told from a generated one by where it came from", isGeneratedImage("https://image.pollinations.ai/prompt/x") && !isGeneratedImage("content/packs/valley/assets/thornmother.png") && !isGeneratedImage(""));
  const rebuilt = regenerateImage(pell(), "npc", { ratingLevel: 2, attempt: 1, promptOverride: "a grey-haired smith at an anvil, soot on her forearms" });
  check("401 §2: a rebuild draws from the NEW words, not the record's own description", decodeURIComponent(rebuilt.url).includes("soot on her forearms") && !decodeURIComponent(rebuilt.url).includes("file in hand"));
  check("401 §2: …and the floors still run on the player's own words", decodeURIComponent(regenerateImage(pell(), "npc", { ratingLevel: 0, attempt: 1, promptOverride: "an erotic nude portrait" }).url).match(/erotic|nude/) === null);
  check("401 §2: a rebuild with no record at all still draws (a moment has no record, only words)", !!regenerateImage(null, "moment", { promptOverride: "the seam sealed at dawn" })?.url);
  check("401: nothing to draw from is refused rather than guessed", regenerateImage(null, "moment", {}) === null);

  // the kind table — one place that knows where each subject is read from and kept
  check("401: every regenerable kind declares BOTH how to find it and where a kept image lands", /const REGEN_KINDS = \{/.test(appSrc401)
    && ["npc", "character", "location", "item", "ability", "moment", "beast"].every(k => new RegExp(`\\b${k}: \\{`).test(appSrc401.slice(appSrc401.indexOf("const REGEN_KINDS")))) );
  check("401: an UNKNOWN kind yields no button rather than a guess", /const spec = REGEN_KINDS\[regen\.kind\];\s*\n\s*if \(!spec\) return null;/.test(appSrc401));
  check("401: a record-less kind is legitimate, not an error (the gallery tile IS its record)", /A null record is legitimate/.test(appSrc401));

  // §3 in the UI — append, never replace. This is the line that would undo the whole spec.
  // ⚠️ RE-AIMED (CCODE-172). It pinned `list.push`, and a draw is now INSERTED beside its source instead of
  // at the end — a better answer to the same requirement. The property is unchanged and is what it asserts:
  // the old picture is never overwritten, only added to.
  check("401 §3/172: a new draw is ADDED to the list, never written over the current item",
    /list\.splice\(i \+ 1, 0, drawn\);/.test(appSrc401) && !/list\[i\] = drawn/.test(appSrc401));
  check("401 §3: Keep shows only on a draw the player made, not on the picture they already had", /const isNewDraw = !!it\.regen && !!it\.isDraw;/.test(appSrc401));
  check("401 §4: the button is disabled in flight, shows work, and NAMES a failure", /regenBtn\.disabled = true; regenBtn\.textContent = "…drawing"/.test(appSrc401) && /couldn't draw/.test(appSrc401) && /didn't come through/.test(appSrc401));
  check("401 §5: there is a direct way in from the people list, only when a picture exists", /data-repic=/.test(appSrc401) && /\?\.\[p\.id\]\?\.image \?/.test(appSrc401));
  check("401: art OFF means no draw at all (generation is the on-switch, honoured here too)", (() => { setArtMode("off"); const r = regenerateImage(pell(), "npc", {}); setArtMode("generate"); return r === null; })());

  // ⛔ FOUND WHILE MUTATING SNG-401 — A PRE-EXISTING HOLE, NOT A NEW ONE. Deleting the FLOORS call from
  // `ensureImage` — the path every FIRST image in the game takes — left all ~3400 checks green. The rating
  // ceiling and minor-protection on the primary image path were entirely ungated; only the re-roll I had
  // just written was covered. A safety floor nobody tests is a safety floor that can be removed by accident.
  {
    const kidRec = { id: "wren2", name: "Wren", role: "a child of the mill", isMinor: true };
    ensureImage(kidRec, "npc", { ratingLevel: 4 });
    check("035/401: ensureImage runs the FLOORS — minor-protection on a first mint", /child-safe|wholesome/i.test(decodeURIComponent(kidRec.image || "")));
    const adultG = { id: "a1", name: "Roth", role: "a soldier, blood on his hands" };
    ensureImage(adultG, "npc", { ratingLevel: 0 });
    check("035/401: ensureImage runs the FLOORS — the viewer's ceiling on a first mint", (() => { const u = decodeURIComponent(adultG.image || ""); return u.includes("family-friendly") && !/\bblood\b/.test(u); })());
    const tail = { id: "t1", name: "Anyone", role: "a traveller" };
    ensureImage(tail, "npc", { ratingLevel: 2 });
    check("035/401/176/182: …and the ceiling rides every first mint that HAS one", /mild peril, no gore/.test(decodeURIComponent(tail.image || "")));
  }
  check("401: the prompt lookup is keyed off the DOM, not stored in it", /const _regenPrompts = new Map\(\)/.test(appSrc401) && /notePromptFor\(url, moment\.prompt\)/.test(appSrc401));
  if (artWas) localStorage.setItem("singularity.artMode", artWas);
}

// ---- SNG-400/400b: the death news carries its facts, and the battle image is BUILT ----
{
  const { buildBattlePrompt, battleKey, figureLook, powerPhrase } = await import("../engine/battleprompt.js");
  const { stampNews, clashNewsItem, applyEpicClashOutcome: applyClash400 } = await import("../engine/worldtick.js");

  // §1 THE BLOCKER. Aevi: "No victimId. No killerId. No locationId. A sentence, and a tier."
  const flat = stampNews("Word reaches you: Veln Ashpause was killed.", { worldDay: 32 });
  check("400 §1: an ordinary line is unchanged (additive — every existing caller untouched)", flat.text.length > 0 && !("victimId" in flat) && !("kind" in flat));
  const rich = stampNews({ text: "A legend has fallen.", kind: "death", victimId: "neth_the_stayed", killerId: "morvane_the_harvest", arcId: "arc_what_wakes_beneath" }, { worldDay: 32 });
  check("400 §1 THE FIX: the facts survive the news builder that used to drop them", rich.kind === "death" && rich.victimId === "neth_the_stayed" && rich.killerId === "morvane_the_harvest" && rich.arcId === "arc_what_wakes_beneath" && rich.worldDay === 32);
  check("400 §1: clashNewsItem carries a string line AND an object line (an object wrapped as {text} becomes '[object Object]')",
    clashNewsItem("X bested Y", { worldDay: 3 }).text === "X bested Y"
    && clashNewsItem({ text: "fell", kind: "death", victimId: "v" }, { worldDay: 3, arcId: "a1" }).victimId === "v"
    && !/\[object Object\]/.test(String(clashNewsItem({ text: "fell", victimId: "v" }, {}).text)));
  const wtSrc400 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
  // ⛔ SNG-433 — THIS WAS A SOURCE REGEX PINNED TO `text: event.text`, AND IT WENT RED THE MOMENT THE NEWS
  // LINE CAME FROM AEVI'S TEMPLATES INSTEAD OF THE ENGINE'S OWN SENTENCE. The claim was never about which
  // words the item carries; it is that a DEATH NEWS ITEM CARRIES ITS IDS, so the player can click it back
  // into the fight. Asserted behaviourally now — the prose is free to change and the contract is not.
  {
    const kNews = (applyClash400({}, { id: "w400", name: "W" }, { id: "l400", name: "L" }, "killed", 40).news || [])
      .find(n => n.kind === "death");
    check("400 §1: the death is emitted WITH its ids at the source, not just in the propagated event",
      !!kNews && kNews.victimId === "l400" && kNews.killerId === "w400" && !!String(kNews.text || "").trim(),
      JSON.stringify(kNews || null));
  }
  // ⛔ SNG-431 §3 — THE NUMBER IN THIS GATE ENCODED THE BUG. It asserted exactly 3 while its own sentence
  // says EVERY site, and there are FOUR places that resolve a clash: the arc fight, the strike, the
  // challenge, and the narrated stir. The fourth wrapped `{ text: line }` around the object — which is the
  // "[object Object]" failure `clashNewsItem`'s own header warns about, latent there for every death.
  // ⚠️ So it is a CENSUS now: as many shapings as there are outcomes to shape. A count that has to be
  // hand-updated when a site is added is a count that will be left behind by the next one.
  {
    // …minus the declaration itself, which matches the same call shape.
    const applies = (wtSrc400.match(/(?<!export function )applyEpicClashOutcome\(ws,/g) || []).length;
    const shapings = (wtSrc400.match(/news\.push\(clashNewsItem\(line,/g) || []).length;
    check("400 §1: every clash site emits through the one shaping",
      applies === 4 && shapings === applies, `${applies} clash sites, ${shapings} shaped emissions`);
  }
  check("400: a CHALLENGE carries no arcId — it is deliberately not part of an arc", /a challenge is NOT part of an arc[\s\S]{0,400}clashNewsItem\(line, \{ worldDay: currentWorldDay \}\)/.test(wtSrc400));

  // §3 THE BUILD — real figures from the shipped roster, not fixtures
  const epics400 = JSON.parse(readFileSync(join(root, "content/packs/valley/tradition_epics.json"), "utf8")).epics;
  const neth = epics400.find(f => f.id === "neth_the_stayed");
  const morvane = epics400.find(f => f.id === "morvane_the_harvest");
  check("400b: the roster carries the builder's INPUTS on all 66 (appearance + fightingStyle)", epics400.length === 66 && epics400.every(f => f.appearance && f.fightingStyle));
  check("400b: …and they had no reader before this (the writer-with-no-reader Aevi flagged)", !!neth && !!morvane);
  const built = buildBattlePrompt({ victim: morvane, killer: neth, place: "the braided confluence", depth: 0 });

  // ⛔ THE POINT OF THE WHOLE TICKET: a list with a conjunction in it is not a picture.
  check("400b §1 THE FAILURE IT REPLACES: the output is NOT the two presences joined by 'AGAINST'", !/\bAGAINST\b/i.test(built.prompt));
  check("400b §3: the POWER leads — it is the subject of the image, not decoration", built.prompt.toLowerCase().indexOf(String(neth.fightingStyle).slice(0, 12).toLowerCase()) === 0);
  check("400b: both figures are IN it, and in one relation rather than two descriptions", /standing over/.test(built.prompt) && /falling/.test(built.prompt) && built.prompt.includes("braided confluence"));
  check("400b §3: SHORT is the requirement — a long prompt averages into a generic picture", built.prompt.length <= 340);
  check("400b: it is a battle, sized as one", built.kind === "battle");

  // ⛔ §2a — THE FAILURE THAT KEEPS COMING BACK, AND THE CENSUS THAT CATCHES IT. Aevi's first version made
  // "the two people most likely to kill each other render as one person fighting a mirror." My first
  // version did it again by stripping the role, and my second still mirrored 2 of 5 rival pairs. This is a
  // census, not a sentence: every killer distinct, and EVERY authored rival pair distinct in both directions.
  const shots = epics400.map(f => buildBattlePrompt({ victim: morvane, killer: f, place: "x" }).prompt);
  check("400b §2a: all 66 killers give 66 different pictures", new Set(shots).size === 66);
  const rivalPairs = epics400.filter(f => (f.rivals || []).length)
    .map(f => [f, epics400.find(x => x.id === f.rivals[0])]).filter(([, r]) => r);
  const mirrored = rivalPairs.filter(([a, b]) => buildBattlePrompt({ victim: b, killer: a }).prompt === buildBattlePrompt({ victim: a, killer: b }).prompt);
  check(`400b §2a: not one of ${rivalPairs.length} authored rival pairs renders as a mirror`, rivalPairs.length >= 50 && mirrored.length === 0);
  check("400b §2a: it individuates from the ONE field that is 66/66 distinct (Aevi's own answer)", (() => {
    const stripped = epics400.map(f => buildBattlePrompt({ victim: morvane, killer: { ...f, offscreenVerbs: [], personalVerbs: [] }, place: "x" }).prompt);
    return new Set(stripped).size < 66;   // remove it and the collisions come straight back
  })());
  check("400b: a prompt never ends on a dangling fragment (a truncated clause is drawn as detail)", shots.every(s => !s.includes("…")) && Math.max(...shots.map(s => s.length)) <= 400);
  check("400b: the ABILITY, when there is one, outranks the fighting style — the power actually used",
    powerPhrase({ name: "The Cut Thread", shape: "a single severing motion", effectTags: ["sever"], description: "ends without wounding" }, neth).startsWith("The Cut Thread"));
  check("400b: with no ability it falls back to the killer's authored style, never to nothing", powerPhrase(null, neth).length > 5 && powerPhrase(null, {}) === "a killing blow");
  check("400b: a figure reduces to a LOOK and a MOTION, not a biography", (() => { const l = figureLook(neth); return l.look.length <= 160 && l.motion.length <= 70 && l.name === neth.name; })());
  // ⚠️ ITS OWN GATE, because it is no longer load-bearing for DISTINCTNESS and would otherwise be
  // droppable in silence. Once the per-person verb landed, removing the role stopped collapsing anything
  // — but "master ashwarden" vs "reaper ashwarden" is real information about what the picture shows, and
  // a thing that is only valuable and not load-bearing is exactly the thing a refactor deletes.
  check("400b: the role + tradition survive the trim (a master and a reaper are different pictures)", (() => {
    const a = figureLook(neth).look, b = figureLook(morvane).look;
    return /master/.test(a) && /ashwarden/.test(a) && /reaper/.test(b) && a !== b;
  })());
  check("400b: figureLook survives a null figure rather than throwing mid-build", (() => { try { return figureLook(null).name === "someone"; } catch { return false; } })());

  // §4 THE FALLBACK — "there is no illness in this game"; the real fallback is a death with no named killer
  const lone = buildBattlePrompt({ victim: neth, killer: null, place: "the ridge", depth: 2 });
  check("400b §4: no killer → ONE figure, and it prefers the authored deathImagePrompt", lone.kind === "death" && lone.prompt.includes(String(neth.deathImagePrompt).slice(0, 25)));
  check("400b §4: …and it invents no opponent", !/standing over|falling/.test(lone.prompt));
  check("400b: how deep the ending ran changes the picture", buildBattlePrompt({ victim: morvane, killer: neth, depth: 0 }).prompt !== buildBattlePrompt({ victim: morvane, killer: neth, depth: 2 }).prompt);

  // §3 CACHING — "a re-rolling battle quietly says it was a different fight"
  const k1 = battleKey({ victimId: "a", killerId: "b", abilityId: null, worldDay: 32 });
  check("400b §3: the cache key is victim|killer|ability|worldDay", k1 === "a|b|-|32" && battleKey({}) === "?|-|-|?");
  check("400b: the same fight keys the same forever; a different day is a different fight", k1 === battleKey({ victimId: "a", killerId: "b", worldDay: 32 }) && k1 !== battleKey({ victimId: "a", killerId: "b", worldDay: 33 }));

  // the reader — Aevi: "without ids there is nothing to click"
  const appSrc400 = readFileSync(join(root, "app.js"), "utf8");
  check("400 §3.2: a death news item is CLICKABLE and opens the battle", /data-battlenews=/.test(appSrc400) && /function battleImageFor/.test(appSrc400));
  // ⚠️ SNG-431 §3 widened this to every clash, so the shape it asserts moved. The CLAIM is unchanged and is
  // the load-bearing half: a control is offered only when the figures are on the roster and art is on —
  // "a control that opens nothing is worse than a line of prose".
  check("400 §3.2: …only when it is genuinely openable (a control that opens nothing is worse than prose)",
    /const known = \(id\) => !!id && roster188\.some\(f => f\.id === id\);/.test(appSrc400)
    && /const roster188 = worldRoster\(character\.worldState \|\| \{\}, CONTENT\) \|\| \[\];/.test(appSrc400)
    && /const canSee = \(n\) => imagesEnabled\(\) && \(/.test(appSrc400)
    && /\(n\?\.kind === "death" && known\(n\.victimId\)\)/.test(appSrc400));
  // ⛔ SNG-431 §3: and the other three outcomes are the ones Erik actually sees.
  check("431/3: a wounded, checked or stalemated fight is clickable too — not only a death",
    /\(n\?\.kind === "clash" && known\(n\.winnerId\) && known\(n\.loserId\)\)\);/.test(appSrc400)
    && /if \(!isDeath && !\(item\.kind === "clash" && outcome\)\) return null;/.test(appSrc400));
  // ⚠️ THE OUTCOME IS IN THE CACHE KEY, or two fights between the same pair share one picture.
  // ⛔ CCODE-188 (Erik): "there's no link to click on the 'bested' to see the scene where those two
  // fought." The lines already in his log predate the ids and would never carry them, so a fix that only
  // helps future fights leaves every fight he can currently see dead on the page. Recovered from the
  // ENGINE'S OWN four templates — exact splits, whole-name `===` against the roster, null on any miss.
  // ⚠️ AND IT ASSERTS THE USE, NOT THE PRESENCE. Written as "the CLASH_SHAPES constant exists" it stayed
  // GREEN with the loop mutated to iterate an empty array — the table was still there and reached nothing.
  // That is the same shape as a registered-but-unloaded content file, one layer down, and it is the fifth
  // time this session a gate of mine has checked that something EXISTS rather than that it RUNS.
  check("CCODE-188: a fight recorded before the ids existed is still openable",
    /for \(const \[re, outcome\] of CLASH_SHAPES\) \{/.test(appSrc400)
    && /const n = raw\?\.kind \? raw : \(recovered\(raw\) \|\| raw\);/.test(appSrc400)
    && /const byName = \(nm\) => roster188\.find\(f => f\?\.name === nm\) \|\| null;/.test(appSrc400)
    && /if \(!w \|\| !l\) return null;/.test(appSrc400));
  // ⚠️ AND THE PATTERNS ARE THE ENGINE'S. A recovery regex that drifts from the template it parses is a
  // silent no-op, so it is checked against what `applyEpicClashOutcome` actually writes, not against itself.
  check("CCODE-188: …and the patterns still match what the engine writes, for all four outcomes", (() => {
    const A = { id: "w", name: "The Unbound", tier: "heroic", homeLocation: "a" };
    const B = { id: "l", name: "The Ender Who Forgot Why", tier: "heroic", homeLocation: "b" };
    const SHAPES = [
      [/^(.+?) bested (.+?) — .+ withdraws to lick their wounds\.$/, "wounded"],
      [/^(.+?) checked (.+?) — for now, .+ designs are held\.$/, "stopped"],
      [/^(.+?) and (.+?) met — and neither could break the other\.$/, "stalemate"],
      [/^A legend has fallen: (.+?) has killed (.+?)\. The world is one great figure lighter/, "killed"],
    ];
    return ["wounded", "stopped", "stalemate", "killed"].every(k => {
      const t = applyEpicClashOutcome({}, A, B, k, 10, {}).news[0].text;
      return SHAPES.some(([re, o]) => { const m = re.exec(t); return m && o === k && m[1] === A.name && m[2] === B.name; });
    });
  })());
  // ⛔ CCODE-188 (Erik, on the whois card for The Unbound): "this popup screen doesn't have a discard
  // button." A world figure's portrait is minted from a seed and never enters the gallery, so it had
  // neither a `meta` nor a second picture — the two things the old rule required.
  check("CCODE-188: the ONLY picture of a subject can be discarded — the card re-mints from the seed",
    /\|\| \(isGeneratedImage\(it\.url\) && !!it\.regen\?\.subjectId && !!spec\?\.keep\);/.test(appSrc400));

  check("431/3: the same pair meeting twice gets two pictures — the outcome is part of the key",
    /const key = battleKey\(\{ victimId: loserId, killerId: winnerId, abilityId: item\.abilityId, worldDay: item\.worldDay, outcome \}\);/.test(appSrc400));
  // …and the picture is not a killing when nobody died.
  check("431/3: the prompt frames what actually happened — a stalemate is not drawn as a death", (() => {
    const bp = { name: "A", appearance: "lean", fightingStyle: "fast" }, cp = { name: "B", appearance: "vast", fightingStyle: "slow" };
    const k = buildBattlePrompt({ victim: bp, killer: cp, place: "here", outcome: "killed" }).prompt;
    const st = buildBattlePrompt({ victim: bp, killer: cp, place: "here", outcome: "stalemate" }).prompt;
    return /standing over/.test(k) && /falling/.test(k) && /the moment of the ending/.test(k)
      && /locked against/.test(st) && !/falling/.test(st) && !/the moment of the ending/.test(st)
      && buildBattlePrompt({ victim: bp, killer: cp, outcome: "stalemate" }).kind === "battle";
  })());
  check("400b: the cache key IS the image seed, so stability is a property of the build", /imageURLFor\(built\.kind, safe, key\)/.test(appSrc400));
  // ⚠️ CCODE-190 moved what the floors are applied TO — the COMPOSED line, not the builder's raw list.
  // The claim is unchanged and is the load-bearing half: the floors run on whatever reaches the model.
  check("400b: the mint runs the FLOORS like every other image", /sanitizeImagePrompt\(composedOut\.prompt, \{ ratingLevel: viewerRatingLevel\(\), isMinor: isMinorSubject\(victim\) \}\)/.test(appSrc400));
  check("400b: an unknown figure yields no picture rather than a guessed one", /if \(!victim\) return null;/.test(appSrc400));
  // ⚠️ WINDOW WIDENED FOR CCODE-186, which gave `battle` a `current` and a fallback store — the entry grew
  // past 200 characters and this went red on a change that made it MORE capable, not less. A byte-window
  // around a code shape is a gate that fails on its own subject growing; the assertion is what it stores.
  check("400b × 401: the battle is re-rollable AND re-describable — the first real builder behind Rebuild",
    /battle: \{[\s\S]{0,700}character\.battleImages\[key\]\.url = url/.test(appSrc400));
  const artSrc400 = readFileSync(join(root, "engine/art.js"), "utf8");
  // ---- CCODE-189: author-directed text was reaching the image model ------------------------------------
  // ⛔ Measured on a live world: 35 of 385 abilities and 8 of 70 appearances carry ⛔/⚠️ markers or SHOUTING,
  // and all of it went into the picture. A real prompt opened "The Borne Bargain — reposition, ⚠️ ABYSSAL
  // ---- CCODE-190: code selects the parts, a model composes the line -----------------------------------
  // ⛔ Erik, on the measured numbers: "wire it. Do this for every image because i think it will be hugely
  // valuable." Across 269 real fights the deterministic builder produced a median of 14 comma clauses,
  // 268 of 269 with eight or more, and 248 repeating a word — "a list with a conjunction in it", the exact
  // failure battleprompt.js exists to replace, after two rounds of tuning its clamps.
  // ⚠️ EVERY CHECK HERE INJECTS ITS OWN `call`. No test spends Erik's API key.
  {
    const IP = await import("../engine/imageprompt.js");
    const LIST = "The Borne Bargain — reposition, sovereign abyssal, horned, dressed better than anyone "
      + "expects, closes a bargain that hollows someone, sovereign, bargain-marks lighting as they take, "
      + "locked against, investigator verist, nothing concealed, says the true thing no one wanted said, "
      + "neither of them breaking, at The Unblinking Stone";
    const ONE_LINE = "a horned figure in fine dress closing a bargain, bargain-marks lighting as they take, "
      + "locked against a plain-faced investigator, neither breaking, at the Unblinking Stone";

    let calls = 0;
    const call = async () => { calls++; return ONE_LINE; };
    const cache = {};
    const first = await IP.composeImagePrompt(LIST, { cache, kind: "battle", call });
    check("CCODE-190: a list of parts comes back as one line",
      first.composed && first.prompt === ONE_LINE && calls === 1, JSON.stringify(first));

    // ⛔ AEVI'S STABILITY RULE IS THE LOAD-BEARING ONE: "same fight, same picture, forever. A re-rolling
    // battle quietly says it was a different fight." Determinism is a property of the CACHE, so the model
    // is asked once, ever — non-determinism never reaches the player.
    const second = await IP.composeImagePrompt(LIST, { cache, kind: "battle", call: async () => { calls++; return "SOMETHING ELSE ENTIRELY"; } });
    check("CCODE-190: the same subject is composed ONCE, ever — the cache is what makes it stable",
      second.prompt === ONE_LINE && second.composed && calls === 1, `calls=${calls} prompt=${second.prompt}`);

    // ⛔ AND IT NEVER BLOCKS A PICTURE. No key, offline, refused, rate-limited — the deterministic prompt
    // is what comes back, unchanged. This is the project's own law applied to a call in front of an image.
    // ⚠️ WRAPPED, BECAUSE A GATE THAT CRASHES IS NOT A GATE THAT FAILS. With the fallback mutated out,
    // `composeImagePrompt` rejects, the rejection escapes this block, and the whole SUITE dies mid-file —
    // taking the twelve checks below it with it. The run then looks like a crash rather than a red line,
    // and a harness reading stdout's tail reports it as a pass. Turn the throw into the failure it is.
    let boom;
    try { boom = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => { throw new Error("NO_API_KEY"); } }); }
    catch (e) { boom = { prompt: `THREW: ${e?.message}`, composed: null }; }
    check("CCODE-190: a failed or keyless compose returns the builder's own prompt, unchanged",
      boom.prompt === LIST && boom.composed === false, boom.prompt.slice(0, 60));

    // ⚠️ A REFUSAL IS NOT A PROMPT — returning one puts "I can't help with that" into an image generator.
    for (const bad of ["I can't help with that.", "Sorry, I cannot create that image.", "", "```", "  "]) {
      const r = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => bad });
      check(`CCODE-190: a refusal or empty reply is refused, not drawn — ${JSON.stringify(bad.slice(0, 22))}`,
        r.prompt === LIST && r.composed === false, r.prompt.slice(0, 60));
    }
    // …and the wrapper a model adds anyway is stripped rather than trusted.
    const wrapped = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", call: async () => `Here's the prompt:\n"${ONE_LINE}"` });
    check("CCODE-190: 'Here's the prompt:' and its quotes are stripped rather than drawn",
      wrapped.composed && wrapped.prompt === ONE_LINE, wrapped.prompt);

    // ⚠️ ASSERTED BEHAVIOURALLY, not against an imported constant — an exported constant that is only ever
    // READ is indistinguishable from a dead export to the importedNeverCalled ratchet. 240 is the module's cap.
    const longOut = (await IP.composeImagePrompt(LIST, { cache: {}, kind: "b", call: async () => "x, ".repeat(400) })).prompt;
    check("CCODE-190: a composed line respects the cap the builders could not hold",
      longOut.length <= 240 && longOut.length > 0, `${longOut.length} chars`);

    // ⛔ A SHORT PROMPT IS NOT WORTH A CALL. Composing one adds drift and spends a request for nothing.
    let cheap = 0;
    const short = await IP.composeImagePrompt("a lean scarred woman on a wet stone bridge at dusk",
      { cache: {}, kind: "npc", call: async () => { cheap++; return ONE_LINE; } });
    check("CCODE-190: an already-short prompt is left alone — no call, no drift",
      cheap === 0 && short.composed === false);

    // ---- CCODE-191: both fights came back as ONE person -------------------------------------------------
    // ⛔ Erik, on the first real results: "seems like you'll really need to start with the two figures if you
    // want to get them both in." The pictures proved it — Neth's grey wool robes wearing the Choirmaster's
    // mid-blow palm, in one body. The composer was told it was compressing "a list of visual details" and had
    // no idea two people were in the list, so it fused them: `buildBattlePrompt`'s own design ("two figures in
    // ONE relation") undone by the thing meant to serve it.
    {
      const twoSys = [];
      const spy = async (msgs, o) => { twoSys.push(o.system); return "figure in grey wool robes, palm raised mid-blow, kneeling"; };
      const r2 = await IP.composeImagePrompt(LIST, { cache: {}, kind: "battle", subjects: 2, call: spy });
      // ⚠️ SUBJECT COUNT IS THE FRAME, NOT A DETAIL. An image model decides how many bodies to draw in the
      // first few words — a count that arrives as a subordinate clause a third of the way in gets ignored.
      check("CCODE-191: a two-figure fight is composed as two figures, and the count LEADS",
        /^two figures\b/i.test(r2.prompt), r2.prompt);
      check("CCODE-191: …and the composer is told there are two, rather than left to guess from a comma list",
        /TWO FIGHTING FIGURES/.test(twoSys[0] || "") && /FIRST WORDS/.test(twoSys[0] || ""));
      // ⛔ ENFORCED, NOT MERELY ASKED FOR — the model mostly complies; when it does not, code puts the frame
      // back rather than shipping a two-person fight as one body.
      check("CCODE-191: a reply that forgets the count has it restored, not shipped as one body",
        IP.cleanComposed("figure in grey wool robes, kneeling, palm raised", true).startsWith("Two figures"));
      check("CCODE-191: …and a reply that already leads with it is not doubled",
        (IP.cleanComposed("Two figures — a spectre and a kneeling woman", true).match(/two figures/gi) || []).length === 1);
      check("CCODE-191: a single-subject picture is never given a second body",
        !/two figures/i.test(IP.cleanComposed("a lean scarred woman on a wet bridge at dusk", false)));
      // ⛔ AND THE COUNT IS IN THE CACHE KEY, or the one-figure picture Erik already has would be served
      // back forever and never re-composed.
      // ⚠️ ASSERTED THROUGH `composeImagePrompt`, NOT `composeKey`. Written against the helper it stayed GREEN
      // with the count removed from the call site — the key function still distinguished "1" from "2" while
      // nothing passed either. Testing the helper is not testing the wiring.
      {
        const shared = {};
        await IP.composeImagePrompt(LIST, { cache: shared, kind: "battle", subjects: 1, call: async () => "one lone figure kneeling in mist, palm raised" });
        const asTwo = await IP.composeImagePrompt(LIST, { cache: shared, kind: "battle", subjects: 2, call: async () => "Two figures locked, one striking, one giving no ground" });
        check("CCODE-191: the subject count is part of the cache key — an old one-figure compose is not reused",
          /^two figures/i.test(asTwo.prompt), asTwo.prompt);
      }
      // The builder is the only thing that knows there are two; it now says so.
      const bp191 = await import("../engine/battleprompt.js");
      const two191 = bp191.buildBattlePrompt({ victim: { name: "A", appearance: "grey wool" }, killer: { name: "B", appearance: "half-transparent" }, place: "x", outcome: "wounded" });
      const one191 = bp191.buildBattlePrompt({ victim: { name: "A", appearance: "grey wool" }, place: "x" });
      check("CCODE-191: the builder reports how many figures it composed for",
        two191.subjects === 2 && one191.subjects === 1, `${two191.subjects}/${one191.subjects}`);
      check("CCODE-191: …and the battle mint passes that count through to the composer",
        /subjects: built\.subjects \|\| 1/.test(readFileSync(join(root, "app.js"), "utf8")));
    }

    // ⛔ COMPOSE BEFORE THE FLOORS, NEVER AFTER — composing on top of them would let the model compress
    // away the ceiling tone and house style they exist to add.
    const src190 = readFileSync(join(root, "app.js"), "utf8");
    check("CCODE-190: the composed line is what the floors are applied TO, not the other way round",
      /const composedOut = await composeImagePrompt\(built\.prompt, \{[^}]*\}\);\s*\n\s*const safe = sanitizeImagePrompt\(composedOut\.prompt,/.test(src190));
    // …and a record-backed re-roll hands the composed words in as the override, or `regenerateImage`
    // rebuilds the list from the record on the way past and the composition is silently discarded.
    check("CCODE-190: a re-roll passes the composed words through, rather than re-deriving the list",
      /const c = await composeImagePrompt\(rawWords, \{ cache: character\.promptCompositions, kind: it\.regen\.kind \}\);/.test(src190)
      && /promptOverride: words,/.test(src190));
    // \u26a0\uFE0F Haiku 4.5 rejects `effort` and takes `budget_tokens`, not adaptive thinking — neither belongs on a
    // compression call, and passing either would 400 or be ignored.
    const csrc190 = readFileSync(join(root, "engine/claude.js"), "utf8");
    check("CCODE-190: the composer is routed to Haiku, with no effort or thinking config",
      /"image-prompt": "claude-haiku-4-5-20251001"/.test(csrc190)
      && !/effort/.test(readFileSync(join(root, "engine/imageprompt.js"), "utf8").replace(/\/\/.*|\/\*[\s\S]*?\*\//g, "")));
  }


  // FLIGHT, AND YOU DO NOT DO IT, sovereign abyssal, HORNED…" — the first clause is a note from one author
  // to the next. Same class as the injection Erik caught before, arriving from the other direction:
  // authored INTO the content rather than appended by the engine.
  {
    const { plainForArt } = await import("../engine/art.js");
    const aside = "⚠️ ABYSSAL FLIGHT, AND YOU DO NOT DO IT — SOMETHING CARRIES YOU. A bargain struck for passage.";
    check("CCODE-189: an authored aside never reaches the image model",
      plainForArt(aside) === "A bargain struck for passage." ,
      JSON.stringify(plainForArt(aside)));
    // ⚠️ DE-SHOUTED, NOT DELETED. "HORNED" and "PART-MACHINE" are Aevi emphasising a REAL VISUAL FEATURE
    // — the caps are for a human reading the file. Dropping the word would lose the horns.
    check("CCODE-189: …and emphasis is lowered, never dropped — the horns stay in the picture",
      plainForArt("sovereign among them: HORNED, dressed better than anyone expects")
        === "sovereign among them: horned, dressed better than anyone expects"
      && plainForArt("hollower enginewright, PART-MACHINE, hollows a person")
        === "hollower enginewright, part-machine, hollows a person");
    check("CCODE-189: ordinary authored prose passes through untouched",
      plainForArt("grey wool worn thin at the knees, hands stained to the wrist")
        === "grey wool worn thin at the knees, hands stained to the wrist");
    // ⛔ AND THE BUILDER USES IT. A scrubber nothing calls is the fifth presence-not-use gate this session.
    const bpSrc189 = readFileSync(join(root, "engine/battleprompt.js"), "utf8");
    check("CCODE-189: every clause the battle prompt takes goes through it",
      /const s = plainForArt\(text\)\.trim\(\)/.test(bpSrc189)
      && /import \{ plainForArt \} from "\.\/art\.js";/.test(bpSrc189));
    // ⛔ SHORT IS THE REQUIREMENT (Aevi). The description is reader-prose and was appended on top of the
    // visual `shape`, pushing 269 real prompts to a 362-char average against a 400 cap.
    check("CCODE-189: the power phrase leads with what it LOOKS like, not the paragraph explaining it",
      /const visual = \[shape, tags\]\.filter\(Boolean\)\.join\(", "\);/.test(bpSrc189)
      && /const named = visual \|\| clause\(ability\.description/.test(bpSrc189));
    check("CCODE-189: …and a craft with no shape still says something",
      /Old Hunger — a slow taking/.test(powerPhrase({ name: "Old Hunger", description: "a slow taking that leaves the shape behind" }, {})),
      powerPhrase({ name: "Old Hunger", description: "a slow taking that leaves the shape behind" }, {}));
  }
  check("400b: a battle has its own wide frame (a portrait crop of a fight shows one shoulder)", /battle:\s+\{ width: 1024, height: 512 \}/.test(artSrc400) && /death:\s+\{ width: 768, height: 512 \}/.test(artSrc400));
}

// ---- CCODE-180: the caption was running under the buttons ----
// Erik sent a screenshot: "…e waystation fire—shelter-keeper, traveler · version 2 of 2 · 19/29 in the
// gallery · a new draw" with the head cut off by one button and the tail colliding with another.
// ⛔ CAUSE: each action was ABSOLUTELY POSITIONED at its own offset into the band the caption occupies, so
// a long caption slid beneath them, and a button that did not render left a hole instead of letting its
// neighbours close up. Four independent anchors is how it got there; pixel-nudging them is how it stays.
{
  const css180 = readFileSync(join(root, "style.css"), "utf8");
  const app180 = readFileSync(join(root, "app.js"), "utf8");
  const ACTIONS = ["lightbox-regen", "lightbox-rebuild", "lightbox-discard", "lightbox-keep"];

  check("CCODE180: the four actions live in ONE row", /<div class="lightbox-actions">/.test(app180)
    && /\.lightbox-actions \{[^}]*display: flex[^}]*flex-wrap: wrap/.test(css180));
  // ⛔ THE REGRESSION THAT ALMOST SHIPPED: a stale absolute rule sat LATER in the file than the new row and
  // won the cascade, so the button would have re-absoluted itself while the row looked correct in source.
  check("CCODE180: not one action is absolutely positioned any more", ACTIONS.every(cls => {
    const rules = [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].map(m => m[1]);
    return rules.length > 0 && rules.every(body => !/position:\s*absolute/.test(body));
  }), () => ACTIONS.filter(cls => [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].some(m => /position:\s*absolute/.test(m[1]))).join(", "));
  check("CCODE180: and none of them carries a hand-tuned left/right offset", ACTIONS.every(cls =>
    [...css180.matchAll(new RegExp(`\\.${cls}[^{]*\\{([^}]*)\\}`, "g"))].every(m => !/(^|;)\s*(left|right):/.test(m[1]))));
  // ⚠️ COUNT THE STRUCTURAL RULE, NOT EVERY MENTION. My first version counted `.lightbox-actions {` and
  // caught the responsive `gap` override inside the media query — a legitimate second mention, not a
  // second definition. What must be unique is the rule that decides the LAYOUT.
  check("CCODE180: the row's layout is defined ONCE, so a later rule cannot quietly re-break it",
    (css180.match(/\.lightbox-actions \{[^}]*display:/g) || []).length === 1);
  check("CCODE180: the caption is free to wrap rather than slide under anything", /\.lightbox-cap \{ max-width: 92vw; \}/.test(css180));
  // the image must yield room, or the row clips off the bottom and looks like it does not exist
  check("CCODE180: the picture leaves room for the caption and the row on a short screen", (() => {
    const m = css180.match(/\.lightbox-inner img \{[^}]*max-height:\s*(\d+)vh/);
    return m && Number(m[1]) <= 80;
  })());
  check("CCODE180: close/save/details stay pinned at the top, away from the caption band",
    /\.lightbox-close \{[^}]*position: absolute[^}]*top:/.test(css180) && /\.lightbox-meta-btn \{[^}]*position: absolute[^}]*top:/.test(css180));
}

// ---- CCODE-185: an index into a mutable list is not a handle ----
// Erik: "after keeping some photos the gallery doesn't refresh, so when I click on something it opens up
// something else." ⛔ The tile carried `data-lbindex` — a POSITION captured when the grid rendered. Keeping
// an image unshifts a new entry at index 0, so every index the DOM was holding shifted by one and every
// tile opened its neighbour. The bug is not "the gallery is stale"; it is that a position was ever used as
// a name for a thing.
{
  const src185 = readFileSync(join(root, "app.js"), "utf8");
  // the class of bug, demonstrated rather than described
  check("CCODE185 THE BUG: an index handle points at the wrong picture once the list grows at the front", (() => {
    const g = [{ url: "a" }, { url: "b" }, { url: "c" }];
    const idxAtRender = 1;
    g.unshift({ url: "NEW" });                    // exactly what addGalleryImage does on a Keep
    return g[idxAtRender].url !== "b";
  })());
  check("CCODE185 THE FIX: a URL handle survives it", (() => {
    const g = [{ url: "a" }, { url: "b" }, { url: "c" }];
    g.unshift({ url: "NEW" });
    return g[g.findIndex(x => x.url === "b")].url === "b";
  })());
  // ⚠️ STRIP COMMENTS BEFORE A NEGATIVE. The note above explaining this bug contains `data-lbindex`, so the
  // assertion failed on its own explanation — the fifth time this session a checker has matched the prose
  // about a thing rather than the thing. A negative claim about CODE has to be made against code.
  const markup185 = src185.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  check("CCODE185: the tile carries its url and no index at all",
    /data-lburl="\$\{esc\(g\.url\)\}"/.test(markup185) && !/data-lbindex/.test(markup185));
  check("CCODE185: …and the position is resolved against the CURRENT gallery at click time",
    /const at = Math\.max\(0, items\.findIndex\(x => x\.url === want\)\);/.test(src185));
  check("CCODE185: a url that has since been discarded still opens something rather than nothing", /Math\.max\(0, /.test(src185));
  // and the grid catches up with whatever happened inside the box
  check("CCODE185: the lightbox tells its caller when it closes", /function openLightbox\(items, start = 0, \{ onClose = null \} = \{\}\)/.test(src185)
    && /try \{ onClose\?\.\(\); \} catch/.test(src185));
  check("CCODE185: the gallery re-renders on close, so counts and defaults are current",
    /onClose: \(\) => \{ if \(document\.querySelector\("\.gallery-grid"\)\) renderGallery\(\); \}/.test(src185));
  check("CCODE185: …and a failing redraw never eats the close", /catch \{ \/\* a redraw is never worth eating the close \*\/ \}/.test(src185));
}

// ---- CCODE-184: "I want to be able to set the default picture please." ----
// ⛔ KEEP WAS DOING TWO JOBS. It cast the likeness vote AND silently became the shown picture — so keeping a
// fifth image because you liked one detail of it replaced the face you had already chosen, and there was no
// way to say which one represents someone. Two sentences, two buttons:
//   ☆ Keep this look  — this is what they LOOK like   (a vote, many, accumulates, steers future renders)
//   ★ Set as default  — this is the picture to SHOW   (exactly one, and it pins against the re-mint)
{
  const src184 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ THE MARKUP **AND** THE HANDLER. Checking the bare attribute passed while half the feature was gone —
  // the mutation removed the button and the querySelector still matched.
  check("CCODE184: there is a button that sets the default picture, and something listening to it",
    /<button class="lightbox-default" data-lbdefault/.test(src184) && /★ Set as default/.test(src184)
    && /el\.querySelector\("\[data-lbdefault\]"\)/.test(src184));
  check("CCODE184: it is offered only when this is NOT already the default", /const canSetDefault = !!it\.regen\?\.subjectId && !!spec\?\.keep && !isCurrent;/.test(src184));
  // ⛔ THE SPLIT ITSELF: keeping must no longer change what is shown
  check("CCODE184: KEEP no longer sets the shown picture — it is a vote and only a vote",
    !/if \(!spec\.keep\(it\.regen\.subjectId, it\.url, it\.seedKey\)\) return false;/.test(src184));
  check("CCODE184: …and the default button is what calls the kind's keep", /const ok = sub\.spec\.keep\(it\.regen\.subjectId, it\.url, it\.seedKey\);/.test(src184));
  // ⚠️ CCODE-186 SUPERSEDED THE CLAIM THIS ONE USED TO MAKE. It read "a subject-less picture offers
  // neither (nothing to represent, nothing to vote on)" — true when written, and Erik has since ruled the
  // other way: *"make sure all images have this."* There are no subject-less pictures now; `keepableRegen`
  // gives a one-off its own url as a subject. The LINE is still the right guard (a kind with no `keep`
  // still offers nothing), so the check stays and its sentence is corrected rather than left lying.
  check("CCODE184: the offer is keyed on a subject and a kind that can store one",
    /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src184));
  // the two must remain independent, which is the whole point
  const { toggleKeep: tk184, acceptImage: ai184 } = await import("../engine/art.js");
  const store184 = {}, rec184 = { id: "pell", name: "Pell", image: "chosen" };
  tk184(store184, "npc:pell", { url: "other", note: "dark hair", prompt: "dark hair, strong build" });
  check("CCODE184: keeping a DIFFERENT picture does not move the default", rec184.image === "chosen" && store184["npc:pell"].keeps.length === 1);
  ai184(rec184, { url: "other", seedKey: "s" });
  check("CCODE184: …and setting the default does not add a vote", rec184.image === "other" && store184["npc:pell"].keeps.length === 1);
  check("CCODE184: setting a default still PINS, so the milestone re-mint cannot overrule the choice", rec184.imagePinned === true);
  // and the gallery stack shows whatever the default is
  check("CCODE184: the stack's representative follows the default", /const rep = st\.members\.find\(m => m\.url === chosen\) \|\| st\.members\[0\];/.test(src184));
}

// ---- CCODE-183: the gallery stacks by subject ----
// Erik: "I have created several images of Pell now that I like and have kept. They don't need to appear
// separate in the gallery — they should show up as the one I choose to represent her, and when clicked I
// can see all the other kept images in a rotating stack… This can apply to all versions of images rendered.
// If I like a battle scene I want to be able to render a few more images of it to keep."
// ⚠️ THE GRID AND THE LIGHTBOX ALREADY DISAGREED: the lightbox has grouped versions by subject since
// CCODE-172, and the grid never did — so one person held four tiles and the count said 76 for far fewer
// actual subjects. This is that same grouping applied one layer up.
{
  const src183 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE183: the grid groups into stacks before it renders", /const stacks = galleryStacks\(shown\);/.test(src183) && /function galleryStacks\(entries\)/.test(src183));
  check("CCODE183: a stack shows the picture the player CHOSE, not merely the newest",
    /const chosen = spec\?\.current \? spec\.current\(st\.regen\.subjectId\) : null;/.test(src183)
    && /const rep = st\.members\.find\(m => m\.url === chosen\) \|\| st\.members\[0\];/.test(src183));
  check("CCODE183: …and it says how many are behind it", /gal-stack-badge/.test(src183) && /\$\{n\} pictures of this/.test(src183));
  check("CCODE183: a picture with NO subject stays its own tile (a moment is not part of anything)", /`solo:\$\{g\.url\}`/.test(src183));
  // ⚠️ CORRECTED BY CCODE-185: the tile carries its URL, not a position — an index captured at render time
  // pointed at the wrong picture the moment a Keep unshifted a new entry. The property is unchanged: the
  // stack opens on its own representative, and the lightbox's per-subject ring takes it from there.
  check("CCODE183/185: opening a stack opens the REPRESENTATIVE, resolved at click time",
    /data-lburl="\$\{esc\(g\.url\)\}"/.test(src183)
    && /const at = Math\.max\(0, items\.findIndex\(x => x\.url === want\)\);/.test(src183));

  // ⚠️ THE SHAPE keepLightboxItem ACTUALLY WRITES — his four Pell tiles, plus a legacy one with no
  // provenance that must still join them, plus two of one battle, plus a one-off that must not.
  const tiles183 = [
    { kind: "npc", caption: "Pell", url: "p1", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell", url: "p2", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell", url: "p3", subjectKind: "npc", subjectId: "pell" },
    { kind: "npc", caption: "Pell — devoted", url: "p0" },
    { kind: "battle", caption: "A — killed by B", url: "b1", subjectKind: "battle", subjectId: "a|b|-|44" },
    { kind: "battle", caption: "A — killed by B", url: "b2", subjectKind: "battle", subjectId: "a|b|-|44" },
    { kind: "moment", caption: "a chase", url: "m1" }
  ];
  const { namesMatch: nm183 } = await import("../engine/namematch.js");
  const reg183 = [{ id: "pell", name: "Pell" }];
  const keyOf = (t) => {
    if (t.subjectKind && t.subjectId) return `${t.subjectKind}:${t.subjectId}`;
    const nm = String(t.caption || "").split("—")[0].trim();
    if (t.kind === "portrait" || t.kind === "npc") { const h = reg183.find(n => nm183(n.name, nm)); if (h) return `npc:${h.id}`; }
    return `solo:${t.url}`;
  };
  const grouped = tiles183.reduce((m, t) => { const k = keyOf(t); (m[k] = m[k] || []).push(t); return m; }, {});
  check("CCODE183: four kept Pell pictures become ONE tile", (grouped["npc:pell"] || []).length === 4);
  check("CCODE183: …including one minted before provenance existed, joined by name", (grouped["npc:pell"] || []).some(t => t.url === "p0"));
  check("CCODE183: two pictures of the SAME battle stack too — 'if I like a battle scene I want to render a few more'", (grouped["battle:a|b|-|44"] || []).length === 2);
  check("CCODE183: a one-off moment is left alone", (grouped["solo:m1"] || []).length === 1 && Object.keys(grouped).length === 3);
  // a battle is keepable, or "render a few more of it to keep" is not a thing you can do
  check("CCODE183: a battle CAN be kept (it carries a subject, so the Keep button is real)",
    /battle: \{[\s\S]{0,400}character\.battleImages\[key\]\.url = url/.test(src183));
}

// ---- CCODE-179: the house style follows the PEOPLE ----
// Erik: "I like to keep the house style but make sure that house style is variable based on the tradition
// they're from." The old constant locked a PALETTE — "muted earth tones with teal and gold accents" — onto
// every image in the game, competing with 26 authored tradition palettes for the same slot. An Umbral
// rendered in teal and gold is not an Umbral. The tradition file's own usage note asks for exactly this.
{
  const A179 = await import("../engine/art.js");
  const tr179 = JSON.parse(readFileSync(join(root, "content/packs/core/rules/tradition_visual_aesthetics.json"), "utf8")).traditions;
  const ids = Object.keys(tr179);
  const styles = ids.map(t => A179.houseStyleFor(tr179[t]));

  check(`CCODE179: all ${ids.length} traditions give ${ids.length} distinct style wrappers`, ids.length >= 26 && new Set(styles).size === ids.length);
  // ⚠️ THE MEDIUM NEVER MOVES — that is what keeps it one game rather than 26 unrelated galleries.
  check("CCODE179: every one keeps the constant medium", styles.every(v => v.startsWith(A179.IMAGE_STYLE_MEDIUM)));
  check("CCODE179: …and the house palette is GONE from a tradition wrapper (it was the thing competing)",
    styles.every(v => !v.includes(A179.IMAGE_STYLE_HOUSE)));
  check("CCODE179: a subject with no tradition still gets the house look",
    A179.houseStyleFor(null) === `${A179.IMAGE_STYLE_MEDIUM}, ${A179.IMAGE_STYLE_HOUSE}` && A179.houseStyleFor({}) === A179.houseStyleFor(null));
  check("CCODE179: the wrapper carries palette, light and mood — the three that make a people look like themselves", (() => {
    const w = A179.houseStyleFor(tr179.umbral);
    return /near-black, cold indigo/.test(w) && /no light source/.test(w) && /soft-footed/.test(w);
  })());
  check("CCODE179: each borrowed clause is clamped — an aesthetic is prose, the wrapper is a wrapper", styles.every(v => v.length < 260));
  check("CCODE179: the URL builder takes the aesthetic and BOTH mint paths hand it over", (() => {
    const src = readFileSync(join(root, "engine/art.js"), "utf8");
    return /export function imageURLFor\(kind, safePrompt, seedKey = "", \{ aesthetic = null \} = \{\}\)/.test(src)
      && (src.match(/\{ aesthetic: promptOpts\.aesthetic \|\| null \}/g) || []).length === 2;
  })());
  check("CCODE179: two traditions genuinely produce different URLs for the same prompt", (() => {
    const was = localStorage.getItem("singularity.artMode"); A179.setArtMode("generate");
    const a = A179.imageURLFor("npc", "a person", "seed", { aesthetic: tr179.umbral });
    const b = A179.imageURLFor("npc", "a person", "seed", { aesthetic: tr179.blazeborn });
    if (was) localStorage.setItem("singularity.artMode", was);
    return a !== b && decodeURIComponent(a).includes("cold indigo") && decodeURIComponent(b).includes("white-gold");
  })());
  const src179 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE179: a re-roll keeps the people's look (the regen path resolves the aesthetic too)",
    /promptOpts: rec => \(\{ aesthetic: npcAesthetic\(rec\) \}\)/.test(src179));
}

// ---- CCODE-175/176/177: Erik's rulings on what gets injected, and where a look actually comes from ----
{
  const A176 = await import("../engine/art.js");
  const was176 = localStorage.getItem("singularity.artMode"); A176.setArtMode("generate");
  const d176 = "scorched leather apron, forearms scarred";

  // ⛔ CCODE-175 — WHERE A LOOK COMES FROM. Erik: "I have Cevaine's image with white hair that I love… but
  // no re-render is giving her white hair anymore." MEASURED: nothing in her record mentions hair at all.
  // Her beloved picture was minted from "a person, character portrait, named Cevaine, Woman, …" — the
  // pre-SNG-367 generic lead — so the white hair was the model's invention from one seed. Keeping that
  // image taught the likeness nothing, because the words were never there to count. A keep can carry the
  // player's OWN words now, and they outrank clauses the engine merely assembled.
  const st175 = {};
  A176.toggleKeep(st175, "npc:cevaine", { url: "u1", note: "white hair, translucent skin",
    prompt: A176.sanitizeImagePrompt("white hair, translucent skin, Tall, angular, character portrait, named Cevaine, Woman", { ratingLevel: 2 }) });
  const lk175 = A176.likenessClause(st175["npc:cevaine"].keeps);
  check("CCODE-175 CEVAINE: the words the player typed LEAD the likeness", lk175.startsWith("white hair, translucent skin"), lk175);
  // ⚠️ A CASE WHERE THE WEIGHT ALONE DECIDES. My first version put the note first in BOTH weightings, because
  // a note also sorts earliest on ties — so it proved order, not weight. Here one note (seen once) must beat
  // an assembled clause that TWO keeps agree on; that only holds if a typed word counts double.
  check("CCODE-175: …and a word the player typed ONCE outranks a clause two prompts merely share", (() => {
    const s3 = {};
    // the note must NOT also sit in the prompt, or it wins on ordinary count and the weight proves nothing
    A176.toggleKeep(s3, "w", { url: "a", note: "white hair", prompt: "grey cloak" });
    A176.toggleKeep(s3, "w", { url: "b", prompt: "grey cloak" });
    return A176.likenessClause(s3.w.keeps).startsWith("white hair");
  })(), () => { const s3 = {}; A176.toggleKeep(s3, "w", { url: "a", note: "white hair", prompt: "grey cloak" }); A176.toggleKeep(s3, "w", { url: "b", prompt: "grey cloak" }); return A176.likenessClause(s3.w.keeps); });
  check("CCODE-175: the engine's own framing never gets a vote (it is on every portrait, so agreement would elect it)",
    !/character portrait|named cevaine|a person/i.test(lk175), lk175);
  check("CCODE-175: a keep with no note still votes on its description", (() => {
    const s2 = {}; A176.toggleKeep(s2, "k", { url: "a", prompt: "grey wool cloak, a scar" });
    return A176.likenessClause(s2.k.keeps).includes("grey wool cloak");
  })());

  // ⛔ CCODE-176 — ERIK'S RULING ON THE INJECTIONS
  check("CCODE-176: the blanket safety tail is GONE from every prompt", !/no signature|no copyrighted characters/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" })));
  check("CCODE-176: the tone now shifts by KIND, so a battle and a portrait stop looking the same", (() => {
    const b = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "battle" });
    const n = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" });
    return /action, epic fantasy/.test(b) && !/action, epic fantasy/.test(n) && b !== n;
  })());
  check("CCODE-176: every scene kind gets its own register", ["battle", "death", "beast", "location", "moment", "item"]
    .map(k => A176.sanitizeImagePrompt(d176, { ratingLevel: 3, kind: k })).every((v, _, all) => all.filter(x => x === v).length === 1));
  check("CCODE-176: the rating still governs on top of the kind", /no gore/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 1, kind: "battle" })) && !/no gore/.test(A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "battle" })));
  // the scrub leaves a hole and the hole is visible — "a sensual, erotic encounter" became "a , encounter",
  // an empty clause the generator reads as detail. Same junk class as the "no ," in the old safety tail.
  check("CCODE-178: a scrubbed word leaves no orphaned comma behind", (() => {
    const out = A176.sanitizeImagePrompt("a sensual, erotic encounter between two lovers", { ratingLevel: 0, kind: "moment" });
    return !/\s,|,\s*,|^\s*,|,\s*$/.test(out) && !/\ba\s*,/.test(out);
  })(), () => A176.sanitizeImagePrompt("a sensual, erotic encounter between two lovers", { ratingLevel: 0, kind: "moment" }));
  check("CCODE-176: the boilerplate is a fraction of what it was", (A176.sanitizeImagePrompt(d176, { ratingLevel: 4, kind: "npc" }).length - d176.length) < 60);
  // ⛔ AND THE ONE THING THAT DID NOT MOVE
  check("CCODE-176/178: a MINOR's clause rides ALONGSIDE the scene, and the ceiling is still clamped to PG", (() => {
    const m = A176.sanitizeImagePrompt(d176, { ratingLevel: 4, isMinor: true, kind: "battle" });
    return /a child, fully clothed, non-sexual/.test(m) && /epic fantasy/.test(m) && !/mature dramatic tone/.test(m) && /adventurous, mild, no gore/.test(m);
  })());
  check("CCODE-176: and the sexual scrub is still absolute for a minor at any ceiling",
    !/sensual|erotic/i.test(A176.sanitizeImagePrompt("a sensual erotic study", { ratingLevel: 4, isMinor: true })));

  // ⛔ CCODE-181/182: three things that had no gate at all, found by mutating rather than by review.
  check("CCODE-182: a KIND tone round-trips — it is strippable, so re-sanitising stays idempotent", (() => {
    const wk = A176.sanitizeImagePrompt("a fight at the gate", { ratingLevel: 2, kind: "battle" });
    return A176.bareImagePrompt(wk) === "a fight at the gate" && A176.sanitizeImagePrompt(wk, { ratingLevel: 2, kind: "battle" }) === wk;
  })());
  const srcA181 = readFileSync(join(root, "app.js"), "utf8");
  // Erik on Dawn Surgery: a Radiant craft came back in muted earth tones because the RE-ROLL carried no
  // tradition — the first mint passed one, this entry had no promptOpts at all.
  check("CCODE-182: a CRAFT keeps its people on a re-roll (its tradition drives prompt and style alike)",
    /promptOpts: rec => \(\{ aesthetic: rec \? \(CONTENT\.traditionVisualAesthetics\?\.\[abilityTradition\(rec\) \|\| rec\.tradition\]/.test(srcA181));
  // "no ability to keep this image" — on the warpling. A creature recurs and has an authored look; it was
  // prompt-only purely because nothing ever gave its tile a subject.
  check("CCODE-181: a BEAST tile resolves to its creature, so its look can be kept",
    /if \(g\.kind === "beast"\) \{/.test(srcA181) && /namesMatch\(c\.name, nm\)/.test(srcA181) && /subjectKind: "beast", subjectId: creature\.id/.test(srcA181));

  // ⛔ CCODE-186 (Erik): "the keep button isn't showing up on every image type. I generated a new one I
  // liked and neither the initial nor the regen had a keep button. Make sure all images have this."
  // ⚠️ AND THE INTENT WAS ALREADY IN A COMMENT AND NEVER BUILT — `likenessKey` says a tile with no record
  // "keys on its own url", and returned null. A comment describing behaviour that does not exist.
  {
    const s186 = srcA181;
    // The rule lands at the ONE place all eleven surfaces pass through. Per-surface fixes are how this got here.
    check("CCODE-186: every picture the lightbox opens is given a subject, whatever surface it came from",
      /function keepableRegen\(it\)/.test(s186) && /for \(const it of list\) it\.regen = keepableRegen\(it\);/.test(s186));
    // ⛔ CCODE-187 (Erik): "my new versions of Resonant Sight have split from the default view… leave the
    // more generic subject as the stack title." Resonant Sight is a `discovery` out of emergence_recipes
    // — not on the sheet, not in customAbilities, not in the catalog — so the name lookup finds nothing and
    // every picture of it keyed on its own URL: a stack of one, per draw. The CAPTION is the subject when
    // nothing else is, and it is identical across every draw of the same thing.
    check("CCODE-187: a tile with no record stacks on its CAPTION, so every draw of one thing is one stack",
      /if \(cap\) return `solo:cap:\$\{cap\.slice\(0, 90\)\}`;/.test(s186)
      && /const solo = soloSubjectId\(\{ caption: it\.caption \|\| it\.meta\?\.caption, seedKey: it\.seedKey, url: it\.url \}\);/.test(s186));
    check("CCODE-187: …and a tile with NO caption still falls back to its url — a stack of one is honest there",
      /return g\?\.seedKey \? `solo:\$\{g\.seedKey\}` : \(g\?\.url \? `solo:\$\{g\.url\}` : null\);/.test(s186));
    // ⚠️ A stack holds pictures made on DIFFERENT days, so one day stamped on the stack is wrong the moment
    // there are two. The details panel already carries it per image.
    check("CCODE-187: the stack title is the subject — world-day is a fact about one picture, not the stack",
      /\$\{n > 1 \? ` <span class="hint">· \$\{n\} pictures<\/span>` : g\.worldDay \?/.test(s186)
      && /\["world-day", m\.worldDay\]/.test(s186));
    // ⛔ A KIND THAT NEEDS A RECORD AND HAS NONE MUST NOT BE HANDED A SYNTHETIC ID — its `keep` would look
    // up "solo:https://…" in the registry, find nothing, and return false on click. That is the exact
    // "✕ couldn't keep" Erik hit at CCODE-166, and giving every item a subject is a fresh way to cause it.
    check("CCODE-186: …and a record-backed kind with no record falls to `moment`, never to a synthetic id",
      /return spec\.needsId \? \{ \.\.\.it\.regen, kind: "moment", label: it\.regen\.label \|\| "this moment", subjectId: solo \}/.test(s186));
    // Every kind in the table can store a keep — the census, not a spot check on the three I touched.
    const table186 = s186.slice(s186.indexOf("const REGEN_KINDS = {"), s186.indexOf("const _regenPrompts"));
    const kinds186 = [...table186.matchAll(/^  (\w+): \{/gm)].map(m => m[1]);
    const noKeep186 = kinds186.filter(k => {
      const seg = table186.slice(table186.indexOf(`  ${k}: {`), table186.indexOf(`  ${k}: {`) + 900);
      return !/\bkeep: /.test(seg.slice(0, seg.indexOf("\n  },") + 1 || undefined));
    });
    check("CCODE-186: every image kind can be kept — the census, not the three I happened to touch",
      kinds186.length >= 9 && noKeep186.length === 0, `${kinds186.length} kinds; without keep: ${noKeep186.join(", ")}`);
    // ⚠️ AND OFFERING A DRAW WITH NOTHING TO DRAW FROM IS "some images say they fail to redraw" reborn.
    check("CCODE-186: Draw again is offered only when there IS a record or a stored prompt behind it",
      /const hasSource = !!\(it\.regen && \(REGEN_KINDS\[it\.regen\.kind\]\?\.find\?\.\(it\.regen\.subjectId\)/.test(s186)
      && /const canRegen = !!\(it\.regen && it\.regen\.kind && hasSource && imagesEnabled\(\)\);/.test(s186));
    // Erik: "I don't need the 'chosen' tag on the display."
    check("CCODE-186: the gallery no longer tags the stack's own top picture as 'chosen'",
      !/st\.chosen \? ` <span class="rep-band trusted">chosen<\/span>`/.test(s186)
      && /class="gal-stack-badge"/.test(s186));
  }

  // CCODE-177 — discarding
  const src177 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-177: a picture can be discarded", /data-lbdiscard/.test(src177));
  // ⚠️ CCODE-188 widened this — a subject's ONLY picture is discardable now too, because a figure portrait
  // is minted from a seed and re-mints on the next open. The claim here is unchanged: a KEPT picture is
  // discardable, not only an unsaved draw.
  check("CCODE-177: …a KEPT picture too, not only an unsaved draw",
    /const canDiscard = isDraw172 \|\| \(!!it\.meta && list\.length > 1\)/.test(src177));
  check("CCODE-177: an UNKEPT draw is simply dropped from the run — it was never written anywhere", /if \(isDraw172 && !keepsFor\(it\.regen\)\.some\(k => k\.url === it\.url\)\)/.test(src177));
  check("CCODE-177: a KEPT one is confirmed, and leaves the gallery", /deleteGalleryImage\(character, it\.url\)/.test(src177) && /Delete this picture\?/.test(src177));
  check("CCODE-177: ⛔ and its VOTE is withdrawn with it — a deleted picture must stop steering what they look like",
    /if \(at >= 0\) ks\.splice\(at, 1\);/.test(src177));
  check("CCODE-177: discarding the last one closes the box rather than showing nothing", (src177.match(/if \(!list\.length\) \{ close\(\); return; \}/g) || []).length >= 2);
  if (was176) localStorage.setItem("singularity.artMode", was176);
}

// ---- CCODE-174: the floors were corrupting their own safety tail ----
// Erik, reading a prompt in the details panel: "What's all this stuff getting injected into my image
// prompt?" — the ceiling tone and safety tail appended TWICE, and the first copy mangled:
//   "…tasteful, non-explicit, no , original character not a real person… no signature,
//     dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no nudity…"
// ⛔ THE WORD "nudity" WAS EATEN OUT OF THE SAFETY TAIL BY THE SAFETY SCRUB. A stored prompt is an
// ALREADY-SANITISED prompt, so re-running the floors ran SEXUAL_MARKERS across the tail this function had
// itself written. The guard degraded itself a little more every time a picture was redrawn.
{
  const { sanitizeImagePrompt: san174, bareImagePrompt: bare174, likenessClause: lc174, IMAGE_STYLE: STY174, setArtMode: sam174 } = await import("../engine/art.js");
  const was174 = localStorage.getItem("singularity.artMode"); sam174("generate");
  const raw174 = "someone tending the waystation fire—shelter-keeper, traveler";
  const once = san174(raw174, { ratingLevel: 2, kind: "npc" });   // CCODE-182: R+ contributes no tone at all now, so idempotency is proved at a ceiling that does

  check("CCODE-174 THE RULE: the floors are IDEMPOTENT — twice is the same as once", san174(once, { ratingLevel: 2, kind: "npc" }) === once);
  check("CCODE-174: …and so is three times, four times, forever", san174(san174(san174(once, { ratingLevel: 2, kind: "npc" }), { ratingLevel: 2, kind: "npc" }), { ratingLevel: 2, kind: "npc" }) === once);
  // the ORIGINAL bug was the tail eating its own word; the tail is gone (CCODE-176) so the property is now
  // simply that nothing repeats and nothing arrives mangled.
  check("CCODE-174/176/182: nothing is appended twice and nothing arrives mangled", !/no ,/.test(once) && (once.match(/mild peril, no gore/g) || []).length === 1 && !/no signature/.test(once));
  check("CCODE-174/182: the ceiling tone appears exactly once", (once.match(/mild peril, no gore/g) || []).length === 1);
  // ⛔ CCODE-182 REGRESSION GUARD: setting a ceiling tone to "" put an EMPTY ALTERNATIVE into the strip
  // regex, so `(?:a|b|)` matched at every position and bareImagePrompt deleted every space in the prompt —
  // "Surgery using Light as a scalpel" came out "SurgeryusingLightasascalpel". Caught only because the
  // verification PRINTED real output instead of asserting a boolean about it.
  check("CCODE-182: an empty ceiling tone does not turn the strip into a space-eater",
    bare174("Surgery using Light as a scalpel. Bright lights to see every detail.") === "Surgery using Light as a scalpel. Bright lights to see every detail.",
    () => bare174("Surgery using Light as a scalpel. Bright lights to see every detail."));
  check("CCODE-182: …and a real prompt survives a full round-trip with its spaces",
    /Bright lights to see/.test(san174("Bright lights to see and work", { ratingLevel: 4, kind: "ability" })));
  check("CCODE-182: the upper ceilings impose no MOOD (a rating is a limit, not a look)",
    san174("a bright clean workshop", { ratingLevel: 4, kind: "ability" }) === "a bright clean workshop"
    && !/dark, intense/.test(san174("a bright clean workshop", { ratingLevel: 3, kind: "ability" })));
  check("CCODE-182: …while the LOW ceilings still say what they exclude",
    /no gore/.test(san174("x", { ratingLevel: 0 })) && /no gore/.test(san174("x", { ratingLevel: 2 })));

  // ⚠️ ERIK'S ACTUAL CORRUPTED STRING, recovered — an already-damaged prompt must heal, not stay damaged
  const broken174 = "someone tending the waystation fire—shelter-keeper, traveler, dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no , original character not a real person, no copyrighted characters, no text, no watermark, no signature, dark, intense, cinematic, mature dramatic tone, tasteful, non-explicit, no nudity, original character not a real person, no copyrighted characters, no text, no watermark, no signature";
  check("CCODE-174: the string Erik pasted strips back to its description", bare174(broken174) === raw174, () => bare174(broken174));
  check("CCODE-174: …and re-sanitising it gives a clean single pass", san174(broken174, { ratingLevel: 2, kind: "npc" }) === once);

  // the floors still DO their job — idempotency must not have softened them
  check("CCODE-174/178: the floors still scrub BELOW the ceiling that allows it", !/erotic|nude study/.test(san174("an erotic nude study of a woman", { ratingLevel: 2 })));
  check("CCODE-174/176: minor-protection still absolute at any ceiling", /a child, fully clothed, non-sexual/.test(san174("a person", { ratingLevel: 4, isMinor: true })));
  check("CCODE-174: the ceiling still shapes the tone", /family-friendly/.test(san174("a person", { ratingLevel: 0 })) && !/family-friendly/.test(san174("a person", { ratingLevel: 4 })));

  // ⛔ AND THE LIKENESS VOTE WAS COUNTING THE BOILERPLATE. Every kept prompt ends with the same tail, and
  // the vote ranks by AGREEMENT — so the unanimous winners would have been "tasteful", "non-explicit",
  // "no nudity", and the actual face would have been pushed out by the floors.
  const keeps174 = [{ url: "a", prompt: san174("silver hair, sharp cheekbones, grey wool cloak", { ratingLevel: 2 }) },
                    { url: "b", prompt: san174("pale eyes, silver hair, grey wool cloak", { ratingLevel: 2 }) }];
  const clause174 = lc174(keeps174);
  check("CCODE-174: the likeness vote counts the DESCRIPTION, never the safety boilerplate",
    clause174.startsWith("silver hair, grey wool cloak") && !/tasteful|non-explicit|no nudity|no gore/.test(clause174), clause174);

  // the panel showed a prompt that was not the whole prompt
  const src174 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ UPDATED BY CCODE-179: the style is no longer one constant, so the panel shows the one THIS picture
  // used. The property — the appended style is visible rather than hidden — is unchanged and stronger.
  check("CCODE-174/179: the details panel shows the style wrapper this picture actually used",
    /…and the style wrapper/.test(src174) && /esc\(houseStyleFor\(aes\)\)/.test(src174));
  check("CCODE-174/179: the style is a named export rather than a hidden constant", typeof STY174 === "string" && STY174.length > 20);
  if (was174) localStorage.setItem("singularity.artMode", was174);
}

// ---- CCODE-173: a portrait is drawn from what someone LOOKS LIKE ----
// Erik: "I can't make the re-gen image look like the same person… it's almost like we're missing a field
// that describes the person's appearance?" The field exists — it was not being read, and the two paths were
// not even reading the same one. Measured on Cinder Vael: the card drew from `imagePrompt` (a SCENE — "a
// wright's workshop crowded with half-finished machines…") while the re-roll drew from `appearance` (the
// LOOK — "scorched leather apron, forearms scarred…"). Two sentences about two different things, so Draw
// again was never redrawing the same description.
// ⚠️ AEVI SAID THIS IN SNG-400b §2 AND MY SIDE NEVER DID ITS HALF: "`imagePrompt` is a SCENE and cannot be
// reused as 'what this person looks like' in a different scene."
{
  const { figureArtRecord: far173 } = await import("../engine/whois.js");
  const { assembleImagePrompt: asm173, setArtMode: sam173 } = await import("../engine/art.js");
  const was173 = localStorage.getItem("singularity.artMode"); sam173("generate");
  const epics173 = JSON.parse(readFileSync(join(root, "content/packs/valley/tradition_epics.json"), "utf8")).epics;

  // ⛔ THE PROPERTY ERIK ASKED FOR, AS A CENSUS: the card and the re-roll must describe the same person.
  const mismatched = epics173.filter(f => {
    const rec = far173(f);
    return asm173("npc", { ...rec, id: `whois-${f.id}` }, {}) !== asm173("npc", rec, {});
  });
  check(`CCODE-173: all ${epics173.length} figures build ONE prompt for the card and the re-roll`,
    epics173.length === 66 && mismatched.length === 0, () => mismatched.slice(0, 3).map(f => f.name).join("; "));

  const cinder = epics173.find(f => /Cinder Vael/.test(f.name));
  check("CCODE-173: the LOOK leads, not the scene", far173(cinder).appearance === cinder.appearance && far173(cinder).appearance !== cinder.imagePrompt);
  check("CCODE-173: …and a figure with no authored look still gets a picture from the scene rather than nothing",
    far173({ id: "x", name: "X", imagePrompt: "a scene" }).appearance === "a scene" && far173({ id: "y", name: "Y" }).appearance === "");
  check("CCODE-173: the DEAD are drawn from their authored death, which IS a scene on purpose (SNG-399b)",
    far173(cinder, { dead: true }).appearance === cinder.deathImagePrompt);
  check("CCODE-173: gender and role ride, so the portrait is not a coin toss", far173(cinder).gender === "she" && far173(cinder).role === "Maker");
  check("CCODE-173: nothing in, nothing out", far173(null) === null);

  // ⚠️ THE SCENE WAS BEING CUT ANYWAY — the prompt seed clamps its lead, so the workshop sentence arrived as
  // a fragment ("on a bench she has ,") which a generator draws as detail. The look fits; check it survives.
  const built173 = asm173("npc", far173(cinder), {});
  check("CCODE-173: the description reaches the prompt whole, not severed mid-sentence",
    built173.includes("unslept, mid-task even now") && !built173.includes("…"));

  const whoSrc173 = readFileSync(join(root, "engine/whois.js"), "utf8");
  check("CCODE-173: whoIs hands the card the look first", /appearance: fig\.appearance \|\| fig\.imagePrompt \|\| fig\.form \|\| null,/.test(whoSrc173));
  const appSrc173 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ ASSERT THE USE. My first version checked the record was BUILT — so putting the old hand-rolled object
  // back into the ensureImage call left the gate green with the bug fully restored. Fourth time today.
  check("CCODE-173: the card and the regen path ask the SAME builder (two records was the bug)",
    /const artRec = figureArtRecord\(rosterFig, \{ dead: !!known\.dead \}\)/.test(appSrc173)
    && /ensureImage\(\{ \.\.\.artRec, id: artSeed \}/.test(appSrc173)
    && /find: id => figureArtRecord\(rosterFigureOf\(id\), \{ dead: \/\^whois-death-\/\.test\(String\(id\)\) \}\)/.test(appSrc173));
  if (was173) localStorage.setItem("singularity.artMode", was173);
}

// ---- CCODE-172: the lightbox tells you what you are looking at, and the arrows stay on it ----
// Erik, on a 70-tile gallery: "can you make it so i can see all the fields — also, I'd like to be able to
// see the prompt that generated the image. And when I click an image that has re-generated more versions…
// I'd like to only go through the versions of the subject image; right now it runs through all images."
{
  const src172 = readFileSync(join(root, "app.js"), "utf8");

  // ⛔ THE NAVIGATION BUG WAS MINE. SNG-401 §3 said to append a draw to "the list the arrows already walk",
  // and I did — which is right for a one-image lightbox and wrong for a gallery, where the new version
  // landed at index 70 and comparing it against the original meant arrowing past sixty-eight other
  // pictures. Comparing the two IS the point of not destroying the old one.
  const rootOf = (x) => x?.versionOf || x?.url;
  const runOf = (list, i) => {
    const c = list[i]; if (!c) return null;
    const r = rootOf(c), sub = c.regen?.subjectId || null;
    const run = list.map((x, n) => (rootOf(x) === r || (sub && x?.regen?.subjectId === sub)) ? n : -1).filter(n => n >= 0);
    return run.length > 1 ? run : null;
  };
  // Erik's exact shape: a beast at tile 20 of 70, then two draws from it
  const g172 = Array.from({ length: 70 }, (_, n) => ({ url: `u${n}`, regen: { kind: "moment", subjectId: null } }));
  g172[19] = { url: "warpling", caption: "warpling", regen: { kind: "beast", subjectId: null } };
  check("CCODE-172: one picture with no versions still browses the whole gallery", runOf(g172, 19) === null);
  g172.splice(20, 0, { url: "w2", versionOf: "warpling", regen: g172[19].regen });
  g172.splice(21, 0, { url: "w3", versionOf: "warpling", regen: g172[19].regen });
  const ring = runOf(g172, 19);
  check("CCODE-172 THE FIX: once drawn, the run is just those versions", JSON.stringify(ring) === JSON.stringify([19, 20, 21]));
  check("CCODE-172: stepping wraps WITHIN the run and never escapes into the gallery", (() => {
    let i = 20; const stp = d => { const at = ring.indexOf(i); i = ring[(at + d + ring.length) % ring.length]; };
    stp(1); const a = g172[i].url; stp(1); const b = g172[i].url; stp(-1); const c = g172[i].url;
    return a === "w3" && b === "warpling" && c === "w3";
  })());
  // ⚠️ grouping on subjectId ALONE would have missed his own case — a beast has no subject record
  check("CCODE-172: a SUBJECT-less picture still groups its versions (the warpling has no subject at all)",
    runOf(g172, 20) !== null && g172[20].regen.subjectId === null);
  // …and two gallery tiles of the same PERSON group even without a shared origin
  const people = [{ url: "p1", regen: { kind: "npc", subjectId: "cevaine" } }, { url: "x", regen: { kind: "moment", subjectId: null } },
                  { url: "p2", regen: { kind: "npc", subjectId: "cevaine" } }];
  check("CCODE-172: two separate portraits of one person are one run", JSON.stringify(runOf(people, 0)) === JSON.stringify([0, 2]));

  check("CCODE-172: the app groups by origin AND subject", /const rootOf = \(x\) => x\?\.versionOf \|\| x\?\.url;/.test(src172)
    && /rootOf\(x\) === root \|\| \(sub && x\?\.regen\?\.subjectId === sub\)/.test(src172));
  check("CCODE-172: a draw records what it was drawn FROM", /versionOf: it\.versionOf \|\| it\.url/.test(src172));
  check("CCODE-172: a draw is inserted BESIDE its source, not at the end of the gallery",
    /list\.splice\(i \+ 1, 0, drawn\);/.test(src172) && !/list\.push\(drawn\)/.test(src172));
  check("CCODE-172: both the keys and the arrow buttons use ONE stepper (they cannot disagree)",
    (src172.match(/step\(-1\)/g) || []).length >= 2 && (src172.match(/step\(1\)/g) || []).length >= 2);
  check("CCODE-172: the caption says which ring the arrows are on", /version \$\{run\.indexOf\(i\) \+ 1\} of \$\{run\.length\}/.test(src172) && /in the gallery/.test(src172));

  // the fields + the prompt
  check("CCODE-172: every field the entry carries is shown", /class="lb-fields"/.test(src172)
    && ["caption", "kind", "subject", "world-day", "recorded", "seed", "kept looks", "source", "url"].every(k => src172.includes(`"${k}"`)));
  check("CCODE-172: the PROMPT is shown, and selectable so it can be taken", /class="lb-prompt"/.test(src172) && /user-select: text/.test(readFileSync(join(root, "style.css"), "utf8")));
  check("CCODE-172: …and it says so plainly when an older picture has no prompt on record", /not recorded for this image/.test(src172));
  check("CCODE-172: revealed on demand, not always-on (Aevi: prompts are long and some are spoiler-bearing)",
    /showMeta \? `<div class="lightbox-meta">/.test(src172) && /let showMeta = false;/.test(src172));
  check("CCODE-172: the gallery hands the whole entry through, so there ARE fields to show", /regen: galleryRegenFor\(g\), meta: g/.test(src172));
}

// ---- CCODE-171: one person, one identity, one face ----
// Erik: "there are still too many duplicate NPCs and People and Scenes… how can we make sure that the NPC
// image and name actually point to the same name and image set? Cevaine AND Cevaine of the 7th Order."
// ⛔ MEASURED FIRST: registry duplicates are RARE (one across every save). The duplication he sees is a
// person recorded in THREE id namespaces — registry id, codex topic id, authored content id — with the
// image seed taken from whichever surface he opened. Mara Wells is `mara-wells` to the portrait and
// `water-keeper` to the card: one woman, two faces, two sets of kept looks.
{
  const { canonicalPersonId, bareName, personArtSeed } = await import("../engine/npcs.js");

  // THE NAME INSIDE A LABEL — a codex label is a name plus what they are
  const bares = { "Leth — Edge District Archivist": "Leth", "Dara Holt, the Ditch-Mother": "Dara Holt",
    "Overseer Grael": "Grael", "Cevaine of the Seventh Measure": "Cevaine",
    "Neth, Who Has Buried More Than She Has Known": "Neth" };
  for (const [label, want] of Object.entries(bares))
    check(`CCODE-171: "${label}" is ${want}`, bareName(label) === want, bareName(label));

  // ⛔ AND THE GUARD THAT MAKES IT SAFE. A POSSESSIVE is a relation, never an epithet — `namesMatch` would
  // fold these together, which is why this deliberately is not namesMatch. Erik has just been bitten by a
  // wrong merge; over-folding a person costs far more than leaving two apart.
  check("CCODE-171: a possessive is a DIFFERENT person — Grael's Runner is not Grael", bareName("Grael's Runner — File Removal Witness") === "Grael's Runner");
  check("CCODE-171: …nor is Mara's errand-runner Mara", bareName("Pip Cotter, Mara's Errand-Runner") === "Pip Cotter");
  // ⚠️ THE GUARD, TESTED ON WHAT IT ACTUALLY PROTECTS. My first version mutated it away and nothing went
  // red, because the cases I had chosen carried a possessive OR an "of the", never both. A real alias from
  // Splarf's save carries both — and it names a THING Cevaine did, not Cevaine.
  check("CCODE-171: a possessive survives the epithet strip — \"Cevaine's Reading of the Veil-Breach\" is not a person's by-name",
    bareName("Cevaine's Reading of the Veil-Breach") === "Cevaine's Reading of the Veil-Breach", bareName("Cevaine's Reading of the Veil-Breach"));

  const reg171 = { npcRegistry: {
    cevaine: { id: "cevaine", name: "Cevaine" },
    grael: { id: "grael", name: "Grael" },
    leth: { id: "leth", name: "Leth", aliases: [] }
  } };
  check("CCODE-171 ERIK'S CASE: 'Cevaine of the Seventh Measure' resolves to Cevaine", canonicalPersonId(reg171, { label: "Cevaine of the Seventh Measure" }) === "cevaine");
  check("CCODE-171: a title does not make a second person", canonicalPersonId(reg171, { label: "Overseer Grael" }) === "grael");
  check("CCODE-171: a role-suffix does not either", canonicalPersonId(reg171, { label: "Leth — Edge District Archivist" }) === "leth");
  check("CCODE-171 THE REFUSAL: Grael's Runner stays their own person", canonicalPersonId(reg171, { label: "Grael's Runner — File Removal Witness" }) === null);
  check("CCODE-171: someone the registry has never heard of stays separate", canonicalPersonId(reg171, { label: "A Passing Stranger" }) === null);
  check("CCODE-171: an explicit link beats any name reasoning", canonicalPersonId(reg171, { npcId: "grael", label: "Cevaine" }) === "grael");
  check("CCODE-171: and a seed exists even for someone unknown (never a crash, never a shared 'undefined' face)",
    personArtSeed(reg171, { label: "A Passing Stranger" }).startsWith("whois-") && personArtSeed(reg171, { label: "Cevaine of the Seventh Measure" }) === "whois-cevaine");

  // ⚠️ THE REAL SAVES ARE THE FIXTURE — the report, asserted against what he actually plays
  for (const f of ["char-mrhs8286", "char-msgpisca"]) {
    const c = JSON.parse(readFileSync(join(root, `characters/player-s9z9u1/${f}.json`), "utf8"));
    const people = Object.values(c.codex?.topics || {}).filter(t => t.kind === "person");
    const split = people.filter(t => { const id = canonicalPersonId(c, { entityId: t.entityId || t.id, label: t.label }); return id && `whois-${t.entityId || t.id}` !== `whois-${id}`; });
    check(`CCODE-171: ${c.name}'s card and portrait now agree on every linked person`, people.length > 0 && split.every(t => !!canonicalPersonId(c, { entityId: t.entityId || t.id, label: t.label })),
      () => split.map(t => t.label).join("; "));
  }
  const src171 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ ASSERT THE USE, NOT THE PRESENCE. My first version checked that the resolver was CALLED — so cutting
  // its result out of the seed left the gate green while the bug came straight back.
  check("CCODE-171: the whois card seeds on the canonical identity, not the topic id",
    /const canonId = canonicalPersonId\(character, \{ entityId: known\.codexId \|\| known\.id, label: known\.label \}\);/.test(src171)
    && /const seedKey171 = canonId \|\| seed;/.test(src171)
    && /`whois-death-\$\{seedKey171\}` : `whois-\$\{seedKey171\}`/.test(src171));
  check("CCODE-171: and the codex page asks the same question, through the same helper",
    /personArtSeed\(character, \{ entityId: open\.entityId \|\| open\.id, topicId: open\.id, label: open\.label \}\)/.test(src171)
    && /export function personArtSeed/.test(readFileSync(join(root, "engine/npcs.js"), "utf8")));
}

// ---- CCODE-169: EVERY PICTURE THE PLAYER SEES CAN BE OPENED ----
// ⛔ ERIK ASKED THE RIGHT QUESTION: "have you run the audits lately and would they catch these?" The answer
// to the second half is NO, and the reason is worth writing down. The audits verify that MODULES talk to
// each other — exports, imports, call sites. All three bugs he found were INSIDE a module:
//   · the codex portrait had no `data-lightbox`      → an HTML attribute; no audit reads DOM
//   · the merge-undo button never rendered            → `undoLastMerge` WAS imported and called, so every
//                                                       wiring check reads it as fully wired
//   · the item-kind whitelist                         → a data literal, not an export
// Module granularity cannot see a conditional, an attribute, or a table key. That is the gap, and this is
// the first check aimed at it: a CENSUS of image surfaces, because "I count the writers and never count
// the readers" is exactly how the ninth surface stayed shut.
{
  const appSrc169 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ STRIP COMMENTS FIRST. My own note above — "found by counting <img> tags" — was picked up as a bare
  // image surface with no lightbox and failed the gate. That is the FOURTH time this session a checker has
  // matched the prose EXPLAINING the thing rather than the thing (wiring_audit documents the same trap and
  // I walked into it anyway). A census of markup must read markup.
  const markup169 = appSrc169.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^\s*\/\/.*$/gm, "");
  const tags = [...markup169.matchAll(/<img\s[^>]*>/g)].map(m => m[0]);
  // the lightbox's OWN img is the one that must not be openable — it is already open.
  const surfaces = tags.filter(t => !/data-lbimg/.test(t));
  const shut = surfaces.filter(t => !/data-lightbox/.test(t));
  check(`CCODE-169: all ${surfaces.length} image surfaces open (a picture you cannot look at is a picture you cannot fix)`,
    surfaces.length >= 10 && shut.length === 0,
    () => shut.map(t => t.replace(/\s+/g, " ").slice(0, 90)).join(" || "));

  // ⚠️ AND A FACE MUST BE REDRAWABLE, not merely viewable. A quest illustration or a scene banner has no
  // subject record to redraw against, so view-only is the honest answer there; a PERSON is different.
  const faces = surfaces.filter(t => /class="(?:whois-portrait|comp-portrait|cs-portrait|codex-top-art)"/.test(t));
  const faceless = faces.filter(t => !/data-regen-kind/.test(t));
  check(`CCODE-169: all ${faces.length} PORTRAIT surfaces carry regen provenance (a face you cannot redraw is the whole complaint)`,
    faces.length >= 4 && faceless.length === 0,
    () => faceless.map(t => t.replace(/\s+/g, " ").slice(0, 90)).join(" || "));

  // the tenth surface, found by counting rather than by Erik hitting it
  check("CCODE-169: the COMPANION portrait — found by census, not by report", /class="comp-portrait"[^>]*data-regen-kind="figure"/.test(appSrc169));
  // the companion's panel re-mints on every open, so a kept look has to outrank the mint there too
  const compBlock = appSrc169.slice(appSrc169.indexOf("const artSeed = `companion-"), appSrc169.indexOf("const artSeed = `companion-") + 700);
  check("CCODE-169: a companion's kept look survives the re-mint, like every other person's",
    /const chosen = character\?\.figureImages/.test(compBlock) && /const url = chosen \|\| ensureImage/.test(compBlock));
}

// ---- CCODE-168: an item in a kind nobody listed is counted and never shown ----
// Erik: "I don't see my shadow tablet in my inventory" — with the header reading 27 and twenty-six tiles on
// screen. The bag rendered from a hard-coded five-kind whitelist while content ships SEVEN, so every
// `focus`, `relic` and `armor` item in the game was invisible. My tablet was the one that made it visible.
{
  const { ITEM_KINDS, itemKindsIn, itemKindLabel, addItem: addI168 } = await import("../engine/inventory.js");

  // ⛔ THE CLASS, NOT THE INSTANCE: every shipped item must fall in a kind the bag can render.
  const shipped = [];
  const walk168 = (d) => { for (const f of readdirSync(d, { withFileTypes: true })) {
    const pth = join(d, f.name);
    if (f.isDirectory()) walk168(pth);
    else if (f.name.endsWith(".json")) { try { const j = JSON.parse(readFileSync(pth, "utf8"));
      const arr = Array.isArray(j) ? j : (j.items || []);
      if (Array.isArray(arr)) for (const a of arr) if (a && a.name && a.kind && (a.worth || a.bonusTags || a.consumable !== undefined)) shipped.push(a);
    } catch { /* not an item pack */ } } } };
  walk168(join(root, "content/packs"));
  const orphan = shipped.filter(i => !ITEM_KINDS.includes(i.kind));
  check(`CCODE-168: all ${shipped.length} shipped items fall in a kind the bag can render`, shipped.length > 20 && orphan.length === 0,
    () => [...new Set(orphan.map(i => `${i.kind} (${i.name})`))].join("; "));
  check("CCODE-168: the kinds that were invisible are in the vocabulary", ["focus", "relic", "armor"].every(k => ITEM_KINDS.includes(k)));

  // ⛔ A CENSUS, NOT A WHITELIST — a kind nobody thought of is still the player's item
  const bag = [{ name: "a", kind: "weapon" }, { name: "b", kind: "focus" }, { name: "c", kind: "wholly-new-kind" }];
  const ks = itemKindsIn(bag);
  check("CCODE-168: an UNKNOWN kind still gets a section rather than vanishing", ks.includes("wholly-new-kind"));
  check("CCODE-168: …and the known kinds keep their display order in front of it", ks.indexOf("weapon") < ks.indexOf("focus") && ks.indexOf("focus") < ks.indexOf("wholly-new-kind"));
  check("CCODE-168: EVERY item in a bag is accounted for by some section (the header count and the tiles agree)", (() => {
    const shown = itemKindsIn(bag).reduce((n, k) => n + bag.filter(i => i.kind === k).length, 0);
    return shown === bag.length;
  })());
  check("CCODE-168: headings are words — not 'focuss' or 'armors'", itemKindLabel("focus") === "focus items" && itemKindLabel("armor") === "armour" && itemKindLabel("weapon") === "weapons");

  // the OTHER copy of the same whitelist: a GM-conferred focus was silently flattened to misc
  const ch168 = { inventory: [] };
  addI168(ch168, { name: "A Prism Lens", kind: "focus", description: "a lens" }, {});
  check("CCODE-168: a GM-conferred item KEEPS its kind (the second copy of the whitelist flattened it to misc)",
    ch168.inventory[0].kind === "focus");
  addI168(ch168, { name: "A Nonsense", kind: "not-a-kind" }, {});
  check("CCODE-168: …while a genuinely bogus kind still clamps to misc", ch168.inventory.find(i => i.name === "A Nonsense").kind === "misc");

  const src168 = readFileSync(join(root, "app.js"), "utf8");
  check("CCODE-168: the bag renders from the census and there is no second whitelist left", /const kinds = itemKindsIn\(character\.inventory \|\| \[\]\);/.test(src168)
    && !/\["weapon", "tool", "consumable", "quest", "misc"\]/.test(src168));
  check("CCODE-168: an item with NO kind at all is still shown", /const kindless = inv\.filter\(i => !i\?\.kind\);/.test(src168) && /\$\{grid\}\$\{extra\}/.test(src168));

  // Erik's own bag, with the reclaim applied — the report, asserted
  const silas168 = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-mrhs8286.json"), "utf8"));
  const withTablet = [...(silas168.inventory || []), { id: "shadow_tablet", name: "Shadow Tablet", kind: "focus" }];
  const rendered = itemKindsIn(withTablet).reduce((n, k) => n + withTablet.filter(i => i.kind === k).length, 0);
  check("CCODE-168: Silas's bag WITH the tablet renders every item it counts", rendered === withTablet.length, `${rendered}/${withTablet.length}`);
}

// ---- CCODE-167: a merge the player made by hand had no way back, and the dialog SAID so ----
// Erik: "I accidentally merged Cevaine the person with Cevaine Lore in the codex... :(" — and he was right
// to think it was gone, because the confirm box told him "This can't be undone." ⛔ IT WAS NEVER TRUE.
// mergeInto has written an undo receipt since SNG-153 (its own line: "the player's own merge is undoable
// too") — but the undo button rendered only beside the AUTO-merge digest, so a hand-made merge recorded a
// receipt nobody could reach. A capability, a UI that hid it, and copy that denied it.
{
  const { mergeInto: mi167, undoLastMerge: undo167, ensureCodex: ec167 } = await import("../engine/codex.js");
  const mk167 = () => { const c = { codex: { topics: {
    person: { id: "person", label: "Cevaine of the Seventh Measure", kind: "person", facts: ["[d3] she held the veil"], links: ["thinning"], aliases: ["Cevaine"], entityId: "cevaine" },
    lore: { id: "lore", label: "Cevaine", kind: "lore", facts: ["[d4] the practice as witness"], links: [], aliases: [] },
    thinning: { id: "thinning", label: "The Thinning", kind: "place", facts: [], links: ["person"], aliases: [] }
  } } }; ec167(c); return c; };

  const c167 = mk167();
  mi167(c167, "person", "lore");
  check("CCODE-167: a hand-made merge WRITES a receipt (it always did)", (c167.codex.mergeUndo || []).length === 1);
  check("CCODE-167: …and the merge really happened", !c167.codex.topics.person && c167.codex.topics.lore.facts.length === 2);
  const r167 = undo167(c167);
  check("CCODE-167 THE FIX: Erik's exact merge comes back", r167?.restored === "Cevaine of the Seventh Measure" && !!c167.codex.topics.person);
  check("CCODE-167: the person returns WHOLE — facts, links, aliases, entityId", (() => {
    const p = c167.codex.topics.person;
    return p.facts[0] === "[d3] she held the veil" && p.links[0] === "thinning" && p.aliases[0] === "Cevaine" && p.entityId === "cevaine";
  })());
  check("CCODE-167: and the entry it was folded into is rewound, not left holding both", (() => {
    const l = c167.codex.topics.lore;
    return l.facts.length === 1 && l.aliases.length === 0;
  })());
  check("CCODE-167: a third topic's link back to it is repaired too (an un-merge that strands links is half an un-merge)",
    c167.codex.topics.thinning.links[0] === "person");
  check("CCODE-167: undoing consumes its receipt — a second press cannot double-restore", (c167.codex.mergeUndo || []).length === 0 && undo167(c167) === null);

  // BY INDEX — an accidental merge is not always the last thing you did
  const c2 = mk167();
  c2.codex.topics.other = { id: "other", label: "A Road", kind: "place", facts: [], links: [], aliases: [] };
  mi167(c2, "person", "lore");
  mi167(c2, "other", "thinning");
  check("CCODE-167: an OLDER merge is still reachable by index", undo167(c2, 0)?.restored === "Cevaine of the Seventh Measure" && !!c2.codex.topics.person && !c2.codex.topics.other);

  const src167 = readFileSync(join(root, "app.js"), "utf8");
  // ⚠️ SCOPED TO THE MERGE DIALOG. My first version asserted the phrase was absent from the WHOLE FILE and
  // failed on two innocent hits: the character-DELETE confirm, where "this can't be undone" is true and
  // must stay, and my own comment quoting the old copy. A checker satisfied — or broken — by the note
  // explaining a bug is import_integrity's documented blind spot, arriving yet again.
  const mergeConfirm167 = (src167.match(/if \(!confirm\(`Fold [^`]*`\)\) return;/) || [""])[0];
  check("CCODE-167: the MERGE dialog no longer claims the merge is permanent",
    !!mergeConfirm167 && !/can't be undone/.test(mergeConfirm167) && /You can undo this/.test(mergeConfirm167), mergeConfirm167.slice(0, 120));
  check("CCODE-167: …while the character-DELETE dialog still says so, because there it is TRUE",
    /Delete <strong>\$\{esc\(c\?\.name \|\| "this character"\)\}<\/strong>\? This can't be undone/.test(src167));
  check("CCODE-167: the undo is offered whenever there is something to undo, not only after an auto-merge",
    /\(character\.codex\?\.mergeUndo \|\| \[\]\)\.length \|\| character\._codexDigest/.test(src167));
  check("CCODE-167: a hand-made merge leaves a receipt saying what it did", /character\._codexDigest = `Folded "\$\{foldedLabel\}" into/.test(src167));
  check("CCODE-167: the button carries an INDEX, so it can reach past the newest merge", /data-codexundo="/.test(src167) && /undoLastMerge\(character, Number\(b\.dataset\.codexundo\)\)/.test(src167));
}

// ---- CCODE-166: the tiles with no buttons at all ----
// Erik: "new buttons are now missing from #11/22 and 19/22 in Splarf's gallery." Two causes, both mine.
{
  const { namesMatch: nm166 } = await import("../engine/namematch.js");
  const src166 = readFileSync(join(root, "app.js"), "utf8");

  // ⛔ (a) I HAND-ROLLED AN EXACT COMPARISON WHERE THE PROJECT ALREADY HAD THE RIGHT ONE. Splarf's gallery
  // captions a tile "Cevaine of the Seventh Measure" while his registry says "Cevaine" — SNG-111's case,
  // and precisely what `namesMatch` exists for. Lowercase equality failed it, so a real portrait of a known
  // person offered no controls at all.
  check("CCODE-166: a fuller caption resolves to the known person (Cevaine of the Seventh Measure → Cevaine)",
    nm166("Cevaine", "Cevaine of the Seventh Measure") === true);
  check("CCODE-166: …and it stays conservative — a DESCRIPTION still matches nobody",
    nm166("The Waystation Caretaker", "someone tending the waystation fire") === false && nm166("Cevaine", "someone tending the waystation fire") === false);
  check("CCODE-166: the resolver uses that helper rather than a fresh one", /namesMatch\(n\.name, nm\)/.test(src166) && /namesMatch\(character\.name, nm\)/.test(src166));

  // (b) an UNNAMED person's picture is still a picture — drawable, just not a subject to vote on
  check("CCODE-166: an unnamed subject's tile still draws instead of going dead", /return g\.prompt \? mk\("moment", null\) : null;/.test(src166));

  // ⛔ AND A VOTE NEEDS SOMETHING TO VOTE ON. Keep on a prompt-only tile has a null likeness key, so it
  // would have reported success and recorded nothing.
  check("CCODE-166: Keep requires a subject — a vote that attaches to nothing is a lie that looks like a feature",
    /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src166));

  // crafts and places have names too — most of a gallery was drawable but not keepable
  check("CCODE-166: a craft tile resolves by its own name, so its look can be kept", /if \(g\.kind === "ability" \|\| g\.kind === "discovery"\) \{/.test(src166) && /namesMatch\(cat\[k\]\.name, nm\)/.test(src166));
  check("CCODE-166: a place tile does too", /if \(g\.kind === "location"\) \{/.test(src166) && /namesMatch\(CONTENT\.locations\[k\]\.name, nm\)/.test(src166));

  // ⚠️ THE REAL SAVE IS THE FIXTURE. Every tile with a url must offer SOMETHING; this is the report Erik
  // filed, asserted against the gallery he filed it about.
  const splarf = JSON.parse(readFileSync(join(root, "characters/player-s9z9u1/char-msgpisca.json"), "utf8"));
  const tiles = (splarf.gallery || []).filter(g => g && g.url);
  const dead = tiles.filter(g => !g.prompt && !(g.subjectKind && g.subjectId));
  check(`CCODE-166: every one of Splarf's ${tiles.length} tiles has something to draw from`, tiles.length > 0 && dead.length === 0,
    () => dead.map(g => `${g.kind}: ${g.caption}`).join("; "));
  const named = tiles.filter(g => g.kind === "npc" || g.kind === "portrait");
  const resolved = named.filter(g => {
    const n = String(g.caption || "").split("—")[0].trim();
    return nm166(splarf.name, n) || Object.values(splarf.npcRegistry || {}).some(x => x?.name && nm166(x.name, n));
  });
  check("CCODE-166: the people-tiles that name a known person now resolve to them", named.length > 0 && resolved.length >= named.length - 1,
    () => `${resolved.length}/${named.length} resolved`);
}

// ---- CCODE-164/165: Keep is a VOTE on the likeness, and the codex leads with its subject's face ----
// Erik, redefining the feature after playing: "the keep button should be a highly weighted vote — I like
// the way one image came out so I want to keep that look as the person in any future renderings. If I like
// two images I should be able to keep both, or as many as I want."
{
  const { likenessClause, withLikeness, toggleKeep, likenessSeed, setArtMode: setArt164,
          regenerateImage: regen164, ensureImage: ensure164 } = await import("../engine/art.js");
  const was164 = localStorage.getItem("singularity.artMode");
  setArt164("generate");
  const keeps = [
    { url: "a", prompt: "silver hair, sharp cheekbones, grey wool cloak, a scar at the jaw" },
    { url: "b", prompt: "pale eyes, silver hair, grey wool cloak, lantern light" }
  ];
  const clause = likenessClause(keeps);
  check("CCODE-164 THE VOTE: what two kept pictures AGREE on leads the likeness", /^silver hair, grey wool cloak/.test(clause), clause);
  check("CCODE-164: …and what only one of them says still rides, behind the agreement", /sharp cheekbones/.test(clause) && /pale eyes/.test(clause), clause);
  check("CCODE-164: one keep is a whole vote, in its own order", likenessClause([keeps[0]]).startsWith("silver hair, sharp cheekbones"));
  // ⚠️ THE CASE HAS TO DISCRIMINATE. My first version asserted a thrice-repeated term still led — which it
  // does whether or not repetition is deduped, so the check proved nothing and the mutation stayed green.
  // Now: a term repeated three times in ONE keep must LOSE to a term two SEPARATE keeps agree on.
  check("CCODE-164: a prompt repeating itself is still ONE vote — genuine agreement outranks ballot-stuffing",
    likenessClause([{ url: "x", prompt: "red hat, red hat, red hat, blue coat" }, { url: "y", prompt: "blue coat, green boots" }]).startsWith("blue coat"));
  check("CCODE-164: nothing kept = nothing added (the prompt is untouched)", likenessClause([]) === "" && withLikeness("a smith at her anvil", []) === "a smith at her anvil");
  check("CCODE-164: the likeness LEADS the prompt (a diffusion prompt weights its opening most)", withLikeness("a smith at her anvil", keeps).startsWith("silver hair"));
  check("CCODE-164: the clause is bounded — a preference, never an average of everything",
    likenessClause(Array.from({ length: 8 }, (_, i) => ({ url: `u${i}`, prompt: `trait${i} aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa, common thing` }))).length <= 240);

  const store = {};
  toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair", seedKey: "s1" });
  toggleKeep(store, "npc:pell", { url: "u2", prompt: "grey wool", seedKey: "s2" });
  check("CCODE-164: keeps ACCUMULATE — two liked pictures both guide the face", store["npc:pell"].keeps.length === 2);
  const off = toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair" });
  check("CCODE-164: the same button withdraws a vote (a vote you cannot take back is a trap)", off.kept === false && store["npc:pell"].keeps.length === 1);
  check("CCODE-164: re-keeping restores it", toggleKeep(store, "npc:pell", { url: "u1", prompt: "silver hair" }).kept === true);
  check("CCODE-164: keeps are capped — past a handful it stops being a preference and becomes an average",
    (() => { const s2 = {}; for (let i = 0; i < 20; i++) toggleKeep(s2, "k", { url: `u${i}`, prompt: `p${i}` }); return s2.k.keeps.length <= 8; })());
  check("CCODE-164: a kept SEED anchors a fresh mint (the strongest consistency lever a diffusion model has)",
    likenessSeed(store["npc:pell"].keeps) !== null && likenessSeed([]) === null);

  const pell164 = { id: "pell164", name: "Pell", description: "a village blacksmith" };
  ensure164(pell164, "npc", { ratingLevel: 2, promptOpts: { keeps } });
  check("CCODE-164: a FIRST mint of a liked subject is drawn toward the kept look", decodeURIComponent(pell164.image).includes("silver hair"));
  const rr = regen164({ id: "p2", name: "Pell", description: "a village blacksmith" }, "npc", { ratingLevel: 2, attempt: 1, promptOpts: { keeps } });
  check("CCODE-164: a RE-ROLL keeps the face and changes only the draw", decodeURIComponent(rr.url).includes("silver hair"));
  const rb = regen164({ id: "p3", name: "Pell" }, "npc", { ratingLevel: 2, attempt: 1, promptOpts: { keeps }, promptOverride: "a bald man in red armour" });
  check("CCODE-164: a REBUILD is NOT overridden by old votes — describing it differently must mean something",
    decodeURIComponent(rb.url).includes("bald man in red armour") && !decodeURIComponent(rb.url).includes("silver hair"));
  check("CCODE-164: the FLOORS still run after the likeness (a liked look cannot smuggle past the ceiling)",
    decodeURIComponent(regen164({ id: "p4", name: "X" }, "npc", { ratingLevel: 0, attempt: 1, promptOpts: { keeps: [{ url: "z", prompt: "an erotic nude study" }] } }).url).match(/erotic|nude/) === null);

  const src165 = readFileSync(join(root, "app.js"), "utf8");
  const codexFn = src165.slice(src165.indexOf("function codexTopImage"));
  check("CCODE-165: the codex topic page renders its subject at the top", /\$\{codexTopImage\(open\)\}/.test(src165));
  // ⚠️ RE-AIMED (CCODE-171): both surfaces now build the seed through ONE helper rather than each spelling
  // `whois-${seed}` for itself — which is a stronger form of the same property, so the gate asserts THAT.
  check("CCODE-165: it uses the SAME seed builder as the popup, so it is the same person and not a second one",
    /personArtSeed\(character, \{ entityId: open\.entityId \|\| open\.id, topicId: open\.id, label: open\.label \}\)/.test(codexFn));
  check("CCODE-165: it opens into the lightbox with the same controls", /class="codex-top-art"[^`]*data-lightbox="figure"[^`]*data-regen-kind="figure"/.test(src165));
  check("CCODE-165: only entries that HAVE a subject get a face (an event or a mystery is not a person)", /CODEX_PICTURABLE = new Set\(\["person", "place"\]\)/.test(src165));
  check("CCODE-165: a kept look wins on the codex page too", /const chosen = character\?\.figureImages\?\.\[artSeed\] \|\| null;/.test(codexFn) && /const url = chosen \|\|/.test(codexFn));
  check("CCODE-164: the votes reach the paths that draw people (bond portraits and figure cards)", (src165.match(/keeps: keepsForSubject\(/g) || []).length >= 2);
  if (was164) localStorage.setItem("singularity.artMode", was164);
}

// ---- CCODE-163: the two gaps Erik found by testing SNG-401 ----
// (1) "I don't see where I can select a portrait as Canon."  (2) "the popups that read the codex entry
// don't have an image popup at all."  Both were mine: I gated Keep too narrowly, and I counted eight
// lightbox call sites when there are nine.
{
  const src163 = readFileSync(join(root, "app.js"), "utf8");

  // (2) THE NINTH SURFACE — the whois/codex card's portrait could not even be opened.
  check("CCODE-163: the codex/whois portrait opens the lightbox and carries its provenance",
    /class="whois-portrait"[^`]*data-lightbox="figure"[^`]*data-regen-kind="figure"[^`]*data-regen-subject=/.test(src163));
  check("CCODE-163: `figure` is a real regen kind — found, current, and keepable", (() => {
    // ⚠️ SLICE TO THE NEXT ENTRY, NOT N CHARACTERS. These read a fixed 600/700-char window from the entry
    // start, so adding a comment inside an entry pushed its own properties out of view and failed a gate
    // about the properties. A window measured in bytes is a window that closes when you explain something.
    const tbl = src163.slice(src163.indexOf("const REGEN_KINDS = {"), src163.indexOf("// SNG-401 §1, Aevi's constraint"));
    const NEXT_ENTRY = new RegExp("\\n  \\w+: \\{");
    const entryOf = (k) => { const i = tbl.indexOf(`${k}: {`); if (i < 0) return ""; const nxt = tbl.slice(i + 1).search(NEXT_ENTRY); return nxt < 0 ? tbl.slice(i) : tbl.slice(i, i + 1 + nxt); };
    const blk = entryOf("figure");
    // ⚠️ CCODE-181 widened `find` to fall back to the registry — the epic roster holds 66 legends while the
    // card opens for anyone the player knows, so every ordinary NPC resolved to nothing. Both halves gated.
    return /find: id => figureArtRecord\(rosterFigureOf\(id\)/.test(blk) && /character\?\.npcRegistry\?\.\[String\(id\)\.replace/.test(blk)
      && /current: id => character\?\.figureImages/.test(blk) && /keep: \(id, url\) =>/.test(blk);
  })());
  check("CCODE-163: a figure's seed maps back to the person, alive or dead", /replace\(\/\^whois-\(\?:death-\)\?\/, ""\)/.test(src163));
  // ⛔ the card re-mints from a stable seed on every open, so a chosen picture MUST outrank the mint
  check("CCODE-163: a picture the player chose beats the re-mint (else Keep is undone on the next open)",
    /const chosen = character\?\.figureImages\?\.\[artSeed\] \|\| null;/.test(src163) && /const url = chosen \|\| ensureImage\(/.test(src163));

  // (1) SELECT AN EXISTING PICTURE AS THE ONE — Keep was reachable only from a fresh draw
  // ⚠️ SUPERSEDED BY CCODE-164 AND THE CHANGE IS THE POINT. When Keep meant "make this the portrait", it
  // was correct to hide it on the picture already in use — a no-op button. Now it means "this is what they
  // look like", which is a DIFFERENT statement from "this is the one shown", and is perfectly sensible to
  // cast on the current picture. What must still never appear is a Keep with nothing to attach to.
  check("CCODE-163/164/166: Keep is offered on any picture WITH A SUBJECT, new draw or not", /const canKeep = !!it\.regen\?\.subjectId && !!spec\?\.keep;/.test(src163));
  check("CCODE-163/164: …and never where there is no subject to attach a look to (the '✕ couldn't keep' Erik hit)",
    /needsId: true/.test(src163) && /REGEN_KINDS\[k\] && !REGEN_KINDS\[k\]\.needsId \? k : "moment"/.test(src163));
  check("CCODE-163/172: the caption says WHICH picture is the one in use, so 'use this one' has a reference point",
    /isCurrent && "the one in use"/.test(src163));
  check("CCODE-163: every regenerable kind can say what its current picture is", (() => {
    const tbl = src163.slice(src163.indexOf("const REGEN_KINDS = {"), src163.indexOf("// SNG-401 §1, Aevi's constraint"));
    // the record-backed kinds must all answer `current`; the prompt-only ones (moment/beast/battle/death) need not
    const NEXT_ENTRY = new RegExp("\\n  \\w+: \\{");
    const entryOf = (k) => { const i = tbl.indexOf(`${k}: {`); if (i < 0) return ""; const nxt = tbl.slice(i + 1).search(NEXT_ENTRY); return nxt < 0 ? tbl.slice(i) : tbl.slice(i, i + 1 + nxt); };
    return ["npc", "character", "figure", "location", "item", "ability", "beast"].every(k => /current:/.test(entryOf(k)));
  })());
  // the lightbox must sit ABOVE the card it was opened from, or the picture opens invisibly
  const css163 = readFileSync(join(root, "style.css"), "utf8");
  check("CCODE-163: the lightbox outranks the whois overlay it opens from", (() => {
    const z = (re) => Number((css163.match(re) || [])[1] || 0);
    return z(/\.lightbox \{[^}]*z-index:\s*(\d+)/) > z(/\.help-overlay \{[^}]*z-index:\s*(\d+)/);
  })());
}

// ---- CCODE-162: ONE COMMUNITY, ONE SPELLING (within a region) ----
// ⛔ FOUND BY AN INTERMITTENT GATE, WHICH IS THE WORST WAY TO FIND ANYTHING. "…and the first hop is
// somewhere in its OWN region" failed roughly two runs in three, and only after teaching `check` to print
// the detail its call site had always passed did the cause show: the deed hopped to `echo_vale.millbrook`
// while it started from `valley.millbrook`. ONE community, two spellings — the tail of SNG-427, where the
// regionId was repointed to `valley` and the communityId kept the old prefix.
//
// ⚠️ THE RULE IS NARROW ON PURPOSE. `center.gate` (The Axis Gate) and `abyssal.gate` (The Bargain Gate) are
// genuinely two places that share a leaf name in different regions — that is prefixes doing their job, and
// a cruder "no leaf twice" rule would fail on correct data. The real invariant: WITHIN ONE REGION, a
// community leaf resolves to exactly one full id.
{
  const dir162 = join(root, "content/packs/valley/locations");
  const groups = new Map();
  for (const f of readdirSync(dir162).filter(x => x.endsWith(".json"))) {
    const l = JSON.parse(readFileSync(join(dir162, f), "utf8"));
    if (!l.communityId) continue;
    const key = `${l.regionId || l.region || "?"}::${String(l.communityId).split(".").pop()}`;
    (groups.get(key) || groups.set(key, new Set()).get(key)).add(l.communityId);
  }
  const split = [...groups.entries()].filter(([, s]) => s.size > 1);
  check("CCODE-162: no community is spelled two ways inside one region (it splits the place in half)",
    split.length === 0, () => split.map(([k, s]) => `${k} → ${[...s].join(" | ")}`).join("; "));
  // the fix itself, pinned: the Crossing follows the region it was moved to
  const xing = JSON.parse(readFileSync(join(dir162, "echo_river_crossing.json"), "utf8"));
  check("CCODE-162: the Crossing's community follows its region (Aevi moved it to valley; the id now agrees)",
    xing.regionId === "valley" && xing.communityId === "valley.millbrook",
    `regionId=${xing.regionId} communityId=${xing.communityId}`);
  // ⚠️ and the harness change that made this findable at all
  const smokeSrc162 = readFileSync(join(root, "tests/smoke.mjs"), "utf8");
  check("CCODE-162: check() renders the failure detail its call sites pass (a written diagnostic with no reader)",
    /function check\(name, cond, detail = null\)/.test(smokeSrc162) && /if \(detail\) console\.log/.test(smokeSrc162));
}

// ⚠️ ANYTHING APPENDED BELOW `process.exit` NEVER RUNS. This bit me: eight minting checks were added to
// the end of this file, the suite went green, and not one of them had executed. A test that cannot fail is
// worse than no test — it is a green light with nothing behind it. This guard makes the trap visible.
// ---- CCODE-191: no source file may carry a control character ----------------------------------------
// ⛔ FOUND BY ACCIDENT, AND IT WAS ALREADY SHIPPED. Three regexes in app.js carry a literal BACKSPACE
// (U+0008) where \\b was intended — `teaching`, `finished` and `splitWords`, the guards for "someone is
// teaching me this", "this is finished", and "split the spear". `/\b(taught|teaches|…)\b/` can only match
// text that literally contains a backspace, so ALL THREE HAVE NEVER FIRED in play.
//
// ⚠️ THE CAUSE IS MY OWN TOOLING, four times in one session: a shell heredoc hands python "\\b", python
// reads it as the backspace escape, and the file gets a control character that greps clean, renders
// invisibly, and silently turns a word-boundary guard into a dead one. Reviewing the diff does not catch
// it — the character has no width. A machine has to look.
{
  // ⚠️ WRITTEN AS \uXXXX ESCAPES, DELIBERATELY. Spelled with raw bytes — which is how it arrived the
  // first time — the gate's own pattern would carry the very characters it exists to forbid, and fail on
  // itself. A checker that cannot survive its own rule is not a checker.
  const CONTROL = new RegExp("[\u0000-\u0008\u000b\u000c\u000e-\u001f]");
  const scanned = [], dirty = [];
  const roots = ["app.js", "engine", "tests", "scripts"];
  const walk = (rel) => {
    const abs = join(root, rel);
    let st; try { st = statSync(abs); } catch { return; }
    if (st.isDirectory()) { for (const f of readdirSync(abs)) walk(rel + "/" + f); return; }
    if (!/\.(js|mjs)$/.test(rel)) return;
    scanned.push(rel);
    const txt = readFileSync(abs, "utf8");
    const m = txt.match(CONTROL);
    if (m) {
      const at = txt.indexOf(m[0]);
      dirty.push(`${rel}:${txt.slice(0, at).split("\n").length} (U+${m[0].charCodeAt(0).toString(16).padStart(4, "0")})`);
    }
  };
  for (const r of roots) walk(r);
  check(`CCODE-191: no source file carries a control character (${scanned.length} files scanned)`,
    dirty.length === 0, `a \b written as a literal backspace is an invisible dead regex: ${dirty.slice(0, 5).join(" · ")}`);
}

// ---- SNG-433: the clash news, in the authored voice ------------------------------------------------
// ⛔ ERIK'S THREE QUESTIONS OF THE NEWS — "coherent? interesting? obvious why it's news?" — answered no,
// no and no, because the four sentences were written by an engine and one of them printed a full name
// twice. Aevi re-authored them; these gates are that the words a PLAYER READS come from her file.
{
  const NV = await import("../engine/newsvoice.js");
  const { applyEpicClashOutcome: applyClash433, advanceGeneratedOffscreen: tick433, initWorldState: initWs433 } =
    await import("../engine/worldtick.js");
  const { loadContentHeadless: lch433 } = await import("./headless_content.mjs");
  const C433 = await lch433();
  const T433 = C433.rules?.newsTemplates;

  // 1 · REGISTERED **AND** LOADED. Authored at b197b719, in no manifest, read by nothing — the same
  // invisible-one-step-earlier failure as the name pools, on the very next file Aevi shipped.
  check("433: news_templates is registered AND loaded onto rules.newsTemplates (not merely on disk)",
    !!T433?.templates && !!T433?.fragments,
    `rules.newsTemplates = ${JSON.stringify(Object.keys(T433 || {}))}`);

  // 2 · ⛔ THE ENGINE SAYS "stopped"; THE AUTHOR WROTE "checked". An unmapped outcome returns undefined and
  // falls silently back to the hardcoded line — the exact way a wired file stays unwired.
  {
    const missing = Object.entries(NV.OUTCOME_TEMPLATE_KEY).filter(([, k]) => !T433?.templates?.[k]);
    const thin = Object.entries(T433?.templates || {}).filter(([, b]) => !b.rival || !b.mutual || !b.stranger);
    check("433: every outcome the engine can produce names a template block that exists, with all three relationships",
      missing.length === 0 && thin.length === 0 && Object.keys(NV.OUTCOME_TEMPLATE_KEY).length === 4,
      `unmapped=${missing.map(m => m[0])} thin=${thin.map(t => t[0])}`);
  }

  // 3 · THE TEXT COMES FROM THE FILE. Not "the function exists" — the sentence a player reads is hers.
  {
    const A433 = { id: "a433", name: "The Hollow King of the Wild Half", rivals: ["b433"] };
    const B433 = { id: "b433", name: "Neth, Who Has Buried More Than She Has Known", rivals: ["a433"] };
    const out = applyClash433({}, A433, B433, "stopped", 12, { content: C433 });
    const text = out.news[0]?.text || "";
    // ⚠️ THE LITERAL IS LIFTED FROM THE FILE, NOT RETYPED HERE. A gate carrying its own copy of Aevi's prose
    // goes green while she rewords it, and then guards nothing — the longest run of words BETWEEN the
    // placeholders is whatever she wrote today.
    const authored = T433.templates.checked.mutual.split(/\{[a-zA-Z]+\}/)
      .map(s => s.trim()).sort((a, b) => b.length - a.length)[0];
    check("433: a 'stopped' clash is reported in the AUTHORED words (the 'checked' block), not the engine's own line",
      text.includes(authored) && !/checked .*for now/.test(text), `${text.slice(0, 120)} ⟵ wanted "${authored}"`);
    // 4 · SHORT FORM ON SECOND MENTION — the stutter Erik saw, measured rather than eyeballed.
    check("433: the full name appears ONCE and the second mention is short",
      text.split(B433.name).length === 2 && text.includes("Neth") && text.lastIndexOf("Neth") > text.indexOf(B433.name),
      text);
  }

  // 5 · THE SHORT-NAME RULE, RE-VERIFIED ON THE REAL CORPUS. Aevi's first rule produced "Morvane of the";
  // her claim about the second is "0 cut on a stopword across all 66". Claim, therefore gate.
  {
    const names = (C433.legends?.roster || []).map(f => f?.name).filter(Boolean);
    const bad = names.filter(n => /\b(of|who|that|the|a|an|and|or|with|in|at|on|to|for|by|from)$/i.test(NV.shortName(n).trim()));
    const shortened = names.filter(n => NV.shortName(n) !== n);
    check(`433: no authored name shortens onto a preposition or article (${names.length} names, ${shortened.length} shorten)`,
      names.length > 60 && bad.length === 0 && shortened.length > 20, bad.slice(0, 4).join(" · "));
  }

  // 6 · THE RELATIONSHIP IS WHY IT IS NEWS. Three different sentences for the same two people, chosen by
  // `rivals` — a field authored on 58 of 66 figures and read by nothing since SNG-208.
  {
    const line = (ar, br) => NV.clashLine({ templates: T433.templates, outcome: "killed",
      winner: { id: "x", name: "Winner Name Here", rivals: ar ? ["y"] : [] },
      loser: { id: "y", name: "Loser Name Here", rivals: br ? ["x"] : [] }, place: "The Maw" });
    const mutual = line(true, true), rival = line(true, false), stranger = line(false, false);
    check("433: mutual, rival and stranger are three DIFFERENT sentences for the same two figures",
      mutual !== rival && rival !== stranger && mutual !== stranger && [mutual, rival, stranger].every(s => s && s.includes("The Maw")),
      `${mutual}\n      ${rival}\n      ${stranger}`);
  }

  // 7 · ⛔ NO PLACE → DROP THE PHRASE, NEVER "at null".
  {
    const noPlace = NV.clashLine({ templates: T433.templates, outcome: "killed",
      winner: { id: "x", name: "A Winner" }, loser: { id: "y", name: "A Loser" }, place: null });
    // ⚠️ AND A DANGLING " at ." IS THE SAME BUG WEARING BETTER MANNERS. Emptying the slot instead of
    // dropping the phrase leaves "killed them at ." — which no assertion about the word "null" can see.
    check("433: a clash with no place drops ' at {place}' rather than printing 'at null' or a dangling 'at'",
      !!noPlace && !/\bat (null|undefined|\{place\})/.test(noPlace) && !/\bat\s*([.,;—]|$)/.test(noPlace)
      && !/\s{2,}/.test(noPlace), noPlace);
  }

  // 8 · ⛔ A DISPLAY NAME, NEVER AN ID — "the the_ceaseless" is this fault and it has shipped before.
  {
    const locId = Object.keys(C433.locations || {}).find(id => C433.locations[id]?.name && id.includes("_"));
    const rendered = applyClash433({}, { id: "p1", name: "One Name" }, { id: "p2", name: "Two Name" },
      "wounded", 5, { content: C433, locationId: locId }).news[0]?.text || "";
    check("433: the place in a clash line is the location's DISPLAY NAME, and the id never reaches the player",
      rendered.includes(C433.locations[locId].name) && !rendered.includes(locId), `${locId} → ${rendered.slice(0, 110)}`);
  }

  // 9 · …AND THE SECOND DEFENCE, which fails differently: a caller that skipped the lookup and handed the
  // renderer an id gets the phrase dropped rather than the id printed.
  check("433: an id-shaped place handed straight to the renderer is refused, not printed",
    NV.isIdShaped("the_ceaseless") && !NV.isIdShaped("The Ceaseless")
    && !/the_ceaseless/.test(NV.fillTemplate("{W} killed {L} at {place}.", { W: "A", L: "B", place: "the_ceaseless" })));

  // 10 · THE POWER IS A DETAIL THE TELLER KNEW, NOT A STAT LINE — "roughly one in three", and the SAME
  // fight must say the same words every time, or a news item cannot be trusted to reopen the same battle.
  {
    const draw = (i) => NV.clashLine({ templates: T433.templates, outcome: "wounded",
      winner: { id: `w${i}`, name: "Winner Name" }, loser: { id: `l${i}`, name: "Loser Name" },
      place: "The Maw", power: "The Spent Hour" });
    // ⛔ DETERMINISM OVER 300 FIGHTS, NOT ONE — and the difference is the whole gate. `draw(7) === draw(7)`
    // was my first version, and mutation says it is worth nothing: with a 1-in-3 roll two draws of the SAME
    // fight still agree 5 times in 9 (both roll the power, or both roll a variant — and the variant is fixed
    // by the relationship). A gate that goes red 45% of the time is worse than no gate, because it will be
    // seen green and believed. Two full passes must agree line for line.
    const n = 300;
    const pass = () => Array.from({ length: n }, (_, i) => draw(i));
    const first = pass(), second = pass();
    const withPower = first.filter(s => s.includes("The Spent Hour")).length;
    check(`433: the power names the fight roughly one time in three (${withPower}/${n}) and never re-rolls`,
      withPower > n * 0.2 && withPower < n * 0.47 && first.every((s, i) => s === second[i]));
  }

  // 11 · ⛔ "Overseer Grael of the Edge District a daughter who thinks he is a clerk" IS NOT A SENTENCE.
  // Two grammatical shapes, two templates, chosen by the shape — and Aevi's FIELD hint is backwards for the
  // shipped content, which is why only the shape decides: `personalVerbs` is 219 fragments and 0 verbs.
  {
    const F = T433.fragments;
    const verb = NV.fragmentLine({ templates: F, name: "The Hollow King", frag: "sells a secret that wasn't his" });
    const noun = NV.fragmentLine({ templates: F, name: "Overseer Grael", frag: "a daughter who thinks he is a clerk" });
    check("433: a verb fragment and a noun fragment take DIFFERENT templates, and neither is a bare join",
      NV.fragmentForm("sells a secret that wasn't his") === "verbForm"
      && NV.fragmentForm("a daughter who thinks he is a clerk") === "nounForm"
      && NV.fragmentForm("learning a faster road") === "nounForm"
      && verb !== noun && !noun.startsWith("Overseer Grael a "), `${verb}\n      ${noun}`);
    const pv = (C433.legends?.roster || []).flatMap(f => f.personalVerbs || []);
    check(`433: every fragment this news site can draw is a noun phrase (${pv.length} personalVerbs, 0 verbs) — the shape decides, not the field`,
      pv.length > 100 && pv.every(v => NV.fragmentForm(v) === "nounForm"),
      pv.filter(v => NV.fragmentForm(v) !== "nounForm").slice(0, 3).join(" · "));
  }

  // 12 · AEVI'S OWN ASKED-FOR GATE, verbatim: *"no string under `templates` or `fragments` may contain ⛔ or
  // ⚠️."* She caught one leaking into a stalemate line — an editorial marker inside prose a player reads.
  {
    const leaks = [];
    const walk = (o, path) => {
      if (typeof o === "string") { if (/[⛔⚠]/.test(o) && !path.split(".").pop().startsWith("_")) leaks.push(path); return; }
      if (o && typeof o === "object") for (const [k, v] of Object.entries(o)) walk(v, `${path}.${k}`);
    };
    walk(T433.templates, "templates"); walk(T433.fragments, "fragments");
    check("433: no editorial marker leaks into a string a player reads", leaks.length === 0, leaks.join(" · "));
  }

  // 13 · THE WIRING ITSELF, as a census rather than a number — four sites resolve a clash and all four must
  // hand it the content, or three of them quietly keep the engine's own sentences.
  {
    const wt433 = readFileSync(join(root, "engine/worldtick.js"), "utf8");
    const applies = (wt433.match(/(?<!export function )applyEpicClashOutcome\(ws,/g) || []).length;
    const fed = (wt433.match(/abilitiesByTradition[^}]*, content \}/g) || []).length;
    check("433: every clash site hands the tick's content to the reporter", applies === 4 && fed === applies,
      `${applies} clash sites, ${fed} carrying content`);
  }

  // 14 · AND END TO END: a world that actually runs, and the murmurs it produces are sentences.
  {
    let seed433 = 12345;
    const rng433 = () => ((seed433 = (seed433 * 1664525 + 1013904223) >>> 0) / 4294967296);
    const ch433 = { name: "P", level: 6, worldState: initWs433(1) };
    // 900 days, because the personal-beat path does not fire in the first 400: measured 0 murmurs at
    // day 400 and 19 by day 600. A gate over an empty list is green and proves nothing.
    for (let d = 1; d <= 900; d++) {
      await tick433({ character: ch433, content: C433, evolveFn: async () => ({}), rng: rng433, now: Date.UTC(2025, 0, 1) + d * 86400000 });
    }
    const items = ch433.worldState.news || [];
    const murmurs = items.filter(n => n.tier === "murmur" && !n.kind);
    const templated = murmurs.filter(n => /is spoken of:|Word from/.test(n.text));
    const rawIds = items.filter(n => /\b[a-z0-9]+_[a-z0-9_]+\b/.test(String(n.text)));
    check(`433 END TO END: a live world's personal beats are sentences (${templated.length}/${murmurs.length} through a template) and no id reaches the page`,
      murmurs.length > 0 && templated.length > 0 && rawIds.length === 0,
      rawIds.slice(0, 2).map(n => n.text).join(" · "));
  }
}

check("smoke: no checks are stranded after process.exit (dead tests report green forever)", (() => {
  const src = readFileSync(join(root, "tests/smoke.mjs"), "utf8");
  const after = src.slice(src.indexOf("process.exit(failures") + 1);
  return !/\bcheck\(/.test(after);
})());
console.log(failures === 0 ? "\nAll smoke tests passed." : `\n${failures} FAILURE(S)`);
process.exit(failures === 0 ? 0 : 1);
